            quitf(_wa, "Invalid assignment: student %d cannot give a souvenir to themselves at line %d", u, i + 2);
        }

        pair<int, int> p = {min(u, v), max(u, v)};
        if (edges.count(p) == 0) {
            quitf(_wa, "Invalid assignment: students %d and %d do not know each other at line %d", u, v, i + 2);
        }

        if (edgeAssigned[p]) {
            quitf(_wa, "Invalid assignment: edge between %d and %d assigned more than once at line %d", u, v, i + 2);
        }

        edgeAssigned[p] = true;
        outDegree[u]++; // Student u gives a souvenir to student v
    }

    // Verify that all edges have been assigned
    for (const auto& e : edges) {
        if (!edgeAssigned[e]) {
            quitf(_wa, "Invalid assignment: edge between %d and %d was not assigned", e.first, e.second);
        }
    }

    // Check if the maximum out-degree matches the reported k
    int maxOutDegree = *max_element(outDegree.begin() + 1, outDegree.end());
    if (maxOutDegree != k) {
        quitf(_wa, "Invalid assignment: maximum out-degree %d does not match reported k = %d", maxOutDegree, k);
    }

    quitf(_ok, "Valid assignment with k = %d", k);
}

