#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

const int MAX_N = 100000;
const int MAX_M = 60000;
const int MAX_P = 60000;

// Disjoint Set Union class for Union-Find operations
class DSU {
public:
    vector<int> parent;
    DSU(int n) : parent(n) {
        for (int i = 0; i < n; ++i)
            parent[i] = i;
    }
    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }
    void unite(int x, int y) {
        parent[find(x)] = find(y);
    }
};

vector<bool> is_prime;

// Function to precompute primes using Sieve of Eratosthenes
void sieve(int n) {
    is_prime.assign(n + 1, true);
    is_prime[0] = is_prime[1] = false;
    for (int i = 2; i <= n; ++i) {
        if (is_prime[i]) {
            if ((long long)i * i <= n) {
                for (int j = i * i; j <= n; j += i)
                    is_prime[j] = false;
            }
        }
    }
}

int main(int argc, char* argv[]) {
    registerValidation(argc, argv);

    sieve(MAX_P);

    int t = inf.readInt(1, 100, "t");
    inf.readEoln();
    long long total_n = 0;
    long long total_m = 0;
    for (int test_case = 0; test_case < t; ++test_case) {
        int n = inf.readInt(2, MAX_N, "n");
        total_n += n;
        ensuref(total_n <= MAX_N, "Sum of n over all test cases must not exceed %d", MAX_N);
        inf.readEoln();

        DSU dsu(n + 1); // Nodes are from 1 to n

        for (int i = 0; i < n - 1; ++i) {
            int u = inf.readInt(1, n, "u_i");
            inf.readSpace();
            int v = inf.readInt(1, n, "v_i");
            inf.readEoln();
            ensuref(u != v, "Edge connects node %d to itself", u);
            if (dsu.find(u) == dsu.find(v)) {
                ensuref(false, "Graph contains a cycle at edge %d (%d, %d)", i+1, u, v);
            }
            else {
                dsu.unite(u, v);
            }
        }

        int m = inf.readInt(1, MAX_M, "m");
        total_m += m;
        ensuref(total_m <= MAX_M, "Sum of m over all test cases must not exceed %d", MAX_M);
        inf.readEoln();

        vector<int> p = inf.readInts(m, 2, MAX_P - 1, "p_i");
        inf.readEoln();

        for (int i = 0; i < m; ++i) {
            int pi = p[i];
            ensuref(is_prime[pi], "p_i[%d]=%d is not a prime number", i+1, pi);
        }
    }

    inf.readEof();
    return 0;
}

