#include <bits/stdc++.h>
using namespace std;
using P = pair<short, short>;
using T = pair<short, P>;
int h, w, l, p;
short g[4010][4010];
short s[4][4010][4010];
struct FenwickTree {
  FenwickTree(int n = 0) : v(n + 1, 0) {}
  void init() { fill(begin(v), end(v), 0); }
  void add(int k, int x) {
    k++;
    while (k < v.size()) {
      v[k] += x;
      k += k & -k;
    }
  }
  int sum(int k) {
    k = max(0, min<int>(v.size() - 1, k));
    int s = 0;
    while (k) {
      s += v[k];
      k -= k & -k;
    }
    return s;
  }
  int sum(int l, int r) { return sum(r) - sum(l); }

 private:
  vector<int> v;
};
int main() {
  scanf("%d %d %d %d", &h, &w, &l, &p);
  for (int i = 1; i <= h; i++) {
    for (int j = 1; j <= w; j++) {
      g[i][j] = 1;
    }
  }
  for (int i = 0; i < p; i++) {
    int a, b;
    scanf("%d %d", &a, &b);
    g[a][b] = 0;
  }
  for (int i = 1; i <= h; i++) {
    for (int j = 1; j <= w; j++) {
      if (g[i][j]) {
        s[0][i][j] = s[0][i][j - 1] + 1;
        s[1][i][j] = s[1][i - 1][j] + 1;
      }
    }
  }
  for (int i = h; i >= 1; i--) {
    for (int j = w; j >= 1; j--) {
      if (g[i][j]) {
        s[2][i][j] = s[2][i][j + 1] + 1;
        s[3][i][j] = s[3][i + 1][j] + 1;
      }
    }
  }
  int offset = w - 1;
  vector<vector<T>> vs(h + w - 1);
  for (int i = 1; i <= h; i++) {
    for (int j = 1; j <= w; j++) {
      int k = vs[i - j + offset].size() / 2;
      vs[i - j + offset].emplace_back(min(s[2][i][j], s[3][i][j]), P(0, k));
      vs[i - j + offset].emplace_back(min(s[0][i][j], s[1][i][j]), P(1, k));
    }
  }
  long long res = 0;
  vector<FenwickTree> tr(2, FenwickTree(4010));
