#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

const long long INF = LLONG_MAX / 2; // to avoid overflow when adding

int n, m;
long long L;
int s, t;

struct Edge {
    int u, v;
    long long w;
};

map<pair<int, int>, long long> initialWeights;
set<pair<int, int>> edgeSet;
vector<Edge> edges;

void readInput() {
    n = inf.readInt(2, 1000, "n");
    m = inf.readInt(1, 10000, "m");
    L = inf.readLong(1, 1000000000LL, "L");
    s = inf.readInt(0, n - 1, "s");
    t = inf.readInt(0, n - 1, "t");
    ensuref(s != t, "s should not be equal to t");
    for (int i = 0; i < m; i++) {
        int ui = inf.readInt(0, n - 1, format("u[%d]", i + 1).c_str());
        int vi = inf.readInt(0, n - 1, format("v[%d]", i + 1).c_str());
        ensuref(ui != vi, "Edge cannot connect vertex to itself");
        long long wi = inf.readLong(0, 1000000000LL, format("w[%d]", i + 1).c_str());
        pair<int, int> edgeKey = make_pair(min(ui, vi), max(ui, vi));
        ensuref(edgeSet.find(edgeKey) == edgeSet.end(), "Multiple edges between same pair of vertices");
        edgeSet.insert(edgeKey);
        initialWeights[edgeKey] = wi;
        edges.push_back({ui, vi, wi});
    }
}

string readAnswer(InStream& stream, map<pair<int, int>, long long>& participantWeights) {
    string firstWord = stream.readToken();
    if (firstWord != "YES" && firstWord != "NO") {
        stream.quitf(_pe, "The first line should be YES or NO");
    }
    if (firstWord == "NO") {
        return "NO";
    }
    // Read m edges
    for (int i = 0; i < m; i++) {
        int ui = stream.readInt(0, n - 1, format("u[%d]", i + 1).c_str());
        int vi = stream.readInt(0, n - 1, format("v[%d]", i + 1).c_str());
        if (ui < 0 || ui >= n || vi < 0 || vi >= n) {
            stream.quitf(_pe, "Invalid vertex index");
        }
        pair<int, int> edgeKey = make_pair(min(ui, vi), max(ui, vi));
        if (edgeSet.find(edgeKey) == edgeSet.end()) {
            stream.quitf(_wa, "Edge (%d, %d) does not exist in the input graph", ui, vi);
        }
        long long wi = stream.readLong(1, 1000000000000000000LL, format("w[%d]", i + 1).c_str());
        participantWeights[edgeKey] = wi;
    }
    return "YES";
}

bool verifySolution(map<pair<int, int>, long long>& participantWeights) {
    // Check that participantWeights matches initialWeights for edges with non-zero weights
    for (auto& edge : edgeSet) {
        long long initialW = initialWeights[edge];
        long long participantW = participantWeights[edge];
        if (initialW != 0) {
            if (participantW != initialW) {
                return false; // Participant changed a non-zero weight
            }
        } else {
            if (participantW < 1 || participantW > 1000000000000000000LL) {
                return false; // Assigned weight out of bounds
            }
        }
    }
    // Build the graph and compute shortest path
    vector<vector<pair<int, long long>>> adj(n);
    for (auto& edge : edgeSet) {
        int u = edge.first;
        int v = edge.second;
        long long w = participantWeights[edge];
        adj[u].push_back({v, w});
        adj[v].push_back({u, w}); // undirected graph
    }
    // Dijkstra's algorithm
    vector<long long> dist(n, INF);
    priority_queue<pair<long long, int>, vector<pair<long long, int>>, greater<pair<long long, int>>> pq;
    dist[s] = 0;
    pq.push({0, s});
    while (!pq.empty()) {
        auto [d, u] = pq.top(); pq.pop();
        if (d > dist[u]) continue;
        for (auto& [v, w] : adj[u]) {
            if (dist[v] > dist[u] + w) {
                dist[v] = dist[u] + w;
                pq.push({dist[v], v});
            }
        }
    }
    // Check if shortest path length is exactly L
    return dist[t] == L;
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    readInput();

    map<pair<int, int>, long long> juryWeights;
    string juryAns = readAnswer(ans, juryWeights);

    map<pair<int, int>, long long> participantWeights;
    string participantAns = readAnswer(ouf, participantWeights);

    if (participantAns == "NO") {
        if (juryAns == "YES") {
            quitf(_wa, "Participant claims no solution exists, but jury found a solution");
        } else {
            quitf(_ok, "Participant correctly identified that no solution exists");
        }
    } else {
        // Participant outputs "YES"
        if (participantWeights.size() != m) {
            quitf(_wa, "Participant output has incorrect number of edges");
        }
        if (!verifySolution(participantWeights)) {
            quitf(_wa, "Participant's solution is invalid");
        }
        quitf(_ok, "Participant found a valid solution");
    }
}

