    int n = opt<int>("n");
    int k = opt<int>("k");
    string type = opt<string>("type", "random");

    vector<pair<int, int>> edges;

    if (type == "chain") {
        // Build a chain from 1 to n
        for (int i = 2; i <= n; ++i) {
            edges.push_back({i - 1, i});
        }
    } else if (type == "star") {
        // Connect all nodes to node 1
        for (int i = 2; i <= n; ++i) {
            edges.push_back({1, i});
        }
    } else if (type == "balanced") {
        // Build a balanced binary tree
        for (int i = 1; i <= n / 2; ++i) {
            if (2 * i <= n)
                edges.push_back({i, 2 * i});
            if (2 * i + 1 <= n)
                edges.push_back({i, 2 * i + 1});
        }
    } else if (type == "bigguy") {
        // Build a large subtree and small ones
        int big_subtree_size = n / 2;
        for (int i = 2; i <= big_subtree_size; ++i) {
            edges.push_back({i - 1, i});
        }
        for (int i = big_subtree_size + 1; i <= n; ++i) {
            edges.push_back({1, i});
        }
    } else if (type == "skewed") {
        // Build a skewed tree (a line)
        int parent = 1;
        for (int i = 2; i <= n; ++i) {
            edges.push_back({parent, i});
            parent = i;
        }
    } else {
        // Random tree
        for (int i = 2; i <= n; ++i) {
            int u = i;
            int v = rnd.next(1, i - 1);
            edges.push_back({u, v});
        }
        // Shuffle edges
        shuffle(edges.begin(), edges.end());
    }

    // Output N and K
    printf("%d %d\n", n, k);

    // Output edges
    for (auto e : edges) {
        printf("%d %d\n", e.first, e.second);
    }

    return 0;
}

