#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

// Builds a Cartesian tree for a permutation B (distinct elements).
// Returns the maximum depth of the constructed tree.
// The tree is constructed so that the minimum element is the root,
// recursively splitting into left and right segments.
int cartesianTreeDepth(const vector<int> &B) {
    int n = (int)B.size();
    // Edge case: if n == 0 (should not occur here, but just in case).
    if (n == 0) return 0;
    // Arrays to store parent/children.
    vector<int> parent(n, -1), leftChild(n, -1), rightChild(n, -1);

    // Build Cartesian Tree in O(n).
    stack<int> st;
    for (int i = 0; i < n; i++) {
        int last = -1;
        // Maintain a stack of indices whose elements are strictly less than B[i].
        // Pop while top is greater (we want min-based cartesian tree).
        while (!st.empty() && B[st.top()] > B[i]) {
            last = st.top();
            st.pop();
        }
        if (!st.empty()) {
            parent[i] = st.top();
            rightChild[st.top()] = i;
        }
        if (last != -1) {
            parent[last] = i;
            leftChild[i] = last;
        }
        st.push(i);
    }

    // Find the root (the one with parent == -1).
    // In a Cartesian tree of distinct elements, there is exactly one such root.
    int root = st.top();
    while (parent[root] != -1) {
        root = parent[root];
    }

    // Compute maximum depth by BFS (or DFS). Depth = number of vertices from root to leaf.
    int maxDepth = 1;
    queue<pair<int,int>>q;
    q.push({root, 1});
    while (!q.empty()) {
        auto [u, d] = q.front();
        q.pop();
        maxDepth = max(maxDepth, d);
        if (leftChild[u] != -1)  q.push({leftChild[u],  d + 1});
        if (rightChild[u] != -1) q.push({rightChild[u], d + 1});
    }
    return maxDepth;
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    // Read 'n' and the original permutation from the input file.
    int n = inf.readInt(1, 200000, "n");
    vector<int> A = inf.readInts(n, 1, n, "permutation");

    // Read from the jury's answer file: we only need the official minimal depth.
    int d_jury = ans.readInt(1, n, "jury's minimal depth");
    // The shift from the jury's file is not strictly needed if multiple solutions are possible,
    // but we must read it anyway to keep the answer file pointer consistent.
    // We won't use it for final validation except for boundary checks.
    int sh_jury = ans.readInt(0, n - 1, "jury's shift"); 
    // We do not rely on sh_jury, since multiple shifts can yield the same minimal depth.

    // Read from the contestant's output file: the claimed depth and shift.
    int d_part = ouf.readInt(1, n, "participant's minimal depth");
    int s_part = ouf.readInt(0, n - 1, "participant's shift");

    // Compare the participant's claimed depth with the jury's minimal depth.
    if (d_part < d_jury) {
        // Participant claims a better solution (smaller depth) than the official one.
        // That means the jury's solution wasn't minimal => checker fails.
        quitf(_fail, 
              "Participant's depth (%d) is smaller than jury's depth (%d). Jury's solution not minimal?",
              d_part, d_jury);
    }
    else if (d_part > d_jury) {
        // Participant's solution is definitely worse than minimal.
        quitf(_wa, 
              "Participant's depth (%d) is larger than the minimal depth (%d). Not minimal.",
              d_part, d_jury);
    }
    // Here: d_part == d_jury. We must verify that the shift s_part actually yields depth d_jury.

    // Construct shifted permutation B, shifting A by s_part to the left.
    // B[0] = A[s_part], B[1] = A[s_part+1], ..., wrapping around.
    vector<int> B(n);
    for (int i = 0; i < n; i++) {
        B[i] = A[(i + s_part) % n];
    }

    // Compute the Cartesian Tree's depth for this shifted permutation.
    int actualDepth = cartesianTreeDepth(B);

    // Compare with the official minimal depth.
    if (actualDepth != d_jury) {
        quitf(_wa,
              "Wrong depth for shift %d. Expected %d, but got %d.",
              s_part, d_jury, actualDepth);
    }

    // If it matches, the answer is correct.
    quitf(_ok, 
          "Correct depth = %d with shift %d. Accepted.", 
          d_jury, s_part);
}

