struct SegTree {
  struct node {
    int mx, lazy;
    node() { mx = lazy = 0; }
  };
  vector<node> tree;
  void init(int n) {
    tree.resize(4 * static_cast<size_t>(n));
    for (size_t i = 0; i < tree.size(); i++) {
      tree[i].mx = tree[i].lazy = 0;
    }
  }
  void push(int tl, int tr, int idx) {
    if (tl < tr) {
      tree[static_cast<size_t>(idx) * 2].lazy += tree[idx].lazy;
      tree[static_cast<size_t>(idx) * 2 + 1].lazy += tree[idx].lazy;
    }
    tree[idx].mx += tree[idx].lazy;
    tree[idx].lazy = 0;
  }
  void update(int l, int r, int x, int tl, int tr, int h = 1) {
    push(tl, tr, h);
    if (l > r || tr < l || r < tl) { return; }
    if (l <= tl && tr <= r) {
      tree[h].lazy += x;
      push(tl, tr, h);
      return;
    }
    int mid = (tl + tr) / 2;
    update(l, r, x, tl, mid, h * 2);
    update(l, r, x, mid + 1, tr, h * 2 + 1);
    tree[h].mx = max(tree[static_cast<size_t>(h) * 2].mx, tree[static_cast<size_t>(h) * 2 + 1].mx);
  }
