#include <bits/stdc++.h>
typedef long long LL;
const int MAXN = 500000;
const int MAXP = 2 * MAXN;
const int MAXC = 26;
using namespace std;

int l[MAXN + 5], r[MAXN + 5];

struct SuffixAutomaton {
  int last, tot, trans[MAXP + 5][MAXC], len[MAXP + 5], link[MAXP + 5];
  int pos[MAXP + 5], s[MAXP + 5], sz[MAXP + 5][11];
  SuffixAutomaton(): tot(1), last(1) {}

  void insert(char *s, int n, int id) {
    last = 1; for (int i = 1; i <= n; ++i) extend(s[i], id);
  }
  void extend(char x, int id) {
    int c = x - 'a', cur = ++tot, p = last;
    len[cur] = len[last] + 1;
    while (p && !trans[p][c]) {
      trans[p][c] = cur, p = link[p];
    }

    if (!p) {
      link[cur] = 1;
    } else {
      int q = trans[p][c];
      if (len[p] + 1 == len[q]) {
        link[cur] = q;
      } else {
        int nq = ++tot; len[nq] = len[p] + 1;
        memcpy(trans[nq], trans[q], sizeof(trans[q]));
        while (p && trans[p][c] == q) {
          trans[p][c] = nq, p = link[p];
        }
        link[nq] = link[q], link[cur] = link[q] = nq;
      }
    }
    sz[cur][id] = 1, last = cur;
  }
  int calc(const int n, const int mx_len) {
    for (int p = 1; p <= tot; ++p) ++s[len[p]];
    for (int i = 1; i <= mx_len; ++i) s[i] += s[i - 1];
    for (int p = 1; p <= tot; ++p) pos[s[len[p]]--] = p;

    for (int i = tot; i; --i) {
      int p = pos[i]; 
      for (int j = 0; j <= n; ++j) sz[link[p]][j] += sz[p][j]; 
