#include <bits/stdc++.h>
using namespace std;
const int INF = 0x3f3f3f3f;
int m, n, S, T;
int belong[700], first[700], dep[700], q[700], k;
int v1[700], v2[700];
int mat[700][700];
struct Edge {
  int x, y, next, cap;
  Edge(int x = 0, int y = 0, int next = 0, int cap = 0)
      : x(x), y(y), next(next), cap(cap) {}
} e[200010 << 1];
void add_edge(int x, int y, int cap) {
  e[k] = Edge(x, y, first[x], cap);
  first[x] = k++;
}
bool bfs() {
  memset(dep, 0, sizeof(dep));
  int t = 0, f = 1;
  q[t] = S, dep[S] = 1;
  while (t < f) {
    int u = q[t++];
    for (int i = first[u]; i != -1; i = e[i].next) {
      int v = e[i].y;
      if (e[i].cap > 0 && !dep[v]) {
        dep[v] = dep[u] + 1;
        q[f++] = v;
      }
    }
  }
  if (dep[T])
    return true;
  else
    return false;
}
int dfs(int u, int sum) {
  if (u == T) return sum;
  int t;
  for (int i = first[u]; i != -1; i = e[i].next) {
    int v = e[i].y;
    if (dep[v] == dep[u] + 1 && e[i].cap > 0 &&
        (t = dfs(v, min(sum, e[i].cap)))) {
      e[i].cap -= t;
      mat[e[i].x][v] += t;
      e[i ^ 1].cap += t;
      mat[v][e[i].x] -= t;
      return t;
    }
  }
  return 0;
}
int Dinic() {
  int ans = 0;
  while (bfs()) {
    int flow;
    while (true) {
      flow = dfs(S, INF);
      ans += flow;
      if (!flow) break;
    }
  }
  return ans;
}
int main() {
  while (~scanf("%d%d", &n, &m)) {
    int sum1 = 0;
    for (int i = 1; i <= n; i++) {
      scanf("%d", v1 + i);
      sum1 += v1[i];
    }
    int sum2 = 0;
    for (int i = 1; i <= n; i++) {
      scanf("%d", v2 + i);
      sum2 += v2[i];
    }
    if (sum1 != sum2) {
      puts("NO");
      continue;
    }
    int sum = sum1;
