    k = 0;
    int a, b;
    for (int i = 0; i < m; i++) {
      scanf("%d%d", &a, &b);
      add_edge(a, b + n, v1[a]);
      add_edge(b + n, a, 0);
      add_edge(b, a + n, v1[b]);
      add_edge(a + n, b, 0);
    }
    S = 0, T = 2 * n + 1;
    for (int i = 1; i <= n; i++) {
      add_edge(i, i + n, v1[i]);
      add_edge(i + n, i, 0);
      add_edge(S, i, v1[i]);
      add_edge(i, S, 0);
    }
    for (int i = n + 1; i < T; i++) {
      add_edge(i, T, v2[i - n]);
      add_edge(T, i, 0);
    }
    memset(mat, 0, sizeof(mat));
    for (int i = 1; i <= n; i++) mat[i][i] = v1[i];
