using namespace std;
int main() {
  string s, t, ans;
  cin >> s;
  cin >> t;
  long long len1 = s.length();
  long long len2 = s.length();
  long long dp[len1 + 1][len2 + 1];
  for (long long i = 0; i <= len1; i++) {
    for (long long j = 0; j <= len2; j++) {
      if (i == 0 || j == 0) {
        dp[i][j] = 0;
      } else {
        if (s[i - 1] == t[j - 1]) {
          dp[i][j] = 1 + dp[i - 1][j - 1];
        } else {
          dp[i][j] = max(dp[i - 1][j], dp[i][j - 1]);
        }
      }
    }
  }
  long long a, b;
  a = len1;
  b = len2;
  while (a > 0 && b > 0) {
    if (s[a - 1] == s[b - 1]) {
      ans.push_back(s[a - 1]);
      a = a - 1;
      b = b - 1;
    } else if (dp[a - 1][b] > dp[a][b - 1]) {
      a = a - 1;
    } else {
      b = b - 1;
    }
  }
  for (long long i = dp[len1][len2] - 1; i >= 0; i--) {
    cout << ans[i];
  }
  cout << endl;
}

