int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // Get parameters
    int n = opt<int>("n");
    int m = opt<int>("m");
    string type = opt<string>("type", "random");

    string s, t;

    if (type == "random") {
        // Generate random strings of length n and m
        s = random_string(n);
        t = random_string(m);
    } else if (type == "same") {
        // Generate a common substring and build s and t around it
        int len = min(n, m);
        string common = random_string(len);
        s = common;
        t = common;
        // Append random letters to reach lengths n and m
        if (n > len) s += random_string(n - len);
        if (m > len) t += random_string(m - len);
    } else if (type == "opposite") {
        // Generate a string and its reverse
        s = random_string(n);
        t = s;
        reverse(t.begin(), t.end());
    } else if (type == "no_common") {
        // Generate strings with no common characters
        string letters1 = "abcdefghijklm";
        string letters2 = "nopqrstuvwxyz";
        s = "";
        t = "";
        for (int i = 0; i < n; ++i)
            s += letters1[rnd.next(letters1.size())];
        for (int i = 0; i < m; ++i)
            t += letters2[rnd.next(letters2.size())];
    } else if (type == "single_common") {
        // Generate strings with only a single common character
        char common_char = rnd.next('a', 'z');
        s = "";
        t = "";
        for (int i = 0; i < n; ++i) {
            char c = (rnd.next(5) == 0) ? common_char : rnd.next('a', 'z');
            s += c;
        }
        for (int i = 0; i < m; ++i) {
            char c = (rnd.next(5) == 0) ? common_char : rnd.next('a', 'z');
            t += c;
        }
        // Ensure the common character exists in both strings
        s[rnd.next(n)] = common_char;
        t[rnd.next(m)] = common_char;
    } else if (type == "long_common_subsequence") {
        // Generate a long common subsequence
        int len = min(n, m);
        string common = random_string(len);
        s = common;
        t = common;
        // Insert random characters at random positions
        while ((int)s.size() < n) {
            int pos = rnd.next(s.size() + 1);
            s.insert(s.begin() + pos, rnd.next('a', 'z'));
        }
        while ((int)t.size() < m) {
