                adj[u].push_back(v);
            }
        }
    } 
    else if (type == "random") {
        // Randomly generate edges
        double edge_prob = opt<double>("p", 0.5); // default probability
        bool self_loops = opt<bool>("self_loops", false);

        for (int u = 1; u <= n; ++u) {
