using namespace std;

/*
  This generator produces one *input file* for the substitution problem
  each time it is executed. The input file may contain multiple datasets,
  ending with a single "0".

  Usage example:
    ./gen -d 5 -type random
  This will produce 5 random datasets, then a line "0".

  Alternatively:
    ./gen -d 3 -type corner
  This will produce 3 "corner" datasets (cycling through a small
  library of known tricky datasets), then a line "0".

  The constraint rules for each dataset are:
    1) 1 <= n <= 10
    2) For each 1 <= i <= n:
       - 1 <= |alpha_i| < |beta_i| <= 10
       - alpha_i != alpha_j for i != j
    3) 1 <= |gamma| < |delta| <= 10
    4) All strings are lowercase letters.
*/

static const int ALPH_LEN = 26; // number of lowercase letters

// A small library of corner (fixed) datasets to help detect tricky solutions.
struct CornerSet {
    int n;
    vector<pair<string,string>> subs;
    string gamma, delta;
};

// Some corner cases, partly inspired by the examples in the problem statement.
vector<CornerSet> cornerSets = {
    {
        1,
        {{"a", "aa"}},
        "a",
        "aaaaa"
    },
    {
        2,
        {{"a", "bb"}, {"b", "aa"}},
        "a",
        "bbbbbbbb"
    },
    // The example from the problem statement (first example).
    {
        2,
        {{"aa", "bca"}, {"b", "ab"}},
        "aaxaaa",
        "bcaxbcaa"
    },
    // Another with single substitution, length jump from 3 to 8.
    {
        1,
        {{"abc", "zzzz"}},
        "abc",
        "zzzzzzzz"
    },
    // Another example from the problem statement with n=3
    {
        3,
        {{"ab","aab"}, {"abc","aadc"}, {"ad","dee"}},
        "abc",
        "deeeeeeeec"
    },
};

// Generate a random string of length L using [a..z].
string genRandomString(int L) {
    string s; s.reserve(L);
    for(int i = 0; i < L; i++){
        s.push_back(char('a' + rnd.next(ALPH_LEN)));
    }
    return s;
}

// Generate a single random dataset that satisfies the constraints.
//  1 <= n <= maxN (<= 10)
//  1 <= |alpha_i| < |beta_i| <= 10
//  alpha_i != alpha_j
//  1 <= |gamma| < |delta| <= 10
//  All strings consist of lowercase letters.
struct DataSet {
    int n;
    vector<pair<string,string>> subs;
    string gamma, delta;
};

DataSet genRandomDataset(int maxN) {
    DataSet ds;
    ds.n = rnd.next(1, maxN); // random n in [1..maxN]

    // We store alpha_i in a set to ensure distinctness.
    set<string> usedAlpha;
    for(int i = 0; i < ds.n; i++){
        // Generate alpha
        string alpha;
        while(true){
            int lenA = rnd.next(1, 9); // alpha length in [1..9]
            alpha = genRandomString(lenA);
            if(!usedAlpha.count(alpha)){
                usedAlpha.insert(alpha);
                break;
            }
        }
        // Generate beta with length in (|alpha|..10], strictly greater than |alpha|
        int lenB = rnd.next((int)alpha.size() + 1, 10);
        string beta = genRandomString(lenB);

        ds.subs.push_back({alpha, beta});
    }

    // Generate gamma, delta with 1 <= |gamma| < |delta| <= 10
    int lenGamma = rnd.next(1, 9); 
    ds.gamma = genRandomString(lenGamma);
    int lenDelta = rnd.next(lenGamma + 1, 10);
    ds.delta = genRandomString(lenDelta);

    return ds;
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // Number of datasets to produce.
    int d = opt<int>("d", 1);
    // Type of dataset: "random" or "corner"
    string type = opt<string>("type", "random");

    // We'll produce exactly d datasets, then a line "0".
    for(int i = 0; i < d; i++){
        if(type == "corner"){
            // Cycle through cornerSets
            CornerSet c = cornerSets[i % (int)cornerSets.size()];
            cout << c.n << "\n";
            for(auto &pr: c.subs){
                cout << pr.first << " " << pr.second << "\n";
            }
            cout << c.gamma << "\n";
            cout << c.delta << "\n";
        } else {
            // random
            DataSet ds = genRandomDataset(10);
            cout << ds.n << "\n";
            for(auto &pr: ds.subs){
                cout << pr.first << " " << pr.second << "\n";
            }
            cout << ds.gamma << "\n";
            cout << ds.delta << "\n";
        }
    }

    // Print "0" to mark the end of input
    cout << 0 << "\n";

    return 0;
}

