// Checker for the problem: Given a sequence and a length k, find the starting index of k consecutive elements with minimal sum.

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    // Read n and k from the input file
    int n = inf.readInt();
    int k = inf.readInt();

    // Read the sequence h[1..n]
    vector<int> h(n + 1); // 1-based indexing
    vector<long long> prefix(n + 1, 0); // Prefix sums
    for (int i = 1; i <= n; ++i) {
        h[i] = inf.readInt();
        prefix[i] = prefix[i - 1] + h[i];
    }

    // Compute the minimal sum of any k consecutive elements
    long long minSum = LLONG_MAX;
    for (int i = 1; i <= n - k + 1; ++i) {
        long long sum = prefix[i + k - 1] - prefix[i - 1];
        if (sum < minSum) {
            minSum = sum;
        }
    }

    // Read participant's output
    int j = ouf.readInt(1, n - k + 1, "j");

    // Compute the sum of the subsequence starting at position j
    long long participantSum = prefix[j + k - 1] - prefix[j - 1];

    // Check if the participant's sum matches the minimal sum
    if (participantSum != minSum) {
        quitf(_wa, "Sum at position %d is %lld, but minimal sum is %lld", j, participantSum, minSum);
    } else {
        quitf(_ok, "Sum at position %d is minimal sum %lld", j, participantSum);
    }
}

