    if (n % 2 != 0) {
        return false;
    }
    int half = n / 2;
    return S.substr(0, half) == S.substr(half, half);
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    string type = opt<string>("type");

    // Ensure n is within constraints
    ensure(1 <= n && n <= 100);

    string S;

    if (type == "yes") {
        // n must be even
        if (n % 2 != 0) {
            cerr << "Error: For 'yes' type, n must be even.\n";
            exit(1);
        }
        int half = n / 2;
        string T;
        // Generate a random string T of length half
        for (int i = 0; i < half; ++i) {
            char c = rnd.next('a', 'z');
            T.push_back(c);
        }
        S = T + T;
    } else if (type == "no_random") {
        // Generate a random string S of length n
        // Ensure that S is not a concatenation of two identical strings
        int attempts = 0;
        do {
            S.clear();
            for (int i = 0; i < n; ++i) {
                char c = rnd.next('a', 'z');
                S.push_back(c);
            }
            ++attempts;
            if (attempts > 1000) {
                // Can't find such S, exit with error
                cerr << "Unable to generate non-double string after 1000 attempts.\n";
                return 1;
            }
        } while (isDoubleString(S));
    } else if (type == "no_special") {
        // Generate a string S that is almost T + T
        // For N even
        if (n % 2 != 0) {
            // If n is odd, just generate a random string ensuring it's not T+T
            int attempts = 0;
            do {
                S.clear();
                for (int i = 0; i < n; ++i) {
                    char c = rnd.next('a', 'z');
                    S.push_back(c);
                }
                ++attempts;
                if (attempts > 1000) {
                    // Can't find such S, exit with error
                    cerr << "Unable to generate non-double string after 1000 attempts.\n";
                    return 1;
                }
            } while (isDoubleString(S));
        } else {
            int half = n / 2;
            string T;
            for (int i = 0; i < half; ++i) {
                char c = rnd.next('a', 'z');
                T.push_back(c);
            }
            // Modify one character in the second half
            string T2 = T;
            int pos = rnd.next(0, half - 1);
            char originalChar = T2[pos];
            char newChar;
            do {
                newChar = rnd.next('a', 'z');
            } while (newChar == originalChar);
            T2[pos] = newChar;
            S = T + T2;
        }
    } else if (type == "edge") {
        // Generate edge cases
        // N=1, N=2
        if (n == 1) {
            S = string(1, rnd.next('a', 'z'));
        } else if (n ==2) {
            // Generate both "Yes" and "No" cases randomly
            if (rnd.next(0,1) == 0) {
                // Generate "Yes" case: S[0] == S[1]
                char c = rnd.next('a', 'z');
                S = string(2, c);
            } else {
                // Generate "No" case: S[0] != S[1]
                char c1 = rnd.next('a', 'z');
                char c2;
                do {
                    c2 = rnd.next('a', 'z');
                } while (c2 == c1);
                S.push_back(c1);
                S.push_back(c2);
            }
        } else {
            // For other edge cases, generate a random string
            for (int i = 0; i < n; ++i) {
                char c = rnd.next('a', 'z');
                S.push_back(c);
            }
        }
    } else {
        cerr << "Unknown type: " << type << "\n";
        return 1;
    }

