        for (int i = 0; i < n; ++i)
            a[i] = rnd.next(1, maxA);
        sort(a.rbegin(), a.rend());
    } else if (type == "max") {
        // All errors are maxA
        for (int i = 0; i < n; ++i)
            a[i] = maxA;
    } else if (type == "small") {
