#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

void check_counts(unordered_map<int, int> &count_prev, unordered_map<int, int> &count_next, const char *message) {
    int missing_count = 0;
    for (auto &p : count_prev) {
        int key = p.first;
        int cp = p.second;
        int cn = count_next[key];
        if (cp > cn) {
            int diff = cp - cn;
            if (diff == 1) {
                missing_count++;
            } else {
                ensuref(false, "%s: Count difference for element %d is %d, expected at most 1", message, key, diff);
            }
        } else if (cp == cn) {
            continue;
        } else {
            ensuref(false, "%s: Count for element %d increased from previous to next", message, key);
        }
    }
    for (auto &p : count_next) {
        int key = p.first;
        if (count_prev.find(key) == count_prev.end()) {
            ensuref(false, "%s: Element %d appears in next but not in previous", message, key);
        }
    }
    ensuref(missing_count == 1, "%s: Number of missing elements is %d, expected 1", message, missing_count);
}

int main(int argc, char* argv[]) {
    registerValidation(argc, argv);
    int n = inf.readInt(3, 100000, "n");
    inf.readEoln();
    vector<int> a = inf.readInts(n, 1, 1000000000, "a_i");
    inf.readEoln();
    vector<int> b = inf.readInts(n - 1, 1, 1000000000, "b_i");
    inf.readEoln();
    vector<int> c = inf.readInts(n - 2, 1, 1000000000, "c_i");
    inf.readEoln();

    unordered_map<int, int> count_a, count_b, count_c;
    for (int x : a) count_a[x]++;
    for (int x : b) count_b[x]++;
    for (int x : c) count_c[x]++;

    check_counts(count_a, count_b, "After first compilation");
    check_counts(count_b, count_c, "After second compilation");

    inf.readEof();
    return 0;
}

