#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
  This generator produces exactly ONE test case per execution. You can run
  it multiple times (with different parameters) to produce multiple tests.

  Parameters:
    1) n      : The number of banknotes.
    2) t (type): String describing how to generate the values of a, b, c and x_i.

  Possible types ("t"):
    - "random": Completely random valid a, b, c, and random distribution of x_i.
    - "small":  a, b, c close together (b+1 = a, a+1 = c).
    - "large":  a, b, c all large, near 10^9.
    - "left":   Many x_i on the left side (close to b).
    - "right":  Many x_i on the right side (close to c).
    - "center": Many x_i on or near Oleg's position a.
    - "edges":  Many x_i exactly at b or c (which Oleg cannot collect).
    - "mixed":  A mix of left, center, and right positions for x_i.
*/

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // Read parameters
    int n = opt<int>("n");
    string t = opt<string>("t", "random");

    // We must produce:
    // 1) a, b, c with 1 <= b < a < c <= 10^9
    // 2) n
    // 3) x1..x_n with 1 <= x_i <= 10^9

    // We'll choose a, b, c differently depending on the "type" argument.
    // Then we'll generate x_i in a way appropriate to that type.

    // We define some helper lambdas for convenience:

    // Helper to get a random distinct triple (b < a < c) in [1..10^9]
    auto genABC = [&](bool tight = false, bool large = false) {
        // If "tight", we'll pick b, a, c as consecutive or very close
        // If "large", we'll pick them near 10^9
        // Otherwise, random in [1..10^9].
        long long B, A, C;
        if (tight) {
            // Minimal distances: b+1 = a, a+1 = c
            // But ensure it all fits into [1..10^9]
            // We'll randomly pick a small or random offset
            // for the lower bound, but keep them close.
            long long base = rnd.next(1, 1000000000 - 2);
            B = base;
            A = base + 1;
            C = base + 2;
        } else if (large) {
            // We'll choose them near 10^9 but still valid
            // e.g. pick b in [1e9-2 .. 1e9-2], etc.
            // or just pick something close to 10^9
            B = rnd.next(1, 1000000000 - 2);
            // Force b to be large:
            if (B < 1000000000 / 2) B = 1000000000 - 3;
            A = B + 1;
            C = A + 1;
        } else {
            // fully random
            B = rnd.next(1, 1000000000 - 2);
            A = rnd.next((int)B + 1, 1000000000 - 1);
            C = rnd.next((int)A + 1, 1000000000);
        }
        return make_tuple((int)A, (int)B, (int)C);
    };

    // Generate x array (the positions of the banknotes) in [1..10^9],
    // depending on type.
    // We'll fill them in a vector<int> x, then print them.

    int a, b, c;
    vector<int> x(n);

    if (t == "random") {
        // Random b<a<c, random x
        tie(a, b, c) = genABC(false, false);
        for(int i = 0; i < n; i++){
            x[i] = rnd.next(1, 1000000000);
        }
    }
    else if (t == "small") {
        // b+1 = a, a+1 = c
        tie(a, b, c) = genABC(/*tight=*/true, /*large=*/false);
        // Random x in [1..10^9].
        for(int i = 0; i < n; i++){
            x[i] = rnd.next(1, 1000000000);
        }
    }
    else if (t == "large") {
        // near large numbers
        tie(a, b, c) = genABC(/*tight=*/false, /*large=*/true);
        for(int i = 0; i < n; i++){
            x[i] = rnd.next(1, 1000000000);
        }
    }
    else if (t == "left") {
        // Random b<a<c, place x_i mostly near b
        tie(a, b, c) = genABC(false, false);
        // We'll place many banknotes near b
        // For instance, half of them exactly at b, half random near [b-5..b+5].
        for(int i = 0; i < n; i++){
            if (rnd.next(2) == 0) {
                x[i] = b; // cannot collect if b is guarded, testing corner
            } else {
                long long leftRangeStart = max(1LL, (long long)b - 5);
                long long leftRangeEnd   = min(1000000000LL, (long long)b + 5);
                x[i] = rnd.next((int)leftRangeStart, (int)leftRangeEnd);
            }
        }
    }
    else if (t == "right") {
        // Random b<a<c, place x_i mostly near c
        tie(a, b, c) = genABC(false, false);
        for(int i = 0; i < n; i++){
            if (rnd.next(2) == 0) {
                x[i] = c; // cannot collect if c is guarded
            } else {
                long long rightRangeStart = max(1LL, (long long)c - 5);
                long long rightRangeEnd   = min(1000000000LL, (long long)c + 5);
                x[i] = rnd.next((int)rightRangeStart, (int)rightRangeEnd);
            }
        }
    }
    else if (t == "center") {
        // Random b<a<c, place x_i mostly near a
        tie(a, b, c) = genABC(false, false);
        for(int i = 0; i < n; i++){
            long long centerRangeStart = max(1LL, (long long)a - 5);
            long long centerRangeEnd   = min(1000000000LL, (long long)a + 5);
            x[i] = rnd.next((int)centerRangeStart, (int)centerRangeEnd);
        }
    }
    else if (t == "edges") {
        // Random b<a<c, place many x_i exactly at b or c
        tie(a, b, c) = genABC(false, false);
        for(int i = 0; i < n; i++){
            x[i] = (rnd.next(2) == 0 ? b : c);
        }
    }
    else if (t == "mixed") {
        // Random b<a<c, place some near b, some near a, some near c, some random
        tie(a, b, c) = genABC(false, false);
        for(int i = 0; i < n; i++){
            int choice = rnd.next(4); // 0..3
            if (choice == 0) {
                x[i] = b; 
            } else if (choice == 1) {
                x[i] = c; 
            } else if (choice == 2) {
                // near a
                long long centerRangeStart = max(1LL, (long long)a - 5);
                long long centerRangeEnd   = min(1000000000LL, (long long)a + 5);
                x[i] = rnd.next((int)centerRangeStart, (int)centerRangeEnd);
            } else {
                // random
                x[i] = rnd.next(1, 1000000000);
            }
        }
    }
    else {
        // default to random if unknown type
        tie(a, b, c) = genABC(false, false);
        for(int i = 0; i < n; i++){
            x[i] = rnd.next(1, 1000000000);
        }
    }

    // Now output the data:
    // First line: a, b, c
    // Second line: n
    // Third line: x1..x_n

    // b < a < c
    // In case the generator messed up ordering (it shouldn't), we'll enforce it:
    // But we designed genABC so that b < a < c is guaranteed. Just in case:
    // sort them via a small fix
    // We'll store the original in (A, B, C) then rename them properly:
    // But we used the tie to ensure the order. So no further fix needed.

    // Print
    cout << a << " " << b << " " << c << "\n";
    cout << n << "\n";
    for(int i = 0; i < n; i++){
        cout << x[i];
        if (i + 1 < n) cout << " ";
    }
    cout << "\n";

    return 0;
}

