/*
  We must check that the participant's output is either "Impossible"
  (only acceptable if the jury's solution is also "Impossible"), or
  it is a valid compressed sequence of 'A' and 'B' moves that exactly
  uses up x oranges and y apples from the bag. The rules are:

  1) Initially, the bag has x oranges and y apples. 
  2) Alice starts with (1 orange, 0 apples), Bob with (0 oranges, 1 apple).
     That effectively means we reduce the bag to (x-1, y-1) at the start.
  3) Each move is either 'A' or 'B':
     - If it is 'A': 
         We check if the bag has at least (Alice's oranges, Alice's apples).
         If not, invalid. Otherwise:
            bag -= (aOrange, aApple)
            Bob gains (aOrange, aApple)
         [Alice's own fruit doesn't change]
     - If it is 'B':
         We check if the bag has at least (bOrange, bApple).
         If not, invalid. Otherwise:
            bag -= (bOrange, bApple)
            Alice gains (bOrange, bApple)
         [Bob's own fruit doesn't change]
  4) In the end, the bag must be exactly (0,0).
  5) The compressed format is blocks of the form: <count><letter>, 
     where <count> is a positive integer, and <letter> is 'A' or 'B'. 
     All blocks are concatenated without spaces (e.g. 3A2B10A, etc.).
  6) The entire output string must not exceed 10^6 characters.
  7) If the jury's answer is "Impossible", that means there should be no valid solution;
     a participant solution that claims a valid sequence must cause _fail, 
     since it contradicts the jury's official solution.
  8) If the jury's answer is a valid sequence, then any valid sequence by the participant is accepted,
     "Impossible" by the participant would be wrong.
*/

static const long long MAX_LEN = 1000000; // max length of the compressed string

// We'll parse and check one answer (either jury's or participant's).
// If it is invalid, we call stream.quitf(...) with an appropriate verdict.
// If it is "Impossible", we return true in impossibleFlag, otherwise false.
// If it is a valid sequence that consumes the entire bag, we return false in impossibleFlag.
bool readAndCheckAnswer(InStream &stream, long long x, long long y, bool isJury)
{
    // isJury == true  => if invalid, stream.quitf(_fail, ...)
    // isJury == false => if invalid, stream.quitf(_wa, ...)

    // convenience macro for quitting with the correct verdict
    auto quitBad = [&](const char* format, auto... args) {
        if (isJury) stream.quitf(_fail, format, args...);
        else        stream.quitf(_wa,   format, args...);
    };

    // read the entire solution line
    string ansLine = stream.readLine();

    // Trim possible extra spaces (though typically not expected).
    // But if the line is exactly "Impossible", that's valid in full.
    // We'll do a simple check:
    if(ansLine.size() <= 10) {
        // check if it is exactly "Impossible" (case-sensitive as per statement)
        if(ansLine == "Impossible") {
            // We do not verify correctness of "Impossible" here,
            // the calling logic will compare with the jury's solution
            return true; // means answer says "Impossible"
        }
    }

    // If not "Impossible", we must parse a sequence of <count><letter> blocks.
    // Also verify the total length does not exceed 10^6 characters.
    if((long long)ansLine.size() > MAX_LEN) {
        quitBad("Output exceeds %lld characters", MAX_LEN);
