    if(bagOrange < 0 || bagApple < 0) {
        quitBad("Not enough fruit in the bag even for initial distribution (x=%lld, y=%lld)", x, y);
    }

    // Alice has (1, 0) initially, Bob has (0, 1).
    long long aOrange = 1, aApple = 0;
    long long bOrange = 0, bApple = 1;

    // parse ansLine in form  { <count><letter> }+
