            if(aApple > 0) {
                long long needApple = count * aApple;
                if(needApple > bagApple) {
                    quitBad("Not enough apples in the bag for repeated 'A' moves");
                }
                bagApple -= needApple;
                bApple += needApple;
            }
            // aOrange, aApple remain unchanged
        } else {
            // c == 'B'
            // We need bagOrange >= count * bOrange, bagApple >= count * bApple
            // Then Alice gains (count*bOrange, count*bApple).
            if(bOrange > 0) {
                long long needOrange = count * bOrange;
                if(needOrange > bagOrange) {
                    quitBad("Not enough oranges in the bag for repeated 'B' moves");
                }
                bagOrange -= needOrange;
                aOrange += needOrange;
            }
            if(bApple > 0) {
                long long needApple = count * bApple;
                if(needApple > bagApple) {
                    quitBad("Not enough apples in the bag for repeated 'B' moves");
                }
                bagApple -= needApple;
                aApple += needApple;
            }
            // bOrange, bApple remain unchanged
        }
    }

    // after reading the entire compressed sequence, check if bag is empty
    if(bagOrange != 0 || bagApple != 0) {
        quitBad("After applying all moves, the bag is not fully used up (remaining oranges=%lld, apples=%lld)",
                bagOrange, bagApple);
    }

    // If we are here, it is valid
    return false;  // means not "Impossible"
}

