static int a[MAXN + 1];
static int freq[MAXA + 1];

int main(int argc, char* argv[])
{
    registerTestlibCmd(argc, argv);

    // 1) Read n, k, and the array a[1..n].
    int n = inf.readInt(1, MAXN);
    int k = inf.readInt(1, n);
    for (int i = 1; i <= n; i++) {
        a[i] = inf.readInt(0, MAXA);
    }

    // 2) Compute maxLen for any k-good subarray using a sliding window in O(n).
    std::memset(freq, 0, sizeof(freq));
    int distinct = 0;
    int left = 1;
    long long maxLen = 0;
    for (int right = 1; right <= n; right++) {
        if (freq[a[right]] == 0) {
            distinct++;
        }
        freq[a[right]]++;
        while (distinct > k) {
            freq[a[left]]--;
            if (freq[a[left]] == 0) {
                distinct--;
            }
            left++;
        }
        maxLen = std::max(maxLen, (long long)(right - left + 1));
    }

    // 3) Read the contestant's output (l, r).
    int l = ouf.readInt(1, n);
    int r = ouf.readInt(l, n);

    long long lengthOut = (long long)(r - l + 1);

    // 4) Check length immediately: if != maxLen, no need to scan subarray.
    if (lengthOut < maxLen) {
        ouf.quitf(_wa, "");
    }
    if (lengthOut > maxLen) {
        ouf.quitf(_wa, "");
    }

    // 5) Verify the subarray [l..r] has <= k distinct values.
    std::memset(freq, 0, sizeof(freq));
    distinct = 0;
    for (int i = l; i <= r; i++) {
        if (freq[a[i]] == 0) {
            distinct++;
            if (distinct > k) {
                ouf.quitf(_wa, "");
            }
        }
        freq[a[i]]++;
    }

    // 6) If everything is valid, accept.
    ouf.quitf(_ok, "");
}

