    if (type_ai == "zeros") {
        fill(a.begin(), a.end(), 0);
    } else if (type_ai == "ones") {
        fill(a.begin(), a.end(), 1);
    } else if (type_ai == "max") {
        fill(a.begin(), a.end(), max_ai);
