    // Generate the queries based on 'type_queries'
    vector<pair<int, int>> queries(q);

    if (type_queries == "min") {
        // All queries have l = 1 and x = 0
        for (int i = 0; i < q; ++i)
            queries[i] = make_pair(1, 0);
    } else if (type_queries == "max") {
        // All queries have l = n and x = max_ai
        for (int i = 0; i < q; ++i)
            queries[i] = make_pair(n, max_ai);
    } else if (type_queries == "zeros") {
        // Random l, x = 0
        for (int i = 0; i < q; ++i)
            queries[i] = make_pair(rnd.next(1, n), 0);
    } else if (type_queries == "large_l") {
