#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int m = opt<int>("m", n * (n - 1) / 2);
    string type = opt<string>("type", "random");

    // Ensure m is within valid range
    m = min(m, n * (n - 1) / 2);

    // Generate the true skill order of the robots
    vector<int> order(n);
    for (int i = 0; i < n; ++i) {
        order[i] = i + 1;
    }
    shuffle(order.begin(), order.end());

    vector<pair<int, int>> edges;

    if (type == "unique_early") {
        // The ordering becomes unique early
        // Create a chain of defeats according to the true order
        for (int i = 1; i < n; ++i) {
            edges.push_back({order[i - 1], order[i]});
        }

        // Add extra edges consistent with the true order
        vector<pair<int, int>> extraEdges;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (i + 1 == j) continue; // Skip edges already added
                extraEdges.push_back({order[i], order[j]});
            }
        }
        shuffle(extraEdges.begin(), extraEdges.end());

        int need = m - edges.size();
        for (int i = 0; i < need && i < (int)extraEdges.size(); ++i) {
            edges.push_back(extraEdges[i]);
        }
        shuffle(edges.begin(), edges.end());
    } else if (type == "unique_late") {
        // The ordering becomes unique after many battles
        // Initially, provide minimal information

        // Start with an empty graph
        set<pair<int, int>> edgeSet;

        // We will add edges that avoid forming a total order early
        // Divide robots into groups to delay unique ordering

        int numGroups = 5; // Number of groups to partition the robots
        vector<vector<int>> groups(numGroups);
        for (int i = 0; i < n; ++i) {
            groups[i % numGroups].push_back(order[i]);
        }

        // Within each group, add edges to partially order them
        for (auto& group : groups) {
            for (int i = 0; i < (int)group.size(); ++i) {
                for (int j = i + 1; j < (int)group.size(); ++j) {
                    edgeSet.insert({group[i], group[j]});
                }
            }
        }

        // Add edges between groups at the end to make the ordering unique
        vector<pair<int, int>> interGroupEdges;
        for (int g = 0; g < numGroups - 1; ++g) {
            for (int u : groups[g]) {
                for (int v : groups[g + 1]) {
                    interGroupEdges.push_back({u, v});
                }
            }
        }
        shuffle(interGroupEdges.begin(), interGroupEdges.end());

        // Combine all edges and limit to m edges
        vector<pair<int, int>> allEdges(edgeSet.begin(), edgeSet.end());
        shuffle(allEdges.begin(), allEdges.end());
        allEdges.insert(allEdges.end(), interGroupEdges.begin(), interGroupEdges.end());

        if ((int)allEdges.size() > m) allEdges.resize(m);
        edges = allEdges;
        shuffle(edges.begin(), edges.end());
    } else if (type == "not_unique") {
        // The ordering is not unique even after all battles
        // Create edges that leave multiple possible orderings

        // Create a random DAG without forming a full tournament
        set<pair<int, int>> edgeSet;
        while ((int)edgeSet.size() < m) {
            int u = rnd.next(1, n);
            int v = rnd.next(1, n);
            if (u == v) continue;
            if (edgeSet.count({u, v}) || edgeSet.count({v, u})) continue;
            edgeSet.insert({u, v});
        }
        edges = vector<pair<int, int>>(edgeSet.begin(), edgeSet.end());
        shuffle(edges.begin(), edges.end());
    } else {
        // Random test case with consistent edges
        vector<pair<int, int>> possibleEdges;
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                possibleEdges.push_back({order[i], order[j]});
            }
        }
        shuffle(possibleEdges.begin(), possibleEdges.end());
        if ((int)possibleEdges.size() > m) possibleEdges.resize(m);
        edges = possibleEdges;
        shuffle(edges.begin(), edges.end());
    }

    // Output n and m
    printf("%d %d\n", n, (int)edges.size());

    // Output the rap battles
    for (auto& e : edges) {
        printf("%d %d\n", e.first, e.second);
    }

    return 0;
}

