    if(c == -1){
        cntB++;
    }
    else{
        cntW++;
    }

    bool isOk = true;
    for(int next: E[node]){
        if(color[next] == 0){
            color[next] = -c;
            isOk = (isOk && dfs(next, -c));
        }
        else{
            if(c == color[next]){
                isOk = false;
            }
        }
    }

    return isOk;
}

void solve(int N, int M){
    E = vector<vector<int> >(N);

    int u, v;
    for(int i = 0; i < M; i++){
        cin >> u >> v;
        E[u - 1].push_back(v - 1);
        E[v - 1].push_back(u - 1);
    }

    cntB = 0;
    cntW = 0;
    color = vector<int>(N, 0);

    color[0] = -1;
    bool isOk = dfs(0, -1);

