void generate_random(int n, int m, vector<pair<int,int>>& edges) {
    // Generate a random tree to ensure connectivity
    vector<int> perm(n);
    for(int i = 0; i < n; ++i) perm[i] = i;
    shuffle(perm.begin(), perm.end());

    vector<int> parent(n, -1);
    for(int i = 1; i < n; ++i) {
        parent[perm[i]] = perm[rnd.next(0, i-1)];
        edges.push_back(make_pair(perm[i], parent[perm[i]]));
    }

    // Add extra edges up to m
    set<pair<int,int>> edge_set;
    for(auto e : edges) {
        int u = e.first, v = e.second;
        if(u > v) swap(u, v);
        edge_set.insert(make_pair(u, v));
    }

    int max_edges = n * (n - 1) / 2;
    m = min(m, max_edges);
    while((int)edges.size() < m) {
        int u = rnd.next(0, n-1);
        int v = rnd.next(0, n-1);
        if(u == v) continue;
        if(u > v) swap(u, v);
        if(edge_set.count(make_pair(u, v))) continue;
        edge_set.insert(make_pair(u, v));
        edges.push_back(make_pair(u, v));
    }
}

void generate_complete(int n, vector<pair<int,int>>& edges) {
    // Generate a complete graph
    for(int u = 0; u < n; ++u) {
        for(int v = u + 1; v < n; ++v) {
            edges.push_back(make_pair(u, v));
            if ((int)edges.size() >= 1000) break;
        }
        if ((int)edges.size() >= 1000) break;
    }
}

void generate_bipartite(int n, int m, vector<pair<int,int>>& edges) {
    // Partition the nodes into two sets
    int n1 = n / 2;
    int n2 = n - n1;
    vector<int> left(n1), right(n2);
    for(int i = 0; i < n1; ++i) left[i] = i;
    for(int i = 0; i < n2; ++i) right[i] = n1 + i;
    // Generate edges between left and right sets
    vector<pair<int,int>> possible_edges;
    for(int u : left) {
        for(int v : right) {
            possible_edges.push_back(make_pair(u, v));
        }
    }
    shuffle(possible_edges.begin(), possible_edges.end());
    m = min(m, (int)possible_edges.size());
    for(int i = 0; i < m; ++i) {
        edges.push_back(possible_edges[i]);
    }
    // Ensure connectivity
    if (edges.empty()) {
        edges.push_back(make_pair(left[0], right[0]));
    }
}

void generate_tree(int n, vector<pair<int,int>>& edges) {
    // Generate a random tree
    vector<int> perm(n);
    for(int i = 0; i < n; ++i) perm[i] = i;
    shuffle(perm.begin(), perm.end());
    for(int i = 1; i < n; ++i) {
        int u = perm[i];
        int v = perm[rnd.next(0, i-1)];
        edges.push_back(make_pair(u, v));
    }
}

void generate_zero_case(int n, vector<pair<int,int>>& edges) {
    // Generate a graph where the answer should be zero
    // For example, a complete graph of small size
    for(int u = 0; u < n; ++u) {
        for(int v = u + 1; v < n; ++v) {
            edges.push_back(make_pair(u, v));
            if ((int)edges.size() >= min(1000, n*(n-1)/2)) break;
        }
        if ((int)edges.size() >= min(1000, n*(n-1)/2)) break;
    }
}

