#include <bits/stdc++.h>
using namespace std;
long long int power(long long int x, long long int y, long long int p) {
  long long int res = 1;
  x = x % p;
  while (y > 0) {
    if (y & 1) res = (res * x) % p;
    y = y >> 1;
    x = (x * x) % p;
  }
  return res;
}
int main() {
  long long int n, m;
  cin >> n >> m;
  long long int a = power(2, n, 1000000007);
  a--;
  if (n == 1) a = n + 1;
  long long int ans = power(a, m, 1000000007);
  if (n == 1) ans--;
  if (m == 1) ans = n;
  cout << ans % 1000000007;
  return 0;
}

