    string type = opt<string>("type", "random");

    const long long MAX_TOTAL_N = 200000; // Total sum of 'n' over all test cases should not exceed 2e5
    vector<int> ns; // Stores 'n' for each test case
    long long total_n = 0;

    for (int i = 0; i < t; i++) {
        int n;
        if (n_fixed != -1) {
            n = n_fixed;
        } else {
            // If 'n' is not fixed, distribute remaining allowed 'n' among remaining test cases
            long long remaining_n = MAX_TOTAL_N - total_n;
            int remaining_t = t - i;
            int max_n = min(200000, (int)(remaining_n - (remaining_t - 1) * 2));
            n = rnd.next(2, max_n);
        }
        total_n += n;
        ns.push_back(n);
    }

    // Output 't'
    printf("%d\n", t);

    for (int testCase = 0; testCase < t; testCase++) {
        int n = ns[testCase];

        // Generate tree according to 'type'
        vector<vector<int>> tree(n + 1); // Nodes are numbered from 1 to n

        if (type == "path") {
            // Create a path from 1 to n
            for (int i = 2; i <= n; i++) {
                tree[i - 1].push_back(i);
            }
        } else if (type == "star") {
            // Connect all nodes to the root
            for (int i = 2; i <= n; i++) {
                tree[1].push_back(i);
            }
        } else if (type == "balanced") {
            // Create a balanced binary tree
            for (int i = 2; i <= n; i++) {
                int parent = i / 2;
                tree[parent].push_back(i);
            }
        } else if (type == "skewed") {
            // Create a skewed tree (linear chain)
            for (int i = 2; i <= n; i++) {
                tree[i - 1].push_back(i);
            }
        } else {
            // Generate a random tree
            for (int i = 2; i <= n; i++) {
                int parent = rnd.next(1, i - 1);
                tree[parent].push_back(i);
            }
        }

        // For each node, sort its children in ascending order
        for (int i = 1; i <= n; i++) {
            sort(tree[i].begin(), tree[i].end());
        }

        // Perform BFS and record the visiting order 'a'
        vector<int> a;
        queue<int> q;
        q.push(1);
        while (!q.empty()) {
            int k = q.front(); q.pop();
            a.push_back(k);
            for (int y : tree[k]) {
                q.push(y);
            }
        }

        // Output 'n'
        printf("%d\n", n);
        // Output sequence 'a'
        for (int i = 0; i < n; i++) {
            printf("%d%c", a[i], i + 1 < n ? ' ' : '\n');
        }
    }

    return 0;
}

