int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    long long nmax = opt<long long>("nmax");
    string type = opt<string>("type", "random");

    long long n, k, p, e;

    // Compute maximum possible p such that p*(p+1)/2 ≤ 1e9
    double D = sqrt(1.0 + 8.0 * 1e9);
    long long p_max = (long long)( (-1.0 + D) / 2.0 );
    p_max = min(p_max, nmax); // p cannot exceed nmax

    if (type == "random") {
        while (true) {
            p = rnd.next(1LL, p_max);
            e = rnd.next(0LL, nmax - p);
            n = p + e;

            if (n < 1 || n > nmax) continue;

            k = p * (p + 1) / 2 - e;

            if (k < 0 || k > (long long)1e9) continue;

            break;
        }
    } else if (type == "p_min") {
        // p = 1
        p = 1;
        e = rnd.next(0LL, nmax - p);
        n = p + e;
        if (n < 1 || n > nmax) return 0;
        k = p * (p + 1) / 2 - e;
        if (k < 0 || k > (long long)1e9) return 0;
    } else if (type == "k_zero") {
        // Generate cases where k = 0
        while (true) {
            p = rnd.next(1LL, p_max);
            e = p * (p + 1) / 2; // So k = 0
            n = p + e;
            if (n > nmax || n < 1) continue;
            if (n < 1 || n > nmax) continue;
            k = 0;
            break;
        }
    } else if (type == "k_max") {
        // k as close as possible to 1e9
        p = p_max;
        e = 0;
        n = p + e;
        k = p * (p + 1) / 2 - e;
    } else if (type == "n_max") {
        // n = nmax
        while (true) {
            p = rnd.next(1LL, min(p_max, nmax));
            e = nmax - p;
            n = p + e;
            if (n != nmax) continue;
            k = p * (p + 1) / 2 - e;
            if (k < 0 || k > (long long)1e9) continue;
            break;
        }
    } else {
        // Default: random
        while (true) {
            p = rnd.next(1LL, p_max);
            e = rnd.next(0LL, nmax - p);
            n = p + e;

            if (n < 1 || n > nmax) continue;

            k = p * (p + 1) / 2 - e;

            if (k < 0 || k > (long long)1e9) continue;

            break;
        }
    }

    printf("%lld %lld\n", n, k);
    return 0;
}

