#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
   Because the problem explicitly states "If the first player wins, print ANY winning first move",
   there can be multiple correct answers for a single input. Hence we need a CUSTOM checker
   (rather than a built-in checker) to verify the contestant's output.

   We will implement a recursive "isWinning(n)" function under the problem's rules:

   - "If you CANNOT move from n, you immediately WIN."
   - A move from n consists of choosing a NON-TRIVIAL divisor d of n
     (i.e., 1 < d < n, and n % d == 0).
   - If from n you can move to some d for which isWinning(d) == false, then isWinning(n) == true.
   - Otherwise isWinning(n) == false.

   Equivalently:
   1) If n has no non-trivial divisors (that means n == 1 or n is prime), then isWinning(n) = true.
   2) If n is composite, isWinning(n) = true if there exists at least one non-trivial divisor d
      such that isWinning(d) = false; if all non-trivial divisors lead to positions with isWinning(...) = true,
      then isWinning(n) = false.

   The output format is:
     - First line: 1 or 2 (the winning player)
     - If the first line is "1", then the checker expects a second line with one integer x.
       * If x == 0, that declares that the first player makes no move because none exists.
       * If x != 0, that must be a valid non-trivial divisor of q, and must force the second
         player into a losing position (i.e., isWinning(x) = false).

   We will:
     1) Read q from the input file (inf).
     2) Read the contestant's answer: winner in {1,2}. If winner=1, read the integer x (which could be 0).
     3) Compute isWinning(q).
     4) Check correctness:
        - If winner=2, we verify isWinning(q) == false.
        - If winner=1:
          a) If x=0, we must verify q has NO non-trivial divisor (i.e. q is prime or 1),
             and also isWinning(q) == true.
          b) If x != 0, check 1 < x < q, q % x == 0, and isWinning(x) == false,
             and also isWinning(q) == true.
     5) If any check fails, we quitf(_wa, ...). Otherwise quitf(_ok, ...).
*/

static const long long MAXQ = 10000000000000LL; // 1e13 as per statement constraints

// We'll cache the isWinning(...) results for all encountered positions.
static unordered_map<long long, bool> memo;

// To speed up divisor generation, we need prime factorization. We'll do a simple
// trial division up to 10^6+ for q <= 10^13, which is borderline but should be feasible for a single test.

static vector<pair<long long,int>> primeFactorize(long long n) {
    // Returns vector of (prime, exponent) in ascending order
    // We'll do trial division up to sqrt(n).
    vector<pair<long long,int>> result;
    // Check small primes up to 1e6+ (since sqrt(1e13) ~ 1e6.5)
    for (long long p = 2; p * p <= n; p++) {
        if (n % p == 0) {
            int countp = 0;
            while (n % p == 0) {
                n /= p;
                countp++;
            }
            result.push_back({p, countp});
        }
    }
    if (n > 1) {
        // whatever remains is prime
        result.push_back({n, 1});
    }
    return result;
}

// Generate *all* divisors of n (including 1 and n) from its prime factorization.
static void genDivisors(
    const vector<pair<long long,int>> &factors,
    int idx,
    long long current,
    vector<long long> &divs
) {
    if (idx == (int)factors.size()) {
        divs.push_back(current);
        return;
    }
    auto [prime, exponent] = factors[idx];
    for (int e = 0; e <= exponent; e++) {
        genDivisors(factors, idx + 1, current, divs);
        current *= prime;
    }
}

// Compute isWinning(n) using the rules described.
// We store the result in memo to avoid re-computation.
bool isWinning(long long n) {
    // If already computed, return.
    auto it = memo.find(n);
    if (it != memo.end()) {
        return it->second;
    }
    // If n is prime or n == 1 => no non-trivial divisors => current player wins => isWinning(n) = true.
    // We'll do a quick factor check.
    // First handle n=1 quickly:
    if (n == 1) {
        memo[n] = true;
        return true;
    }
    // Factor n:
    // If n is prime => isWinning(n) = true.
    // Otherwise, we try its non-trivial divisors.
    vector<pair<long long,int>> pf = primeFactorize(n);
    if (pf.size() == 1 && pf[0].second == 1 && pf[0].first == n) {
        // n is prime
        memo[n] = true;
        return true;
    }

    // n is composite. Generate all divisors, remove 1 and n, check if any lead to losing position.
    vector<long long> divs;
    genDivisors(pf, 0, 1LL, divs);
    // sort(divs.begin(), divs.end());  // not strictly necessary to sort
    // remove trivial divisors 1 and n
    bool foundAny = false;
    for (long long d : divs) {
        if (d == 1 || d == n) continue;
        foundAny = true;
        // if we find a divisor d s.t. isWinning(d) = false => isWinning(n) = true
        if (!isWinning(d)) {
            memo[n] = true;
            return true;
        }
    }
    // If found no non-trivial divisors, isWinning(n) = true, 
    // else if all non-trivial divisors lead to isWinning(...) = true, then isWinning(n) = false.
    if (!foundAny) {
        // means no non-trivial divisors at all
        memo[n] = true;
    } else {
        memo[n] = false;
    }
    return memo[n];
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    // Read q
    long long q = inf.readLong(1, MAXQ, "q");

    // The contestant's output:
    int winner = ouf.readInt(1, 2, "winner");
    long long firstMove = -1; // only relevant if winner==1
    if (winner == 1) {
        // expect a second line
        // It can be 0 or a positive integer up to q-1
        firstMove = ouf.readLong(0, q-1, "firstMove");
    } else {
        // if winner==2, we do not read a second line
    }

    // Let's check correctness
    bool wq = isWinning(q); // whether q is a winning position for the first player

    if (winner == 2) {
        // The output claims the second player eventually wins.
        // That means the first player is in a losing position with q => wq must be false.
        if (wq) {
            quitf(_wa, "Contestant claims second player wins, but position is winning for the first player.");
        }
        // If wq==false, that is consistent
        quitf(_ok, "Correct: second player wins from q = %lld", q);
    } else {
        // winner == 1
        // The output claims the first player wins => wq must be true.
        if (!wq) {
            quitf(_wa, "Contestant claims first player wins, but position is losing for the first player.");
        }
        // Now check the declared first move
        // If firstMove == 0 => that means the first player cannot move, so q should have no non-trivial divisors.
        // Also that is consistent only if indeed q is winning in that scenario (which it is if no move is possible).
        if (firstMove == 0) {
            // check that q has no non-trivial divisors. That means q==1 or prime
            // we can re-check: if isWinning(q) = true because no moves, is that consistent with prime or 1?
            // We already know isWinning(q)=true. Now let's see if indeed q has no non-trivial divisors.
            // We can do a quick check if q is prime or 1. We'll do the factor check again.
            vector<pair<long long,int>> pf = primeFactorize(q);
            if (!(pf.size() == 1 && pf[0].second == 1 && pf[0].first == q) && q != 1) {
                // Not prime and not 1 => it does have a non-trivial divisor
                quitf(_wa, "firstMove=0 but q=%lld is not prime nor 1 (so a move existed).", q);
            }
            // Otherwise all good
            quitf(_ok, "Correct: first player wins immediately with no move (q=%lld prime or 1).", q);
        } else {
            // If firstMove != 0 => must be a valid non-trivial divisor of q that leads the second player to a losing position.
            // 1 < firstMove < q and q % firstMove == 0, and isWinning(firstMove) == false
            if (firstMove <= 1 || firstMove >= q) {
                quitf(_wa, "Invalid firstMove=%lld, it must be in (1, q).", firstMove);
            }
            if (q % firstMove != 0) {
                quitf(_wa, "firstMove=%lld is not a divisor of q=%lld.", firstMove, q);
            }
            // Check if isWinning(firstMove) == false
            if (isWinning(firstMove)) {
                quitf(_wa, "Contestant's chosen first move %lld does not lead the second player to a losing position.",
                      firstMove);
            }
            // If all is good:
            quitf(_ok, "Correct: first player wins and a valid winning first move = %lld", firstMove);
        }
    }
    // Should never reach here
    quitf(_fail, "Checker logic error (unexpected path).");
    return 0;
}

