        grid[H - 1][W - 1] = '.';

    } else if (type == "snake") {
        /* Generate a snake-like path */
        grid = vector<string>(H, string(W, '#'));
        int x = 0, y = 0;
        grid[x][y] = '.';
        int dir = 0; // 0: right, 1: down, 2: left, 3: up
        int len = H * W;
        int dx[4] = { 0, 1, 0, -1 };
