    if (type == "chain") {
        // Generate a chain graph
        for(int i = 0; i < n - 1; ++i) {
            S[i][i + 1] = S[i + 1][i] = '1';
        }
    } else if (type == "cycle_even" || type == "cycle_odd") {
        // Generate a cycle graph
        for(int i = 0; i < n - 1; ++i) {
            S[i][i + 1] = S[i + 1][i] = '1';
        }
        S[n - 1][0] = S[0][n - 1] = '1';
    } else if (type == "star") {
        // Generate a star graph
        for(int i = 1; i < n; ++i) {
            S[0][i] = S[i][0] = '1';
        }
    } else if (type == "complete") {
        // Generate a complete graph
        for(int i = 0; i < n; ++i) {
            for(int j = i + 1; j < n; ++j) {
                S[i][j] = S[j][i] = '1';
            }
        }
    } else if (type == "bipartite") {
        // Generate a bipartite graph
        int half = n / 2;
        vector<int> A, B;
        for (int i = 0; i < n; ++i) {
            if (i < half)
                A.push_back(i);
            else
                B.push_back(i);
        }
        for (int u : A) {
            for (int v : B) {
                S[u][v] = S[v][u] = '1';
            }
        }
    } else if (type == "tree") {
        // Generate a random tree using Prüfer code
        vector<int> prufer_code(n - 2);
        for (int i = 0; i < n - 2; ++i) {
            prufer_code[i] = rnd.next(0, n - 1);
        }
        vector<int> degree(n, 1);
        for (int i = 0; i < n - 2; ++i) {
            ++degree[prufer_code[i]];
        }
        set<int> leaves;
        for (int i = 0; i < n; ++i) {
            if (degree[i] == 1) {
                leaves.insert(i);
            }
        }
        for (int i = 0; i < n - 2; ++i) {
            int leaf = *leaves.begin();
            leaves.erase(leaves.begin());
            int v = prufer_code[i];

            S[leaf][v] = S[v][leaf] = '1';

            if (--degree[v] == 1) {
                leaves.insert(v);
            }
        }
        // Connect the last two nodes
        auto it = leaves.begin();
        int u = *it;
        ++it;
        int v = *it;
        S[u][v] = S[v][u] = '1';
    } else if (type == "random") {
        // Generate a random connected graph
        // Start with a random spanning tree
        for (int i = 1; i < n; ++i) {
            int p = rnd.next(0, i - 1);
            S[i][p] = S[p][i] = '1';
        }

        // Add random extra edges
        int max_edges = n * (n - 1) / 2;
        int extra_edges = rnd.next(0, max_edges - (n - 1));
        set<pair<int, int>> edges;
        // Add existing tree edges
        for (int i = 0; i < n; ++i) {
            for (int j = i + 1; j < n; ++j) {
                if (S[i][j] == '1') {
                    edges.insert({i, j});
                }
            }
        }
        // Add extra edges
        while ((int)edges.size() < extra_edges + n - 1) {
            int u = rnd.next(0, n - 1);
            int v = rnd.next(0, n - 1);
            if (u != v && edges.count({min(u, v), max(u, v)}) == 0) {
                edges.insert({min(u, v), max(u, v)});
                S[u][v] = S[v][u] = '1';
            }
        }
    } else {
        fprintf(stderr, "Unknown type '%s'\n", type.c_str());
        return 1;
    }

    // Output N
    printf("%d\n", n);
    // Output the adjacency matrix S
    for(int i = 0; i < n; ++i) {
        for(int j = 0; j < n; ++j) {
            putchar(S[i][j]);
        }
        putchar('\n');
    }

    return 0;
}

