#include<cstdio>
#include<cstdlib>
using namespace std;
const int inf=1e9;
int n,sl,fh,ans,col[210],dis[210][210];
int rd()
{
	sl=0;fh=1;
	int ch=getchar();
	while(ch<'0'||'9'<ch) {if(ch=='-') fh=-1; ch=getchar();}
	while('0'<=ch&&ch<='9') sl=sl*10+ch-'0',ch=getchar();
	return sl*fh;
}
void dfs(int u,int c)
{
	col[u]=c;
	for(int i=1;i<=n;++i)
		if(dis[u][i]<inf)
		{
			if(!~col[i]) { dfs(i,c^1); }
			else if(col[i]==col[u]) { puts("-1"); exit(0); }
		}
}
int main()
{
	n=rd();
	for(int i=1;i<=n;++i) { col[i]=-1; }
	for(int i=1;i<=n;++i)
		for(int j=1;j<=n;++j)
		{
			int val;
			scanf("%1d",&val);
			dis[i][j] = val ? 1 : inf;
		}
	dfs(1,0);
	for(int k=1;k<=n;++k) 
		for(int i=1;i<=n;++i)
			if(i!=k)
				for(int j=1;j<=n;++j)
					if(i!=j&&j!=k)
						{ dis[i][j]=min(dis[i][j],dis[i][k]+dis[k][j]); }
	for(int i=1;i<=n;++i)
		for(int j=1;j<=n;++j)
			if(dis[i][j]<inf)
				{ ans=max(ans,dis[i][j]); }
