  cin >> N >> D;
  for (int i = 0; i < N; i++)
    for (int j = 0; j < D; j++) cin >> cost[j][i];
  pair<int, int> dp[55][55];
  for (int i = 0; i < 55; i++)
    for (int j = 0; j < 55; j++) dp[i][j].first = dp[i][j].second = (1 << 29);
  for (int j = 0; j < N; j++) dp[0][j] = pair<int, int>(cost[0][j], 0);
  for (int i = 1; i < D; i++) {
    for (int j = 0; j < N; j++) {
      for (int k = 0; k < N; k++) {
        pair<int, int> next = dp[i - 1][k];
        next.first += cost[i][j];
        if (j != k) next.second += 1;
        dp[i][j] = min(dp[i][j], next);
      }
    }
  }
  pair<int, int> ans;
  ans.first = ans.second = (1 << 29);
  for (int j = 0; j < N; j++) ans = min(ans, dp[D - 1][j]);
