        for (int i = 0; i < N; ++i)
            for (int j = 0; j < D; ++j)
                prices[i][j] = rnd.next(1, 10000);
    }
    else if (type == "constant")
    {
        int val = rnd.next(1, 10000);
        for (int i = 0; i < N; ++i)
            for (int j = 0; j < D; ++j)
                prices[i][j] = val;
    }
    else if (type == "one_cheap_hotel")
    {
        int cheap_hotel = rnd.next(0, N - 1);
        for (int i = 0; i < N; ++i)
        {
            int base_price = rnd.next(5000, 10000);
            for (int j = 0; j < D; ++j)
                prices[i][j] = base_price + rnd.next(-1000, 1000);
        }
        for (int j = 0; j < D; ++j)
            prices[cheap_hotel][j] = rnd.next(1, 1000);
    }
    else if (type == "alternating_cheapest")
    {
        for (int i = 0; i < N; ++i)
            for (int j = 0; j < D; ++j)
                prices[i][j] = rnd.next(3000, 10000);

        for (int j = 0; j < D; ++j)
        {
            int hotel = j % N;
            prices[hotel][j] = rnd.next(1000, 2000);
        }
    }
    else if (type == "maximal_changes")
    {
        for (int i = 0; i < N; ++i)
            for (int j = 0; j < D; ++j)
                prices[i][j] = rnd.next(5000, 10000);

        for (int j = 0; j < D; ++j)
        {
            int hotel = j % N;
            prices[hotel][j] = rnd.next(1000, 2000);
        }
    }
    else if (type == "minimal_changes")
    {
        int cheap_hotel = rnd.next(0, N - 1);
        for (int i = 0; i < N; ++i)
        {
            int base_price = i == cheap_hotel ? rnd.next(1000, 2000) : rnd.next(5000, 10000);
            for (int j = 0; j < D; ++j)
                prices[i][j] = base_price + rnd.next(-500, 500);
        }
    }
    else if (type == "tie_breaker_lex")
    {
        for (int i = 0; i < N; ++i)
            for (int j = 0; j < D; ++j)
                prices[i][j] = rnd.next(5000, 10000);

        for (int j = 0; j < D; ++j)
        {
            int min_price = rnd.next(1000, 2000);
            prices[0][j] = min_price;
            prices[1][j] = min_price;
        }
    }
    else
    {
        // Default to random
        for (int i = 0; i < N; ++i)
            for (int j = 0; j < D; ++j)
                prices[i][j] = rnd.next(1, 10000);
    }

    // Output the data
    printf("%d %d\n", N, D);
    for (int i = 0; i < N; ++i)
    {
        for (int j = 0; j < D; ++j)
        {
            printf("%d", prices[i][j]);
            if (j + 1 < D)
                printf(" ");
        }
        printf("\n");
    }

    return 0;
}

