    // Initialize the wall grid
    vector<string> grid(R, string(C, '.'));

    if (type == "one-segment") {
        // All columns are non-empty
        for (int c = 0; c < C; ++c) {
            int h = rnd.next(1, R); // Height of column c
            for (int r = 0; r < h; ++r) {
                grid[R - r - 1][c] = 'B';
            }
        }
    } else if (type == "max-segments") {
        // Alternate empty and non-empty columns
        for (int c = 0; c < C; ++c) {
            if (c % 2 == 0) {
                // non-empty column
                int h = rnd.next(1, R);
                for (int r = 0; r < h; ++r) {
                    grid[R - r - 1][c] = 'B';
                }
            }
            // else empty column
        }
    } else if (type == "random") {
        for (int c = 0; c < C; ++c) {
            if (rnd.next(0, 1)) {
                // decide whether this column is non-empty
                int h = rnd.next(1, R);
                for (int r = 0; r < h; ++r) {
                    grid[R - r - 1][c] = 'B';
                }
            }
        }
    } else if (type == "specified-segments") {
        // We need to create 'segments' number of segments
        segments = max(1, min(segments, C));
        // First, decide how many non-empty columns we will have
        int min_non_empty_columns = segments;
        int max_non_empty_columns = C - (segments - 1);
        int non_empty_columns = rnd.next(min_non_empty_columns, C);

        // Distribute non-empty columns among segments
        vector<int> segment_lengths(segments, 1); // At least one non-empty column per segment
        int remaining_columns = non_empty_columns - segments;
        for (int i = 0; i < remaining_columns; ++i) {
            int idx = rnd.next(0, segments - 1);
            segment_lengths[idx]++;
        }

        // Now, create empty columns between segments
        int total_empty_columns = C - non_empty_columns;
        vector<int> extra_empty_lengths(segments + 1, 0);
        for (int i = 0; i < total_empty_columns; ++i) {
            int idx = rnd.next(0, segments); // There are segments + 1 gaps
            extra_empty_lengths[idx]++;
        }

        // Build the grid
        int c = 0;
        for (int i = 0; i < segments; ++i) {
            // Empty columns before segment
            for (int e = 0; e < extra_empty_lengths[i]; ++e) {
                c++;
            }
            // Non-empty columns in segment
            for (int s = 0; s < segment_lengths[i]; ++s) {
                int h = rnd.next(1, R);
                for (int r = 0; r < h; ++r) {
                    grid[R - r - 1][c] = 'B';
                }
                c++;
            }
        }
        // Empty columns after last segment
        for (int e = 0; e < extra_empty_lengths[segments]; ++e) {
            c++;
        }
    }

    // Ensure there's at least one 'B' in the grid
    bool hasB = false;
    for (int r = 0; r < R; ++r)
        for (int c = 0; c < C; ++c)
            if (grid[r][c] == 'B')
                hasB = true;
    if (!hasB) {
        // Place a 'B' randomly
        int r = rnd.next(0, R - 1);
        int c = rnd.next(0, C - 1);
        grid[r][c] = 'B';
    }

    // Output the grid
    printf("%d %d\n", R, C);
    for (int r = 0; r < R; ++r) {
        printf("%s\n", grid[r].c_str());
    }
    return 0;
}

