using namespace std;

char random_letter() {
    int x = rnd.next(52); // 26 uppercase + 26 lowercase letters
    if (x < 26) return 'A' + x;
    else return 'a' + x - 26;
}

void generateBalancedSimple(string& s, int len) {
    // Generate a balanced string with simple structure
    while (s.length() < len - 1) {
        int choice = rnd.next(3); // 0: add letter, 1: add space, 2: add brackets
        if (choice == 0) {
            char c = random_letter();
            s += c;
        } else if (choice == 1) {
            s += ' ';
        } else {
            // Add a pair of brackets with random content inside
            if (s.length() + 2 > len - 1) break;
            char left, right;
            if (rnd.next(2) == 0) {
                left = '('; right = ')';
            } else {
                left = '['; right = ']';
            }
            string content;
            // Decide content inside brackets
            int content_choice = rnd.next(3);
            if (content_choice == 0) {
                content = ""; // empty
            } else if (content_choice == 1) {
                content = string(1, random_letter());
            } else {
                content = " ";
            }
            if (s.length() + content.length() + 2 > len - 1) break;
            s += left + content + right;
        }
    }
}

void generateBalancedNested(string& s, int len, int depth) {
    if (s.length() >= len - 1 || depth <= 0) return;

    char left, right;
    if (rnd.next(2) == 0) {
        left = '('; right = ')';
    } else {
        left = '['; right = ']';
    }

    if (s.length() + 1 >= len - 1) return;
    s += left;

    // Optionally insert letters or spaces
    int choice = rnd.next(3);
    if (choice == 0) {
        // Insert letters
        int letters = rnd.next(1, min(5, len - (int)s.length() - depth * 2));
        for (int i = 0; i < letters; ++i) {
            if (s.length() >= len - 1) break;
            s += random_letter();
        }
    } else if (choice == 1) {
        if (s.length() >= len - 1) return;
        s += ' ';
    } else {
        // Recurse to add more nested brackets
        generateBalancedNested(s, len, depth - 1);
    }

    if (s.length() + 1 >= len - 1) return;
    s += right;
}

void generateUnbalancedMismatch(string& s, int len) {
    // Generate strings with mismatched brackets
    while (s.length() < len - 1) {
        int choice = rnd.next(4); // 0: letter, 1: space, 2: correct brackets, 3: mismatched brackets
        if (choice == 0) {
            s += random_letter();
        } else if (choice == 1) {
            s += ' ';
        } else if (choice == 2) {
            // Correct matching brackets
            if (s.length() + 2 > len - 1) break;
            char left, right;
            if (rnd.next(2) == 0) {
                left = '('; right = ')';
            } else {
                left = '['; right = ']';
            }
            s += left;
            s += right;
        } else {
            // Mismatched brackets
            if (s.length() + 2 > len - 1) break;
            char left, right;
            if (rnd.next(2) == 0) {
                left = '('; right = ']';
            } else {
                left = '['; right = ')';
            }
            s += left;
            s += right;
        }
    }
}

void generateUnbalancedUnmatched(string& s, int len) {
    // Generate strings with unmatched brackets
    while (s.length() < len - 1) {
        int choice = rnd.next(4); // 0: letter, 1: space, 2: opening bracket, 3: closing bracket
        if (choice == 0) {
            s += random_letter();
        } else if (choice == 1) {
            s += ' ';
        } else if (choice == 2) {
            // Opening bracket
            if (s.length() + 1 > len - 1) break;
            char left = (rnd.next(2) == 0) ? '(' : '[';
            s += left;
        } else {
            // Closing bracket
            if (s.length() + 1 > len - 1) break;
            char right = (rnd.next(2) == 0) ? ')' : ']';
            s += right;
        }
    }
}

void generateRandom(string& s, int len) {
    // Generate random datasets
    while (s.length() < len - 1) {
        int choice = rnd.next(6); // 0: letter, 1: space, 2-5: brackets
        if (choice == 0) {
            s += random_letter();
        } else if (choice == 1) {
            s += ' ';
        } else {
            char c = "()[]"[choice - 2];
            if (s.length() + 1 > len - 1) break;
            s += c;
        }
    }
}

void generateOnlyBrackets(string& s, int len) {
    // Generate strings with only brackets and spaces
    while (s.length() < len - 1) {
        int choice = rnd.next(5); // 0: space, 1-4: brackets
        if (choice == 0) {
            s += ' ';
        } else {
            char c = "()[]"[choice - 1];
            if (s.length() + 1 > len - 1) break;
            s += c;
        }
    }
}

void generateNoBrackets(string& s, int len) {
    // Generate strings with letters and spaces only
    while (s.length() < len - 1) {
        int choice = rnd.next(2); // 0: letter, 1: space
        if (choice == 0) {
            s += random_letter();
        } else {
            s += ' ';
        }
    }
}

int main(int argc, char* argv[]) {

    registerGen(argc, argv, 1);

    int n = opt<int>("n",10); // Number of datasets
    string type = opt<string>("type", "random");
    int len = opt<int>("len",100); // Maximum length of each line (<=100)

    if (len > 100) len = 100;

    for (int i = 0; i < n; ++i) {
        string s;
        if (type == "balanced_simple") {
            generateBalancedSimple(s, len);
        } else if (type == "balanced_nested") {
            int depth = rnd.next(1, 10);
            generateBalancedNested(s, len, depth);
        } else if (type == "unbalanced_mismatch") {
            generateUnbalancedMismatch(s, len);
        } else if (type == "unbalanced_unmatched") {
            generateUnbalancedUnmatched(s, len);
        } else if (type == "random") {
            generateRandom(s, len);
        } else if (type == "empty") {
            // Leave s empty
        } else if (type == "only_brackets") {
            generateOnlyBrackets(s, len);
        } else if (type == "no_brackets") {
            generateNoBrackets(s, len);
        } else {
            // Default to random
            generateRandom(s, len);
        }
        // Ensure the string does not exceed the length limit
        if (s.length() > len - 1) {
            s = s.substr(0, len - 1);
        }
        // Append the terminating period
        s += '.';
        cout << s << endl;
    }

    // Output the line with only a period to terminate input
    cout << "." << endl;

    return 0;
}

