    vector<int> cards = inf.readInts(n);   // values on the cards

    // We expect the contestant to print exactly n/2 pairs.
    int numberOfPairs = n / 2;
    vector<bool> used(n, false);

    // We'll track the sum that each pair should match.
    // After reading the first pair, we fix the targetSum.
    int targetSum = -1;

    // Read n/2 pairs from the contestant's output.
    for (int i = 0; i < numberOfPairs; i++) {
        // Each pair contains two card indices in [1..n].
        int c1 = ouf.readInt(1, n, "card index in pair"); 
        int c2 = ouf.readInt(1, n, "card index in pair"); 

        // Check each index wasn't used before.
        if (used[c1 - 1]) 
            quitf(_wa, "Card %d is used more than once", c1);
        if (used[c2 - 1]) 
            quitf(_wa, "Card %d is used more than once", c2);

        used[c1 - 1] = true;
        used[c2 - 1] = true;

        // Compute the sum of values of these two cards.
        int currentSum = cards[c1 - 1] + cards[c2 - 1];

        // If it's the first pair, set the targetSum, otherwise compare.
        if (targetSum < 0) {
            targetSum = currentSum;
        } else {
            if (currentSum != targetSum) {
                quitf(_wa, "All pairs must have the same sum; expected %d, found %d", targetSum, currentSum);
            }
        }
    }

    // Verify that all cards have been used exactly once.
    for (int i = 0; i < n; i++) {
        if (!used[i]) {
            quitf(_wa, "Card %d was never used", i + 1);
        }
    }

    // If we reach this point, the contestant's output is correct.
    quitf(_ok, "All pairs have sum = %d", targetSum);
}

