    inf.readEoln();

    vector<vector<int>> adj(V);
    set<pair<int, int>> edgeSet;

    for (int i = 0; i < E; ++i) {
        int si = inf.readInt(0, V - 1, "si");
        inf.readSpace();
        int ti = inf.readInt(0, V - 1, "ti");
        inf.readEoln();

        ensuref(si != ti, "No self-loops allowed (edge %d): si == ti == %d", i + 1, si);

        int u = min(si, ti);
        int v = max(si, ti);
        pair<int, int> edge = make_pair(u, v);

        ensuref(edgeSet.find(edge) == edgeSet.end(),
                "Parallel edge detected between %d and %d at edge %d", si, ti, i + 1);
        edgeSet.insert(edge);

        adj[si].push_back(ti);
        adj[ti].push_back(si);
    }

    // Check that the graph is connected
    vector<bool> visited(V, false);
    queue<int> q;
    q.push(0);
    visited[0] = true;
    int visitedCount = 1;

    while (!q.empty()) {
        int u = q.front();
        q.pop();
        for (int v : adj[u]) {
            if (!visited[v]) {
                visited[v] = true;
                visitedCount++;
                q.push(v);
            }
        }
    }

    ensuref(visitedCount == V,
            "Graph is not connected: only %d out of %d vertices are reachable", visitedCount, V);

    inf.readEof();
    return 0;
}

