        for (int i = 0; i < n; ++i) {
            s[i] = 1;
        }
    } else if (type == "alternating") {
        // Sizes alternate between 1 and 1,000,000
        for (int i = 0; i < n; ++i) {
            s[i] = (i % 2 == 0) ? 1 : 1000000;
        }
    } else if (type == "cannot_pair") {
        // Largest cowbells cannot be paired
        int singles = n - k;
        for (int i = 0; i < singles; ++i) {
