        // Generate array of curr_n entries, each with 5 bits (integers 0 or 1), with at least one 1.

        vector<vector<int>> availability(curr_n, vector<int>(5));

        if (type == "all_available") {
            // All students have availability [1,1,1,1,1]
            for (int i = 0; i < curr_n; ++i) {
                for (int j = 0; j <5; ++j)
                    availability[i][j] = 1;
            }
        } else if (type == "only_one_day") {
            // All students are only available on one day, e.g., day 1
            for (int i = 0; i < curr_n; ++i) {
                for (int j = 0; j <5; ++j)
                    availability[i][j] = 0;
                availability[i][0] = 1; // Only available on day 1
            }
        } else if (type == "alternating") {
            // Students' availability alternates.
            // Students with even index are available on days 1,3,5
            // Students with odd index are available on days 2,4
            for (int i = 0; i < curr_n; ++i) {
                if (i % 2 == 0) {
                    availability[i] = {1,0,1,0,1};
                } else {
