void generate_identical(int n, vector<int>& A, vector<int>& B) {
    A.resize(n);
    B.resize(n);

    for(int i = 0; i < n; ++i) {
        int val = rnd.next(0, 1000);
        A[i] = B[i] = val;
    }
}

void generate_identical_b_longer(int n, vector<int>& A, vector<int>& B) {
    int extraLength = rnd.next(1, 1000 - n);
    int m = n + extraLength;

    A.resize(n);
    B.resize(m);

    for(int i = 0; i < n; ++i) {
        int val = rnd.next(0, 1000);
        A[i] = B[i] = val;
    }

    for(int i = n; i < m; ++i) {
        B[i] = rnd.next(0, 1000);
    }
}

void generate_identical_a_longer(int m, vector<int>& A, vector<int>& B) {
    int extraLength = rnd.next(1, 1000 - m);
    int n = m + extraLength;

    A.resize(n);
    B.resize(m);

    for(int i = 0; i < m; ++i) {
        int val = rnd.next(0, 1000);
        A[i] = B[i] = val;
    }

    for(int i = m; i < n; ++i) {
        A[i] = rnd.next(0, 1000);
    }
}

void generate_random(int n, int m, vector<int>& A, vector<int>& B) {
    A.resize(n);
    B.resize(m);
    for(int i = 0; i < n; ++i)
        A[i] = rnd.next(0, 1000);
    for(int i = 0; i < m; ++i)
        B[i] = rnd.next(0, 1000);
}

void generate_max_values(int n, int m, vector<int>& A, vector<int>& B) {
    A.resize(n, 1000);
    B.resize(m, 1000);
    if (n == m && n > 0) {
        B[n - 1] = 1000;
        A[n - 1] = 999;
    }
}

void generate_min_values(int n, int m, vector<int>& A, vector<int>& B) {
    A.resize(n, 0);
    B.resize(m, 0);
    if (n == m && n > 0) {
        B[n - 1] = 1;
        A[n - 1] = 0;
    }
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

