typedef pair<int,int> ii;

#define pb push_back
#define fs first
#define sc second
#define openfile {freopen("input.txt", "r", stdin);freopen("output.txt", "w", stdout);}
#define debug 0

int n, m, x, y, a, b;
double dmin = 1e18, res1, res2, res3, res4;

void findClosest(bool isOddx, bool isOddy, double x0, double y0, double x1, double y1, double &x2, double &y2)
{
    if (x <= x0) x2 = x0;
    else if (x >= x1) x2 = x1;
    else x2 = (isOddx) ? (double)x - 0.5 : x;

    if (y <= y0) y2 = y0;
    else if (y >= y1) y2 = y1;
    else y2 = (isOddy) ? (double)y - 0.5 : y;
}

double dist(double x0, double y0, double x1, double y1)
{
    return (x0 - x1) * (x0 - x1) + (y0 - y1) * (y0 - y1);
}

bool smaller(double x0, double y0, double x1, double y1)
{
    return (x0 < res1 || (x0 == res1 && y0 < res2) || (x0 == res1 && y0 == res2 && x1 < res3)
        || (x0 == res1 && y0 == res2 && x1 == res3 && y1 < res4));
}

int main() {
   if (debug) openfile;

   cin >> n >> m >> x >> y >> a >> b;
   int gcd = __gcd(a, b);
   a /= gcd, b /= gcd;
   int da = a, db = b;

   while (a <= n && b <= m)
    {
        double x0 = a / 2.0, y0 = b / 2.0;
        double x1 = x0 + n - a, y1 = y0 + n - b;
        double x2, y2;
        findClosest(a&1, b&1, x0, y0, x1, y1, x2, y2);
        double d = dist(x2, y2, x, y);
        if (d <= dmin)
        {
            double x3 = (x2 * 2 - a) / 2.0, y3 = (y2 * 2 - b) / 2.0;
            double x4 = x3 + a, y4 = y3 + b;
            if (d < dmin || (d == dmin && smaller(x3, y3, x4, y4)))
                res1 = x3, res2 = y3, res3 = x4, res4 = y4;
        }
        a += da, b += db;
    }
    cout << (int)res1 << " " << (int)res2 << " " << (int)res3 << " " << (int)res4 << endl;
   return 0;
}

