  n = read(), m = read();
  for (register long long i = 1; i <= n; ++i) {
    long long p = read();
    sum[i].push_back(0);
    for (register long long j = 1; j <= p; ++j)
      sum[i].push_back(sum[i].back() + read());
    v[i] = p;
    w[i] = sum[i].back();
  }
  solve(1, n);
  printf("%lld\n", ans);
  return 0;
}

