int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // --------------------------------------------------------------------
    // 1. Parse command-line arguments.
    // --------------------------------------------------------------------
    // n    : number of vertices (1 <= n <= 100000)
    // m    : (desired) number of edges (0 <= m <= 100000)
    // type : one of {"none", "chain", "star", "complete", "random"} (default: "none")
    //
    // Note: We will generate exactly one dataset per execution,
    //       then output "0 0" to mark termination of the input.
    // --------------------------------------------------------------------
    int n = opt<int>("n");
    long long m = opt<long long>("m", 0LL);
    string type = opt<string>("type", "none");

    // --------------------------------------------------------------------
    // 2. Generate edges based on type.
    //    - Make sure no duplicates.
    //    - All edges must satisfy 1 <= a < b <= n.
    //    - M must be at most n*(n-1)/2, so clamp if necessary.
    // --------------------------------------------------------------------
    // We store edges in a vector<pair<int,int>>
    vector<pair<int,int>> edges;

    // A safe upper bound for edges.
    long long maxEdges = (long long)n * (n - 1) / 2;
    m = min(m, maxEdges);  // clamp m to avoid impossible requests

    auto make_chain = [&](int n) {
        // A chain of length n has n-1 edges: 1-2, 2-3, ..., (n-1)-n
        // valid only if n >= 2
        for(int i = 1; i < n; i++) {
            edges.push_back({i, i+1});
        }
    };

    auto make_star = [&](int n) {
        // A star: edges from 1 to each of 2..n
        // valid only if n >= 2
        for(int i = 2; i <= n; i++) {
            edges.push_back({1, i});
        }
    };

    auto make_complete = [&](int n) {
        // Complete graph for small n only or for demonstration.
        // The total number of edges is n*(n-1)/2.
        for(int i = 1; i <= n; i++) {
            for(int j = i + 1; j <= n; j++) {
                edges.push_back({i, j});
            }
        }
    };

    auto make_random_edges = [&](int n, long long m) {
        // Generate m distinct edges randomly, each in [1..n].
        // We'll pick pairs (a,b) with a < b.
        // Use a set to avoid duplicates.
        // Then push them into edges vector.
        //
        // For large m, be mindful that 0 < m <= n*(n-1)/2.
        // We'll do a simple approach: keep trying random pairs until we have m.
        // This can be slow if m is close to the maximum, but is simpler to implement
        // for demonstration.
        unordered_set<long long> used;
        used.reserve(m*4ULL); // a small optimization for the hash set
        while((long long)edges.size() < m) {
            int a = rnd.next(1, n);
            int b = rnd.next(1, n);
            if(a == b) continue;
            if(b < a) swap(a, b);
            long long key = ((long long)a << 32) ^ (long long)b; 
            // combine a and b into one 64-bit value
            if(!used.count(key)) {
                used.insert(key);
                edges.push_back({a, b});
            }
        }
    };

    // --------------------------------------------------------------------
    // Based on "type", generate edges.
    // --------------------------------------------------------------------
    if(type == "none") {
        // no edges
        // m is forced to be 0
        m = 0;
        // do nothing
    }
    else if(type == "chain") {
        // chain => exactly n-1 edges if n >= 2
        // if n == 1, no edges
        edges.clear();
        if(n > 1) make_chain(n);
        m = edges.size(); // forced
    }
    else if(type == "star") {
        // star => exactly n-1 edges if n >= 2
        edges.clear();
        if(n > 1) make_star(n);
        m = edges.size(); // forced
    }
    else if(type == "complete") {
        // complete => n*(n-1)/2 edges, but only feasible for small n or demonstration
        edges.clear();
        make_complete(n);
        m = edges.size(); // forced
    }
    else {
        // default to "random" if something else is provided
        // produce m random edges, up to n*(n-1)/2
        edges.clear();
        make_random_edges(n, m);
    }

    // --------------------------------------------------------------------
    // 3. Output the dataset:
    //      N M
    //      a_1 b_1
    //      ...
    //      a_M b_M
    //    Then output "0 0" to mark termination.
    // --------------------------------------------------------------------
    cout << n << " " << (long long)m << "\n";
    for(auto &e : edges) {
        cout << e.first << " " << e.second << "\n";
    }
    cout << "0 0\n";

    return 0;
}

