        s = string(n, 'R');
    } else if (type == "alternating_UR") {
        s = "";
        for (int i = 0; i < n; ++i) {
            if (i % 2 == 0)
                s += 'U';
            else
                s += 'R';
        }
    } else if (type == "alternating_RU") {
        s = "";
        for (int i = 0; i < n; ++i) {
            if (i % 2 == 0)
                s += 'R';
            else
                s += 'U';
        }
    } else if (type == "no_replacements") {
        // Generate a sequence without any 'RU' or 'UR'
        s = "";
        char last = ' ';
        for (int i = 0; i < n; ++i) {
            if (last == 'U') {
                s += 'U';
                last = 'U';
            } else {
                s += 'R';
                last = 'R';
            }
        }
    } else if (type == "max_replacements") {
        // Generate a sequence where every pair is 'RU' or 'UR'
        s = "";
        for (int i = 0; i < n; ++i) {
            if (i % 2 == 0)
                s += 'R';
            else
                s += 'U';
        }
    } else if (type == "complex") {
        // Generate a complex sequence with overlapping patterns
        s = "";
        for (int i = 0; i < n; ++i) {
            if (i > 1 && ((s[i-1] == 'R' && s[i-2] == 'U') || (s[i-1] == 'U' && s[i-2] == 'R'))) {
                s += (rnd.next(2) ? 'U' : 'R');
            } else {
                s += (rnd.next(2) ? 'R' : 'U');
            }
        }
    } else if (type == "single_RU") {
        s = string(n, 'U');
        if (n >= 2) {
            s[n/2 - 1] = 'R';
        }
    } else if (type == "edge_RU_start") {
        s = string(n, 'U');
        if (n >= 2) {
            s[0] = 'R';
        }
    } else if (type == "edge_RU_end") {
        s = string(n, 'U');
        if (n >= 2) {
            s[n-2] = 'R';
