const int N = 1e5;
set<int> adj[N], lft;
void dfs(int s) {
  auto ptr = lft.begin();
  int curr;
  while (ptr != lft.end()) {
    curr = *ptr;
    if (!adj[s].count(curr)) {
      lft.erase(ptr);
      dfs(curr);
    }
    ptr = lft.upper_bound(curr);
  }
}
