  prefixLeft[i] = clacPrefixLeft(next) + (i - next) * arr[i];
  for (int j = i - 1; j > next; j--) {
    prefixLeft[j] = (j - next) * arr[j] + prefixLeft[next];
  }
  return prefixLeft[i];
