            if (len < 2) {
                // Cannot generate square string of length < 2
                s = randomString(1);
            } else {
                int halfLen = rnd.next(1, len / 2);
                string half = randomString(halfLen);
                s = half + half;
            }
        } else if (type == "non-square") {
            if (len == 1) {
                s = randomString(1); // Length 1 strings are not square
            } else {
                int l = rnd.next(1, len);
                if (l % 2 == 1) {
                    // Odd length, automatically non-square
                    s = randomString(l);
                } else {
                    // Even length, make halves different
                    int halfLen = l / 2;
                    string firstHalf = randomString(halfLen);
                    string secondHalf;
                    do {
                        secondHalf = randomString(halfLen);
