        // We can set a, b, c randomly and compute d = (bc)/a if a != 0
        // Be careful with division by zero
        while (true) {
            a = getRandom();
            b = getRandom();
            c = getRandom();
            if (a != 0) {
                d = (b * c) / a;
                if (abs(d) <= max_abs && a * d - b * c == 0) break;
            } else {
                // If a == 0, set d randomly and set b == 0 or c == 0 to make determinant zero
                d = getRandom();
                if (b == 0 || c == 0) {
