    if(m > (long long)n * (n - 1) / 2) {
        cerr << "Error: m is too large" << endl;
        exit(1);
    }

    const int MAX_W = 1000000000;
    const int MIN_W = 1;
    int W = 100000000;

    vector<tuple<int, int, int, int>> edges; // Each edge: {u, v, aj, bj}

    // Generate MST edges (bj = 1)
    vector<pair<int,int>> mst_edges;

    for(int i = 2; i <= n; ++i) {
        int u = i;
        int v = rnd.next(1, i - 1);
        mst_edges.push_back({u, v});
    }

    // Assign weights to MST edges
    vector<int> mst_weights;
    for(int i = 0; i < n - 1; ++i) {
        if(type == "heavy_mst") {
            // MST edges have higher weights
            mst_weights.push_back(rnd.next(W + 1, MAX_W));
        } else {
            // MST edges have lower or equal weights
            mst_weights.push_back(rnd.next(MIN_W, W));
        }
    }

    // Build set of existing edges to avoid duplicates
    set<pair<int,int>> edge_set;
    for(int i = 0; i < n - 1; ++i) {
        int u = mst_edges[i].first;
        int v = mst_edges[i].second;
        if(u > v) swap(u, v);
        edge_set.insert({u, v});
    }

    // Prepare edge list with aj and bj
    for(int i = 0; i < n -1; ++i) {
        int u = mst_edges[i].first;
        int v = mst_edges[i].second;
        int aj = mst_weights[i];
        int bj = 1;
        edges.push_back({u, v, aj, bj});
    }

    // Generate non-MST edges (bj = 0)
    int remaining_edges = m - (n - 1);
    while(remaining_edges > 0) {
        int u = rnd.next(1, n);
        int v = rnd.next(1, n);
        if(u == v) continue; // No self-loops
        if(u > v) swap(u, v);
        if(edge_set.count({u, v})) continue; // No duplicate edges
        edge_set.insert({u, v});
        int aj;
        if(type == "heavy_mst") {
            // Non-MST edges have lower weights
            aj = rnd.next(MIN_W, W);
        } else if(type == "equal_weights") {
            // All edges have the same weight
            aj = W;
        } else {
            // Non-MST edges have higher weights
            aj = rnd.next(W + 1, MAX_W);
        }
        int bj = 0;
        edges.push_back({u, v, aj, bj});
        remaining_edges--;
    }

    // Shuffle the edges
    shuffle(edges.begin(), edges.end());

    // Output n and m
    printf("%d %d\n", n, m);
    // Output m lines of aj and bj
    for(int i = 0; i < edges.size(); ++i) {
        int u, v, aj, bj;
        tie(u, v, aj, bj) = edges[i];
        printf("%d %d\n", aj, bj);
    }

    return 0;
}

