using namespace std;

// A simple DSU for connectivity/cycle checks
struct DSU {
    vector<int> parent, rankv;
    DSU(int n) : parent(n), rankv(n, 0) {
        for (int i = 0; i < n; i++) parent[i] = i;
    }
    int findp(int v) {
        if (v == parent[v]) return v;
        return parent[v] = findp(parent[v]);
    }
    bool unite(int a, int b) {
        a = findp(a); b = findp(b);
        if (a == b) return false;
        if (rankv[a] < rankv[b]) swap(a,b);
        parent[b] = a;
        if (rankv[a] == rankv[b]) rankv[a]++;
        return true;
    }
};

// We'll use LCA (Lowest Common Ancestor) technique to quickly find the maximum edge
// on the path between two vertices in the MST. This lets us verify the MST property.
static const int MAXLOG = 20; // enough for n up to ~1e6 if needed
int n, m;
vector<long long> w;  // edge weights
vector<int> inMST;    // b_j = 1 or 0

// adjacency for MST edges: adj[u] = vector of {v, weight}
vector<vector<pair<int,long long>>> adj;

// LCA structures
vector<int> depth;
int parent[MAXLOG][200001];       // parent[k][v]: 2^k-th ancestor of v
long long mxPar[MAXLOG][200001];  // mxPar[k][v]: max edge weight on the path from v to its 2^k-th ancestor

// DFS to set up depth, parent[0], mxPar[0]
void dfs(int v, int p, long long wgt, int d) {
    parent[0][v] = (p < 0 ? v : p); // if p < 0, v is root: parent is v itself
    mxPar[0][v] = (p < 0 ? -1 : wgt);
    depth[v] = d;
    for (auto &ed : adj[v]) {
        int to = ed.first;
        long long wEdge = ed.second;
        if (to == p) continue;
        dfs(to, v, wEdge, d + 1);
    }
}

// Precompute parent[k][v] and mxPar[k][v]
void buildLCA() {
    for(int k = 1; k < MAXLOG; k++){
        for(int v = 0; v < n; v++){
            parent[k][v] = parent[k-1][ parent[k-1][v] ];
            mxPar[k][v] = max(mxPar[k-1][v],
                              mxPar[k-1][ parent[k-1][v] ]);
        }
    }
}

// Returns the maximum edge weight on the path u -> v in the MST
long long getMaxEdgeOnPath(int u, int v){
    if (depth[u] < depth[v]) std::swap(u, v);
    long long ans = -1;
    // 1) Lift u to the same depth as v
    int diff = depth[u] - depth[v];
    for(int k = 0; k < MAXLOG; k++){
        if(diff & (1 << k)){
            ans = max(ans, mxPar[k][u]);
            u = parent[k][u];
        }
    }
    // 2) If they are the same, we are done
    if(u == v) return ans;
    // 3) Lift them up together
    for(int k = MAXLOG - 1; k >= 0; k--){
        if(parent[k][u] != parent[k][v]){
            ans = max(ans, mxPar[k][u]);
            ans = max(ans, mxPar[k][v]);
            u = parent[k][u];
            v = parent[k][v];
        }
    }
    // one more step to reach LCA
    ans = max(ans, mxPar[0][u]);
    ans = max(ans, mxPar[0][v]);
    return ans;
}

int main(int argc, char* argv[]){
