    string type = opt<string>("type", "random");

    vector<int> p(n);
    for (int i = 0; i < n; ++i)
        p[i] = i + 1;

    if (type == "sorted") {
        // The permutation is already sorted.
        // Do nothing.
    } else if (type == "reversed") {
        // Reverse the permutation.
        reverse(p.begin(), p.end());
    } else if (type == "random") {
        // Shuffle the entire permutation randomly.
        shuffle(p.begin(), p.end());
    } else if (type == "almost_sorted") {
        // Make a sorted permutation with a few swaps.
        int k = opt<int>("k", 1);  // Number of swaps.
        for (int i = 0; i < k; ++i) {
            int a = rnd.next(0, n - 1);
            int b = rnd.next(0, n - 1);
            swap(p[a], p[b]);
        }
    } else if (type == "shuffled_blocks") {
        // Divide permutation into k blocks and shuffle the blocks.
        int k = opt<int>("k", 2);
        int blockSize = n / k;
        vector<vector<int>> blocks;
        int idx = 0;
        for (int i = 0; i < k; ++i) {
            vector<int> block;
            int currentBlockSize = blockSize + (i < n % k ? 1 : 0);
            for (int j = 0; j < currentBlockSize; ++j, ++idx) {
                block.push_back(p[idx]);
            }
            blocks.push_back(block);
        }
        shuffle(blocks.begin(), blocks.end());
        idx = 0;
        for (auto& block : blocks) {
            for (auto num : block) {
                p[idx++] = num;
            }
        }
    } else if (type == "all_same_prefix") {
        // The first k elements are sorted; the rest are shuffled.
        int k = opt<int>("k", n / 2);
        shuffle(p.begin() + k, p.end());
    } else if (type == "all_same_suffix") {
        // The last k elements are sorted; the rest are shuffled.
        int k = opt<int>("k", n / 2);
        shuffle(p.begin(), p.begin() + n - k);
    }

    // Output the permutation.
    printf("%d\n", n);
    for (int i = 0; i < n; ++i)
        printf("%d\n", p[i]);

    return 0;
}

