        return -1; // No solution
    } else {
        t.push_back(first);
        for (int i = 1; i < n; ++i) {
            int x = stream.readInt(1, m, format("album index t[%d]", i + 1).c_str());
            t.push_back(x);
        }
        return 0; // Successfully read the sequence
    }
}

void validateAnswer(vector<int>& t, InStream& stream) {
    if (t.size() != n) {
        stream.quitf(_wa, "Expected %d album indices, but found %d", n, t.size());
    }
    vector<int> used(m + 1, 0); // album indices are from 1 to m
    for (int i = 0; i < n; ++i) {
        int idx = t[i];
        if (idx < 1 || idx > m) {
            stream.quitf(_wa, "Album index t[%d] = %d is out of range [1, %d]", i + 1, idx, m);
        }
        used[idx]++;
        if (used[idx] > ai[idx - 1]) {
            stream.quitf(_wa, "Album %d used %d times, but only has %d photos", idx, used[idx], ai[idx -1]);
        }
    }
    // Now check that no two consecutive photos are from the same album
    for (int i = 0; i < n; ++i) {
        int curr = t[i];
        int next = t[(i + 1) % n]; // Since it's a cycle
        if (curr == next) {
            stream.quitf(_wa, "Consecutive photos t[%d]=%d and t[%d]=%d are from the same album %d", i + 1, curr, (i + 2 <= n) ? (i + 2) : 1, next, curr);
        }
    }
}

