#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
   This generator creates a single test for the problem:
   "Given n and k (2 <= n <= 2000, 1 <= k <= 1e9), output one line with n and k."

   We provide a variety of "type" modes to produce different (n, k) pairs,
   aiming to catch incorrect contestants' solutions. The generator will be run
   multiple times, each producing a single test case.  

   Usage examples:
     ./gen -n 10 -k 20
     ./gen -type random
     ./gen -type yes
     ./gen -type no
     ./gen -type borderline
     ./gen -type small
     ./gen -type large
*/

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // User-provided (n, k)
    int userN = opt<int>("n", -1);
    long long userK = opt<long long>("k", -1);
    string type = opt<string>("type", "random");

    // If the user explicitly gave both n and k, just output them:
    if (userN != -1 && userK != -1) {
        // Ensure they satisfy constraints (2 <= n <= 2000, 1 <= k <= 1e9).
        // In a real contest environment, we might want to check them carefully,
        // but here we assume the problem setter provides valid values.
        cout << userN << " " << userK << "\n";
        return 0;
    }

    // Otherwise, we generate (n, k) according to "type".
    int n;
    long long k;

    // Helper function to pick a random integer in a closed range [L,R].
    auto rndRange = [&](long long L, long long R) {
        // testlib's rnd.next(x,y) is inclusive for integer generation in [x,y].
        // So we can safely use it here.
        return rnd.next((long long)L, (long long)R);
    };

    if (type == "random") {
        // Fully random within constraints
        n = rndRange(2, 2000);
        k = rndRange(1, 1000000000LL);
    }
    else if (type == "yes") {
        // Guarantee tot = n*(n-1)/2 > k
        // So pick an n, then choose a k that is strictly less than that total
        // (provided total <= 1e9).
        // The maximum for n*(n-1)/2 with n=2000 is 1,999,000 which is < 1e9.
        // We'll pick an n >= 3 to make sure total is at least 3.
        n = rndRange(3, 2000);
        long long totalPairs = (long long)n * (n - 1) / 2;
        // We want 1 <= k < totalPairs. 
        // We'll pick something around the middle, or random in [1..totalPairs-1].
        k = rndRange(1, totalPairs - 1);
    }
    else if (type == "no") {
        // Guarantee tot = n*(n-1)/2 <= k
        // So pick an n, then let k >= that total
        // We can pick k up to 1e9
        n = rndRange(2, 2000);
        long long totalPairs = (long long)n * (n - 1) / 2;
        // We want totalPairs <= k
        // We'll choose k in [totalPairs, min(1e9, totalPairs+some margin)]
        long long m = min(1000000000LL, totalPairs + 1000000LL); 
        // in case totalPairs is close to 1e9, this won't exceed 1e9
        k = rndRange(totalPairs, m);
    }
    else if (type == "borderline") {
        // Exactly tot = n*(n-1)/2 = k
        // We'll choose some n >= 2, then k = that total
        n = rndRange(2, 2000);
        long long totalPairs = (long long)n * (n - 1) / 2;
        k = totalPairs;
    }
    else if (type == "small") {
        // Choose small n (like up to 10) and small k up to 100 
        n = rndRange(2, 10);
        k = rndRange(1, 100);
    }
    else if (type == "large") {
        // Choose large n near 2000, and k up to 1e9
        n = rndRange(1900, 2000);
        k = rndRange(500000000LL, 1000000000LL);
    }
    else {
        // Default fallback if an unexpected 'type' is provided
        n = rndRange(2, 2000);
        k = rndRange(1, 1000000000LL);
    }

    // Print the result:
    cout << n << " " << k << "\n";

    return 0;
}

