#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

static long double distance2D(long long x1, long long y1, long long x2, long long y2) {
    long long dx = x2 - x1;
    long long dy = y2 - y1;
    long double dist = sqrt((long double)dx * dx + (long double)dy * dy);
    return dist;
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    // 1. Read n and k from the input file.
    int n = inf.readInt(2, 2000, "n");
    long long k = inf.readLong(1, 1000000000LL, "k");

    // 2. Read the first token of the contestant's output (if any).
    if (!ouf.seekEof()) {
        string firstToken = ouf.readToken();

        // --- Case A: The output is "no solution" ---
        if (firstToken == "no") {
            // The next token must be "solution" if the user is claiming no solution
            string secondToken = ouf.readToken();
            if (secondToken != "solution") {
                ouf.quitf(_wa, "Expected 'no solution' but got 'no %s'", secondToken.c_str());
            }
            // Must not have extra tokens
            if (!ouf.seekEof()) {
                ouf.quitf(_wa, "Extra tokens after 'no solution'");
            }

            // Now confirm if "no solution" is indeed correct or not
            // The maximum possible tot is n*(n-1)/2 (if no break is ever triggered).
            long long maxPossible = (long long)n * (n - 1) / 2;
            if (maxPossible > k) {
                ouf.quitf(_wa, "A solution is possible (maxPossible=%lld > k=%lld), but contestant printed 'no solution'",
                          maxPossible, k);
            } else {
                // It's correct to say "no solution"
                ouf.quitf(_ok, "Correctly printed 'no solution'");
            }
        }

        // --- Case B: The output is a list of n points ---
        // We have already read one token (which we expect to be x-coordinate of the 1st point).
        // We will parse that token as an integer, then parse n-1 more pairs, for a total of n pairs.

        // 2B(i). We must parse the first token as x0 in range.
        //        Then parse another token right now as y0
        //        Then parse the remaining 2*(n-1) tokens similarly.

        // Rewind the first token as integer
        long long xFirst;
        // If reading the first token as integer fails, testlib will throw an error automatically
        xFirst = stoi(firstToken);

        if (xFirst < -1000000000LL || xFirst > 1000000000LL) {
            ouf.quitf(_wa, "First x-coordinate = %lld is out of range [-1e9, 1e9]", xFirst);
        }

        // Read the y-coordinate for the first point
        long long yFirst = ouf.readLong(-1000000000LL, 1000000000LL, "y1");

        vector<pair<long long, long long>> points;
        points.push_back({xFirst, yFirst});

        for (int i = 2; i <= n; i++) {
            long long x = ouf.readLong(-1000000000LL, 1000000000LL, ("x" + to_string(i)).c_str());
            long long y = ouf.readLong(-1000000000LL, 1000000000LL, ("y" + to_string(i)).c_str());
            points.push_back({x, y});
        }

        // Must not have extra tokens
        if (!ouf.seekEof()) {
            ouf.quitf(_wa, "Extra tokens after reading %d points", n);
        }

        // 2B(ii). Check distinctness
        // A simple way is to use a set
        set<pair<long long, long long>> st(points.begin(), points.end());
        if ((int)st.size() != n) {
            ouf.quitf(_wa, "Points are not distinct");
        }

        // 2B(iii). Replicate the pseudo-code to compute tot
        // sort p[] by x ascending, then by y ascending
        sort(points.begin(), points.end(), [&](auto &a, auto &b){
            if (a.first != b.first) return a.first < b.first;
            return a.second < b.second;
        });

        long double d = 1e18L; // INF
        long long tot = 0LL;

        for (int i = 0; i < n; i++) {
            for (int j = i+1; j < n; j++) {
                tot++;
                // check if p[j].x - p[i].x >= d
                long long diffX = points[j].first - points[i].first;
                if ((long double)diffX >= d) {
                    break; // out of the "for j" loop
                }
                long double dist = distance2D(points[i].first, points[i].second,
                                               points[j].first, points[j].second);
                if (dist < d) {
                    d = dist;
                }
            }
        }

        // 2B(iv). Check tot > k
        if (tot <= k) {
            ouf.quitf(_wa, "tot=%lld, but it must be greater than k=%lld", tot, k);
        } else {
            ouf.quitf(_ok, "tot=%lld > k=%lld", tot, k);
        }
    }
    else {
        // The contestant gave no output at all...
        ouf.quitf(_wa, "No output found");
    }

    return 0; // not reached
}

