struct Query {
  long long int f, t, v;
};
vector<set<long long int>> s;
long long int N;
void combine(long long int i) {
  set<long long int> &a = s[i];
  set<long long int> &b = s[i + 1];
  set<long long int> &r = s[i / 2];
  set<long long int> c = r;
  for (long long int n : a) {
    r.insert(n);
    for (long long int m : b) {
      r.insert(m);
    }
    for (long long int m : b) {
      for (long long int k : c) {
        if (k + n > N) break;
        r.insert(k + n);
      }
      for (long long int k : c) {
        if (k + m > N) break;
        r.insert(k + m);
      }
    }
  }
}
void add(long long int idx, long long int val) { s[idx].insert(val); }
long long int M, L;
void imprint(Query &q) {
  long long int f = q.f;
  long long int t = q.t;
  long long int v = q.v;
  long long int i = 1, j = 0;
  while (f != t) {
    long long int o = 1 << (L - j);
    if (f & i) {
      add(o + (f >> j), v);
      f += i;
    }
    if (f == t) break;
    if (t & i) {
      add(o + (t >> j) - 1, v);
      t -= i;
    }
    i <<= 1;
    j++;
  }
}
int main() {
  ios::sync_with_stdio(false);
  long long int Q;
  cin >> N >> Q;
  vector<Query> q;
  for (long long int i = (0); i < (long long int)(Q); ++i) {
    long long int a, b, c;
    cin >> a >> b >> c;
    --a;
    q.push_back({a, b, c});
  }
  M = 1;
  L = 0;
  while (M < N) {
    M <<= 1;
    L++;
  }
  set<long long int> ss;
  ss.insert(0);
  s = vector<set<long long int>>(2 * M, ss);
  for (long long int i = (0); i < (long long int)(Q); ++i) imprint(q[i]);
  for (int i = 2 * M - 2; i > 1; i -= 2) combine(i);
  set<long long int> &r = s[1];
  r.erase(0);
  cout << r.size() << endl;
  for (long long int n : r) cout << n << ' ';
  cout << endl;
  return 0;
}

