// Function to check if two segments (p1,q1) and (p2,q2) intersect
bool segmentsIntersect(pair<int,int> p1, pair<int,int> q1, pair<int,int> p2, pair<int,int> q2) {
    auto ccw = [](pair<int,int> a, pair<int,int> b, pair<int,int> c) {
        return (c.first - a.first) * (b.second - a.second) - (b.first - a.first) * (c.second - a.second);
    };

    int d1 = ccw(p1, q1, p2);
    int d2 = ccw(p1, q1, q2);
    int d3 = ccw(p2, q2, p1);
    int d4 = ccw(p2, q2, q1);

    if(((d1 > 0 && d2 < 0)||(d1 < 0 && d2 > 0)) && ((d3 > 0 && d4 < 0)||(d3 < 0 && d4 > 0)))
        return true;
    if(d1 == 0 && min(p1.first,q1.first) <= p2.first && p2.first <= max(p1.first,q1.first) && min(p1.second,q1.second) <= p2.second && p2.second <= max(p1.second,q1.second))
        return true;
    if(d2 == 0 && min(p1.first,q1.first) <= q2.first && q2.first <= max(p1.first,q1.first) && min(p1.second,q1.second) <= q2.second && q2.second <= max(p1.second,q1.second))
        return true;
    if(d3 == 0 && min(p2.first,q2.first) <= p1.first && p1.first <= max(p2.first,q2.first) && min(p2.second,q2.second) <= p1.second && p1.second <= max(p2.second,q2.second))
        return true;
    if(d4 == 0 && min(p2.first,q2.first) <= q1.first && q1.first <= max(p2.first,q2.first) && min(p2.second,q2.second) <= q1.second && q1.second <= max(p2.second,q2.second))
        return true;
    return false;
}

void ensureSimplePolygon(vector<pair<int,int>>& points) {
    int n = points.size();
    for(int i=0; i<n; ++i) {
        for(int j=i+1; j<n; ++j) {
            int i_next = (i+1)%n;
            int j_next = (j+1)%n;
            if(i == j || i_next == j || i == j_next)
                continue;
            if(segmentsIntersect(points[i], points[i_next], points[j], points[j_next])) {
                swap(points[i_next], points[j]);
                i = -1;
                break;
            }
        }
    }
}

void generateConvexPolygon(int n, vector<pair<int,int>>& points) {
    vector<double> angles(n);
    for(int i=0; i<n; ++i)
        angles[i] = rnd.next(0.0, 2.0 * M_PI);

    sort(angles.begin(), angles.end());

    for(int i=0; i<n; ++i) {
        double r = rnd.next(500.0, 1000.0); // radius between 500 and 1000
        int x = int(round(r * cos(angles[i])));
        int y = int(round(r * sin(angles[i])));
        points.emplace_back(x, y);
    }

    double area = 0.0;
    for(int i=0; i<n; ++i) {
        int x1 = points[i].first, y1 = points[i].second;
        int x2 = points[(i+1)%n].first, y2 = points[(i+1)%n].second;
        area += (x1 * y2 - x2 * y1);
    }

    if(area < 0) {
        reverse(points.begin(), points.end());
    }
}

void generateConcavePolygon(int n, vector<pair<int,int>>& points) {
    generateConvexPolygon(n, points);

    int idx = rnd.next(0, n-1);

    double cx = 0.0, cy = 0.0;
    for(const auto& p : points) {
        cx += p.first;
        cy += p.second;
    }
    cx /= n;
    cy /= n;

    int x = points[idx].first;
    int y = points[idx].second;
    x = x + int((cx - x) * 0.5);
    y = y + int((cy - y) * 0.5);
    points[idx].first = x;
    points[idx].second = y;

    ensureSimplePolygon(points);

    double area = 0.0;
    for(int i=0; i<n; ++i) {
        int x1 = points[i].first, y1 = points[i].second;
        int x2 = points[(i+1)%n].first, y2 = points[(i+1)%n].second;
        area += (x1 * y2 - x2 * y1);
    }
    if(area < 0) {
        reverse(points.begin(), points.end());
    }
}

void generatePolygonWithColinearPoints(int n, vector<pair<int,int>>& points) {
    generateConvexPolygon(n, points);

    int idx = rnd.next(0, n-2);
    int x1 = points[idx].first, y1 = points[idx].second;
    int x2 = points[idx+1].first, y2 = points[idx+1].second;
    int x3 = points[(idx+2)%n].first, y3 = points[(idx+2)%n].second;

    int xmid = (x1 + x3) / 2;
    int ymid = (y1 + y3) / 2;
    points[idx+1].first = xmid;
    points[idx+1].second = ymid;

    ensureSimplePolygon(points);

    double area = 0.0;
    for(int i=0; i<n; ++i) {
        int x1 = points[i].first, y1 = points[i].second;
        int x2 = points[(i+1)%n].first, y2 = points[(i+1)%n].second;
        area += (x1 * y2 - x2 * y1);
    }
    if(area < 0) {
        reverse(points.begin(), points.end());
    }
}

void generateAxisAlignedPolygon(int n, vector<pair<int, int>>& points) {
    int xmin = rnd.next(-900, -500);
    int xmax = rnd.next(500, 900);
    int ymin = rnd.next(-900, -500);
    int ymax = rnd.next(500, 900);

    vector<pair<int, int>> corners = {{xmin, ymin}, {xmax, ymin}, {xmax, ymax}, {xmin, ymax}};
    points.insert(points.end(), corners.begin(), corners.end());

    int additionalPoints = n - 4;

    for(int i = 0; i < 4; ++i) {
        int numNewPoints = additionalPoints / (4 - i);
        additionalPoints -= numNewPoints;

        int x1 = points[i].first;
        int y1 = points[i].second;
        int x2 = points[(i+1)%4].first;
        int y2 = points[(i+1)%4].second;

        vector<pair<int, int>> newPoints;
        for(int j = 1; j <= numNewPoints; ++j) {
            int x = x1 + (x2 - x1) * j / (numNewPoints + 1);
            int y = y1 + (y2 - y1) * j / (numNewPoints + 1);
            newPoints.push_back({x, y});
        }
        points.insert(points.begin() + i + 1, newPoints.begin(), newPoints.end());
        i += newPoints.size();
    }

    double area = 0.0;
    n = points.size();
    for(int i=0; i<n; ++i) {
        int x1 = points[i].first, y1 = points[i].second;
        int x2 = points[(i+1)%n].first, y2 = points[(i+1)%n].second;
        area += (x1 * y2 - x2 * y1);
    }

    if(area < 0) {
        reverse(points.begin(), points.end());
    }
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int datasets = opt<int>("datasets", 1);
    string type = opt<string>("type", "convex");

    for(int ds=0; ds<datasets; ++ds) {
        vector<pair<int,int>> points;
        if(type == "convex") {
            generateConvexPolygon(n, points);
        } else if(type == "concave") {
            generateConcavePolygon(n, points);
        } else if(type == "colinear") {
            generatePolygonWithColinearPoints(n, points);
        } else if(type == "axis") {
            generateAxisAlignedPolygon(n, points);
        } else {
            // Default to convex polygon
            generateConvexPolygon(n, points);
        }

        // Output n
        printf("%d\n", n);
        // Output the coordinates
        for(int i=0; i<n; ++i) {
            printf("%d %d\n", points[i].first, points[i].second);
        }
    }
    // Output a single zero line at the end
    printf("0\n");

    return 0;
}

