#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

struct Point {
    int x, y;
};

int orientation(Point p, Point q, Point r)
{
    // Returns 0 if colinear, 1 if clockwise, 2 if counterclockwise
    int64_t val = (int64_t)(q.x - p.x)*(r.y - p.y) - (int64_t)(q.y - p.y)*(r.x - p.x);
    if (val == 0) return 0; // colinear
    return (val > 0) ? 2 : 1; // 2 for counterclockwise, 1 for clockwise
}

bool onSegment(Point p, Point q, Point r)
{
    // Checks if q lies on segment pr
    if (min(p.x, r.x) <= q.x && q.x <= max(p.x, r.x) &&
        min(p.y, r.y) <= q.y && q.y <= max(p.y, r.y))
        return true;

    return false;
}

bool segmentsIntersect(Point p1, Point q1, Point p2, Point q2)
{
    // Find the four orientations needed for general and special cases
    int o1 = orientation(p1, q1, p2);
    int o2 = orientation(p1, q1, q2);
    int o3 = orientation(p2, q2, p1);
    int o4 = orientation(p2, q2, q1);

    // General case
    if (o1 != o2 && o3 != o4)
        return true;

    // Special Cases
