#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

static const int MAX_VALUE = 1023; // 0..1023 => 10 bits
static const int BITS = 10;        

// Describes how each bit transforms if originally 0 (f0[b]) or 1 (f1[b]).
struct BitTransform {
    bool f0[BITS], f1[BITS];
    BitTransform() {
        for (int i = 0; i < BITS; i++) {
            f0[i] = false; // starting bit 0 remains 0 by default
            f1[i] = true;  // starting bit 1 remains 1 by default
        }
    }
};

// Apply one bitwise operation (op in {&,|,^}, val in [0..1023]) to transform.
void applyOp(BitTransform &bt, char op, int val) {
    for (int b = 0; b < BITS; b++) {
        bool vb = (val >> b) & 1;
        bool old0 = bt.f0[b], old1 = bt.f1[b];
        bool new0, new1;
        switch(op) {
            case '&':
                new0 = old0 & vb;
                new1 = old1 & vb;
                break;
            case '|':
                new0 = old0 | vb;
                new1 = old1 | vb;
                break;
            default: // '^'
                new0 = old0 ^ vb;
                new1 = old1 ^ vb;
                break;
        }
        bt.f0[b] = new0;
        bt.f1[b] = new1;
    }
}

// Compares two transforms for all bits.
bool sameTransform(const BitTransform &a, const BitTransform &b) {
    for (int i = 0; i < BITS; i++) {
        if (a.f0[i] != b.f0[i] || a.f1[i] != b.f1[i]) {
            return false;
        }
    }
    return true;
}

// Reads and compresses exactly k lines of [op val]. If isOfficial => errors => _fail; else => _wa.
BitTransform readAndCompressProgram(InStream &stream, int k, bool isOfficial) {
    // After readInt(k), we should consume that line:
    stream.readEoln();

    BitTransform result;
    for (int i = 0; i < k; i++) {
        string line = stream.readLine(); // read the entire line
        // Trim:
        while (!line.empty() && isspace(line.back())) line.pop_back();
        while (!line.empty() && isspace(line.front())) line.erase(line.begin());

        if (line.empty()) {
            if (isOfficial)
                stream.quitf(_fail, "empty line in official solution (line %d)", i+1);
            else
                stream.quitf(_wa,   "empty line in participant solution (line %d)", i+1);
        }

        // Split
        vector<string> tokens;
        {
            stringstream ss(line);
            string t;
            while (ss >> t) tokens.push_back(t);
        }
        if (tokens.size() != 2) {
            if (isOfficial)
                stream.quitf(_fail, "line %d of official solution must have 2 tokens", i+1);
            else
                stream.quitf(_wa,   "line %d of participant solution must have 2 tokens", i+1);
        }

        // op
        char op = (tokens[0].size() == 1 ? tokens[0][0] : '#');
        if (op != '&' && op != '|' && op != '^') {
            if (isOfficial)
                stream.quitf(_fail, "invalid operation '%s' in official solution line %d", tokens[0].c_str(), i+1);
            else
                stream.quitf(_wa,   "invalid operation '%s' in participant solution line %d", tokens[0].c_str(), i+1);
        }

        // parse val
        int val;
        try {
            val = stoi(tokens[1]);
        } catch(...) {
            if (isOfficial)
                stream.quitf(_fail, "invalid integer '%s' in official solution line %d", tokens[1].c_str(), i+1);
            else
                stream.quitf(_wa,   "invalid integer '%s' in participant solution line %d", tokens[1].c_str(), i+1);
        }
        if (val < 0 || val > MAX_VALUE) {
            if (isOfficial)
                stream.quitf(_fail, "integer %d out of [0..%d] in official solution line %d", val, MAX_VALUE, i+1);
            else
                stream.quitf(_wa,   "integer %d out of [0..%d] in participant solution line %d", val, MAX_VALUE, i+1);
        }

        applyOp(result, op, val);
    }
    return result;
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    // 1) Read n from input
    int n = inf.readInt(1, 500000, "n");
    inf.readEoln(); // CRITICAL: consume the rest of the line that had 'n', so next reads get fresh lines

    // Now read n lines of [op val]
    BitTransform petya;
    for (int i = 0; i < n; i++) {
        string line = inf.readLine(); 
        // parse
        vector<string> tokens;
        {
            stringstream ss(line);
            string t;
            while (ss >> t) tokens.push_back(t);
        }
        if (tokens.size() != 2) {
            inf.quitf(_fail, "line %d of input must have exactly 2 tokens", i+2);
        }
        char op = (tokens[0].size() == 1 ? tokens[0][0] : '#');
        if (op != '&' && op != '|' && op != '^') {
            inf.quitf(_fail, "invalid operation '%s' on input line %d", tokens[0].c_str(), i+2);
        }
        int val;
        try {
            val = stoi(tokens[1]);
        } catch (...) {
            inf.quitf(_fail, "invalid integer '%s' on input line %d", tokens[1].c_str(), i+2);
        }
        if (val < 0 || val > MAX_VALUE) {
            inf.quitf(_fail, "integer %d out of [0..%d] on input line %d", val, MAX_VALUE, i+2);
        }
        applyOp(petya, op, val);
    }

    // 2) Official solution
    int kAns = ans.readInt(0, 5, "k (official solution)");
    BitTransform officialBT = readAndCompressProgram(ans, kAns, /*isOfficial=*/true);
    ans.readEof(); // no extra data

    if (!sameTransform(petya, officialBT)) {
        ans.quitf(_fail, "official solution is not equivalent to Petya's program");
    }

    // 3) Participant solution
    int kOuf = ouf.readInt(0, 5, "k (participant solution)");
    BitTransform participantBT = readAndCompressProgram(ouf, kOuf, /*isOfficial=*/false);
    ouf.readEof(); // no extra data

    if (!sameTransform(petya, participantBT)) {
        ouf.quitf(_wa, "participant solution is not equivalent to Petya's program");
    }

    // If we reach here, solutions match
    quitf(_ok, "OK! Solutions match on [0..1023].");
}

