using namespace std;

// Helper function to generate m unique random edges between nodes 1..n
vector<pair<int, int> > generate_random_edges(int n, int m){
    set<pair<int, int>> edges;
    while ((int)edges.size() < m){
        int a = rnd.next(1, n);
        int b = rnd.next(1, n);
        if (a == b) continue;
        if (a > b) swap(a, b);
        edges.insert(make_pair(a, b));
    }
    return vector<pair<int, int>>(edges.begin(), edges.end());
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int m_param = opt<int>("m", -1); // default -1, meaning set m according to the type
    string type = opt<string>("type", "random");

    long long max_edges = (long long)n * (n - 1) / 2;
    max_edges = min(max_edges, (long long)2e5);

    int m;
    if (m_param == -1){
        // Set default m according to type
        if (type == "chain" || type == "star"){
            m = n - 1;
        } else if (type == "minimal"){
            m = 0;
        } else if (type == "maximal" || type == "full"){
            m = (int)max_edges;
        } else {
            m = rnd.next(0, (int)max_edges);  // For random type, m is random
        }
    } else {
        m = min(m_param, (int)max_edges);
    }

    vector<pair<int, int>> edges;

    if (type == "chain"){
        // Build a chain
        for (int i = 1; i < n; ++i){
            edges.push_back({i, i+1});
        }
    } else if (type == "star"){
        for (int i = 2; i <= n; ++i){
            edges.push_back({1, i});
        }
    } else if (type == "full") {
        // Complete graph
        // But m should not exceed 2e5
        for (int i = 1; i <= n && (int)edges.size() < m; ++i){
            for (int j = i+1; j <= n && (int)edges.size() < m; ++j){
                edges.push_back({i, j});
            }
        }
    } else if (type == "disconnected"){
        // Produce a graph with multiple components
        int c = 1000;  // Component size
        int node = 1;
        while (node <= n){
            int size = min(c, n - node +1);
            // Build a chain in this component
            for (int i = node; i < node + size -1; ++i){
                edges.push_back({i, i+1});
                if ((int)edges.size() >= m)
                    break;
            }
            node += size;
            if ((int)edges.size() >= m)
                break;
        }
    } else if (type == "minimal"){
        // No edges
    } else if (type == "maximal" || type == "full"){
        // Complete or near-complete graph
        for (int i = 1; i <= n && (int)edges.size() < m; ++i){
            for (int j = i+1; j <= n && (int)edges.size() < m; ++j){
                edges.push_back({i, j});
            }
        }
    } else { // type == "random"
        // Generate random edges
        edges = generate_random_edges(n, m);
    }

    if ((int)edges.size() > m){
        edges.resize(m);
    }
    // Shuffle edges to randomize order
    shuffle(edges.begin(), edges.end());

    cout << n << " " << m << endl;

    // Output edges
    for (auto edge : edges){
        cout << edge.first << " " << edge.second << endl;
    }

    return 0;
}

