        int z = ouf.readInt(1, n, "z");

        pair<int, int> edge1 = make_pair(min(x, y), max(x, y));
        pair<int, int> edge2 = make_pair(min(y, z), max(y, z));

        if (edge_set.find(edge1) == edge_set.end())
            quitf(_wa, "Edge between %d and %d does not exist", x, y);
        if (edge_set.find(edge2) == edge_set.end())
            quitf(_wa, "Edge between %d and %d does not exist", y, z);

        if (!used_edges.insert(edge1).second)
            quitf(_wa, "Edge between %d and %d is used more than once", x, y);
        if (!used_edges.insert(edge2).second)
            quitf(_wa, "Edge between %d and %d is used more than once", y, z);
    }

    quitf(_ok, "Number of episodes = %d", w_participant);
