using namespace std;

string generate_random_number(int n) {
    string num = "";
    for(int i = 0; i < n; ++i) {
        char digit = '0' + rnd.next(10);
        // First digit cannot be '0'
        if (i == 0 && digit == '0') {
            digit = '1' + rnd.next(9);
        }
        num += digit;
    }
    return num;
}

string generate_beautiful_number(int n) {
    string num = "";
    int sum = 0;
    for(int i = 0; i < n; ++i) {
        char digit = '0' + rnd.next(10);
        if (i == 0 && digit == '0') {
            digit = '1' + rnd.next(9);
        }
        num += digit;
        sum += digit - '0';
    }
    int mod = sum % 3;
    if (mod != 0) {
        // Try to adjust one digit to make sum % 3 == 0
        bool adjusted = false;
        for(int i = n -1; i >= 0; --i) {
            int digit = num[i] - '0';
            int new_digit = digit + (3 - mod);
            if (new_digit <= 9) {
                num[i] = '0' + new_digit;
                adjusted = true;
                break;
            }
        }
        // If cannot adjust upwards, try adjusting downwards
        if (!adjusted) {
            for(int i = n -1; i >= 0; --i) {
                int digit = num[i] - '0';
                int new_digit = digit - mod;
                if (new_digit >= 0 && !(i == 0 && new_digit == 0)) {
                    num[i] = '0' + new_digit;
                    adjusted = true;
                    break;
                }
            }
        }
    }
    return num;
}

string generate_impossible_number(int n) {
    string num = "";
    for(int i = 0; i < n; ++i) {
        num += "1";
    }
    int mod = n % 3;
    if (mod == 0) {
        num[0] = '2';
    }
    return num;
}

string generate_min_erase_k_number(int n, int k) {
    string num = "";
    if (k >= n) {
        k = n -1;
    }
    for(int i = 0; i < n - k; ++i) {
        num += '3';
    }
    for(int i = n - k; i < n; ++i) {
        num += '1';
    }
    return num;
}

string generate_leading_zero_trap(int n) {
    string num = "1";
    for (int i =1; i < n; ++i) {
        num += '0';
    }
    return num;
}

