    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    string type = opt<string>("type", "random");

    string num;

    if (type == "random") {
        num = generate_random_number(n);
    } else if (type == "already_beautiful") {
        num = generate_beautiful_number(n);
    } else if (type == "impossible") {
        num = generate_impossible_number(n);
    } else if (type == "min_erase_k") {
        int k = opt<int>("k", 1);
        num = generate_min_erase_k_number(n, k);
    } else if (type == "leading_zero_trap") {
