bool isSubsequence(const string& small, const string& large) {
    size_t pos = 0;
    for (char c : large) {
        if (pos < small.size() && c == small[pos]) {
            pos++;
        }
    }
    return pos == small.size();
}

bool isBeautiful(const string& m) {
    if (m.empty())
        return false;
    if (m == "0")
        return true;
    if (m[0] == '0')
        return false;
    int digitSum = 0;
    for (char c : m) {
        if (!isdigit(c))
            return false;
        digitSum += c - '0';
    }
    return digitSum % 3 == 0;
}

