        for (int i = 0; i < k; ++i) {
            xi[i] = min(1 + i * step, n);
        }
        sort(xi.begin(), xi.end());

        for (int i = 0; i < l; ++i) {
            ai[i] = rnd.next(1, 2);
        }

    } else if (type == "small_flips") {
        for (int i = 0; i < l; ++i) {
            ai[i] = rnd.next(1, 3);
        }
        k = rnd.next(1, 10);
        xi = generate_k_distinct_numbers(k, n);

    } else if (type == "large_flips") {
        for (int i = 0; i < l; ++i) {
