#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;
int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int k = opt<int>("k");
    int q = opt<int>("q");
    string t_tree = opt<string>("t_tree", "random");
    string t_colors = opt<string>("t_colors", "random");
    string t_queries = opt<string>("t_queries", "mixed");

    vector<pair<int, int>> edges;
    vector<int> deg(n+1, 0);

    // Generate the tree
    if (t_tree == "chain") {
        for (int i = 2; i <= n; ++i) {
            edges.push_back({i-1, i});
            deg[i-1]++;
            deg[i]++;
        }
    }
    else if (t_tree == "star") {
        for (int i = 2; i <= n; ++i) {
            edges.push_back({1, i});
            deg[1]++;
            deg[i]++;
        }
    }
    else if (t_tree == "balanced") {
        for (int i = 2; i <= n; ++i) {
            int parent = i / 2;
            edges.push_back({parent, i});
            deg[parent]++;
            deg[i]++;
        }
    }
    else if (t_tree == "random") {
        for (int i = 2; i <= n; ++i) {
            int parent = rnd.next(1, i-1);
            edges.push_back({parent, i});
            deg[parent]++;
            deg[i]++;
        }
        shuffle(edges.begin(), edges.end());
    }
    else {
        fprintf(stderr, "Invalid tree type\n");
        exit(1);
    }

    // Identify leaves
    vector<int> leaves;
    for (int i = 1; i <= n; ++i) {
        if (i == 1) continue; // Node 1 is not considered a leaf
        if (deg[i] == 1) {
            leaves.push_back(i);
        }
    }

    // s_i array
    vector<int> s(n+1, -1); // s[1..n], s[0] unused
    if (t_colors == "all_red") {
        for (int leaf : leaves) {
            s[leaf] = 0;
        }
    }
    else if (t_colors == "all_blue") {
        for (int leaf : leaves) {
            s[leaf] = 1;
        }
    }
    else if (t_colors == "alternating") {
        int c = 0;
        for (int leaf : leaves) {
            s[leaf] = c;
            c = 1 - c;
        }
    }
    else if (t_colors == "random") {
        for (int leaf : leaves) {
            s[leaf] = rnd.next(0,1);
        }
    }
    else {
        fprintf(stderr, "Invalid color type\n");
        exit(1);
    }

    // Output n and k
    printf("%d %d\n", n, k);

    // Output edges
    for (auto e : edges) {
        printf("%d %d\n", e.first, e.second);
    }

    // Output s_i array
    for (int i = 1; i <= n; ++i) {
        printf("%d%c", s[i], i==n?'\n':' ');
    }

    // Generate queries
    // We need to generate q queries
    // Depending on t_queries
    vector<int> internal_nodes;
    for (int i = 1; i <= n; ++i) {
        if (s[i] == -1) internal_nodes.push_back(i);
    }
    vector<string> queries;
    if (t_queries == "only_type1") {
        for (int i = 0; i < q; ++i) {
            int v = rnd.next(1, n);
            queries.push_back("1 " + to_string(v));
        }
    }
    else if (t_queries == "mixed") {
        for (int i = 0; i < q; ++i) {
            int type = rnd.next(1,3); // 1,2,3
            if (type == 1) {
                int v = rnd.next(1, n);
                queries.push_back("1 " + to_string(v));
            }
            else if (type == 2) {
                if (leaves.empty()) continue;
                int idx = rnd.next(0, (int)leaves.size()-1);
                int v = leaves[idx];
                int c = rnd.next(0,1);
                queries.push_back("2 " + to_string(v) + " " + to_string(c));
            }
            else if (type == 3) {
                int h = rnd.next(-n, n);
                queries.push_back("3 " + to_string(h));
            }
        }
    }
    else if (t_queries == "max_updates") {
        // Ensure that we have many updates
        for (int i = 0; i < q; ++i) {
            int type = rnd.next(2,3); // Only types 2 and 3
            if (type == 2) {
                if (leaves.empty()) continue;
                int idx = rnd.next(0, (int)leaves.size()-1);
                int v = leaves[idx];
                int c = rnd.next(0,1);
                queries.push_back("2 " + to_string(v) + " " + to_string(c));
            }
            else if (type == 3) {
                int h = rnd.next(-n, n);
                queries.push_back("3 " + to_string(h));
            }
        }
    }
    else {
        fprintf(stderr, "Invalid queries type\n");
        exit(1);
    }

    // Output q
    printf("%d\n", q);
    // Output queries
    for (string s : queries) {
        printf("%s\n", s.c_str());
    }

    return 0;
}

