    inf.readEoln();

    vector<int> parent(n + 1);
    for(int i = 1; i <= n; ++i)
        parent[i] = i;

    function<int(int)> find = [&](int x) {
        if(parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    };

    auto unite = [&](int x, int y) {
        x = find(x);
        y = find(y);
        ensuref(x != y, "The graph contains cycles, not a tree");
        parent[y] = x;
    };

    vector<int> degree(n + 1, 0);

    for(int i = 0; i < n - 1; ++i) {
        int u = inf.readInt(1, n, "u");
        inf.readSpace();
        int v = inf.readInt(1, n, "v");
        inf.readEoln();

        ensuref(u != v, "Self-loop detected at node %d", u);

        unite(u, v);

        degree[u]++;
        degree[v]++;
    }

    vector<int> s(n + 1);
    for(int i = 1; i <= n; ++i) {
        if(i > 1)
            inf.readSpace();
        s[i] = inf.readInt(-1, 1, "s_i");
    }
    inf.readEoln();

    for(int i = 1; i <= n; ++i) {
        if(i == 1 || degree[i] > 1) {
            ensuref(s[i] == -1, "Node %d is not a leaf, s[%d] must be -1", i, i);
        } else {
            ensuref(degree[i] == 1, "Node %d must be a leaf (degree == 1)", i);
            ensuref(s[i] == 0 || s[i] == 1, "Leaf node %d must have s[%d] = 0 or 1", i, i);
        }
    }

    int q = inf.readInt(1, 100000, "q");
    inf.readEoln();

    for(int i = 0; i < q; ++i) {
        int t = inf.readInt(1, 3, "t");
        if(t == 1) {
            inf.readSpace();
            int v = inf.readInt(1, n, "v");
            inf.readEoln();
        } else if(t == 2) {
            inf.readSpace();
            int v = inf.readInt(1, n, "v");
            inf.readSpace();
            int c = inf.readInt(0, 1, "c");
            inf.readEoln();
            ensuref(degree[v] == 1 && v != 1, "In query %d: Node %d is not a leaf", i+1, v);
        } else if(t == 3) {
            inf.readSpace();
            int h = inf.readInt(-n, n, "h");
            inf.readEoln();
        } else {
            ensuref(false, "Invalid query type %d at query %d", t, i+1);
        }
    }

    inf.readEof();
    return 0;
}

