    int n = opt<int>("n");
    int m = opt<int>("m", n - 1); // default to n - 1 if not provided
    string type = opt<string>("type", "random");

    if (n < 2 || n > 100000) {
        cerr << "Invalid n: " << n << endl;
        exit(1);
    }
    if (m < 1 || m > 200000) {
        cerr << "Invalid m: " << m << endl;
        exit(1);
    }
    if (m > n * (n - 1) / 2) {
        cerr << "Too many edges for the given n: " << m << endl;
        exit(1);
    }

    vector<pair<int, int>> edges;

    if (type == "chain") {
        // Generate a chain: nodes 1 to n, edges from i to i+1
        if (m != n - 1) {
            cerr << "For type chain, m must be n - 1" << endl;
            exit(1);
        }
        for (int i = 1; i <= n - 1; ++i) {
            edges.push_back({i, i + 1});
        }

    } else if (type == "star") {
        // Generate a star: node 1 is boss of all others
        if (m != n - 1) {
            cerr << "For type star, m must be n - 1" << endl;
            exit(1);
        }
        for (int i = 2; i <= n; ++i) {
            edges.push_back({1, i});
        }

    } else if (type == "layered") {
        // Divide nodes into layers
        int layers = opt<int>("layers", 10);
        if (layers < 1 || layers > n) {
            cerr << "Invalid number of layers: " << layers << endl;
            exit(1);
        }
        vector<vector<int>> layer_nodes(layers);
        for (int i = 1; i <= n; ++i) {
            int layer = (i - 1) * layers / n;
            layer_nodes[layer].push_back(i);
        }
        for (int i = 0; i < layers - 1 && (int)edges.size() < m; ++i) {
            for (int u : layer_nodes[i]) {
                for (int v : layer_nodes[i + 1]) {
                    if ((int)edges.size() < m) {
                        edges.push_back({u, v});
                    }
                }
            }
        }
        // If not enough edges, add more randomly between layers
        while ((int)edges.size() < m) {
            int l1 = rnd.next(0, layers - 2);
            int l2 = rnd.next(l1 + 1, layers - 1);
            int u = layer_nodes[l1][rnd.next(0, (int)layer_nodes[l1].size() - 1)];
            int v = layer_nodes[l2][rnd.next(0, (int)layer_nodes[l2].size() - 1)];
            edges.push_back({u, v});
        }
        // Remove duplicates and ensure uniqueness
        sort(edges.begin(), edges.end());
        edges.erase(unique(edges.begin(), edges.end()), edges.end());
        // Trim to size m
        if ((int)edges.size() > m) {
            edges.resize(m);
        }

    } else if (type == "random") {
        // Generate random DAG with conditions 1 ≤ a_i < b_i ≤ n, no cycles
        set<pair<int, int>> edge_set;
        int max_edges = n * (n - 1) / 2;
        if (m > max_edges) {
            cerr << "Cannot have more than " << max_edges << " edges in DAG with n = " << n << endl;
            exit(1);
        }
        while ((int)edge_set.size() < m) {
            int a = rnd.next(1, n - 1);
            int b = rnd.next(a + 1, n);
            edge_set.insert({a, b});
        }
        edges.assign(edge_set.begin(), edge_set.end());

    } else if (type == "bamboo") {
        // Generate a chain with additional edges
        if (m < n - 1) {
            cerr << "For type bamboo, m must be >= n - 1" << endl;
            exit(1);
        }
        for (int i = 1; i <= n - 1; ++i) {
            edges.push_back({i, i + 1});
        }
        set<pair<int, int>> edge_set(edges.begin(), edges.end());
        while ((int)edge_set.size() < m) {
            int u = rnd.next(1, n - 2);
            int v = rnd.next(u + 2, n);
            edge_set.insert({u, v});
        }
        edges.assign(edge_set.begin(), edge_set.end());
        // Ensure uniqueness and correct size
        sort(edges.begin(), edges.end());
        if ((int)edges.size() > m) {
            edges.resize(m);
        }

    } else {
        cerr << "Unknown type: " << type << endl;
        exit(1);
    }

    // Output n m
    printf("%d %d\n", n, m);
    // Output the edges
    for (int i = 0; i < (int)edges.size(); ++i) {
        printf("%d %d\n", edges[i].first, edges[i].second);
    }

    return 0;
}

