const int MAX_N = 100000;
const int MAX_M = 200000;

vector<vector<int>> adj;
vector<int> visited; // 0: unvisited, 1: visiting, 2: visited
bool hasCycle = false;

void dfs_iterative(int start) {
    stack<pair<int, size_t>> stk;
    stk.push({start, 0});
    visited[start] = 1; // visiting
    while (!stk.empty()) {
        int u = stk.top().first;
        size_t &i = stk.top().second;
        if (i < adj[u].size()) {
            int v = adj[u][i];
            i++;
            if (visited[v] == 0) {
                visited[v] = 1; // visiting
                stk.push({v, 0});
            } else if (visited[v] == 1) {
                // Cycle detected
                hasCycle = true;
                return;
            }
        } else {
            visited[u] = 2; // visited
            stk.pop();
        }
    }
}

