        cin >> r;
        if(r == 0)
            return 0;

        int w[2], h[2], x0[2], y0[2];
        vector<vector<int> > room[2];
        for(int i=0; i<2; ++i){
            cin >> w[i] >> h[i] >> x0[i] >> y0[i];
            room[i].assign(h[i]+2, vector<int>(w[i]+2, INF));
            for(int j=1; j<=h[i]; ++j){
                for(int k=1; k<=w[i]; ++k){
                    cin >> room[i][j][k];
                }
            }
        }

        vector<int> level[2];
        for(int i=0; i<2; ++i){
            level[i].resize(h[i]*w[i]+1, INF);
            level[i][0] = 0;
