int n, k;
int grid[5][51]; // The parking lot grid
map<int, pair<int, int>> carPosition; // Current position of each car
map<int, pair<int, int>> carParkingSpot; // Designated parking spots for each car

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    // Read input
    n = inf.readInt(1, 50, "n");
    k = inf.readInt(1, 2 * n, "k");

    // Initialize the grid and data structures
    for (int r = 1; r <= 4; ++r) {
        for (int c = 1; c <= n; ++c) {
            int x = inf.readInt(0, k, format("grid[%d][%d]", r, c).c_str());
            grid[r][c] = x;

            if (r == 1 || r == 4) {
                // Parking spots
                if (x > 0) {
                    carParkingSpot[x] = make_pair(r, c);
                }
            } else {
                // Initial positions
                if (x > 0) {
                    carPosition[x] = make_pair(r, c);
                }
            }
        }
    }

    // Read judge's answer
    int judgeM = ans.readInt(-1, 20000, "judge m");
    bool judgeImpossible = false;
    if (judgeM == -1) {
        judgeImpossible = true;
    }

    // Read contestant's answer
    int m = ouf.readInt(-1, 20000, "m");
    if (m == -1) {
        if (judgeImpossible) {
            quitf(_ok, "Contestant correctly claims impossible");
        } else {
            quitf(_wa, "Contestant claims impossible, but a solution exists");
        }
    } else {
        if (m < 0 || m > 20000) {
            quitf(_wa, "Invalid number of moves m: %d", m);
        }
        if (judgeImpossible) {
            quitf(_fail, "Contestant provides a solution, but judge says impossible");
        }

        // Simulate the moves
        int gridOcc[5][51]; // Occupancy grid
        memset(gridOcc, 0, sizeof(gridOcc));
        for (auto &entry : carPosition) {
            int car = entry.first;
            int r = entry.second.first;
            int c = entry.second.second;
            gridOcc[r][c] = car;
        }

        for (int moveNum = 1; moveNum <= m; ++moveNum) {
            int car = ouf.readInt(1, k, format("move %d car", moveNum).c_str());
            int r = ouf.readInt(1, 4, format("move %d r", moveNum).c_str());
            int c = ouf.readInt(1, n, format("move %d c", moveNum).c_str());

            // Validate move
            if (carPosition.find(car) == carPosition.end()) {
                quitf(_wa, "Move %d: Car %d does not exist", moveNum, car);
            }
            int r0 = carPosition[car].first;
            int c0 = carPosition[car].second;

            // Check adjacency
            if (abs(r - r0) + abs(c - c0) != 1) {
                quitf(_wa, "Move %d: Car %d moves to non-adjacent position (%d,%d)", moveNum, car, r, c);
            }

            // Check if destination is empty
            if (gridOcc[r][c] != 0) {
                quitf(_wa, "Move %d: Destination (%d,%d) is not empty", moveNum, r, c);
            }

            // Check parking spot constraints
            if ((r == 1 || r == 4) && carParkingSpot[car] != make_pair(r, c)) {
                quitf(_wa, "Move %d: Car %d cannot enter parking spot (%d,%d) which is not its own", moveNum, car, r, c);
            }

            // Apply the move
            gridOcc[r0][c0] = 0;
            gridOcc[r][c] = car;
            carPosition[car] = make_pair(r, c);
        }

        // Check final positions
        for (int car = 1; car <= k; ++car) {
            if (carPosition[car] != carParkingSpot[car]) {
                quitf(_wa, "After all moves, car %d is at (%d,%d), but its parking spot is at (%d,%d)",
                      car, carPosition[car].first, carPosition[car].second,
                      carParkingSpot[car].first, carParkingSpot[car].second);
            }
        }

        quitf(_ok, "Correct solution with %d moves", m);
    }
}

