        for (int i = 0; i < n; ++i) {
            grid[i] = string(m, '0');
        }
    }
    else if (type == "full") {
        // All cells are pre-colored, ensuring valid coloring
        grid.assign(n, string(m, '0'));
        for (int i = 0; i < n; ++i) {
            grid[i] = string(m, '0');
            for (int j = 0; j < m; ++j) {
                grid[i][j] = '0' + ((i % 2) * 2 + (j % 2) + 1); // Colors 1-4
            }
        }
    }
    else if (type == "checkerboard") {
        // Valid checkerboard pattern with four colors
        grid.assign(n, string(m, '0'));
        for (int i = 0; i < n; ++i) {
            grid[i] = string(m, '0');
            for (int j = 0; j < m; ++j) {
                grid[i][j] = '0' + ((i % 2) * 2 + (j % 2) + 1); // Colors 1-4
            }
        }
    }
    else if (type == "conflict") {
        // Create a grid where pre-colored cells are in conflict so that no solution exists
        grid.assign(n, string(m, '0'));
        if (n >= 2 && m >= 2) {
            int x = n / 2;
            int y = m / 2;
            grid[x][y] = '1'; // Color 1

            // Now color all neighbors with the same color
            for (int dx = -1; dx <= 1; ++dx) {
                int ni = x + dx;
                if (ni < 0 || ni >= n) continue;
                for (int dy = -1; dy <= 1; ++dy) {
                    int nj = y + dy;
                    if (nj < 0 || nj >= m) continue;
                    if (dx == 0 && dy == 0) continue;
                    grid[ni][nj] = '1'; // Same color as center
                }
            }
        }
    }
    else if (type == "diagconflict") {
        // Conflict in diagonally adjacent cells
        grid.assign(n, string(m, '0'));
        if (n >= 2 && m >= 2) {
            grid[0][0] = '1'; // Color 1
            grid[1][1] = '1'; // Diagonally adjacent with same color
        }
    }
    else if (type == "twocolors") {
        // Use two colors in a checkerboard pattern (invalid due to diagonals)
        grid.assign(n, string(m, '0'));
        for (int i = 0; i < n; ++i) {
            grid[i] = string(m, '0');
            for (int j = 0; j < m; ++j) {
                grid[i][j] = '0' + ((i + j) % 2 + 1); // Colors 1 and 2
            }
        }
    }
    else if (type == "random") {
        // Randomly pre-color some cells with random colors
        grid.assign(n, string(m, '0'));
        int num_precolored = rnd.next(0, n * m);
        for (int k = 0; k < num_precolored; ++k) {
            int i = rnd.next(0, n - 1);
            int j = rnd.next(0, m - 1);
            int color = rnd.next(1, 4);
            grid[i][j] = '0' + color;
        }
    }
    else {
        // Default to empty grid
        grid.assign(n, string(m, '0'));
    }

    // Now output n and m
    printf("%d %d\n", n, m);
    // Output the grid
    for (int i = 0; i < n; ++i) {
        printf("%s\n", grid[i].c_str());
    }

