using namespace std;

void generate_possible(int n, int m) {
    vector<vector<int>> S(n, vector<int>(m));
    int base = rnd.next(1, (int)1e9 - n * m * 10);
    int delta = rnd.next(1, 10); // Step between numbers to ensure strictly increasing
    for (int i = 0; i < n; ++i) {
        int row_base = base + i * delta * 10;
        for (int j = 0; j < m; ++j) {
            S[i][j] = row_base + j * delta * 10 + rnd.next(1, delta);
        }
    }

    // Initialize A and B matrices from S
    vector<vector<int>> A(n, vector<int>(m)), B(n, vector<int>(m));
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            A[i][j] = S[i][j];
            B[i][j] = S[i][j] + rnd.next(1, delta); // Slightly different to ensure swapping helps
        }

    // Randomly swap elements with a chance
    for (int i = 0; i < n; ++i)
        for (int j = 0; j < m; ++j) {
            if (rnd.next(0, 1)) {
                swap(A[i][j], B[i][j]);
            }
        }
    // Output n and m
    printf("%d %d\n", n, m);
    // Output A
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            printf("%d", A[i][j]);
            if (j + 1 < m) printf(" ");
        }
        printf("\n");
    }
    // Output B
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            printf("%d", B[i][j]);
            if (j +1 < m) printf(" ");
        }
        printf("\n");
    }
}

void generate_impossible(int n, int m) {
    vector<vector<int>> A(n, vector<int>(m));
    vector<vector<int>> B(n, vector<int>(m));

    // Create an unavoidable conflict in the first row
    // Set first row elements to same values in decreasing order
    int val = rnd.next((int)1e9 - 1000, (int)1e9);
    for (int j = 0; j < m; ++j) {
        A[0][j] = val - j;
        B[0][j] = val - j;
    }

    // For other rows, fill with increasing values
    int counter = val + 1;
    for (int i = 1; i < n; ++i) {
        int row_base = counter + i * 1000;
        for (int j = 0; j < m; ++j) {
            A[i][j] = row_base + j * 10;
            B[i][j] = row_base + j * 10 + rnd.next(1, 9);
        }
    }

    // Output n and m
    printf("%d %d\n", n, m);
    // Output A
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            printf("%d", A[i][j]);
            if (j +1 < m) printf(" ");
        }
        printf("\n");
    }
    // Output B
    for (int i = 0; i < n; ++i) {
        for (int j = 0; j < m; ++j) {
            printf("%d", B[i][j]);
            if (j +1 < m) printf(" ");
        }
        printf("\n");
    }
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int m = opt<int>("m");
    string type = opt<string>("type", "possible");

    if (type == "possible") {
        // Generate a test case where it's possible
        generate_possible(n, m);
    } else if (type == "impossible") {
        // Generate a test case where it's impossible
        generate_impossible(n, m);
