#include <bits/stdc++.h>
using namespace std;
template <typename T>
class BIT {
 public:
  T b[500000 + 1];
  int n;

 private:
 public:
  void init(int num);
  T sum(int i);
  void add(int i, T x);

 private:
};
template <typename T>
void BIT<T>::init(int num) {
  n = num;
  for (int i = 0; i <= n; i++) {
    b[i] = 0;
  }
  return;
}
template <typename T>
T BIT<T>::sum(int i) {
  T s = 0;
  for (; i > 0; i -= i & -i) {
    s += b[i];
  }
  return s;
}
template <typename T>
void BIT<T>::add(int i, T x) {
  for (; i <= n; i += i & -i) {
    b[i] += x;
  }
  return;
}
int N, K;
int P[500000];
int cnt_less[500000 + 1];
long long int sum_unused, sum_cnt_more;
long long int fac[500000 + 1];
BIT<int> bit;
long long int ans;
int main() {
  long long int t1, t2, cur_k;
  long long int inv2 = (1000000007LL + 1) / 2;
  scanf("%d", &N);
  fill(cnt_less, cnt_less + N, 1);
  cnt_less[0] = 0;
  fac[0] = 1;
  for (int i = 1; i <= N; i++) {
    fac[i] = (fac[i - 1] * i) % 1000000007LL;
  }
  bit.init(N);
  sum_unused = N * (N + 1) / 2 % 1000000007LL;
  for (int i = 0; i < N; i++) {
    scanf("%d", &P[i]);
    if (P[i] == 0) {
      K++;
    } else {
      cnt_less[P[i]] = 0;
      sum_unused = (sum_unused - P[i] + 1000000007LL) % 1000000007LL;
    }
  }
  for (int i = 1; i <= N; i++) {
    cnt_less[i] += cnt_less[i - 1];
  }
  cur_k = 0;
  sum_cnt_more = 0;
  ans = 0;
  for (int i = 0; i < N; i++) {
    if (P[i] == 0) {
      t1 = (sum_unused * fac[K - 1] - fac[K] + 1000000007LL) % 1000000007LL;
      t2 = (sum_cnt_more * fac[K - 1] % 1000000007LL +
            cur_k * fac[K] % 1000000007LL * inv2 % 1000000007LL) %
           1000000007LL;
      cur_k++;
    } else {
      t1 = (P[i] - 1) * fac[K] % 1000000007LL;
      t2 = ((long long int)bit.sum(P[i]) * fac[K] % 1000000007LL +
            cur_k * cnt_less[P[i] - 1] % 1000000007LL * fac[max(K - 1, 0)] %
                1000000007LL) %
           1000000007LL;
      sum_cnt_more = (sum_cnt_more + K - cnt_less[P[i]]) % 1000000007LL;
      bit.add(P[i], 1);
    }
    ans = (ans + (t1 - t2 + 1000000007LL) % 1000000007LL * fac[N - 1 - i]) %
          1000000007LL;
  }
  ans = (ans + fac[K]) % 1000000007LL;
  printf("%lld\n", ans);
  return 0;
}

