            P[i] = nums[i - k];

        // First k positions of P are zero

    } else if (type == "zeros_at_end") {
        // Last k positions are zero
        int k = opt<int>("k", N/2);
        if (k > N) k = N;

        vector<int> nums;
        for (int i = 1; i <= N; ++i)
            nums.push_back(i);

        shuffle(nums.begin(), nums.end());

        for (int i = 0; i < N - k; ++i)
            P[i] = nums[i];

        // Last k positions of P are zero

    } else if (type == "zeros_in_middle") {
        // Zeros from position l to r (inclusive)
        int l = opt<int>("l", N/4);
        int r = opt<int>("r", 3*N/4);
        if (l < 0) l = 0;
        if (r >= N) r = N - 1;
        if (l > r) swap(l, r);

        vector<int> nums;
        for (int i = 1; i <= N; ++i)
            nums.push_back(i);

        shuffle(nums.begin(), nums.end());

        int idx = 0;

        for (int i = 0; i < N; ++i) {

            if (i >= l && i <= r) {
                // P_i = 0
                P[i] = 0;
            } else {
                P[i] = nums[idx++];
            }
        }

    } else if (type == "one_zero") {
        // Exactly one P_i is zero
        int zero_pos = rnd.next(0, N - 1);

        vector<int> nums;
        for (int i = 1; i <= N; ++i)
            nums.push_back(i);

        nums.erase(nums.begin() + zero_pos);

        for (int i = 0, idx = 0; i < N; ++i) {
            if (i == zero_pos) {
                P[i] = 0;
            } else {
                P[i] = nums[idx++];
            }
        }

    } else if (type == "one_non_zero") {
        // Exactly one P_i is non-zero
        int non_zero_pos = rnd.next(0, N - 1);

        vector<int> nums;
        for (int i = 1; i <= N; ++i)
            nums.push_back(i);

        int val = nums[rnd.next(0, N - 1)];

        P[non_zero_pos] = val;

    } else if (type == "increasing") {
        // P_i = i
        for (int i = 0; i < N; ++i)
            P[i] = i + 1;

    } else if (type == "decreasing") {
        // P_i = N - i
        for (int i = 0; i < N; ++i)
            P[i] = N - i;

    } else if (type == "maximal_perm") {
        // P_i is lexicographically largest permutation
        for (int i = 0; i < N; ++i)
            P[i] = N - i;

    } else if (type == "minimal_perm") {
        // P_i is lexicographically smallest permutation
        for (int i = 0; i < N; ++i)
            P[i] = i + 1;

    } else if (type == "random_half_zero") {
        // About half zeros, half non-zeros

        vector<int> nums;
        for (int i = 1; i <= N; ++i)
            nums.push_back(i);

        shuffle(nums.begin(), nums.end());

        int idx = 0;
        set<int> used_numbers;

        for (int i = 0; i < N; ++i) {
            if (rnd.next(0, 1) == 0) {
