                P[i] = 0;
            } else {
                // Non-zero
                int val;
                do {
                    if (idx >= N) break;
                    val = nums[idx++];
                } while (used_numbers.count(val));

                if (used_numbers.count(val)) {
                    P[i] = 0;
                } else {
                    P[i] = val;
                    used_numbers.insert(val);
                }
            }
        }

    } else {
        // Random P_i ∈ [0, N], non-zero P_i are distinct
        // Try to have approximately half zeros
        int zero_prob = opt<int>("zero_prob", 2); // 1 in zero_prob chance of being non-zero

        vector<int> nums;
        for (int i = 1; i <= N; ++i)
            nums.push_back(i);

        shuffle(nums.begin(), nums.end());

        int idx = 0;

        set<int> used_numbers;

        for (int i = 0; i < N; ++i) {
            if (rnd.next(0, zero_prob - 1) == 0) {
                // Non-zero
                int val;
                do {
