                    val = nums[idx++];
                } while (used_numbers.count(val));

                if (used_numbers.count(val)) {
                    P[i] = 0;
                } else {
                    P[i] = val;
                    used_numbers.insert(val);
                }

            } else {
                // Zero
                P[i] = 0;
            }
        }
    }

    // Ensure that non-zero P_i are distinct and in [1,N]
    set<int> used_vals;
    for (int i = 0; i < N; ++i) {
        if (P[i] != 0) {
            if (P[i] < 1 || P[i] > N || used_vals.count(P[i])) {
