using namespace std;
int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int m = opt<int>("m", n);
    string perm_a_type = opt<string>("perm_a_type", "random");
    string perm_b_type = opt<string>("perm_b_type", "random");
    string query_type = opt<string>("query_type", "mixed");
    int num_type1 = opt<int>("num_type1", -1);
    int num_type2 = opt<int>("num_type2", -1);

    // Ensure m is within constraints
    m = min(m, 200000);

    // Generate permutations a and b
    vector<int> a(n), b(n);

    auto generate_permutation = [&](vector<int>& p, string type) {
        if (type == "random") {
            for (int i = 0; i < n; ++i) p[i] = i + 1;
            shuffle(p.begin(), p.end());
        } else if (type == "sorted" || type == "identity") {
            for (int i = 0; i < n; ++i) p[i] = i + 1;
        } else if (type == "reversed") {
            for (int i = 0; i < n; ++i) p[i] = n - i;
        } else if (type == "same") {
            // "same" only applies to perm_b_type
            // Copy from a
            p = a;
        } else if (type == "almost_sorted") {
            // Sorted with a few swaps
            for (int i = 0; i < n; ++i) p[i] = i + 1;
            int swaps = n / 100; // Swap 1% of elements
            for (int i = 0; i < swaps; ++i) {
                int x = rnd.next(0, n - 1);
                int y = rnd.next(0, n - 1);
                swap(p[x], p[y]);
            }
        } else {
            // Default to random
            for (int i = 0; i < n; ++i) p[i] = i + 1;
            shuffle(p.begin(), p.end());
        }
    };

    generate_permutation(a, perm_a_type);
    generate_permutation(b, perm_b_type);

    // Output n m
    printf("%d %d\n", n, m);

    // Output permutations a and b
    for (int i = 0; i < n; ++i)
        printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');
    for (int i = 0; i < n; ++i)
        printf("%d%c", b[i], i + 1 == n ? '\n' : ' ');

    // Generate queries
    vector<string> queries;
    if (num_type1 == -1 && num_type2 == -1) {
        // num_type1 and num_type2 are not specified, use query_type
        if (query_type == "all_type1") {
            num_type1 = m;
            num_type2 = 0;
        } else if (query_type == "all_type2") {
            num_type1 = 1; // At least one type 1 query
            num_type2 = m - 1;
        } else if (query_type == "mixed") {
            num_type1 = rnd.next(1, m);
            num_type2 = m - num_type1;
        } else {
            // Default to mixed
            num_type1 = rnd.next(1, m);
            num_type2 = m - num_type1;
        }
    } else {
        // num_type1 and num_type2 are specified
        if (num_type1 == -1) num_type1 = m - num_type2;
        if (num_type2 == -1) num_type2 = m - num_type1;
        if (num_type1 + num_type2 != m) {
            // Adjust num_type1 or num_type2
            num_type1 = m - num_type2;
        }
    }
    // Ensure there is at least one type 1 query
    if (num_type1 == 0) num_type1 = 1, num_type2 = m - 1;

    // Generate the queries
    vector<int> q_types(m);
    for (int i = 0; i < m; ++i) q_types[i] = (i < num_type1) ? 1 : 2;
    shuffle(q_types.begin(), q_types.end());

    for (int i = 0; i < m; ++i) {
        int q_type = q_types[i];
        if (q_type == 1) {
            // Generate type 1 query
            int l_a = rnd.next(1, n);
            int r_a = rnd.next(l_a, n);
            int l_b = rnd.next(1, n);
            int r_b = rnd.next(l_b, n);
            queries.push_back("1 " + to_string(l_a) + " " + to_string(r_a) + " " + to_string(l_b) + " " + to_string(r_b));
        } else {
            // Generate type 2 query
            int x = rnd.next(1, n);
            int y = rnd.next(1, n);
            while (x == y) y = rnd.next(1, n);
            queries.push_back("2 " + to_string(x) + " " + to_string(y));
        }
    }

    // Output queries
    for (const auto& q : queries) {
        printf("%s\n", q.c_str());
    }

    return 0;
}

