        row2 = randomString(n);
        word = randomString(m);
    } else if (type == "same_letters") {
        char ch = 'a' + rnd.next(26);
        row1 = string(n, ch);
        row2 = string(n, ch);
        word = string(m, ch);
    } else if (type == "impossible") {
        // Field letters from 'a' to 'y', word consists of 'z's
        row1 = row2 = "";
        for (int i = 0; i < n; ++i) {
            row1 += (char)('a' + rnd.next(25)); // 'a' to 'y'
            row2 += (char)('a' + rnd.next(25));
        }
        word = string(m, 'z'); // 'z'
    } else if (type == "min_paths") {
        // We need to ensure m is reasonable (<=26)
        if (m > 26) m = 26;
        string letters;
        for (char c = 'a'; c < 'a' + m; ++c)
            letters += c;
        word = letters;
        // Generate field with unique path matching the word
        // Fill other positions with letters not in word
        vector<char> other_letters;
        for (char c = 'a' + m; c <= 'z'; ++c)
            other_letters.push_back(c);
        if (other_letters.empty()) {
            // We cannot have letters not in word
            // So we reduce m
            m = 20;
            letters = "";
            for (char c = 'a'; c < 'a' + m; ++c)
                letters += c;
            word = letters;
            other_letters.clear();
            for (char c = 'a' + m; c <= 'z'; ++c)
                other_letters.push_back(c);
        }
        row1 = "";
        row2 = "";
        int row = 0;
        for (int i = 0; i < n; ++i) {
            if (i < m) {
                if (row == 0) {
                    row1 += word[i];
                    row2 += other_letters[rnd.next(other_letters.size())];
                } else {
                    row1 += other_letters[rnd.next(other_letters.size())];
                    row2 += word[i];
                }
                row = 1 - row;
            } else {
                row1 += other_letters[rnd.next(other_letters.size())];
                row2 += other_letters[rnd.next(other_letters.size())];
            }
        }
    } else if (type == "long_word") {
