    string type = opt<string>("type", "random");
    int max_m = opt<int>("max_m", 1000000000);
    int min_m = opt<int>("min_m", 1);

    assert(1 <= n && n <= 1000);
    assert(1 <= min_m && min_m <= max_m && max_m <= 1000000000);

    vector<int> m(n);
    if (type == "random") {
        for (int i = 0; i < n; ++i) {
            m[i] = rnd.next(min_m, max_m);
        }
    } else if (type == "max_limits") {
        for (int i = 0; i < n; ++i) {
            m[i] = max_m;
        }
    } else if (type == "min_limits") {
        for (int i = 0; i < n; ++i) {
            m[i] = min_m;
        }
    } else if (type == "increasing") {
        int delta = (max_m - min_m) / max(1, n - 1);
        for (int i = 0; i < n; ++i) {
            m[i] = min_m + delta * i;
            if (m[i] > max_m) m[i] = max_m;
        }
    } else if (type == "decreasing") {
        int delta = (max_m - min_m) / max(1, n - 1);
        for (int i = 0; i < n; ++i) {
            m[i] = max_m - delta * i;
            if (m[i] < min_m) m[i] = min_m;
        }
    } else if (type == "hill") {
        int mid = n / 2;
        int delta = (max_m - min_m) / max(1, mid);
        for (int i = 0; i < n; ++i) {
            if (i <= mid) {
                m[i] = min_m + delta * i;
            } else {
                m[i] = m[n - i - 1];  // Symmetric
            }
            m[i] = min(max(m[i], min_m), max_m);
        }
    } else if (type == "valley") {
        int mid = n / 2;
        int delta = (max_m - min_m) / max(1, mid);
        for (int i = 0; i < n; ++i) {
            if (i <= mid) {
                m[i] = max_m - delta * i;
            } else {
                m[i] = m[n - i - 1];  // Symmetric
            }
            m[i] = min(max(m[i], min_m), max_m);
        }
    } else if (type == "same") {
        int value = opt<int>("value", max_m);
        assert(min_m <= value && value <= max_m);
        for (int i = 0; i < n; ++i) {
            m[i] = value;
        }
    } else if (type == "zigzag") {
        for (int i = 0; i < n; ++i) {
            m[i] = (i % 2 == 0) ? min_m : max_m;
        }
    } else {
        // Default to random if unknown type
        for (int i = 0; i < n; ++i) {
            m[i] = rnd.next(min_m, max_m);
        }
    }
    // Output
    printf("%d\n", n);
    for (int i = 0; i < n; ++i) {
        printf("%d%c", m[i], i == n - 1 ? '\n' : ' ');
    }
    return 0;
}

