    for (int i = 0; i < n; i++) {
        jury_total += jury_a[i];
    }
    // Read participant's answer
    for (int i = 0; i < n; i++) {
        if (ouf.seekEof())
            quitf(_wa, "Expected %d numbers, but found less", n);
        part_a[i] = ouf.readLong(1, m[i], format("participant_a[%d]", i+1).c_str());
    }
    if (!ouf.seekEof())
        quitf(_wa, "Expected only %d numbers, but found more", n);
    // Check the 'no local minima' constraint
    left_max[0] = 0;
    for (int i = 0; i < n; i++) {
        left_max[i+1] = max(left_max[i], part_a[i]);
    }
    right_max[n] = 0;
    for (int i = n - 1; i >= 0; i--) {
        right_max[i] = max(right_max[i+1], part_a[i]);
    }
    for (int i = 0; i < n; i++) {
        if (part_a[i] < left_max[i] && part_a[i] < right_max[i+1]) {
            quitf(_wa, "Building at position %d is shorter than taller buildings on both sides", i+1);
        }
    }
    // Compute participant's total
    long long part_total = 0;
    for (int i = 0; i < n; i++) {
        part_total += part_a[i];
    }
    if (part_total > jury_total) {
        quitf(_fail, "Participant has a better total: participant_total = %lld, jury_total = %lld", part_total, jury_total);
    }
    else if (part_total == jury_total) {
        quitf(_ok, "Correct, total = %lld", part_total);
    }
    else {
        quitf(_wa, "Participant's total is less than optimal: participant_total = %lld, jury_total = %lld", part_total, jury_total);
    }
}

