      }
  }
  void acc(int a) {
    for (int i = 0; a; i = a, a = e[a].f) splay(a), e[a].s[1] = i, pup(a);
  }
  void evert(int a) {
    acc(a), splay(a);
    e[a].rev ^= 1, swap(e[a].s[0], e[a].s[1]);
