        fprintf(stderr, "Invalid number of edges: m must be between n-1 and min(n*(n-1)/2, 200000).\n");
        return 1;
    }

    vector<pair<int, int>> edges;
    set<pair<int, int>> edge_set;

    if (type == "tree") {
        // Generate a random tree
