            int v = i + 1;
            edges.push_back({u, v});
            edge_set.insert({min(u, v), max(u, v)});
        }
    } else if (type == "cycle") {
        // Generate a cycle
        for (int i = 1; i <= n; ++i) {
            int u = i;
            int v = i % n + 1;
            edges.push_back({u, v});
            edge_set.insert({min(u, v), max(u, v)});
        }
