        // Create two connected components and connect them with bridges
        int n1 = n / 2;
        int n2 = n - n1;
        // First component
        vector<int> vertices1(n1);
        for (int i = 0; i < n1; ++i) vertices1[i] = i + 1;
        for (int i = 1; i < n1; ++i) {
            int u = vertices1[i - 1];
            int v = vertices1[i];
            edges.push_back({u, v});
            edge_set.insert({min(u, v), max(u, v)});
        }
        // Second component
        vector<int> vertices2(n2);
        for (int i = 0; i < n2; ++i) vertices2[i] = n1 + i + 1;
        for (int i = 1; i < n2; ++i) {
            int u = vertices2[i - 1];
            int v = vertices2[i];
            edges.push_back({u, v});
            edge_set.insert({min(u, v), max(u, v)});
        }
        // Connect components with bridges
        int bridges = m - (n - 2);
        for (int i = 0; i < bridges; ++i) {
            int u = vertices1[rnd.next(0, n1 - 1)];
            int v = vertices2[rnd.next(0, n2 - 1)];
            if (edge_set.count({min(u, v), max(u, v)})) continue;
            edges.push_back({u, v});
            edge_set.insert({min(u, v), max(u, v)});
        }
    } else if (type == "random") {
        // Generate a random connected graph
        // Start with a tree
        vector<int> parent(n);
        for (int i = 1; i < n; ++i) {
            parent[i] = rnd.next(0, i - 1);
            int u = i + 1;
            int v = parent[i] + 1;
            edges.push_back({u, v});
            edge_set.insert({min(u, v), max(u, v)});
