            if (edge_set.count({min(u, v), max(u, v)})) continue;
            edges.push_back({u, v});
            edge_set.insert({min(u, v), max(u, v)});
        }
    } else {
        fprintf(stderr, "Invalid type specified.\n");
        return 1;
    }

    // Assign random weights
    vector<int> weights(edges.size());
    for (size_t i = 0; i < edges.size(); ++i) {
        weights[i] = rnd.next(1, 1000000000);
    }

