    is_prime[0] = is_prime[1] = false;
    for(int i = 2; i <= n; ++i){
        if(is_prime[i]){
            primes.push_back(i);
            for(int j = i*2; j <= n; j += i){
                is_prime[j] = false;
            }
        }
    }
}

void compute_special_primes(int n) {
    compute_primes(n);
    set<int> prime_set(primes.begin(), primes.end());
    for(int i = 0; i+1 < primes.size(); ++i) {
        int candidate = primes[i] + primes[i+1] + 1;
        if(candidate <= n && prime_set.count(candidate)) {
            special_primes.push_back(candidate);
        }
    }
