        } else if (type == "alternating") {
            for (int i = 0; i < K; i++) {
                s[i] = (i % 2 == 0) ? 0 : 50;
            }
        } else if (type == "increasing") {
            for (int i = 0; i < K; i++) {
                s[i] = i % 51; // s_i from 0 to 50
            }
        } else if (type == "decreasing") {
            for (int i = 0; i < K; i++) {
                s[i] = 50 - (i % 51);
            }
        } else if (type == "random") {
            for (int i = 0; i < K; i++) {
                s[i] = rnd.next(0, 50);
            }
        } else {
            // Default to random
