bool cmp(const pair<int, list<int>::iterator> &lhs,
         const pair<int, list<int>::iterator> &rhs) {
  return lhs.first < rhs.first;
}
int main() {
  list<int> l;
  int N;
  scanf("%d", &N);
  for (int i = 0; i < N; i++) {
    int x;
    scanf("%d", &x);
    l.push_back(x);
  }
  vector<pair<int, list<int>::iterator> > v;
  for (auto it = l.begin(); it != l.end(); it++)
    v.push_back(make_pair(*it, it));
  sort(v.begin(), v.end(), cmp);
  long long int total = 0;
  for (int i = 0; i < v.size(); i++) {
    auto it = v[i].second;
    if (it == l.begin() || it == --l.end()) continue;
    auto itp = it, itn = it;
    itp--;
    itn++;
    if (*it <= *itp && *it <= *itn) {
      l.erase(it);
      total += min(*itp, *itn);
      v[i].first = 0;
    }
  }
  reverse(v.begin(), v.end());
  for (int i = 0; i < v.size(); i++) {
    if (v[i].first == 0) continue;
    auto it = v[i].second;
    if (it == l.begin() || it == --l.end()) continue;
    auto itp = it, itn = it;
    itp--;
    itn++;
    l.erase(it);
    total += min(*itp, *itn);
  }
  printf("%lld\n", total);
  return 0;
}

