    vector<int> a(n);

    if (type == "random") {
        for (int i = 0; i < n; ++i)
            a[i] = rnd.next(min_a, max_a);
    } else if (type == "increasing") {
        int delta = max(1, (max_a - min_a) / max(1, n - 1));
        for (int i = 0; i < n; ++i)
            a[i] = min_a + i * delta;
    } else if (type == "decreasing") {
        int delta = max(1, (max_a - min_a) / max(1, n - 1));
        for (int i = 0; i < n; ++i)
            a[i] = max_a - i * delta;
    } else if (type == "constant") {
        int val = rnd.next(min_a, max_a);
        for (int i = 0; i < n; ++i)
            a[i] = val;
    } else if (type == "alternating") {
        int val1 = min_a;
        int val2 = max_a;
        for (int i = 0; i < n; ++i)
            a[i] = (i % 2 == 0) ? val1 : val2;
    } else if (type == "all_ones") {
        for (int i = 0; i < n; ++i)
            a[i] = 1;
    } else if (type == "all_max") {
        for (int i = 0; i < n; ++i)
            a[i] = max_a;
    } else if (type == "peak") {
        int mid = n / 2;
        int delta = max(1, (max_a - min_a) / max(1, mid));
        for (int i = 0; i < n; ++i) {
            if (i <= mid)
                a[i] = min_a + i * delta;
            else
                a[i] = min_a + (n - 1 - i) * delta;
        }
    } else if (type == "valley") {
        int mid = n / 2;
        int delta = max(1, (max_a - min_a) / max(1, mid));
        for (int i = 0; i < n; ++i) {
            if (i <= mid)
                a[i] = max_a - i * delta;
            else
                a[i] = max_a - (n - 1 - i) * delta;
        }
    } else if (type == "zigzag") {
        int delta = max(1, (max_a - min_a) / max(1, n / 2));
        bool up = true;
        a[0] = rnd.next(min_a, max_a);
        for (int i = 1; i < n; ++i) {
            if (up) {
                a[i] = min(a[i-1] + delta, max_a);
            } else {
                a[i] = max(a[i-1] - delta, min_a);
            }
            up = !up;
        }
    } else {
        fprintf(stderr, "Unknown type: %s\n", type.c_str());
        return -1;
    }

    // Output n
    printf("%d\n", n);
    // Output array
    for (int i = 0; i < n; ++i) {
        printf("%d", a[i]);
        if (i + 1 < n) printf(" ");
