        quitf(_fail, "Input n is not an odd integer"); // Should not happen since input guarantees n is odd
    }

    // Read the contestant's output
    vector<vector<int>> mat(n, vector<int>(n));
    set<int> used_numbers;
    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            mat[i][j] = ouf.readInt(1, n * n,
                format("mat[%d][%d]", i + 1, j + 1).c_str());
            if (used_numbers.count(mat[i][j])) {
                ouf.quitf(_wa, "Number %d used more than once", mat[i][j]);
            } else {
                used_numbers.insert(mat[i][j]);
            }
        }
    }

    // Verify that all numbers from 1 to n^2 are used exactly once
    if ((int)used_numbers.size() != n * n) {
        ouf.quitf(_wa, "Not all numbers from 1 to %d are used", n * n);
    }

    // Check the sums of rows
    for (int i = 0; i < n; i++) {
        long long sum = 0;
        for (int j = 0; j < n; j++) {
            sum += mat[i][j];
        }
        if (sum % 2 == 0) {
            ouf.quitf(_wa, "Sum of row %d is not odd", i + 1);
        }
    }

    // Check the sums of columns
    for (int j = 0; j < n; j++) {
        long long sum = 0;
        for (int i = 0; i < n; i++)
            sum += mat[i][j];
        if (sum % 2 == 0) {
            ouf.quitf(_wa, "Sum of column %d is not odd", j + 1);
        }
    }

    // Check sums of both main diagonals
    long long sum_main_diag = 0;
    for (int i = 0; i < n; i++)
        sum_main_diag += mat[i][i];
    if (sum_main_diag % 2 == 0) {
        ouf.quitf(_wa, "Sum of main diagonal is not odd");
    }

    long long sum_anti_diag = 0;
    for (int i = 0; i < n; i++)
        sum_anti_diag += mat[i][n - 1 - i];
    if (sum_anti_diag % 2 == 0) {
        ouf.quitf(_wa, "Sum of anti-diagonal is not odd");
    }

    // All checks passed
    quitf(_ok, "Correct answer");
}

