        shuffle(points.begin(), points.end());
        vector<int> endpoints(points.begin(), points.begin() + 2*k);

        // Shuffle the endpoints to get random pairs
        shuffle(endpoints.begin(), endpoints.end());

        for (int i = 0; i < 2*k; i += 2) {
            int x = endpoints[i];
            int y = endpoints[i+1];
            chords.emplace_back(x, y);
        }
    } else if (type == "consecutive") {
        // Pair up consecutive points
        for (int i = 0; i < 2*k; i += 2) {
            int x = points[i];
            int y = points[(i+1) % (2*n)];
            chords.emplace_back(x, y);
