          d[e.to] = d[v] + e.cost;
          que.emplace(d[e.to], e.to);
        }
      }
    }
  }
  void warshall_floyd(long long** w) {
    for (long long i = 0; i < V; i++) {
      for (long long j = 0; j < V; j++) {
        w[i][j] = LLONG_MAX / 2;
      }
    }
    for (long long i = 0; i < V; i++) {
      for (const auto& e : vertices[i].edges) {
