#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
  This generator produces a single test case for the "street illumination" problem.

  Usage example:
    ./gen -n 10 -m 3 -k 5 -type random

  Command line parameters:
    n     : length of the segment (1 <= n <= 10^6)
    m     : number of blocked positions (0 <= m <= n)
    k     : maximum lamp power (1 <= k <= n)
    type  : one of 
            "random",             // random blocked positions, random costs
            "none_blocked",       // m=0, no blocked positions
            "all_blocked",        // m=n, all positions blocked => immediate -1
            "impossible_zero",    // position 0 is blocked => immediate -1
            "sparse_blocked",     // a small fraction of blocked positions, random
            "dense_blocked",      // a large fraction of blocked positions, random
            "cost_increasing",    // costs strictly increasing
            "cost_decreasing",    // costs strictly decreasing
            "cost_same"           // all costs are the same
            // (if not specified, defaults to "random")

  The generator will output:
    1) a single line: n m k
    2) a second line: m distinct blocked positions in ascending order
    3) a third line: k costs (between 1 and 1e6)

  NOTE: This generator does not accept or set a random seed.  
  NOTE: If you pass contradictory parameters (e.g. -m 10 but type=none_blocked),
        the generator will override m or other parameters as needed.
*/

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // Parse command-line arguments.
    int n = opt<int>("n", 10);
    int m = opt<int>("m", 3);
    int k = opt<int>("k", 5);
    string type = opt<string>("type", "random");

    // Make sure arguments are within the problem constraints.
    // We will do simple checks.
    // (Real usage might have more thorough checks or rely on the organizer.)
    // But we won't artificially clamp well beyond.
    // Instead, we trust the user not to exceed 1e6, etc.
    if (n < 1)  n = 1;
    if (m < 0)  m = 0;
    if (m > n)  m = n;
    if (k < 1)  k = 1;
    if (k > n)  k = n;

    // We will generate:
    // 1) n, m, k
    // 2) list of m distinct blocked positions in [0..n-1] sorted
    // 3) list of k costs (1..1e6)

    // Prepare a vector of possible positions [0..n-1].
    // We'll mark which are blocked depending on the type.
    vector<int> blocked;
    blocked.reserve(n); // to avoid reallocation if needed

    // cost array
    vector<int> costs(k, 1);

    // We'll handle "type" to override or guide m and the blocked positions.
    if (type == "none_blocked") {
        // no blocked positions at all
        m = 0;
    }
    else if (type == "all_blocked") {
        // block everything => immediate -1
        m = n;
    }
    else if (type == "impossible_zero") {
        // specifically block position 0 => immediate -1 if n>0
        // just override m to 1 if it doesn't conflict with n=0
        if (n > 0) {
            m = 1;
        }
        else {
            // if n=0 is nonsensical, fallback
            m = 0;
        }
    }
    else if (type == "sparse_blocked") {
        // we want a small fraction blocked, say 5% of n (capped)
        // override m
        int proposed = max(1, (int)(0.05 * n)); 
        m = min(proposed, n);
    }
    else if (type == "dense_blocked") {
        // we want a large fraction blocked, say 80% of n
        // override m
        int proposed = max(1, (int)(0.8 * n));
        m = min(proposed, n);
    }
    // "random" or anything else just uses user-provided m (capped earlier).
    // Now let's build the blocked positions array accordingly.

    if (type == "all_blocked") {
        // block everything from 0..n-1
        blocked.resize(n);
        iota(blocked.begin(), blocked.end(), 0);
    }
    else if (type == "impossible_zero" && n > 0) {
        // block just position 0
        blocked.clear();
        blocked.push_back(0);
    }
    else {
        // general random blocking, including random, sparse_blocked, dense_blocked
        // or none_blocked if m=0, that is fine
        // generate m distinct random positions in [0..n-1]
        // but if we already handled "impossible_zero" or "all_blocked", skip
        if (!(type == "impossible_zero" && n > 0) && !(type == "all_blocked")) {
            // pick m distinct positions
            // create a list of [0..n-1], shuffle, take first m, sort them
            vector<int> allPos(n);
            iota(allPos.begin(), allPos.end(), 0);
            shuffle(allPos.begin(), allPos.end());
            blocked.assign(allPos.begin(), allPos.begin() + m);
            sort(blocked.begin(), blocked.end());
        }
    }

    // At this point, 'blocked' has exactly m distinct positions or is already set.

    // Next, generate costs according to possible cost patterns.
    // For "cost_increasing", "cost_decreasing", "cost_same".
    // Otherwise random in [1..1e6].
    if (type == "cost_increasing") {
        // strictly increasing from 1..k
        for (int i = 0; i < k; i++) {
            costs[i] = i + 1; // 1,2,3,...,k
        }
    }
    else if (type == "cost_decreasing") {
        // strictly decreasing from k..1
        // but ensure each cost is >= 1
        for (int i = 0; i < k; i++) {
            costs[i] = k - i; // k, k-1, ..., 1
        }
    }
    else if (type == "cost_same") {
        // all costs are the same random value in [1..1e6]
        int val = rnd.next(1, 1000000);
        for (int i = 0; i < k; i++) {
            costs[i] = val;
        }
    }
    else {
        // random cost in [1..1e6]
        for (int i = 0; i < k; i++) {
            costs[i] = rnd.next(1, 1000000);
        }
    }

    // Now we can output the test.
    // 1) n, m, k
    printf("%d %d %d\n", n, m, k);

    // 2) m blocked positions
    // If m>0, print them. If m=0, no output on the second line.
    // The problem statement says "m integer numbers" on the second line
    // If m=0, it will just be a blank line.
    for (int i = 0; i < m; i++) {
        printf("%d%c", blocked[i], (i + 1 < m ? ' ' : '\n'));
    }
    if (m == 0) {
        printf("\n");
    }

    // 3) k costs
    for (int i = 0; i < k; i++) {
        printf("%d%c", costs[i], (i + 1 < k ? ' ' : '\n'));
    }

    return 0;
}

