struct edge{
  int from,to,cost;
};
struct state{
  int pos,cost;
  bool operator < (const state &p)const{
    return cost > p.cost;
  }
};

vector<int> v;
vector<edge> G[MAX_N],g;
int N,M,K,d[MAX_N];

void dijkstra(){
  priority_queue< state > Q;
  for(int i=0;i<MAX_N;i++)d[i]=INF;
  for(int i=0;i<K;i++){
    int w=v[i];
    d[w]=0;
    Q.push( (state){w,0} );
  }
  while(!Q.empty()){
    state s=Q.top();Q.pop();
    if(s.cost>d[s.pos])continue;
    for(int i=0;i<(int)G[s.pos].size();i++){
      edge e=G[s.pos][i];
      if(s.cost+e.cost>=d[e.to])continue;
      d[e.to]=s.cost+e.cost;
      Q.push( (state){e.to,d[e.to]} );
    }
  }
}

