        s = "";
        for (int i = 0; i < n; ++i) {
            s += (char)('A' + rnd.next(2));
        }
    } else if (type == "allA") {
        // Generate a string of 'A's
        s = string(n, 'A');
    } else if (type == "allB") {
        // Generate a string of 'B's
        s = string(n, 'B');
    } else if (type == "alternating") {
        // Generate 'ABABAB...'
        s = "";
        for (int i = 0; i < n; ++i) {
            s += (i % 2 == 0) ? 'A' : 'B';
        }
    } else if (type == "blocks") {
        // Generate random blocks of 'A's and 'B's
        s = "";
        char current = 'A' + rnd.next(2); // Random starting character
        while ((int)s.length() < n) {
            int block_size = rnd.next(1, min(n - (int)s.length(), 10));
            for (int i = 0; i < block_size; ++i) {
                s += current;
            }
            current = (current == 'A') ? 'B' : 'A';
        }
    } else if (type == "palindromeFull") {
        // Generate a palindrome of length n
        s = "";
        if (n % 2 == 0) {
            string half;
            for (int i = 0; i < n / 2; ++i) {
                half += (char)('A' + rnd.next(2));
            }
            string rev_half = half;
            reverse(rev_half.begin(), rev_half.end());
            s = half + rev_half;
        } else {
            string half;
            for (int i = 0; i < n / 2; ++i) {
                half += (char)('A' + rnd.next(2));
            }
            s = half + (char)('A' + rnd.next(2));
            string rev_half = half;
            reverse(rev_half.begin(), rev_half.end());
            s += rev_half;
        }
    } else if (type == "repeats") {
        // Generate string by repeating a random base string
        string base;
        int base_len = rnd.next(1, min(n, 10));
        for (int i = 0; i < base_len; ++i) {
            base += (char)('A' + rnd.next(2));
        }
        while ((int)s.length() < n) {
            s += base.substr(0, min(base_len, n - (int)s.length()));
        }
    } else if (type == "bad") {
        // Generate a string where letters may not be covered by palindromes
        s = "";
        for (int i = 0; i < n; ++i) {
            s += ((i % 3) == 0) ? 'A' : 'B';
        }
    } else if (type == "good") {
        // Generate a string where all letters belong to palindromes
        s = "";
        while ((int)s.length() < n) {
            char c = (char)('A' + rnd.next(2));
            int repeat = min(2, n - (int)s.length());
            for (int i = 0; i < repeat; ++i) {
                s += c;
            }
        }
    } else {
        fprintf(stderr, "Unknown type\n");
        exit(1);
    }

    // Output n and s
    printf("%d\n", n);
    printf("%s\n", s.c_str());

    return 0;
}

