            p[i] = i - 1;
    } else if (type == "star") {
        for (int i = 2; i <= n; ++i)
            p[i] = 1;
    } else if (type == "binary") {
        for (int i = 2; i <= n; ++i)
            p[i] = i / 2;
    } else if (type == "skewed") {
        for (int i = 2; i <= n; ++i)
            p[i] = i - 1; // similar to chain
    } else if (type == "random") {
        for (int i = 2; i <= n; ++i)
            p[i] = rnd.next(1, i - 1);
    } else {
        // Default to random
        for (int i = 2; i <= n; ++i)
            p[i] = rnd.next(1, i - 1);
    }

    // Shuffle the nodes to randomize node labels
    vector<int> perm(n + 1);
    for (int i = 1; i <= n; ++i)
        perm[i] = i;

    shuffle(perm.begin() + 1, perm.end());

    // Create edges
    vector<pair<int, int>> edges;
    for (int i = 2; i <= n; ++i) {
        int u = perm[p[i]];
        int v = perm[i];
        edges.push_back({ u, v });
    }

    // Shuffle edges
    shuffle(edges.begin(), edges.end());

    // Output
    printf("%d\n", n);
    for (auto& edge : edges)
        printf("%d %d\n", edge.first, edge.second);

