}
void unite(int u, int v) {
    int pu = find(u);
    int pv = find(v);
    ensuref(pu != pv, "Graph contains a cycle at edge (%d, %d)", u, v);
    if (rank_[pu] < rank_[pv]) {
        parent[pu] = pv;
    } else if (rank_[pu] > rank_[pv]) {
        parent[pv] = pu;
    } else {
