                a[j] = rnd.next(1, n);
            }
        } else if (type == "few_uniques") {
            int num_unique = opt<int>("uniques", 2);
            vector<int> unique_vals;
            set<int> used_vals;
            while ((int)unique_vals.size() < num_unique) {
                int val = rnd.next(1, n);
                if (!used_vals.count(val)) {
