using namespace std;

int compute_steps(int N) {
    if (N % 1111 == 0) {
        // All digits are the same, output NA.
        return -1;
    }
    int steps = 0;
    set<int> seen;
    while (N != 6174) {
        if (seen.count(N)) {
            // Loop detected, break to avoid infinite loop.
            return -1;
        }
        seen.insert(N);

        char s[5];
        sprintf(s, "%04d", N);

        // Arrange digits in ascending order to get S.
        string digits(s);
        sort(digits.begin(), digits.end());
        int S = atoi(digits.c_str());

        // Arrange digits in descending order to get L.
        reverse(digits.begin(), digits.end());
        int L = atoi(digits.c_str());

        N = L - S;
        steps++;
        if (N == 0) {
            // N becomes 0, cannot proceed further.
            return -1;
        }
    }
    return steps;
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n", 1); // Number of test cases to generate.
    string type = opt<string>("type", "random"); // Type of test case.
    int steps_param = opt<int>("steps", -1); // Desired number of steps if type is 'steps'.

    vector<int> Ns;

    if (type == "random") {
        for (int i = 0; i < n; ++i) {
            int N = rnd.next(1, 9999);
            Ns.push_back(N);
        }
    } else if (type == "all_same") {
        for (int i = 0; i < n; ++i) {
            int digit = rnd.next(0, 9);
            int N = digit * 1111;
            Ns.push_back(N);
        }
    } else if (type == "leading_zeros") {
        for (int i = 0; i < n; ++i) {
            int N = rnd.next(1, 999);
            Ns.push_back(N);
        }
    } else if (type == "6174") {
        for (int i = 0; i < n; ++i) {
            int N = 6174;
            Ns.push_back(N);
        }
    } else if (type == "steps") {
        if (steps_param < 0 || steps_param > 7) {
            fprintf(stderr, "Invalid steps parameter. Must be between 0 and 7.\n");
            return 1;
        }
        int count = 0;
        while (count < n) {
            int N = rnd.next(1, 9999);
            if (N % 1111 == 0) continue; // Skip numbers with all digits the same.
            int steps = compute_steps(N);
            if (steps == steps_param) {
                Ns.push_back(N);
                count++;
            }
        }
    } else if (type == "max_steps") {
        int max_steps = 0;
        // First, find the maximum number of steps.
        for (int N = 1; N <= 9999; ++N) {
            if (N % 1111 == 0) continue;
            int steps = compute_steps(N);
            if (steps > max_steps) {
                max_steps = steps;
            }
        }
        // Now, generate numbers that require max_steps to reach 6174.
        int count = 0;
        while (count < n) {
            int N = rnd.next(1, 9999);
            if (N % 1111 == 0) continue;
            int steps = compute_steps(N);
            if (steps == max_steps) {
                Ns.push_back(N);
                count++;
            }
        }
    } else {
        fprintf(stderr, "Unknown type '%s'\n", type.c_str());
        return 1;
    }

    // Output Ns, padded with leading zeros to 4 digits.
    for (int N : Ns) {
        printf("%04d\n", N);
    }
    // Output the terminating '0000'
    printf("0000\n");

    return 0;
}

