        // All elements are equal to minimal value
        fill(a.begin(), a.end(), min_value);
    } else if(type == "all_same_max") {
        // All elements are equal to maximal value
        fill(a.begin(), a.end(), max_value);
    } else if(type == "random") {
        // Random elements between min_value and max_value
        for(int i = 0; i < n; ++i) {
            a[i] = rnd.next(min_value, max_value);
        }
    } else if(type == "few_min") {
        // A few elements are minimal, rest are larger random values
        if(num_min > n) num_min = n;
        for(int i = 0; i < num_min; ++i) {
            a[i] = min_value;
        }
        for(int i = num_min; i < n; ++i) {
            a[i] = rnd.next(min_value+1, max_value); // Ensure larger than min_value
        }
        shuffle(a.begin(), a.end());
    } else if(type == "many_min") {
        // Many elements are minimal, rest are larger random values
        int num_min_elements = n / 2;
        for(int i = 0; i < num_min_elements; ++i) {
            a[i] = min_value;
        }
        for(int i = num_min_elements; i < n; ++i) {
            a[i] = rnd.next(min_value+1, max_value);
        }
        shuffle(a.begin(), a.end());
    } else if(type == "increasing") {
        // Elements increase from min_value to max_value
        for(int i = 0; i < n; ++i) {
            a[i] = min_value + ((long long)(max_value - min_value) * i) / (n - 1);
        }
    } else if(type == "decreasing") {
        // Elements decrease from max_value to min_value
        for(int i = 0; i < n; ++i) {
            a[i] = max_value - ((long long)(max_value - min_value) * i) / (n - 1);
        }
    } else if(type == "zigzag") {
        // Elements alternate between min_value and max_value
        for(int i = 0; i < n; ++i) {
            if(i % 2 == 0)
                a[i] = min_value;
            else
                a[i] = max_value;
        }
    } else if(type == "worst_overflow") {
        // Elements close to max_value to test overflow issues
        for(int i = 0; i < n; ++i) {
            a[i] = max_value - rnd.next(0, 10); // Close to max_value
        }
    } else {
        // Default: random elements
        for(int i = 0; i < n; ++i) {
            a[i] = rnd.next(min_value, max_value);
        }
    }

    // Output
    printf("%d\n", n);
    for(int i = 0; i < n; ++i) {
        printf("%d%c", a[i], i == n - 1 ? '\n' : ' ');
    }

    return 0;
}

