#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
    This generator outputs a valid "Domino Carpet" of size n x m.
    Each cell of the n x m grid is either a "vertical" half or a "horizontal" half.
    We embed each cell into a 3×3 block of '.' or 'O' characters, separated by '#' boundaries.

    Reading the official solution, it checks the number of 'O' in the 3×3 region:
       - if there are 2 or 3 'O's, it looks at C[4*x+1][4*y+1];
         if that position is '.', the half is vertical; if 'O', the half is horizontal.
       - if there are 6 'O's, it looks at C[4*x+1][4*y+2];
         if '.', vertical; otherwise horizontal.
    In this generator, we only produce the first scenario (2 'O's total). That is enough
    to ensure a correct interpretation in the official solution.

    We'll define one pattern for "vertical" and one for "horizontal," each of which has exactly
    two 'O's in the 3x3 interior, guaranteeing a single orientation.

    vertical pattern (top-left '.' => recognized as vertical):
       Row0:  ..O
       Row1:  O..
       Row2:  ...
    horizontal pattern (top-left 'O' => recognized as horizontal):
       Row0:  O..
       Row1:  ..O
       Row2:  ...
*/

static const vector<string> VERT_CELL = {
    "..O",
    "O..",
    "..."
};

static const vector<string> HORIZ_CELL = {
    "O..",
    "..O",
    "..."
};

// Print the row of boundary '#' characters, which is of length (4*m + 1).
void printBoundaryLine(int m) {
    string boundary(4 * m + 1, '#');
    cout << boundary << "\n";
}

// Print one row of the carpet (3 lines) for cells in [0..m-1].
void printRow(const vector<char> &rowOrient) {
    // rowOrient has size m, each element is 'v' or 'h'.
    // We'll print 3 lines of interior for each cell, separated by '#'.
    for(int line = 0; line < 3; line++) {
        // Start each line with a '#'
        cout << "#";
        for(int j = 0; j < (int)rowOrient.size(); j++) {
            if(rowOrient[j] == 'v') {
                cout << VERT_CELL[line];
            } else {
                cout << HORIZ_CELL[line];
            }
            // Then print the boundary after each cell
            cout << "#";
        }
        cout << "\n";
    }
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // Parse parameters
    int n = opt<int>("n");               // number of rows
    int m = opt<int>("m");               // number of columns
    string type = opt<string>("type", "random"); // type of orientation pattern

    // Prepare orientation array
    vector<vector<char>> orientation(n, vector<char>(m, 'v'));

    // Fill orientation
    if(type == "allv") {
        // all vertical
        for(int i = 0; i < n; i++){
            for(int j = 0; j < m; j++){
                orientation[i][j] = 'v';
            }
        }
    }
    else if(type == "allh") {
        // all horizontal
        for(int i = 0; i < n; i++){
            for(int j = 0; j < m; j++){
                orientation[i][j] = 'h';
            }
        }
    }
    else if(type == "checker") {
        // checkerboard pattern
        // 'v' if i+j is even, 'h' otherwise
        for(int i = 0; i < n; i++){
            for(int j = 0; j < m; j++){
                orientation[i][j] = ((i + j) % 2 == 0) ? 'v' : 'h';
            }
        }
    }
    else {
        // random pattern
        for(int i = 0; i < n; i++){
            for(int j = 0; j < m; j++){
                // 50/50 random v or h
                if(rnd.next(2) == 0) orientation[i][j] = 'v'; 
                else orientation[i][j] = 'h';
            }
        }
    }

    // Output
    // 1) Print n, m (the problem demands these in the first line).
    // 2) Then print the 4n+1 lines describing the chart.

    cout << n << " " << m << "\n";

    for(int i = 0; i < n; i++){
        // boundary
        printBoundaryLine(m);
        // interior
        printRow(orientation[i]);
    }
    // final boundary
    printBoundaryLine(m);

    return 0;
}

