#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

// We'll implement a custom checker because there can be multiple valid necklaces 
// (i.e., multiple correct outputs) that use the same multiset of beads and achieve
// the same maximum number of "beautiful cuts".

// To verify correctness, we will:
// 1) Read the problem input from inf (the number of colors and their quantities).
// 2) Read the jury's solution from ans, check correctness, and compute its number of beautiful cuts.
// 3) Read the participant's solution from ouf, check correctness, and compute its number of beautiful cuts.
// 4) Compare: if the jury's solution has strictly more beautiful cuts, we issue WA; 
//    if the participant's solution has strictly more, we issue FAIL (the jury's solution was not optimal).
//    Otherwise, we accept (OK).

static const unsigned long long BASE = 131542391ULL;
static vector<unsigned long long> p; // Powers of BASE for hashing

int main(int argc, char* argv[])
{
    registerTestlibCmd(argc, argv);

    // Read input (n and the array of bead counts)
    int n = inf.readInt(1, 26);
    vector<long long> beads(n);
    long long total = 0;
    for (int i = 0; i < n; i++) {
        beads[i] = inf.readLong(1, 100000);
        total += beads[i];
    }
    // total is guaranteed to be >= 2 and <= 100000.

    // Precompute powers of BASE up to length = 2 * total (for the doubled string).
    p.resize(2 * total + 1);
    p[0] = 1ULL;
    for (int i = 1; i <= 2 * total; i++) {
        p[i] = p[i - 1] * BASE;
    }

    // Helper function: reads a solution from the given stream, checks correctness,
    // and returns the actual number of beautiful cuts. If it fails, it calls quitf(_wa/_fail).
    auto readSolutionAndCountCuts = [&](InStream &stream)
    {
        // 1) Read the declared number of beautiful cuts
        long long declaredCuts = stream.readLong(0, total, "declared_cuts");

        // 2) Read the necklace as a token (it must match the total length in beads).
        //    IMPORTANT: do NOT supply a pattern string like "necklace" here; that
        //    would mean the token must literally match "necklace". So just readToken().
        string necklace = stream.readToken();

        // Check length
        if ((long long)necklace.size() != total) {
            stream.quitf(_wa, 
                "Necklace length mismatch: expected %lld, got %d",
                total, (int)necklace.size());
        }

        // 3) Check letter usage
        vector<long long> used(n, 0LL);
        for (char c : necklace) {
            if (c < 'a' || c >= char('a' + n)) {
                stream.quitf(_wa, "Invalid color '%c' found in the necklace", c);
            }
            used[c - 'a']++;
        }
        for (int i = 0; i < n; i++) {
            if (used[i] != beads[i]) {
                stream.quitf(_wa, 
                    "Wrong usage for color '%c': expected %lld, got %lld",
                    char('a' + i), beads[i], used[i]);
            }
        }

        // 4) Count the actual number of beautiful cuts using a rolling-hash palindrome check
        auto countBeautifulCuts = [&](const string &s) {
            // ds = s + s
            string ds = s + s;
            // Build prefix hashes for ds
            static vector<unsigned long long> H, R;
            H.resize(ds.size() + 1);
            R.resize(ds.size() + 1);

            // Forward hash
            H[0] = 0ULL;
            for (int i = 0; i < (int)ds.size(); i++) {
                H[i + 1] = H[i] * BASE + (unsigned long long)(ds[i] - 'a' + 1);
            }

            // Reverse hash (we can build it by reversing ds or we can index from the end on the fly).
            // For simplicity, let's build the reversed ds directly:
            string dsr(ds.rbegin(), ds.rend());
            R[0] = 0ULL;
            for (int i = 0; i < (int)dsr.size(); i++) {
                R[i + 1] = R[i] * BASE + (unsigned long long)(dsr[i] - 'a' + 1);
            }

            // Helper to get substring hash in O(1)
            auto getHash = [&](const vector<unsigned long long> &pref, int l, int r){
                unsigned long long res = pref[r + 1] - pref[l] * p[r - l + 1];
                return res;
            };

            int len = (int)s.size();
            long long countCuts = 0;
            for (int i = 0; i < len; i++) {
                // substring [i..i+len-1] in ds, reversed substring is [i2..i2+len-1] in dsr
                int i2 = 2 * len - (i + len);
                // get forward hash
                unsigned long long hashF = getHash(H, i, i + len - 1);
                // get reverse hash
                unsigned long long hashR = getHash(R, i2, i2 + len - 1);
                if (hashF == hashR) {
                    countCuts++;
                }
            }
            return countCuts;
        };

        long long realCuts = countBeautifulCuts(necklace);

        // 5) Compare realCuts vs declaredCuts
        if (realCuts != declaredCuts) {
            stream.quitf(_wa, 
                "Mismatch in the number of beautiful cuts: declared %lld, found %lld",
                declaredCuts, realCuts);
        }

        return realCuts;
    };

    // Read jury's solution
    long long jVal = readSolutionAndCountCuts(ans);
    // Read participant's solution
    long long pVal = readSolutionAndCountCuts(ouf);

    // Compare
    if (jVal > pVal) {
        quitf(_wa, 
            "Participant's solution has fewer beautiful cuts than jury's (jury=%lld > part=%lld)", 
            jVal, pVal);
    }
    else if (jVal < pVal) {
        quitf(_fail, 
            "Participant's solution has more beautiful cuts than jury's (jury=%lld < part=%lld)", 
            jVal, pVal);
    }
    else {
        quitf(_ok, "OK: number of beautiful cuts = %lld", pVal);
    }
}

