vector<int> parent;

int find(int x) {
    if (parent[x] != x) parent[x] = find(parent[x]);
    return parent[x];
}

bool unite(int x, int y) {
    x = find(x);
    y = find(y);
    if (x == y) return false; // Cycle detected
    parent[x] = y;
    return true;
}

int main(int argc, char* argv[]) {
