        int u = inf.readInt(1, N, "u_i");
        inf.readSpace();
        int v = inf.readInt(1, N, "v_i");
        inf.readEoln();
        ensuref(u != v, "Edge %d connects vertex %d to itself", i + 1, u);
        if (!unite(u, v)) {
            ensuref(false, "Found a cycle when processing edge %d between %d and %d", i + 1, u, v);
        }
    }

    // Check if the graph is connected
    int root = find(1);
    for (int i = 2; i <= N; ++i) {
        ensuref(find(i) == root, "Graph is not connected; vertex %d is disconnected", i);
    }

    inf.readEof();
    return 0;
}

