using namespace std;

/* 
   A helper function to generate a random convex polygon with n vertices,
   where the radius of each vertex from the center is in [minR, maxR],
   and then all vertices are shifted by (shiftX, shiftY).

   This uses the "random angles" method:
   1. Generate n angles in [0, 2π).
   2. Sort them.
   3. Assign a random radius to each angle in [minR, maxR].
   4. Compute coordinates = (r_i cos(θ_i), r_i sin(θ_i)), then shift.
   5. This yields a convex polygon.
*/
static void generateRandomConvexPolygon(
    int n,
    double minR,
    double maxR,
    double shiftX,
    double shiftY,
    vector<double> &xs,
    vector<double> &ys)
{
    xs.clear();
    ys.clear();
    xs.resize(n);
    ys.resize(n);

    // Generate random angles
    vector<double> angles(n);
    for (int i = 0; i < n; i++){
        angles[i] = rnd.next(0.0, 2.0 * M_PI);
    }
    sort(angles.begin(), angles.end());

    // Generate random radii
    vector<double> radii(n);
    for (int i = 0; i < n; i++){
        radii[i] = rnd.next(minR, maxR);
    }

    // Compute coordinates
    for (int i = 0; i < n; i++){
        xs[i] = radii[i] * cos(angles[i]) + shiftX;
        ys[i] = radii[i] * sin(angles[i]) + shiftY;
    }
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // n will be the number of vertices we attempt to generate
    // For special types like triangle/rectangle we may override it
    int n = opt<int>("n");
    // type can be "random", "triangle", "rectangle", "regular",
    // "randomSmall", "randomLarge", "randomNegative", etc.
    string type = opt<string>("type", "random");

    vector<double> xs, ys;

    // Predefined shapes that override n (just to show variety)
    if (type == "triangle") {
        // Force 3 points forming a simple right triangle
        // (0,0), (w,0), (0,h)
        // with w,h in [1,10).
        double w = rnd.next(1.0, 10.0);
        double h = rnd.next(1.0, 10.0);
        xs = {0.0, w, 0.0};
        ys = {0.0, 0.0, h};
        n = 3; // override
    }
    else if (type == "rectangle") {
        // Force 4 points forming a rectangle
        // (0,0), (w,0), (w,h), (0,h)
        // with w,h in [1,10).
        double w = rnd.next(1.0, 10.0);
        double h = rnd.next(1.0, 10.0);
        xs = {0.0, w, w, 0.0};
        ys = {0.0, 0.0, h, h};
        n = 4; // override
    }
    else if (type == "regular") {
        // Generate a regular n-gon with radius 10
        xs.clear(); ys.clear();
        xs.resize(n); ys.resize(n);
        double R = 10.0;
        // center at (0,0), equally spaced angles.
        for(int i=0; i<n; i++){
            double theta = 2.0 * M_PI * i / n;
            xs[i] = R * cos(theta);
            ys[i] = R * sin(theta);
        }
    }
    else if (type == "randomSmall") {
        // Random convex polygon with radius ~ [0.5, 1.0]
        generateRandomConvexPolygon(n, 0.5, 1.0, 0.0, 0.0, xs, ys);
    }
    else if (type == "randomLarge") {
        // Random convex polygon with radius up to ~1e5
        generateRandomConvexPolygon(n, 50000.0, 100000.0, 0.0, 0.0, xs, ys);
    }
    else if (type == "randomNegative") {
        // Random convex polygon with radius ~ [5, 10], shifted negatively
        generateRandomConvexPolygon(n, 5.0, 10.0, -5.0, -5.0, xs, ys);
    }
    else {
        // Default: random convex polygon with radius ~ [5,10], no shift
        // e.g. type == "random"
