using namespace std;

int main(int argc, char* argv[]) {
    registerValidation(argc, argv);

    vector<double> x, y;

    // Define the regex pattern for a real number
    string real = "[+-]?((0|[1-9][0-9]*)(\\.[0-9]+)?|(0?\\.[0-9]+))([eE][+-]?[0-9]+)?";
    string line_regex = "\\s*" + real + "\\s*,\\s*" + real + "\\s*";

    int line_num = 0;

    while (!inf.eof()) {
        line_num++;
        string line = inf.readLine();

        // Trim leading and trailing whitespace
        line = trim(line);

        if (line.empty()) {
            quitf(_fail, "Empty line at line %d", line_num);
        }

        // Check if line matches the expected format
        if (!regex_match(line, regex(line_regex))) {
            quitf(_fail, "Line does not match expected format at line %d: %s", line_num, line.c_str());
        }

        // Find the comma separating xi and yi
        size_t comma_pos = line.find(',');
        if (comma_pos == string::npos) {
            quitf(_fail, "Line does not contain a comma at line %d", line_num);
        }

        // Extract xi and yi as strings
        string xi_str = trim(line.substr(0, comma_pos));
        string yi_str = trim(line.substr(comma_pos + 1));

        double xi, yi;
        char* xi_end;
        char* yi_end;

        // Convert xi_str to double
        xi = strtod(xi_str.c_str(), &xi_end);
        if (xi_end != xi_str.c_str() + xi_str.size()) {
            quitf(_fail, "Could not parse xi at line %d", line_num);
        }

        // Convert yi_str to double
        yi = strtod(yi_str.c_str(), &yi_end);
        if (yi_end != yi_str.c_str() + yi_str.size()) {
            quitf(_fail, "Could not parse yi at line %d", line_num);
        }

        x.push_back(xi);
        y.push_back(yi);
    }

    int n = x.size();

    // Check that n is between 3 and 20
    if (n < 3 || n > 20) {
        quitf(_fail, "Number of vertices n=%d is not in [3, 20]", n);
    }

    const double EPS = 1e-8;

    // Check for duplicate adjacent points
    for (int i = 0; i < n; i++) {
        int i1 = i;
        int i2 = (i + 1) % n;

        double dx = x[i1] - x[i2];
        double dy = y[i1] - y[i2];

        if (fabs(dx) < EPS && fabs(dy) < EPS) {
            quitf(_fail, "Polygon has duplicate points at vertices %d and %d", i1 + 1, i2 + 1);
        }
    }

    // Check that the polygon is convex
    int firstSign = 0;
    for (int i = 0; i < n; i++) {
        int i0 = (i + n - 1) % n;
        int i1 = i;
        int i2 = (i + 1) % n;

        double x0 = x[i0], y0 = y[i0];
        double x1 = x[i1], y1 = y[i1];
        double x2 = x[i2], y2 = y[i2];

        double dx1 = x1 - x0, dy1 = y1 - y0;
        double dx2 = x2 - x1, dy2 = y2 - y1;

        double cross = dx1 * dy2 - dy1 * dx2;

        if (fabs(cross) < EPS) {
            quitf(_fail, "Polygon is not convex, has colinear edges at vertices %d, %d, %d", i0 + 1, i1 + 1, i2 + 1);
        }

        int sign = cross > 0 ? 1 : -1;
        if (firstSign == 0) {
            firstSign = sign;
        } else if (sign != firstSign) {
            quitf(_fail, "Polygon is not convex, sign change at vertices %d, %d, %d", i0 + 1, i1 + 1, i2 + 1);
        }
    }

    // Ensure that EOF is reached
    inf.readEof();

    return 0;
}

