// Convert integer to base-26 string of length len
string intToString(int num, int len) {
    string s(len, 'a');
    for (int i = len - 1; i >= 0; --i) {
        s[i] = 'a' + num % 26;
        num /= 26;
    }
    return s;
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    string type = opt<string>("type", "random");

    vector<string> S(n);

    if (type == "all_same") {
        // Generate one random string
        int len = rnd.next(1, 10);
        string s = generateRandomString(len);
        for(int i = 0; i < n; ++i) {
            S[i] = s;
        }
    } else if (type == "all_different") {
        // Generate n unique strings
        int len = 6; // Length of strings, can be adjusted (ensure len between 1 and 10)
        long long total_strings = 1;
        for(int i = 0; i < len; ++i) {
            total_strings *= 26;
        }
        if (total_strings < n) {
            len = 7;
            total_strings = 1;
            for(int i = 0; i < len; ++i) {
                total_strings *= 26;
            }
            if (total_strings < n) {
                len = 8;
                total_strings = 1;
                for(int i = 0; i < len; ++i) {
                    total_strings *= 26;
                }
                if (total_strings < n) {
                    len = 9;
                    total_strings = 1;
                    for(int i = 0; i < len; ++i) {
                        total_strings *= 26;
                    }
                    if (total_strings < n) {
                        len = 10;
                        total_strings = 1;
                        for(int i = 0; i < len; ++i) {
                            total_strings *= 26;
                        }
                        if (total_strings < n) {
                            cerr << "Cannot generate " << n << " unique strings of length at most 10." << endl;
                            exit(1);
                        }
                    }
                }
            }
        }
        // Now generate n unique strings
        for(int i = 0; i < n; ++i) {
            S[i] = intToString(i, len);
        }
        // Shuffle S
        shuffle(S.begin(), S.end());
    } else if (type == "random") {
        // Generate random strings, duplicates allowed
        for (int i = 0; i < n; ++i) {
            int len = rnd.next(1, 10);
            S[i] = generateRandomString(len);
        }
    } else if (type == "small_changes") {
        // Generate strings that differ by one character
        int len = rnd.next(1, 10);
        string base = generateRandomString(len);
        for (int i = 0; i < n; ++i) {
            S[i] = base;
            int pos = rnd.next(0, len - 1);
            char new_char = 'a' + rnd.next(26);
            S[i][pos] = new_char;
        }
    } else if (type == "max_length") {
        // Generate strings of length 10
        for (int i = 0; i < n; ++i) {
            S[i] = generateRandomString(10);
        }
    } else if (type == "min_length") {
        // Generate strings of length 1
        for (int i = 0; i < n; ++i) {
            S[i] = generateRandomString(1);
        }
    } else if (type == "alternating") {
        // Generate two strings and alternate
        string s1 = generateRandomString(rnd.next(1, 10));
        string s2 = generateRandomString(rnd.next(1, 10));
        for (int i = 0; i < n; ++i) {
            if (i % 2 == 0) S[i] = s1;
            else S[i] = s2;
        }
    } else if (type == "repeated_pairs") {
        // Ensure n is even
        if (n % 2 != 0) {
            cerr << "n must be even for repeated_pairs type" << endl;
            exit(1);
        }
        int num_pairs = n / 2;
        for (int i = 0; i < num_pairs; ++i) {
            int len = rnd.next(1, 10);
            string s = generateRandomString(len);
            S[2 * i] = s;
            S[2 * i + 1] = s;
        }
        shuffle(S.begin(), S.end());
    } else {
        cerr << "Unknown type: " << type << endl;
        exit(1);
    }

    // Output N
    printf("%d\n", n);
    // Output strings
    for (int i = 0; i < n; ++i) {
        printf("%s\n", S[i].c_str());
    }

    return 0;
}

