        for (int i = 0; i < 6; ++i) {
            const string& token = tokens[i];
            double x;
            try {
                size_t idx;
                x = std::stod(token, &idx);
                ensuref(idx == token.size(), "Invalid double: '%s'", token.c_str());
                ensuref(x >= -100.0 && x <= 100.0, "Double %s not in range [-100, 100]", token.c_str());
            } catch (const std::exception& e) {
                ensuref(false, "Invalid double: '%s'", token.c_str());
            }
            nums[i] = x;
        }

        // Extract points
        double x1 = nums[0], y1 = nums[1];
        double x2 = nums[2], y2 = nums[3];
        double xq = nums[4], yq = nums[5];

        // Check that P1 != P2
        ensuref(!(x1 == x2 && y1 == y2), "P1 and P2 are the same point");

        // Check that P1 != Q
        ensuref(!(x1 == xq && y1 == yq), "P1 and Q are the same point");

        // Check that P2 != Q
        ensuref(!(x2 == xq && y2 == yq), "P2 and Q are the same point");

        // Check that Q is not on the line defined by P1 and P2
        double dx1 = x2 - x1;
        double dy1 = y2 - y1;
        double dx2 = xq - x1;
        double dy2 = yq - y1;
        double cross = dx1 * dy2 - dy1 * dx2;
        const double EPS = 1e-8;
        ensuref(fabs(cross) > EPS, "Point Q lies on the line defined by P1 and P2");
    }
    inf.readEof();
    return 0;
}

