        int currentNode = 1;
        int nodeCount = 1;
        q.push(currentNode);
        while (nodeCount < n) {
            int parent = q.front();
            q.pop();
            if (nodeCount < n) {
                ++currentNode;
                edges.push_back({parent, currentNode});
