#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
  This checker compares the contestant's T-decomposition to the jury's T-decomposition and verifies:
    1) Both are valid T-decompositions of the original tree s.
    2) Their "weights" (maximum subset cardinality) are the same.
    3) Among all T-decompositions with that weight, the number of nodes in T is minimal.
       - We compare to the jury's T-decomposition:
         * If the contestant's decomposition is invalid, we report WA.
         * If the jury's decomposition is invalid, we report FAIL (shouldn't happen with correct jury).
         * Then compare weights:
             If contestant's < jury's => FAIL (official solution wasn’t minimal).
             If contestant's > jury's => WA.
             If equal => compare number of nodes:
                 If contestant's < jury's => FAIL (official solution wasn’t minimal).
                 If contestant's > jury's => WA.
                 Otherwise => OK.
*/

static const string TREE_NOT_CONNECTED = "T-decomposition graph is not connected";
static const string WRONG_NUMBER_OF_EDGES = "T-decomposition must have (m - 1) edges if it has m nodes";

// Global storage
int n;
vector<vector<int>> adj; // adjacency of the original tree s, 1-based

// Data structure to store a T-decomposition
struct TDecomposition {
    int m; // number of nodes in T
    vector<vector<int>> subsets; // subsets[i] is the list of tree-s nodes in the T's node i
    vector<vector<int>> tAdj;    // adjacency of T
    int weight;                  // maximum subset cardinality
};

// Reads T-decomposition from stream
TDecomposition readDecomposition(InStream &stream) {
    TDecomposition dec;
    dec.m = stream.readInt(1, n, "number_of_nodes_in_T_decomposition");
    dec.subsets.resize(dec.m);
    for(int i = 0; i < dec.m; i++){
        // read each T-decomposition node
        int k = stream.readInt(1, n, "size_of_subset");
        dec.subsets[i].resize(k);
        set<int> used; 
        for(int j = 0; j < k; j++){
            int v = stream.readInt(1, n, "tree_node_in_subset");
            if(!used.insert(v).second){
                stream.quitf(_wa, "A subset of T-decomposition contains duplicate node %d", v);
            }
            dec.subsets[i][j] = v;
        }
    }
    dec.tAdj.assign(dec.m, {});
    // read edges of T
    // T must have exactly dec.m - 1 edges
    if(dec.m == 1){
        // no edges to read
    } else {
        for(int e = 0; e < dec.m - 1; e++){
            int p = stream.readInt(1, dec.m, "t_edge_p");
            int q = stream.readInt(1, dec.m, "t_edge_q");
            if(p == q){
                stream.quitf(_wa, "T-decomposition edge connects the same node %d", p);
            }
            // convert to zero-based
            p--; q--;
            dec.tAdj[p].push_back(q);
            dec.tAdj[q].push_back(p);
        }
    }
    // no more edges for T
    // compute weight
    dec.weight = 0;
    for(int i = 0; i < dec.m; i++){
        dec.weight = max(dec.weight, (int)(dec.subsets[i].size()));
    }
    return dec;
}

// Checks if T-decomposition is connected graph with exactly m-1 edges
bool checkTConnected(const TDecomposition &dec){
    // BFS or DFS
    int m = dec.m;
    // check number of edges
    // sum of adjacency is 2*(m-1) if T is correct => let's verify quickly
    int countEdges = 0;
    for(int i = 0; i < m; i++){
        countEdges += (int)dec.tAdj[i].size();
    }
    if(m > 1 && countEdges != 2*(m-1)) return false;
    // connectivity check
    vector<bool> visited(m, false);
    int compCount = 0;
    function<void(int)> dfs = [&](int u){
        visited[u] = true;
        for(int w: dec.tAdj[u]){
            if(!visited[w]){
                dfs(w);
            }
        }
    };
    for(int i=0; i<m; i++){
        if(!visited[i]){
            compCount++;
            if(compCount > 1) return false;
            dfs(i);
        }
    }
    return true;
}

// Checks validity of T-decomposition
// Conditions:
//   1) union of subsets = {1..n}
//   2) for each edge (a,b) in s there is a subset containing both
//   3) for each vertex v in s, the subsets that contain v form a connected subgraph in T
// Returns true if valid, false otherwise. If invalid and stream==ans => _fail, else _wa.
bool checkValidity(InStream &stream, const TDecomposition &dec){
    // Condition 1: union of subsets = {1..n}
    vector<bool> used(n+1,false);
    for(int i=0; i<dec.m; i++){
        for(int v: dec.subsets[i]){
            used[v] = true;
        }
    }
    for(int v=1; v<=n; v++){
        if(!used[v]){
            // missing
            stream.quitf(_wa, "Not all nodes appear in the union of T-decomposition. Missing node %d", v);
        }
    }
    // Condition 2: for each edge (a,b) in original tree S, there is a subset containing both
    // We'll store adjacency in global 'adj'
    for(int v=1; v<=n; v++){
        for(int w: adj[v]){
            if(v < w){ // ensure each edge once
                bool found = false;
                for(int i=0; i<dec.m && !found; i++){
                    // check if dec.subsets[i] contains both v and w
                    // to speed up checking, we might store them in a set, but n can be large
                    // We'll do a direct membership test
                    // We'll do a small trick: if subsets are large, this can be slow, but let's keep it simpler for the example
                    // A real system solution might require a more optimal approach
                    // or a hashing approach
                    bool vIn = false, wIn = false;
                    for(int nodeInSubset: dec.subsets[i]){
                        if(nodeInSubset == v) vIn = true;
                        if(nodeInSubset == w) wIn = true;
                        if(vIn && wIn) {found = true; break;}
                    }
                }
                if(!found){
                    stream.quitf(_wa, "No subset in T-decomposition contains edge (%d, %d)", v, w);
                }
            }
        }
    }
    // Condition 3: for each vertex v in s, the subsets containing v form a connected subgraph in T
    // We'll gather the T-nodes that contain v
    // Then check if they form a connected subgraph in the T
    // We'll do a BFS/DFS inside T restricted to those T-nodes.
    for(int vert = 1; vert <= n; vert++){
        vector<int> nodesInT;
        for(int i=0; i<dec.m; i++){
            // check membership
            // we do a quick membership check
            // for a real solution we might store sets or use hashing
            // here just do it plainly
            bool found = false;
            for(int nodeInSubset: dec.subsets[i]){
                if(nodeInSubset == vert){
                    found = true; 
                    break;
                }
            }
            if(found){
                nodesInT.push_back(i);
            }
        }
        // nodesInT should form a connected subgraph
        // We'll pick any, BFS, and see if we reach all
        if(!nodesInT.empty()){
            vector<bool> usedT(dec.m,false);
            queue<int>q;
            usedT[nodesInT[0]] = true;
            q.push(nodesInT[0]);
            int countVisited = 0;
            unordered_set<int> mustVisit(nodesInT.begin(), nodesInT.end());
            while(!q.empty()){
                int u = q.front(); q.pop();
                if(mustVisit.count(u)) countVisited++;
                for(int nxt: dec.tAdj[u]){
                    // only traverse if that T-node also contains v
                    // check membership
                    if(!usedT[nxt]){
                        bool hasVert = false;
                        // check quickly
                        for(int nodeInSubset: dec.subsets[nxt]){
                            if(nodeInSubset == vert) { hasVert=true; break; }
                        }
                        if(hasVert){
                            usedT[nxt] = true;
                            q.push(nxt);
                        }
                    }
                }
            }
            if(countVisited != (int)nodesInT.size()){
                stream.quitf(_wa, 
                    "T-decomposition violates condition 3 for original node %d. Sets containing %d are not all connected in T",
                    vert, vert);
            }
        }
    }
    // check T is connected and has exactly m-1 edges => otherwise it's not a tree
    if(!checkTConnected(dec)){
        stream.quitf(_wa, "The T-decomposition is not a tree (connected with exactly m-1 edges).");
    }
    return true;
}

// We'll read and validate both the jury's solution (ans) and the participant's solution (ouf).
// If the jury's T-decomposition is invalid => quitf(_fail).
// If the participant's T-decomposition is invalid => quitf(_wa).
// Then compare weight, compare number of nodes.

int main(int argc, char* argv[]){
    registerTestlibCmd(argc, argv);
    // Read original tree s
    n = inf.readInt(2, 100000,"n");
    adj.resize(n+1);
    for(int i=0; i<n-1; i++){
        int a = inf.readInt(1,n,"edge_a");
        int b = inf.readInt(1,n,"edge_b");
        adj[a].push_back(b);
        adj[b].push_back(a);
    }
    // read ans
    TDecomposition decAns = readDecomposition(ans);
    // check ans validity
    // if invalid => _fail
    // else we have ansWeight, ansNodes
    checkValidity(ans, decAns); // will _fail if invalid
    int ansWeight = decAns.weight;
    int ansNodesCount = decAns.m;

    // read ouf
    TDecomposition decOuf = readDecomposition(ouf);
    // check ouf validity
    // if invalid => _wa
    checkValidity(ouf, decOuf); // will _wa if invalid
    int oufWeight = decOuf.weight;
    int oufNodesCount = decOuf.m;

    // compare
    if(oufWeight < ansWeight){
        // that means official answer wasn't minimal
        quitf(_fail,
            "Participant's T-decomposition has smaller weight (%d) than jury's (%d). Jury not minimal?",
            oufWeight, ansWeight);
    } else if(oufWeight > ansWeight){
        // participant's solution is worse
        quitf(_wa,
            "Participant's T-decomposition has weight %d but jury's is %d, which is better.",
            oufWeight, ansWeight);
    } else {
        // weights are the same; compare number of nodes
        if(oufNodesCount < ansNodesCount){
            // participant found same weight with fewer nodes! => official solution not minimal in # of nodes
            quitf(_fail,
                "Participant's T-decomposition has the same weight (%d) but fewer T-nodes (%d < %d). Jury not minimal?",
                oufWeight, oufNodesCount, ansNodesCount);
        } else if(oufNodesCount > ansNodesCount){
            // participant used more T-nodes => WA
            quitf(_wa,
                "Participant's T-decomposition has the same weight (%d) but uses more T-nodes (%d > %d).",
                oufWeight, oufNodesCount, ansNodesCount);
        } else {
            // all match
            quitf(_ok, "OK. weight=%d, #nodes=%d", oufWeight, oufNodesCount);
        }
    }
    return 0; // unreachable, but just for completeness
}

