using namespace std;

const int MAXN = 100000;

int parent[MAXN + 1];

int find(int x) {
    if (parent[x] != x)
        parent[x] = find(parent[x]);
    return parent[x];
}

bool unite(int x, int y) {
    int px = find(x);
    int py = find(y);
    if (px == py) {
        // Cycle detected
        return false;
    }
    parent[px] = py;
    return true;
}

int main(int argc, char* argv[]) {
    registerValidation(argc, argv);

    int n = inf.readInt(2, 100000, "n");
    inf.readEoln();

    set<pair<int, int>> edges;
    for (int i = 1; i <= n; ++i)
        parent[i] = i;

    for (int i = 0; i < n - 1; ++i) {
        int a = inf.readInt(1, n, "a_i");
        inf.readSpace();
        int b = inf.readInt(1, n, "b_i");
        inf.readEoln();

        ensuref(a != b, "Self-loop detected on node %d", a);

        int u = min(a, b);
        int v = max(a, b);

        auto edge = make_pair(u, v);
        ensuref(!edges.count(edge), "Duplicate edge between %d and %d", u, v);
        edges.insert(edge);

        ensuref(unite(a, b), "Cycle detected when adding edge between %d and %d", a, b);
    }

    inf.readEof();
    return 0;
}

