using namespace std;

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    int t = inf.readInt(1, 10000);
    int total_n = 0;

    for (int testCase = 1; testCase <= t; ++testCase) {
        // Skip blank lines in input file
        while (!inf.seekEof() && inf.curChar() == '\n') {
            inf.readChar();
        }

        int n = inf.readInt(1, 200000, format("n in test case %d", testCase));
        int m = inf.readInt(0, 1000000, format("m in test case %d", testCase));

        total_n += n;
        if (total_n > 200000) {
            quitf(_fail, "Total n exceeds 200000");
        }

        vector<int> a(n), b(n);
        long long sum_a = 0, sum_b = 0;
        long long S_min = 0, S_max = 0;

        for (int i = 0; i < n; ++i) {
            a[i] = inf.readInt(0, 1000000, format("a[%d] in test case %d", i + 1, testCase));
            b[i] = inf.readInt(0, 1000000, format("b[%d] in test case %d", i + 1, testCase));
            if (m > a[i] + b[i]) {
                quitf(_fail, "In test case %d, m > a_i + b_i", testCase);
            }
            sum_a += a[i];
            sum_b += b[i];

            int min_x_i = max(0, m - b[i]);
            int max_x_i = min(a[i], m);
            S_min += min_x_i;
            S_max += max_x_i;
        }
        long long C = (sum_a - sum_b) + n * (long long)m;
        long long sum_x_opt = (C >= 0) ? (C / 2) : ((C - 1) / 2); // integer division rounding toward zero
        sum_x_opt = max(S_min, min(S_max, sum_x_opt));
        long long minimal_balance = abs(C - 2 * sum_x_opt);

        // Read participant's claimed balance_p
        long long balance_p = ouf.readLong(0, LLONG_MAX, format("balance in test case %d", testCase));

        // Read n lines of x_i and y_i
        vector<int> x(n), y(n);
        long long sum_x_p = 0, sum_y_p = 0;
        for (int i = 0; i < n; ++i) {
            x[i] = ouf.readInt(0, a[i], format("x[%d] in test case %d", i + 1, testCase));
            y[i] = ouf.readInt(0, b[i], format("y[%d] in test case %d", i + 1, testCase));
            if (x[i] + y[i] != m) {
                quitf(_wa, "In test case %d, x[%d] + y[%d] != m", testCase, i + 1, i + 1);
            }
            sum_x_p += x[i];
            sum_y_p += y[i];
        }

        long long balance_pp = abs((sum_a - sum_x_p) - (sum_b - sum_y_p));
        if (balance_p != balance_pp) {
            quitf(_wa, "In test case %d, claimed balance %lld does not match calculated balance %lld", testCase, balance_p, balance_pp);
        }

        if (balance_p != minimal_balance) {
            quitf(_wa, "In test case %d, balance is not minimal: expected %lld, found %lld", testCase, minimal_balance, balance_p);
        }
    }

    if (!ouf.seekEof()) {
        quitf(_wa, "Extra data found in output after last test case");
    }

    quitf(_ok, "All test cases passed");
}

