#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
    We must ensure that for each X we output, there exist integers A and B
    such that A^5 - B^5 = X, with 1 <= X <= 1e9.

    Strategy:
      1. We'll pick random A and B in certain ranges (depending on "type"), using testlib's global rnd variable.
      2. Compute diff = A^5 - B^5 using a function that avoids overflow for |A|, |B| <= 1000.
      3. If 1 <= diff <= 1e9, we output diff.
      4. If we fail to find any valid diff after a certain number of tries, output 1 (A=1, B=0 => 1^5 - 0^5=1).

    This ensures X always meets the problem constraints. 
    We do not set any random seed explicitly, as requested.
*/

static const long long MAX_X = 1000000000LL;

// Safely compute x^5 in 64-bit for |x| <= 1000 (1000^5 = 1e15 < 2^63).
long long myPow5(long long x) {
    bool neg = (x < 0);
    x = llabs(x);
    long long res = 1;
    for (int i = 0; i < 5; i++) {
        res *= x;
    }
    return neg ? -res : res;
}

// Attempt to find X = A^5 - B^5 in [1..1e9] by sampling A,B in [minAB..maxAB].
long long findX(int minAB, int maxAB) {
    const int MAX_TRIES = 30000;
    for (int t = 0; t < MAX_TRIES; t++) {
        long long A = rnd.next(minAB, maxAB);
        long long B = rnd.next(minAB, maxAB);
        long long diff = myPow5(A) - myPow5(B);
        if (diff >= 1 && diff <= MAX_X) {
            return diff;
        }
    }
    // fallback – if no valid result found after many tries, print 1.
    return 1LL;
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // "type" picks how we choose A,B for generating X.
    string type = opt<string>("type", "smallrandom");

    long long X = 1; // Default fallback

    if (type == "smallrandom") {
        // A,B in [-10..10]
        X = findX(-10, 10);
    }
    else if (type == "mediumrandom") {
        // A,B in [-100..100]
        X = findX(-100, 100);
    }
    else if (type == "largerandom") {
        // A,B in [-1000..1000]
        X = findX(-1000, 1000);
    }
    else if (type == "power") {
        // Also in [-1000..1000]. 
        X = findX(-1000, 1000);
    }
    else if (type == "special") {
        // Some known valid differences.
        vector<long long> specialVals = {1, 31, 211, 40951, 33};
        X = specialVals[rnd.next(0, (int)specialVals.size() - 1)];
    }
    else {
        // default fallback if type unrecognized
        X = findX(-10, 10);
    }

    cout << X << "\n";
    return 0;
}

