        {1, 0}, {2, 0}, {3, 0},
        {-3,1}, {-2,1}, {-1,1}, {0,1}, {1,1}, {2,1}, {3,1},
        {-3,2}, {-2,2}, {-1,2}, {0,2}, {1,2}, {2,2}, {3,2},
        {-3,3}, {-2,3}, {-1,3}, {0,3}, {1,3}, {2,3}, {3,3}
    };

    while (true) {
        if (inf.seekEof()) {
            // No more data
            break;
        }

        string line = inf.readLine();
        if (line.empty()) {
            continue; // skip empty lines
        }

        istringstream iss(line);
        vector<string> tokens;
        string token;
        while (iss >> token) {
            tokens.push_back(token);
        }

        if (tokens.empty()) {
            continue;
        }

        if (tokens.size() == 1) {
            // Possibly terminating line
            int x;
            try {
                x = stoi(tokens[0]);
            } catch (exception& e) {
                quitf(_fail, "Invalid integer in terminating line: '%s'", tokens[0].c_str());
            }
            if (x > 4) {
                // Ensure EOF after this
                if (!inf.seekEof()) {
                    quitf(_fail, "Extra data after terminating line");
                }
                break;
            } else {
                quitf(_fail, "Unexpected single integer %d", x);
            }
        } else {
            if (tokens.size() != 8) {
                quitf(_fail, "Expected 8 integers per data set, found %d", (int)tokens.size());
            }
            vector<pair<int,int>> data_positions;
            for (int i = 0; i < 4; ++i) {
                int xi, yi;
                try {
                    xi = stoi(tokens[2*i]);
                } catch (exception& e) {
                    quitf(_fail, "Invalid integer xi: '%s'", tokens[2*i].c_str());
                }
                try {
                    yi = stoi(tokens[2*i+1]);
                } catch (exception& e) {
                    quitf(_fail, "Invalid integer yi: '%s'", tokens[2*i+1].c_str());
                }
                if (xi < -3 || xi > 3) {
                    quitf(_fail, "xi[%d]=%d out of range [-3,3]", i+1, xi);
                }
                if (yi < 0 || yi > 3) {
                    quitf(_fail, "yi[%d]=%d out of range [0,3]", i+1, yi);
                }
                if (allowed_positions.count({xi, yi}) == 0) {
                    quitf(_fail, "(xi,yi)=(%d,%d) is not an allowed position", xi, yi);
                }
                data_positions.push_back({xi, yi});
            }
            // Check that positions are distinct
            set<pair<int,int>> position_set(data_positions.begin(), data_positions.end());
            if (position_set.size() != 4) {
                quitf(_fail, "The 4 positions are not distinct");
            }
