    }

    // Calculate cumulative_x_max and x_range
    long long cumulative_x_max = min(50000000LL, (long long)q * 1000LL);
    long long x_range = min(1000LL, cumulative_x_max / q);
    long long S_MIN = -MAX_SJ + cumulative_x_max;
    long long S_MAX = MAX_SJ - cumulative_x_max;

    // Generate initial sequence S
    vector<long long> S(n);
    if (s_type == "random") {
        for (int i = 0; i < n; ++i) {
            S[i] = rnd.next(S_MIN, S_MAX);
        }
    } else if (s_type == "palindrome") {
        for (int i = 0; i < n / 2; ++i) {
            S[i] = rnd.next(S_MIN, S_MAX);
            S[n - i - 1] = S[i];
        }
    } else if (s_type == "almost_palindrome") {
        // Generate a palindrome first
        for (int i = 0; i < n / 2; ++i) {
            S[i] = rnd.next(S_MIN, S_MAX);
            S[n - i - 1] = S[i];
        }
        // Change a few elements to break the palindrome property
        int changes = max(1, n / 1000); // Change 0.1% of the elements
        for (int i = 0; i < changes; ++i) {
            int idx = rnd.next(0, n - 1);
            S[idx] = rnd.next(S_MIN, S_MAX);
        }
    } else if (s_type == "all_same") {
        long long val = rnd.next(S_MIN, S_MAX);
        for (int i = 0; i < n; ++i) {
            S[i] = val;
        }
    } else {
        // Default to random if unrecognized type
        for (int i = 0; i < n; ++i) {
            S[i] = rnd.next(S_MIN, S_MAX);
        }
    }

    // Output N
    printf("%d\n", n);
    // Output S_1 ... S_N
    for (int i = 0; i < n; ++i) {
        printf("%lld", S[i]);
