#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 500000 + 5;
struct Node {
    long long minVal, maxVal;
    long long lazy;
};

Node st[4 * MAXN];
int N;
vector<int> S;

void build(int node, int l, int r) {
    if (l == r) {
        st[node].minVal = st[node].maxVal = S[l];
        st[node].lazy = 0;
    } else {
        int mid = (l + r) / 2;
        build(2 * node, l, mid);
        build(2 * node + 1, mid + 1, r);
        st[node].minVal = min(st[2 * node].minVal, st[2 * node + 1].minVal);
        st[node].maxVal = max(st[2 * node].maxVal, st[2 * node + 1].maxVal);
        st[node].lazy = 0;
    }
}

void push(int node, int l, int r) {
    if (st[node].lazy != 0) {
        st[node].minVal += st[node].lazy;
        st[node].maxVal += st[node].lazy;
        if (l != r) {
            st[2 * node].lazy += st[node].lazy;
            st[2 * node + 1].lazy += st[node].lazy;
        }
        st[node].lazy = 0;
    }
}

void update(int node, int l, int r, int ql, int qr, int x) {
    push(node, l, r);
    if (r < ql || l > qr)
        return;
    if (ql <= l && r <= qr) {
        st[node].lazy += x;
        push(node, l, r);
    } else {
        int mid = (l + r) / 2;
        update(2 * node, l, mid, ql, qr, x);
        update(2 * node + 1, mid + 1, r, ql, qr, x);
        st[node].minVal = min(st[2 * node].minVal, st[2 * node + 1].minVal);
        st[node].maxVal = max(st[2 * node].maxVal, st[2 * node + 1].maxVal);
    }
}

