    inf.readEoln();

    // Read S[0..N-1]
    S = inf.readInts(N, -100000000, 100000000, "S");
    inf.readEoln();

    // Build the segment tree
    build(1, 0, N - 1);

    // Read Q
    int Q = inf.readInt(1, 100000, "Q");
    inf.readEoln();

    for (int i = 0; i < Q; i++) {
        int l = inf.readInt(1, N, "l");
        inf.readSpace();
        int r = inf.readInt(l, N, "r");
        inf.readSpace();
        int x = inf.readInt(-1000, 1000, "x");
        inf.readEoln();

        // Update the segment tree
        update(1, 0, N - 1, l - 1, r - 1, x);

        // Check if any element is out of bounds
        long long minVal = st[1].minVal;
        long long maxVal = st[1].maxVal;
        ensuref(minVal >= -100000000,
                "After query %d, element minimum value %lld is less than -1e8", i + 1, minVal);
