#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);
    int t = inf.readInt(1, 10000, "t");
    long long total_n = 0;
    for (int testCase = 1; testCase <= t; ++testCase) {
        // Read n and m
        int n = inf.readInt(3, 100000, "n");
        int m = inf.readInt(1, n - 1, "m");
        total_n += n;
        if (total_n > 100000)
            quitf(_fail, "Total n exceeds 1e5");

        // Read m restrictions
        vector<tuple<int, int, int>> restrictions(m);
        for (int i = 0; i < m; ++i) {
            int a = inf.readInt(1, n, "a_i");
            int b = inf.readInt(1, n, "b_i");
            int c = inf.readInt(1, n, "c_i");
            if (a == b || b == c || a == c) {
                quitf(_fail, "Invalid restriction: nodes are not pairwise distinct in test case %d", testCase);
            }
            restrictions[i] = make_tuple(a - 1, b - 1, c - 1); // Convert to 0-based indices
        }

        // Read n-1 edges from participant output
        vector<vector<int>> adj(n);
        set<pair<int, int>> edgeSet;
        for (int i = 0; i < n - 1; ++i) {
            int u = ouf.readInt(1, n, format("u in edge %d of test case %d", i + 1, testCase).c_str()) - 1;
            int v = ouf.readInt(1, n, format("v in edge %d of test case %d", i + 1, testCase).c_str()) - 1;
            if (u == v)
                quitf(_wa, "Edge %d connects node %d to itself in test case %d", i + 1, u + 1, testCase);
            if (edgeSet.count({u, v}) || edgeSet.count({v, u})) {
                quitf(_wa, "Duplicate edge between node %d and node %d in test case %d", u + 1, v + 1, testCase);
            }
            edgeSet.insert({u, v});
            adj[u].push_back(v);
            adj[v].push_back(u);
        }

        // Check if the graph is connected and acyclic
        vector<bool> visited(n, false);
        function<void(int,int)> dfs = [&](int u, int p) {
            visited[u] = true;
            for (int v : adj[u]) {
                if (v != p) {
                    if (visited[v]) {
                        quitf(_wa, "The graph contains a cycle in test case %d", testCase);
                    }
                    dfs(v, u);
                }
            }
        };
        dfs(0, -1);
        if (std::any_of(visited.begin(), visited.end(), [](bool v){ return !v; })) {
            quitf(_wa, "The graph is not connected in test case %d", testCase);
        }
        // The graph is connected and acyclic (since n-1 edges), hence it is a tree.

        // Preprocess for LCA
        int LOGN = 17;
        vector<vector<int>> up(n, vector<int>(LOGN));
        vector<int> depth(n);
        vector<int> tin(n), tout(n);
        int timer = 0;

        function<void(int, int)> dfs_lca = [&](int u, int p) {
            tin[u] = timer++;
            up[u][0] = p == -1 ? u : p;
            for (int i = 1; i < LOGN; ++i) {
                up[u][i] = up[up[u][i-1]][i-1];
            }
            for (int v : adj[u]) {
                if (v != p) {
                    depth[v] = depth[u] + 1;
                    dfs_lca(v, u);
                }
            }
            tout[u] = timer++;
        };

        dfs_lca(0, -1);

        auto isAncestor = [&](int u, int v) {
            return tin[u] <= tin[v] && tout[u] >= tout[v];
        };

        auto lca = [&](int u, int v) {
            if (isAncestor(u, v)) return u;
            if (isAncestor(v, u)) return v;
            for (int i = LOGN - 1; i >= 0; --i) {
                if (!isAncestor(up[u][i], v)) {
                    u = up[u][i];
                }
            }
            return up[u][0];
        };

        auto is_on_path = [&](int u, int v, int x) {
            int l = lca(u, v);
            if ((isAncestor(x, u) && isAncestor(l, x)) || (isAncestor(x, v) && isAncestor(l, x)))
                return true;
            return false;
        };

        // Now, check each restriction
        for (int i = 0; i < m; ++i) {
            int a, b, c;
            tie(a, b, c) = restrictions[i];
            if (is_on_path(a, c, b)) {
                quitf(_wa, "Restriction %d violated in test case %d: node %d lies on path between %d and %d", i + 1, testCase, b + 1, a + 1, c + 1);
            }
        }
    }
    quitf(_ok, "All test cases passed");
}

