vector<int> partition_sum(int total, int parts, int min_value = 1){
    assert(total >= parts * min_value);
    total -= parts * min_value;

    vector<int> dividers;
    for(int i = 0; i < parts - 1; ++i){
        dividers.push_back(rnd.next(0, total));
    }
    dividers.push_back(0);
    dividers.push_back(total);
    sort(dividers.begin(), dividers.end());

    vector<int> res;
    for(int i = 1; i < dividers.size(); ++i){
        res.push_back(dividers[i] - dividers[i-1] + min_value);
    }

    return res;
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int q = opt<int>("q"); // Number of queries
    int sumlen = opt<int>("sumlen", 300000); // Total length of all s_i
    int maxa = opt<int>("maxa", 300000);
    string type = opt<string>("type", "random"); // Type of test cases
    int maxlen = opt<int>("maxlen", 300000); // Maximum length of s_i

    // Limitations
    ensure(1 <= q && q <= 300000);
    ensure(1 <= sumlen && sumlen <= 300000);
    ensure(1 <= maxlen && maxlen <= 300000);

    vector<int> s_lens(q);

    if(type == "max_length"){
        int base_len = sumlen / q;
        int remainder = sumlen % q;
        for(int i = 0; i < q; ++i){
            s_lens[i] = base_len + (i < remainder ? 1 : 0);
        }
    }else{
        s_lens = partition_sum(sumlen, q, 1);
    }

    vector<int> a_list, b_list;
    vector<string> s_list;

    for(int i = 0; i < q; ++i){
        int s_len = s_lens[i];
        int a, b;
        string s;

        if(type == "random"){
            b = rnd.next(1, maxa -1);
            a = rnd.next(b +1, maxa);
            // s_i is random
            for(int j = 0; j < s_len; ++j){
                s += (rnd.next(0,1) ? '.' : 'X');
            }
        }
        else if(type == "only_dots"){
            s = string(s_len, '.');
            b = rnd.next(1, maxa -1);
            a = rnd.next(b +1, maxa);
        }
        else if(type == "only_X"){
            s = string(s_len, 'X');
            b = rnd.next(1, maxa -1);
            a = rnd.next(b +1, maxa);
        }
        else if(type == "alternating"){
            s = "";
            for(int j = 0; j < s_len; ++j){
                s += (j%2 ==0 ? '.' : 'X');
            }
            b = rnd.next(1, maxa -1);
            a = rnd.next(b +1, maxa);
        }
        else if(type == "edge_case_a_gt_len"){
            // Ensure a > s_len
            a = s_len + rnd.next(1, 1000);
            if(a > 300000) a = 300000;
            b = rnd.next(1, a -1);
            s = "";
            for(int j = 0; j < s_len; ++j){
                s += (rnd.next(0,1) ? '.' : 'X');
            }
        }
        else if(type == "edge_case_b_gt_len"){
            // Ensure b > s_len
            b = s_len + rnd.next(1, 1000);
            if(b >= 300000) b = 300000 - 1;
            a = b + rnd.next(1, 1000);
            if(a > 300000) a = 300000;
            s = "";
            for(int j = 0; j < s_len; ++j){
                s += (rnd.next(0,1) ? '.' : 'X');
            }
        }
        else if(type == "long_dots"){
            // s_i consists of long sequences of '.'s
            s = "";
            int pos = 0;
            while(pos < s_len){
                int len_dot = rnd.next(1, s_len - pos);
                s += string(len_dot, '.');
                pos += len_dot;
                if(pos == s_len) break;
                int len_X = rnd.next(1, s_len - pos);
                s += string(len_X, 'X');
                pos += len_X;
            }
            b = rnd.next(1, maxa -1);
            a = rnd.next(b +1, maxa);
        }
        else{
            // Default to random
            b = rnd.next(1, maxa -1);
            a = rnd.next(b +1, maxa);
            // s_i is random
            for(int j = 0; j < s_len; ++j){
                s += (rnd.next(0,1) ? '.' : 'X');
            }
        }

        a_list.push_back(a);
        b_list.push_back(b);
        s_list.push_back(s);
    }

    // Now, output
    printf("%d\n", q);
    for(int i = 0; i < q; ++i){
        printf("%d %d\n", a_list[i], b_list[i]);
        printf("%s\n", s_list[i].c_str());
    }

    return 0;
}

