  for (int i = 0; i < (int)3; i++) a[i] *= s;
  return a;
}
double dot(const vector<double> &a, const vector<double> &b) {
  double res = 0;
  for (int i = 0; i < (int)3; i++) res += a[i] * b[i];
  return res;
}
vector<double> cross(const vector<double> &a, const vector<double> &b) {
  vector<double> c;
  c.push_back(a[1] * b[2] - b[1] * a[2]);
  c.push_back(b[0] * a[2] - a[0] * b[2]);
  c.push_back(a[0] * b[1] - b[0] * a[1]);
  return c;
}
double norm(const vector<double> &a) { return dot(a, a); }
double abs(const vector<double> &a) { return sqrt(norm(a)); }
int n, m, r;
vector<double> s[2000], t[2000], o;
double sr[2000], tb[2000];
bool v[1 << 15], flag[2000];
vector<double> projection(const vector<double> &a, const vector<double> &b,
                          const vector<double> &p) {
  double t = dot(p - a, a - b) / norm(a - b);
  return a + t * (a - b);
}
bool intersectSP(const vector<double> &a, const vector<double> &b,
                 const vector<double> &p) {
  if (abs(cross(a - b, p - b)) > EPS) return 0;
  double t = dot(p - b, a - b) / norm(a - b);
  return 0 <= t && t <= 1;
}
double distanceSP(const vector<double> &a, const vector<double> &b,
                  const vector<double> &p) {
  const vector<double> r = projection(a, b, p);
  if (intersectSP(a, b, r)) return abs(r - p);
  return min(abs(a - p), abs(b - p));
}
