// Generates a random integer coordinate in the range (-499..499).
int randCoord() {
    return rnd.next(-499, 499);
}

// Generates a random positive integer less than 500.
int randRadius() {
    // Problem states radius > 0 and < 500
    return rnd.next(1, 499);
}

// Generates a random brightness (1..79999).
int randBrightness() {
    return rnd.next(1, 79999);
}

// Returns the square of the Euclidean distance between (x1, y1, z1) and (x2, y2, z2).
double dist2(double x1, double y1, double z1, double x2, double y2, double z2) {
    double dx = x1 - x2;
    double dy = y1 - y2;
    double dz = z1 - z2;
    return dx * dx + dy * dy + dz * dz;
}

// Generates a random point (x, y, z) in [-499..499]^3, 
// then enforces minDist <= distance(E, T) <= maxDist.
void genLightPoint(double Ex, double Ey, double Ez,
                   double &Tx, double &Ty, double &Tz,
                   double minDist, double maxDist) {
    while (true) {
        Tx = randCoord();
        Ty = randCoord();
        Tz = randCoord();
        double d2 = dist2(Tx, Ty, Tz, Ex, Ey, Ez);
        // We want the distance, sqrt(d2), to be in [minDist, maxDist].
        // Also problem constraints: distance >= 1 from objective point.
        double d = sqrt(d2);
        if (d >= minDist && d <= maxDist) {
            break;
        }
    }
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // Read parameters
    int n = opt<int>("n", 5);       // number of balloons (1..2000)
    int m = opt<int>("m", 1);       // number of lights (1..15)
    int r = opt<int>("r", 0);       // number of balloons we can remove (0..n)
    string type = opt<string>("type", "random");

    // Make sure r <= n
    if (r > n) r = n;

    // We will store our dataset in these vectors/variables:
    vector<double> Sx(n), Sy(n), Sz(n);  // balloon centers
    vector<double> Sr(n);               // balloon radii
    vector<double> Tx(m), Ty(m), Tz(m);  // light positions
    vector<double> Tb(m);               // light brightness
    double Ex, Ey, Ez;                  // objective point

    // First, decide the objective point E.
    // By default, let's pick it randomly in [-499..499].
    // No explicit constraint forbids E = (0,0,0), so random is fine.
    Ex = randCoord();
    Ey = randCoord();
    Ez = randCoord();

    // Potential special behaviors based on "type"
    // We'll let "random" just produce fully random data, 
    // whereas other types might force certain arrangements.

    // If type == "rzero", override r=0
    if (type == "rzero") {
        r = 0;
    }
    // If type == "rall", override r=n
    if (type == "rall") {
        r = n;
    }

    // Generate balloon centers/radii
    // For simplicity, we do them all random in [-499..499], radius in [1..499].
    // There's no constraint that a balloon must be strictly away from E or lights.
    for (int i = 0; i < n; i++) {
        Sx[i] = randCoord();
        Sy[i] = randCoord();
        Sz[i] = randCoord();
        Sr[i] = randRadius();
    }

    // Now generate the M light sources.
    // Problem requires: distance(E, Tj) >= 1.
    // We'll decide the minDist,maxDist based on type for variety:
    double minDist = 1.0, maxDist = 499.0; // default for "random"

    if (type == "lightsclose") {
        // Place them near E, but still distance >= 1 and up to ~10
        minDist = 1.0;
        maxDist = 10.0;
    } else if (type == "lightsfar") {
        // Place them far from E, distance in [300..499]
        minDist = 300.0;
        maxDist = 499.0;
    }
    // If none of these special types, we just keep the default [1..499].

    for (int j = 0; j < m; j++) {
        double xx, yy, zz;
        genLightPoint(Ex, Ey, Ez, xx, yy, zz, minDist, maxDist);
        Tx[j] = xx;
        Ty[j] = yy;
        Tz[j] = zz;
        Tb[j] = randBrightness();
    }

    // Now we print out the dataset.
    // Format:
    // N M R
    // For i in [1..N]: Sx Sy Sz Sr
    // For j in [1..M]: Tx Ty Tz Tb
    // Ex Ey Ez
    // Next dataset or "0 0 0" for termination

    printf("%d %d %d\n", n, m, r);
    // Balloons
    for (int i = 0; i < n; i++) {
        // Must print integers, but it's allowed in the problem statement 
        // that coords are strictly > -500 and < 500. We used -499..499, so it's valid.
        // The problem statement says "Six, Siy, Siz are greater than -500, and less than 500",
        // and radius in (0, 500).
        // We'll cast to int and print. 
        printf("%.0f %.0f %.0f %.0f\n", Sx[i], Sy[i], Sz[i], Sr[i]);
    }
    // Lights
    for (int j = 0; j < m; j++) {
        printf("%.0f %.0f %.0f %.0f\n", Tx[j], Ty[j], Tz[j], Tb[j]);
    }
    // Objective point
    printf("%.0f %.0f %.0f\n", Ex, Ey, Ez);

    // End of all data sets with "0 0 0"
    // (Each run of the generator yields exactly one dataset plus the terminating line.)
    printf("0 0 0\n");

    return 0;
}

