    // Generate the initial list of errors a1, ..., an
    vector<int> a(n);

    if (type == "random") {
        // Random errors, no duplicates
        for (int i = 0; i < n; ++i)
            a[i] = rnd.next(1, maxA);
    } else if (type == "duplicates") {
        // Random errors with duplicates
        int distinct = rnd.next(1, n);
        vector<int> distinctErrors(distinct);
        for (int i = 0; i < distinct; ++i)
            distinctErrors[i] = rnd.next(1, maxA);
        for (int i = 0; i < n; ++i)
            a[i] = distinctErrors[rnd.next(0, distinct - 1)];
    } else if (type == "all_same") {
        // All errors are the same number
        int num = rnd.next(1, maxA);
        for (int i = 0; i < n; ++i)
            a[i] = num;
    } else if (type == "sorted") {
        // Errors are sorted in increasing order
        for (int i = 0; i < n; ++i)
            a[i] = rnd.next(1, maxA);
        sort(a.begin(), a.end());
    } else if (type == "reverse_sorted") {
        // Errors are sorted in decreasing order
        for (int i = 0; i < n; ++i)
            a[i] = rnd.next(1, maxA);
        sort(a.rbegin(), a.rend());
    } else if (type == "max") {
        // All errors are maxA
        for (int i = 0; i < n; ++i)
            a[i] = maxA;
    } else if (type == "small") {
        // All errors are small numbers
        maxA = min(maxA, 10);
        for (int i = 0; i < n; ++i)
            a[i] = rnd.next(1, maxA);
    } else if (type == "one_duplicate") {
        // Errors with exactly one duplicate number
        if (n < 2) {
            // Can't have duplicates with less than 2 elements
            for (int i = 0; i < n; ++i)
                a[i] = rnd.next(1, maxA);
        } else {
            int num = rnd.next(1, maxA);
            a[0] = num;
            a[1] = num;
            for (int i = 2; i < n; ++i)
                a[i] = rnd.next(1, maxA);
        }
    } else if (type == "many_duplicates") {
        // Errors where multiple numbers are duplicated
        int k = rnd.next(1, n); // number of distinct errors
        vector<int> distinctErrors(k);
        for (int i = 0; i < k; ++i)
            distinctErrors[i] = rnd.next(1, maxA);
        for (int i = 0; i < n; ++i)
            a[i] = distinctErrors[rnd.next(0, k - 1)];
    }

    // Now generate b by removing one error from a
    vector<int> b = a;
    int pos1 = rnd.next(0, n - 1);
    int removed1 = b[pos1];
    b.erase(b.begin() + pos1);

    // Generate c by removing another error from b
    int pos2 = rnd.next(0, n - 2);
    int removed2 = b[pos2];
    b.erase(b.begin() + pos2);
    vector<int> c = b;

    // Shuffle errors in a, b, c since the compiler shows errors in random order every time
    shuffle(a.begin(), a.end());
    shuffle(b.begin(), b.end());
    shuffle(c.begin(), c.end());

    // Output the sequences
    printf("%d\n", n);
    for (int i = 0; i < n; ++i)
        printf("%d%c", a[i], i + 1 == n ? '\n' : ' ');
    for (int i = 0; i < n - 1; ++i)
        printf("%d%c", b[i], i + 1 == n - 1 ? '\n' : ' ');
    for (int i = 0; i < n - 2; ++i)
        printf("%d%c", c[i], i + 1 == n - 2 ? '\n' : ' ');

    return 0;
}

