#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

typedef long long ll;
const ll MOD1 = 1000000007;
const ll MOD2 = 1000000009;
const int BASE = 911;

struct hash_pair {
    size_t operator()(const pair<ll,ll>& p) const {
        return hash<ll>{}(p.first) ^ (hash<ll>{}(p.second) << 1);
    }
};

int n, k;

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);
    n = inf.readInt(1, 100000, "n");
    inf.readSpace();
    k = inf.readInt(1, 100000, "k");
    ensuref(n >= k, "n must be >= k");
    ensuref(n % 2 == k % 2, "n mod 2 must equal k mod 2");
    inf.readEoln(); // don't need more from inf

    // Read participant's output
    std::string s = ouf.readLine();
    if ((int)s.length() != n)
        quitf(_wa, "Output string length is %d, expected %d", (int)s.length(), n);

    for (char c : s) {
        if (c != '0' && c != '1')
            quitf(_wa, "Invalid character '%c' in output string", c);
    }

    // Precompute powers
    vector<ll> powBase1(n + 1, 1), powBase2(n + 1, 1);
    for (int i = 1; i <= n; ++i) {
        powBase1[i] = (powBase1[i - 1] * BASE) % MOD1;
        powBase2[i] = (powBase2[i - 1] * BASE) % MOD2;
    }

    // Compute prefix hashes
    vector<ll> hashPrefix1(n + 1, 0), hashPrefix2(n +1, 0);
    for (int i = 0; i < n; ++i) {
        int val = s[i] - '0' + 1;
        hashPrefix1[i + 1] = (hashPrefix1[i] * BASE + val) % MOD1;
        hashPrefix2[i + 1] = (hashPrefix2[i] * BASE + val) % MOD2;
    }

    // Now compute minimal unique substring length
    int minUniqueLen = -1;

    int low = 1, high = n;

    while (low <= high) {
        int mid = (low + high) /2;
        unordered_map<pair<ll,ll>, int, hash_pair> hashCount;
        bool isUniqueExists = false;
        for (int i = 0; i <= n - mid; ++i) {
            ll hash1 = (hashPrefix1[i + mid] - hashPrefix1[i] * powBase1[mid] % MOD1 + MOD1) % MOD1;
            ll hash2 = (hashPrefix2[i + mid] - hashPrefix2[i] * powBase2[mid] % MOD2 + MOD2) % MOD2;

            pair<ll,ll> combinedHash = make_pair(hash1, hash2);
            hashCount[combinedHash]++;
        }
        for (auto &p : hashCount) {
            if (p.second == 1) {
                isUniqueExists = true;
                break;
            }
        }
        if (isUniqueExists) {
            minUniqueLen = mid;
            high = mid -1;
        } else {
            low = mid +1;
        }
    }

    if (minUniqueLen != k) {
        quitf(_wa, "Minimal unique substring length is %d, expected %d", minUniqueLen, k);
    } else {
        quitf(_ok, "OK, minimal unique substring length is %d", k);
    }
}

