            sizes[idx]++;
        }

        // Reverse the clusters
        reverse(clusters.begin(), clusters.end());

        // Assign clusters to files
        int idx = 0;
        files.resize(m);
        for (int i = 0; i < m; ++i) {
            int ni = sizes[i];
            files[i].resize(ni);
            for (int j = 0; j < ni; ++j) {
                files[i][j] = clusters[idx++];
            }
        }

    } else if (type == "non_contiguous") {
        // Clusters assigned to each file are scattered
        total_clusters_used = rnd.next(m, n - 1);
        sizes.assign(m, 1);
        int remaining = total_clusters_used - m;
        for (int i = 0; i < remaining; ++i) {
            int idx = rnd.next(0, m - 1);
            sizes[idx]++;
        }

        // Shuffle clusters
        shuffle(clusters.begin(), clusters.end());

        // Assign non-consecutive clusters to files
        int idx = 0;
        files.resize(m);
        for (int j = 0; j < (int)sizes[0]; ++j) {
            for (int i = 0; i < m; ++i) {
                if (j < sizes[i]) {
                    files[i].push_back(clusters[idx++]);
                }
            }
        }

    } else if (type == "consecutive_files") {
        // Files are already in perfect order
        total_clusters_used = rnd.next(m, n - 1);
        sizes.assign(m, 1);
        int remaining = total_clusters_used - m;
        for (int i = 0; i < remaining; ++i) {
            int idx = rnd.next(0, m - 1);
            sizes[idx]++;
        }

        // Assign clusters in order
        int idx = 0;
        files.resize(m);
        for (int i = 0; i < m; ++i) {
            int ni = sizes[i];
            files[i].resize(ni);
            for (int j = 0; j < ni; ++j) {
                files[i][j] = clusters[idx++];
            }
        }

    } else if (type == "worst_case") {
        // Construct a worst-case scenario for contestants
        total_clusters_used = n - 1;
        sizes.assign(m, total_clusters_used / m);
        int remainder = total_clusters_used % m;
        for (int i = 0; i < remainder; ++i) {
            sizes[i]++;
        }

        // Interleave clusters among files
        vector<int> idx(m, 0);
        int total = 0;
        files.resize(m);
        for (int i = 0; total < total_clusters_used; ++i) {
            for (int j = 0; j < m && total < total_clusters_used; ++j) {
                if (idx[j] < sizes[j]) {
                    files[j].push_back(clusters[total++]);
                    idx[j]++;
                }
            }
        }

    } else {
        // Default to random type
        // (Same as 'random' case)
        // Shuffle cluster indices
        shuffle(clusters.begin(), clusters.end());

        // Decide total clusters used
        total_clusters_used = rnd.next(m, n - 1);

        // Initialize file sizes to 1
        sizes.assign(m, 1);
        int remaining = total_clusters_used - m;

        // Distribute remaining clusters randomly
        for (int i = 0; i < remaining; ++i) {
            int idx = rnd.next(0, m - 1);
            sizes[idx]++;
        }

        // Assign clusters to files
        int idx = 0;
        for (int i = 0; i < m; ++i) {
            int ni = sizes[i];
            files[i].resize(ni);
            for (int j = 0; j < ni; ++j) {
                files[i][j] = clusters[idx++];
            }
        }
    }

    // Output the test case
    printf("%d %d\n", n, m);
    for (int i = 0; i < m; ++i) {
        int ni = files[i].size();
        printf("%d", ni);
        for (int j = 0; j < ni; ++j) {
            printf(" %d", files[i][j]);
        }
        printf("\n");
    }

    return 0;
}

