using namespace std;

// Each cluster can store content of form (fileID, indexInFile),
// or (0,0) if it is truly free initially.
struct ClusterContent {
    int fileID, indexInFile;
};

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    int n = inf.readInt(); // number of clusters
    int m = inf.readInt(); // number of files

    // fileSize[i] = number of clusters for file i (1-based indexing).
    vector<int> fileSize(m + 1);

    // content[c] = current (fileID, indexInFile) at cluster c (1-based).
    // By default, all clusters are free (0,0).
    vector<ClusterContent> content(n + 1, {0, 0});

    // Read the initial layout from the input:
    for (int i = 1; i <= m; i++) {
        int len = inf.readInt(1, n, "fileSize");
        fileSize[i] = len;
        for (int j = 1; j <= len; j++) {
            int clusterPos = inf.readInt(1, n, "clusterPos");
            content[clusterPos] = {i, j};
        }
    }

    // The contestant output:
    // 1) The number of copy operations K (0 <= K <= 2*n).
    // 2) Then K lines: "i j" meaning "copy from cluster i to cluster j".
    int K = ouf.readInt(0, 2 * n, "K");

    for (int step = 1; step <= K; step++) {
        int i = ouf.readInt(1, n, "copy_from");
        int j = ouf.readInt(1, n, "copy_to");
        if (i == j) {
            quitf(_wa, "Operation #%d: cannot copy from and to the same cluster", step);
        }
        // Apply the copy:
        content[j] = content[i];
    }

    // Check final arrangement:
    // Files must occupy the first some clusters, contiguously and in correct fragment order,
    // from fragment #1 through #fileSize[i]. The order of files is arbitrary,
    // but each file must appear exactly once, and leftover clusters are "unused"
    // regardless of their physical contents.

    vector<bool> usedFile(m + 1, false);
    int filesPlaced = 0;
    int c = 1; // pointer to current cluster

    // Place all m files:
    while (filesPlaced < m) {
        // If no more clusters yet not all files are placed => invalid
        if (c > n) {
            quitf(_wa, "Not enough clusters to place all files contiguously at the start");
        }
        // The next cluster must belong to some file. If it is free, that means there's a gap earlier.
        if (content[c].fileID == 0) {
            quitf(_wa, "Cluster %d is free while not all files are placed", c);
        }

        // Let this cluster start file f with fragment idx=1
        int f = content[c].fileID;
        int idx = content[c].indexInFile;
        if (idx != 1) {
            quitf(_wa, "File %d must start with fragment #1, but found fragment #%d at cluster %d",
                  f, idx, c);
        }
        if (usedFile[f]) {
            quitf(_wa, "File %d appears more than once in the final layout", f);
        }

        // Check that this file occupies fileSize[f] consecutive clusters
        // with indices 1..fileSize[f].
        for (int offset = 0; offset < fileSize[f]; offset++) {
            int pos = c + offset;
            if (pos > n) {
                quitf(_wa, "Not enough clusters to place file %d entirely", f);
            }
            if (content[pos].fileID != f || content[pos].indexInFile != offset + 1) {
                quitf(_wa,
                      "File %d's cluster at position %d has (fileID=%d, index=%d), expected (fileID=%d, index=%d)",
                      f, pos,
                      content[pos].fileID, content[pos].indexInFile,
                      f, offset + 1);
            }
        }

        // Mark file f as placed
        usedFile[f] = true;
        filesPlaced++;

        // Advance 'c' beyond this file
        c += fileSize[f];
    }

    // The leftover clusters (c..n) are beyond all files. The problem statement allows
    // them to contain anything physically. We do not require them to be (0,0).
    // So no further check is needed.

    quitf(_ok, "All files defragmented correctly");
}

