using namespace std;

vector<int> nAll; // Number of nodes for each test case
vector<int> mAll; // Number of edges for each test case
vector< vector< pair<int, int> > > edgesAll; // Edges for each test case

// Function to read and validate an answer from the stream. Returns the total number of cities where in-degree equals out-degree.
int readAns(InStream& stream, int tc, int n, int m, vector< pair<int, int> >& edges) {
    // Read the maximum number of cities
    int maxCities = stream.readInt(0, n, format("Test case %d: number of cities with equal in-degree and out-degree", tc+1).c_str());

    // Read m lines of oriented edges
    vector< pair<int, int> > orientedEdges;
    for (int i = 0; i < m; ++i) {
        int u = stream.readInt(1, n, format("Test case %d: edge %d: u", tc+1, i+1).c_str());
        int v = stream.readInt(1, n, format("Test case %d: edge %d: v", tc+1, i+1).c_str());
        orientedEdges.push_back(make_pair(u, v));
    }

    // Validate that each oriented edge corresponds to the original undirected edges
    set< pair<int, int> > undirectedEdgesSet;
    for (auto e : edges) {
        int u = e.first;
        int v = e.second;
        if (u > v) swap(u, v);
        undirectedEdgesSet.insert(make_pair(u, v));
    }

    // Build degree counts
    vector<int> inDegree(n+1, 0);
    vector<int> outDegree(n+1, 0);

    // Validate oriented edges and build degree counts
    set< pair<int, int> > usedEdges;
    for (auto e : orientedEdges) {
        int u = e.first;
        int v = e.second;

        if (u < 1 || u > n || v < 1 || v > n) {
            stream.quitf(_wa, "Invalid node number in edge (%d, %d)", u, v);
        }

        // Check that edge exists in original undirected edges
        int x = u;
        int y = v;
        if (x > y) swap(x, y);

        if (!undirectedEdgesSet.count(make_pair(x, y))) {
            stream.quitf(_wa, "Edge (%d, %d) is not present in the input graph", u, v);
        }

        // Check that each undirected edge is used only once
        if (usedEdges.count(make_pair(x, y))) {
            stream.quitf(_wa, "Edge (%d, %d) is used more than once", u, v);
        }

        usedEdges.insert(make_pair(x, y));

        outDegree[u]++;
        inDegree[v]++;
    }

    if ((int)usedEdges.size() != m) {
        stream.quitf(_wa, "Number of oriented edges (%d) does not match number of edges in input (%d)", (int)usedEdges.size(), m);
    }

    // Count the number of nodes where in-degree equals out-degree
    int cntEqualDegrees = 0;
    for (int i = 1; i <= n; ++i) {
        if (inDegree[i] == outDegree[i]) {
            cntEqualDegrees++;
        }
    }

    if (cntEqualDegrees != maxCities) {
        stream.quitf(_wa, "The number of cities where in-degree equals out-degree (%d) does not match the number reported in the output (%d)", cntEqualDegrees, maxCities);
    }

    return maxCities;
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    int t = inf.readInt(1, 200, "t");
    nAll.resize(t);
    mAll.resize(t);
    edgesAll.resize(t);

    // Read input from inf
    for (int tc = 0; tc < t; ++tc) {
        int n = inf.readInt(1, 200, "n");
        int m = inf.readInt(0, n * (n - 1) / 2, "m");
        nAll[tc] = n;
        mAll[tc] = m;

        set< pair<int, int> > edgeSet;
        vector< pair<int, int> > edges;
        for (int i = 0; i < m; ++i) {
            int u = inf.readInt(1, n, "u");
            int v = inf.readInt(1, n, "v");
            edges.push_back(make_pair(u, v));
            if (u > v) swap(u, v);
            edgeSet.insert(make_pair(u, v));
        }
        edgesAll[tc] = edges;
    }

    // Read and validate the jury's answer
    for (int tc = 0; tc < t; ++tc) {
        int jans = readAns(ans, tc, nAll[tc], mAll[tc], edgesAll[tc]);
        int pans = readAns(ouf, tc, nAll[tc], mAll[tc], edgesAll[tc]);

        if (pans < jans) {
            quitf(_wa, "Test case %d: Participant's answer (%d) is less than the optimal answer (%d).", tc + 1, pans, jans);
        } else if (pans > jans) {
            quitf(_fail, "Test case %d: Participant's answer (%d) is better than jury's answer (%d).", tc + 1, pans, jans);
        }
    }

    // If we reach here, all test cases passed
    quitf(_ok, "All test cases passed.");
}

