                            grid[y][x] = mat;
                        }
                    }
                } else {
                    auto cells = suspicious_shapes[m - (num_materials - num_suspicious)];
                    for(auto cell : cells){
                        int y = cell.first;
                        int x = cell.second;
                        grid[y][x] = mat;
                    }
                }
            }

            // Output grid
            for(int i = 0; i < H; ++i){
                printf("%s\n", grid[i].c_str());
            }

        } else if (type == "random") {
            // Generate a random grid with random letters
            for(int i = 0; i < H; ++i) {
                string line = "";
                for(int j = 0; j < W; ++j){
                    int coin = rnd.next(3);
