            }

            // Output grid
            for(int i = 0; i < H; ++i){
                printf("%s\n", grid[i].c_str());
            }

        } else {
            // Unknown type
            fprintf(stderr, "Unknown type: %s\n", type.c_str());
            exit(1);
        }
    }

    return 0;
