using namespace std;

void generate_random(int n, int m, vector<pair<int,int>>& edges) {
    // Generate a random tree to ensure connectivity
    vector<int> perm(n);
    for(int i = 0; i < n; ++i) perm[i] = i;
    shuffle(perm.begin(), perm.end());

    vector<int> parent(n, -1);
    for(int i = 1; i < n; ++i) {
        parent[perm[i]] = perm[rnd.next(0, i-1)];
        edges.push_back(make_pair(perm[i], parent[perm[i]]));
    }

    // Add extra edges up to m
    set<pair<int,int>> edge_set;
    for(auto e : edges) {
        int u = e.first, v = e.second;
        if(u > v) swap(u, v);
        edge_set.insert(make_pair(u, v));
    }

    int max_edges = n * (n - 1) / 2;
    m = min(m, max_edges);
    while((int)edges.size() < m) {
        int u = rnd.next(0, n-1);
        int v = rnd.next(0, n-1);
        if(u == v) continue;
        if(u > v) swap(u, v);
        if(edge_set.count(make_pair(u, v))) continue;
        edge_set.insert(make_pair(u, v));
        edges.push_back(make_pair(u, v));
    }
}

void generate_complete(int n, vector<pair<int,int>>& edges) {
    // Generate a complete graph
    for(int u = 0; u < n; ++u) {
        for(int v = u + 1; v < n; ++v) {
            edges.push_back(make_pair(u, v));
            if ((int)edges.size() >= 1000) break;
        }
        if ((int)edges.size() >= 1000) break;
    }
}

void generate_bipartite(int n, int m, vector<pair<int,int>>& edges) {
    // Partition the nodes into two sets
    int n1 = n / 2;
    int n2 = n - n1;
    vector<int> left(n1), right(n2);
    for(int i = 0; i < n1; ++i) left[i] = i;
    for(int i = 0; i < n2; ++i) right[i] = n1 + i;
    // Generate edges between left and right sets
    vector<pair<int,int>> possible_edges;
    for(int u : left) {
        for(int v : right) {
            possible_edges.push_back(make_pair(u, v));
        }
    }
    shuffle(possible_edges.begin(), possible_edges.end());
    m = min(m, (int)possible_edges.size());
    for(int i = 0; i < m; ++i) {
        edges.push_back(possible_edges[i]);
    }
    // Ensure connectivity
    if (edges.empty()) {
        edges.push_back(make_pair(left[0], right[0]));
    }
}

void generate_tree(int n, vector<pair<int,int>>& edges) {
    // Generate a random tree
    vector<int> perm(n);
    for(int i = 0; i < n; ++i) perm[i] = i;
    shuffle(perm.begin(), perm.end());
    for(int i = 1; i < n; ++i) {
        int u = perm[i];
        int v = perm[rnd.next(0, i-1)];
        edges.push_back(make_pair(u, v));
    }
}

void generate_zero_case(int n, vector<pair<int,int>>& edges) {
    // Generate a graph where the answer should be zero
    // For example, a complete graph of small size
    for(int u = 0; u < n; ++u) {
        for(int v = u + 1; v < n; ++v) {
            edges.push_back(make_pair(u, v));
            if ((int)edges.size() >= min(1000, n*(n-1)/2)) break;
        }
        if ((int)edges.size() >= min(1000, n*(n-1)/2)) break;
    }
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int t = opt<int>("t", 1); // Number of datasets
    string type = opt<string>("type", "random");

    for(int dataset = 0; dataset < t; ++dataset) {
        vector<pair<int,int>> edges;

        if(type == "random") {
            int m = opt<int>("m", 1000);
            m = min(m, 1000);
            m = max(m, n - 1);
            generate_random(n, m, edges);
        } else if(type == "complete") {
            if(n*(n-1)/2 > 1000) {
                fprintf(stderr, "Complete graph with n=%d exceeds M=1000\n", n);
                return 1;
            }
            generate_complete(n, edges);
        } else if(type == "bipartite") {
            int m = opt<int>("m", 1000);
            m = min(m, 1000);
            generate_bipartite(n, m, edges);
        } else if(type == "tree") {
            generate_tree(n, edges);
        } else if(type == "zero_case") {
            generate_zero_case(n, edges);
        } else {
            fprintf(stderr, "Unknown type: %s\n", type.c_str());
            return 1;
        }

        // Ensure the graph is connected
        vector<int> parent(n, -1);
        function<int(int)> find = [&](int x) {
            return parent[x] < 0 ? x : parent[x] = find(parent[x]);
        };
        auto unite = [&](int x, int y) {
            x = find(x); y = find(y);
            if(x != y) {
                parent[x] = y;
                return true;
            }
            return false;
        };
        // Verify connectivity
        for(auto e : edges) {
            unite(e.first, e.second);
        }

        int root = find(0);
        bool connected = true;
        for(int i = 1; i < n; ++i) {
            if(find(i) != root) {
                connected = false;
                break;
            }
        }
        if(!connected) {
            // Add edges to connect the components
            vector<int> components;
            for(int i = 0; i < n; ++i) {
                if(parent[i] < 0) components.push_back(i);
            }
            for(size_t i = 1; i < components.size(); ++i) {
                edges.push_back(make_pair(components[0], components[i]));
            }
        }

        // Output the dataset
        int m = edges.size();
        printf("%d %d\n", n, m);
        for(auto e : edges) {
            int u = e.first + 1;
            int v = e.second + 1;
            if(u > v) swap(u, v);
            printf("%d %d\n", u, v);
        }
    }
    // Output the end of input
    printf("0 0\n");
    return 0;
