            int a = inf.readInt(1, 60, "a");
            // Compute V *= p^a
            __int128_t temp = 1;
            for (int j = 0; j < a; ++j) {
                temp *= p;
                if (temp > ((__int128_t)1 << 110)) // Avoid overflow
                    break;
            }
            V *= temp;
        }

        // Read answer from ans (jury's output)
        long long S_ans = ans.readLong(1LL, LLONG_MAX, "S_ans");
        long long a_ans = ans.readLong(1LL, LLONG_MAX, "a_ans");
        long long b_ans = ans.readLong(1LL, LLONG_MAX, "b_ans");
        long long c_ans = ans.readLong(1LL, LLONG_MAX, "c_ans");

        // Read participant's output
        long long S_part = ouf.readLong(1LL, LLONG_MAX, "S_part");
        long long a_part = ouf.readLong(1LL, LLONG_MAX, "a_part");
        long long b_part = ouf.readLong(1LL, LLONG_MAX, "b_part");
        long long c_part = ouf.readLong(1LL, LLONG_MAX, "c_part");

        if (a_part <= 0 || b_part <= 0 || c_part <= 0)
            quitf(_wa, "Test case #%d: Edge lengths must be positive integers.", test);

        // Verify that a_part * b_part * c_part == V
        __int128_t V_part = (__int128_t)a_part * b_part * c_part;
        if (V_part != V)
            quitf(_wa, "Test case #%d: Product of edge lengths does not match volume V.", test);

        // Compute S_part = 2(ab + bc + ca)
        __int128_t S_computed = 2 * ((__int128_t)a_part * b_part + (__int128_t)b_part * c_part + (__int128_t)c_part * a_part);
        if (S_computed != S_part)
            quitf(_wa, "Test case #%d: Participant's surface area S does not match calculated S.", test);

        // Compare S_part to S_ans
        if (S_part > S_ans)
            quitf(_wa, "Test case #%d: Participant's surface area is larger than minimal.", test);
        else if (S_part == S_ans) {
            // OK
            continue;
        }
        else // S_part < S_ans
            quitf(_fail, "Test case #%d: Participant's surface area is smaller than the minimal in the jury's answer.", test);
    }
    quitf(_ok, "All %d test cases passed.", t);
}

