#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

typedef __int128 int128;

// Function to compute (a * b) with overflow check
bool multOverflow(int128 a, int128 b, int128 limit) {
    if (a == 0 || b == 0)
        return false;
    return a > limit / b;
}

// Function to compute (a ^ b) with overflow check
bool powOverflow(long long base, long long exponent, int128 limit, int128& result) {
    result = 1;
    int128 b = base;
    while (exponent > 0) {
        if (exponent % 2 == 1) {
            if (multOverflow(result, b, limit))
                return true;
            result *= b;
        }
        exponent /= 2;
        if (exponent > 0) {
            if (multOverflow(b, b, limit))
                return true;
            b *= b;
        }
    }
    return false;
}

// Modular multiplication with overflow check
long long mulmod(long long a, long long b, long long mod) {
    return (__int128)a * b % mod;
}

// Modular exponentiation
long long power_mod(long long a, long long d, long long mod) {
    long long result = 1 % mod;
    a %= mod;
    while (d) {
        if (d & 1)
            result = mulmod(result, a, mod);
        a = mulmod(a, a, mod);
        d >>= 1;
    }
    return result;
}

// Deterministic Miller-Rabin primality test for n < 1e18
bool isPrime(long long n) {
    if (n < 2)
        return false;
    if (n <= 3)
        return true;
    if (n % 2 == 0)
        return false;
    long long d = n - 1;
    int s = 0;
    while ((d & 1) == 0) {
        d >>= 1;
        s++;
    }
