#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
  Since the problem statement explicitly allows multiple correct solutions
  (indeed, it says "If there are several solutions, you can output any of them"),
  we must use a custom checker that verifies whether a contestant's output is
  a valid N×N arrangement (or "-1" if truly impossible) in which
  the rook pays strictly fewer teleports ("vuns") than the queen.

  Outline of the checker logic:
  1) Read N from the input file (inf).
  2) Read the contestant's output (ouf).
     - If the contestant prints "-1":
       • If N == 1, accept (because problem statement says no solution exists).
         Rook and queen both pay 0 teleports → cannot satisfy "rook < queen" → must output -1.
       • Otherwise, reject ("_wa"), because for N>1 the checker expects an arrangement is possible.
     - Otherwise, parse an N×N grid of integers. Check:
       • Exactly N lines each having N integers.
       • The numbers form a permutation of 1..N^2 (no repeats, none missing).
     - Simulate the described "movement rules" for both a rook and a queen:
       • They both begin in the cell labeled '1' (which is immediately visited).
       • In each step, if there is an unvisited cell reachable in one move, go to the unvisited one with
         the smallest label. ("One move" = same row/column for the rook; row/column/diagonal for the queen.)
       • If no unvisited cell is reachable, teleport to the smallest unvisited label and increment teleport cost.
       • Repeat until all cells are visited.
     - If rookTeleports < queenTeleports, verdict is _ok; otherwise, _wa.

  N can be up to 500, so N^2 up to 250000. We implement an approach that demonstrates correctness checks.
  In practice, you may need to optimize the data structures for large N.
*/

// We will simulate the path. For large N, care must be taken to keep it efficient.
// This example code focuses on correctness for demonstration.

long long simulate(
    int N,
    const vector<pair<int,int>>& pos,
    const vector< set<int> >& rowSetsIn,
    const vector< set<int> >& colSetsIn,
    const vector< set<int> >& d1SetsIn,  // might be empty for rook
    const vector< set<int> >& d2SetsIn,  // might be empty for rook
    bool isQueen)
{
    // Make local copies so we can erase from them
    vector< set<int> > rowSets = rowSetsIn;
    vector< set<int> > colSets = colSetsIn;
    vector< set<int> > d1Sets = d1SetsIn;
    vector< set<int> > d2Sets = d2SetsIn;

    // Track unvisited labels
    set<int> unvisited;
    for (int x = 1; x <= N*N; x++) {
        unvisited.insert(x);
    }

    // Start from label 1
    long long teleports = 0;
    int current = 1;
    unvisited.erase(1);

    // Remove label '1' from row, col, diag sets
    auto [r, c] = pos[1];
    rowSets[r].erase(1);
    colSets[c].erase(1);
    if (isQueen) {
        // For a cell (r,c),
        //  d1 = r - c + (N-1)
        //  d2 = r + c
        int d1 = r - c + (N - 1);
        int d2 = r + c;
        d1Sets[d1].erase(1);
        d2Sets[d2].erase(1);
    }

    // Continue until all visited
    while (!unvisited.empty()) {
        // Gather possible reachable labels in one move
        vector<int> candidates;
        // row
        if (!rowSets[r].empty()) {
            candidates.push_back(*rowSets[r].begin());
        }
        // column
        if (!colSets[c].empty()) {
            candidates.push_back(*colSets[c].begin());
        }
        if (isQueen) {
            int d1 = r - c + (N - 1);
            int d2 = r + c;
            if (!d1Sets[d1].empty()) {
                candidates.push_back(*d1Sets[d1].begin());
            }
            if (!d2Sets[d2].empty()) {
                candidates.push_back(*d2Sets[d2].begin());
            }
        }

        if (candidates.empty()) {
            // Teleport to smallest unvisited
            int v = *unvisited.begin();
            teleports++;
            current = v;
            unvisited.erase(v);
            auto [nr, nc] = pos[v];
            rowSets[nr].erase(v);
            colSets[nc].erase(v);
            if (isQueen) {
                int nd1 = nr - nc + (N - 1);
                int nd2 = nr + nc;
                d1Sets[nd1].erase(v);
                d2Sets[nd2].erase(v);
            }
            r = nr; c = nc;
        } else {
            // Move to the minimum among the candidates
            int best = *min_element(candidates.begin(), candidates.end());
            current = best;
            unvisited.erase(best);
            auto [nr, nc] = pos[best];
            rowSets[nr].erase(best);
            colSets[nc].erase(best);
            if (isQueen) {
                int nd1 = nr - nc + (N - 1);
                int nd2 = nr + nc;
                d1Sets[nd1].erase(best);
                d2Sets[nd2].erase(best);
            }
            r = nr; c = nc;
        }
    }

    return teleports;
}

int main(int argc, char* argv[])
{
    registerTestlibCmd(argc, argv);

    int N = inf.readInt(1, 500, "N");

    // The contestant's output can be "-1" or an N×N matrix of integers in [1..N*N]
    // Try reading first token
    if (!ouf.seekEof()) {
        string firstToken = ouf.readToken();

        if (firstToken == "-1") {
            // Accept only if N == 1. Otherwise, expect a valid arrangement
            if (N == 1) {
                // Must ensure there's no extra output
                if (!ouf.seekEof()) {
                    ouf.quitf(_wa, "Unexpected extra output after -1");
                }
                ouf.quitf(_ok, "Correctly printed -1 for N=1");
            } else {
                ouf.quitf(_wa, "Printed -1 but a solution likely exists for N > 1");
            }
        } else {
            // The first token should be the first integer in the board
            // parse it using either std::stoll or testlib's stringToLongLong().
            long long val = stringToLongLong(ouf, firstToken);
            if (val < 1 || val > 1LL * N * N) {
                ouf.quitf(_wa, "Board value out of range [1..N^2], got %lld", val);
            }

            vector<int> board(N*N);
            board[0] = (int) val;

            // Read the remaining N*N - 1 values
            for (int i = 1; i < N*N; i++) {
                long long v = ouf.readLong(1, (long long)N*N, "board value");
                board[i] = (int) v;
            }
            // Ensure no extra tokens
            if (!ouf.seekEof()) {
                ouf.quitf(_wa, "Extra tokens after N*N board values");
            }

            // Check if it's a valid permutation of [1..N*N]
            vector<int> freq(N*N + 1, 0);
            for (int x : board) {
                freq[x]++;
            }
            for (int x = 1; x <= N*N; x++) {
                if (freq[x] != 1)
                    ouf.quitf(_wa, "Number %d appears %d times, not a valid permutation", x, freq[x]);
            }

            // pos[x] = (row, col) for label x
            vector<pair<int,int>> pos(N*N + 1);
            for (int r = 0; r < N; r++) {
                for (int c = 0; c < N; c++) {
                    int x = board[r*N + c];
                    pos[x] = make_pair(r, c);
                }
            }

            // Build sets for rows, cols, diag1, diag2
            vector< set<int> > rowSets(N), colSets(N);
            // d1Sets, d2Sets each has range up to (2N-1) possible diagonals
            vector< set<int> > d1Sets(2*N - 1), d2Sets(2*N - 1);

            for (int r = 0; r < N; r++) {
                for (int c = 0; c < N; c++) {
                    int x = board[r*N + c];
                    rowSets[r].insert(x);
                    colSets[c].insert(x);
                    int d1 = r - c + (N - 1);
                    int d2 = r + c;
                    d1Sets[d1].insert(x);
                    d2Sets[d2].insert(x);
                }
            }

            // Simulate rook
            long long rookTeleports = simulate(N, pos, rowSets, colSets, {}, {}, false);

            // Simulate queen
            long long queenTeleports = simulate(N, pos, rowSets, colSets, d1Sets, d2Sets, true);

            if (rookTeleports < queenTeleports) {
                ouf.quitf(_ok, "Valid board with rookTeleports=%lld, queenTeleports=%lld",
                          rookTeleports, queenTeleports);
            } else {
                ouf.quitf(_wa,
                          "Rook teleports=%lld, Queen teleports=%lld, not strictly less",
                          rookTeleports, queenTeleports);
            }
        }
    } else {
        // No output
        ouf.quitf(_wa, "No output found");
    }

    return 0;
}

