using namespace std;

int main(int argc, char* argv[]){
    registerTestlibCmd(argc, argv);

    // Read input data from the test (inf)
    int n = inf.readInt();
    int m = inf.readInt();
    vector<pair<int,int>> nails(n);
    for(int i = 0; i < n; i++){
        int x = inf.readInt();
        int y = inf.readInt();
        nails[i] = {x, y};
    }
    vector<long long> rods(m);
    for(int i = 0; i < m; i++){
        rods[i] = inf.readLong();
    }

    // Read the jury (official) answer (ans)
    string juryFirstToken = ans.readToken();
    bool jurySaysYes = false;
    if (juryFirstToken == "YES") {
        jurySaysYes = true;
        // Read the jury's rod assignment, but we do not strictly validate it here.
        // We trust the jury's solution is consistent with the test data.
        for(int i = 0; i < n; i++){
            ans.readInt(-1, m);
        }
    }
    else if (juryFirstToken != "NO") {
        ans.quitf(_fail, "Jury output must be either YES or NO");
    }

    // Read the participant's answer (ouf)
    string partFirstToken = ouf.readToken();
    if (jurySaysYes)
    {
        // If the jury says YES (there is a solution):
        if (partFirstToken == "NO") {
            quitf(_wa, "Participant claims NO, but jury found a solution");
        }
        if (partFirstToken != "YES") {
            ouf.quitf(_wa, "Participant output must be either YES or NO");
        }

        // Now read the participant's rod assignment
        vector<int> rodsUsed(n);
        for(int i = 0; i < n; i++){
            rodsUsed[i] = ouf.readInt(-1, m, ("rodFoldAtNail#" + to_string(i+1)).c_str());
        }

        // A helper to compute Manhattan distance
        auto distMan = [&](int a, int b){
            return (long long)abs(nails[a].first - nails[b].first)
                 + (long long)abs(nails[a].second - nails[b].second);
        };

        // 1) Check that each rod index is used at most once for folding
        vector<bool> usedRod(m, false);
        for(int i = 0; i < n; i++){
            if (rodsUsed[i] != -1) {
                int rIdx = rodsUsed[i] - 1; // zero-based
                if (rIdx < 0 || rIdx >= m)
                    ouf.quitf(_wa, "Fold rod index %d out of valid range [1..%d]", rodsUsed[i], m);
                if (usedRod[rIdx])
                    ouf.quitf(_wa, "Rod %d is folded at more than one nail", rodsUsed[i]);
                usedRod[rIdx] = true;
            }
        }

        // 2) Check that each edge (i -> i+1 mod n) is covered exactly once
        //    An edge is covered if it is adjacent to a nail where a rod is folded.
        for(int i = 0; i < n; i++){
            int nxt = (i + 1) % n;
            bool coveredByI = (rodsUsed[i] != -1);
            bool coveredByNext = (rodsUsed[nxt] != -1);

            if (!coveredByI && !coveredByNext) {
                ouf.quitf(_wa, "Edge (%d -> %d) is not covered by any folded rod", i+1, nxt+1);
            }
            if (coveredByI && coveredByNext) {
                ouf.quitf(_wa, "Edge (%d -> %d) is covered by two folded rods", i+1, nxt+1);
            }
        }

        // 3) Check rod length correctness: 
        //    If rodsUsed[i] = r != -1, then rods[r-1] must equal
        //    distance(i, i-1) + distance(i, i+1) (Manhattan distances).
        for(int i = 0; i < n; i++){
            if (rodsUsed[i] != -1) {
                long long needed = distMan(i, (i - 1 + n) % n) + distMan(i, (i + 1) % n);
                long long actual = rods[rodsUsed[i] - 1];
                if (needed != actual) {
                    ouf.quitf(_wa, 
                        "Rod %d folded at nail %d has length %lld, but needed %lld",
                        rodsUsed[i], i+1, actual, needed
                    );
                }
            }
        }

        quitf(_ok, "Correct solution");
    }
    else
    {
        // Jury says NO
        if (partFirstToken == "NO") {
            // Both say NO
            quitf(_ok, "Both jury and participant say NO");
        }
        else if (partFirstToken == "YES") {
            // Participant found a solution while jury says NO => contradiction with the jury's data
            quitf(_fail, "Participant found a solution while jury claims none exists");
        }
        else {
            ouf.quitf(_wa, "Participant output must be either YES or NO");
        }
    }
}

