        char c = inf.readToken().c_str()[0];
        int color;
        if (c == 'R')
            color = 0;
        else if (c == 'B')
            color = 1;
        else
            inf.quitf(_fail, "Invalid color '%c' at edge %d.", c, i + 1);

        edges[i] = {u, v, color};
        adj[u].push_back(i);
        adj[v].push_back(i);
    }
}

int simulateMoves(InStream& stream, vector<int>& moves, int& k) {
    int first = stream.readInt(-1, n);
    if (first == -1) {
        k = -1;
        return -1;
    } else {
        k = first;
        moves.resize(k);
        for (int i = 0; i < k; ++i) {
            moves[i] = stream.readInt(1, n, format("move[%d]", i + 1).c_str());
        }
        // Simulate moves
        vector<int> edge_colors(m);
        for (int i = 0; i < m; ++i)
            edge_colors[i] = edges[i].color;

        for (int move : moves) {
            // Flip colors of all edges incident to move
            for (int idx : adj[move]) {
                edge_colors[idx] ^= 1;
            }
        }
        // Check if all edges have the same color
        int color = edge_colors[0];
        for (int c : edge_colors) {
            if (c != color) {
                stream.quitf(_wa, "Not all edges have the same color after %d moves", k);
            }
        }
        return color; // 0 or 1
    }
