    adj[u].append((v, c))
    adj[v].append((u, c))

VISITED = S = T = None


def bfs(start, k):
    """Perform BFS from start node with edge color k."""
    queue = deque([(start, 0)])
    while queue:
        node, parity = queue.pop()

        if VISITED[node] >= 0:
            if VISITED[node] == parity:
                continue
            return False

        VISITED[node] = parity
        if parity:
            S.append(node)
        else:
            T.append(node)

        for neighbor, color in adj[node]:
            nxt = parity if color == k else parity ^ 1
            queue.appendleft((neighbor, nxt))

