            for (int i = 0; i < N; ++i) {
                A[i] = rnd.next(1, 3000);
            }
        }
    } else if (type == "bigS") {
        // S equals sum of all A_i.
        for (int i = 0; i < N; ++i) A[i] = rnd.next(1, 3000);
        S = accumulate(A.begin(), A.end(), 0LL);
        if (S > 3000) S = 3000; // Ensure S within limits
    } else if (type == "smallS") {
        // S is 1.
        S = 1;
        for (int i = 0; i < N; ++i) A[i] = rnd.next(1, 3000);
    } else if (type == "middleS") {
        // S is about half of sum of A_i.
        for (int i = 0; i < N; ++i) A[i] = rnd.next(1, 3000);
        long long sumA = accumulate(A.begin(), A.end(), 0LL);
        S = sumA / 2;
        if (S < 1) S = 1;
        if (S > 3000) S = 3000;
    } else if (type == "special1") {
        // A_i = 1, maximize number of subsets summing to S.
        for (int i = 0; i < N; ++i) A[i] = 1;
        S = N; // Sum of all A_i
        if (S > 3000) S = 3000;
    } else {
        // Default to random if type not recognized.
        for (int i = 0; i < N; ++i) {
            A[i] = rnd.next(1, 3000);
        }
    }
    // Ensure N and S within constraints.
    N = max(1, min(N, 3000));
    S = max(1, min(S, 3000));
    // Output
    printf("%d %d\n", N, S);
    for (int i = 0; i < N; ++i) {
        printf("%d", A[i]);
        if (i < N -1) printf(" ");
        else printf("\n");
    }
