#include <bits/stdc++.h>
using namespace std;
const double eps = 1e-10;
double cross(complex<double> a, complex<double> b) {
  return (a.real() * b.imag() - a.imag() * b.real());
}
bool isp(complex<double> a, complex<double> b, complex<double> c) {
  return abs(a - c) + abs(b - c) < abs(a - b) + eps;
}
bool is_intersected_ll(complex<double> a1, complex<double> a2,
                       complex<double> b1, complex<double> b2) {
  return !(fabs((cross(a1 - a2, b1 - b2)) - (0.0)) < eps);
}
complex<double> intersection_ll(complex<double> a1, complex<double> a2,
                                complex<double> b1, complex<double> b2) {
  complex<double> a = a2 - a1, b = b2 - b1;
  return a1 + a * cross(b, b1 - a1) / cross(b, a);
}
double distance_l_p(complex<double> a, complex<double> b, complex<double> c) {
  return abs(cross(b - a, c - a)) / abs(b - a);
}
complex<double> getcand(pair<complex<double>, complex<double> > &a,
                        pair<complex<double>, complex<double> > &b, double r) {
  complex<double> ta = (a.second - a.first), tb = (b.second - b.first);
  ta /= abs(ta);
  tb /= abs(tb);
  a.second = a.first + ta;
  b.second = b.first + tb;
  complex<double> tmp = ((a.second - a.first) + (b.second - b.first)) / 2.;
  double theta = arg(tmp);
  r = abs(r / sin(theta));
  tmp = tmp / abs(tmp) * r;
  return a.first + tmp;
}
bool check(pair<complex<double>, complex<double> > a,
           pair<complex<double>, complex<double> > b,
           vector<pair<complex<double>, complex<double> > > &in,
           vector<double> &t, double r, double w, double h) {
  if (abs(a.second - b.second) < eps) return false;
  if (abs(a.first - a.second) < eps || abs(b.first - b.second) < eps)
    return false;
  complex<double> cand = getcand(a, b, r);
  if (!(-eps < cand.real() - r && cand.real() + r < w + eps &&
        -eps < cand.imag() - r && cand.imag() + r < h + eps))
    return false;
  for (int i = 0; i < in.size(); i++) {
    if (distance_l_p(in[i].first, in[i].second, cand) < t[i] + r) {
      return false;
    }
  }
  return true;
}
bool solve(vector<pair<complex<double>, complex<double> > > &a,
           vector<pair<complex<double>, complex<double> > > &b,
           vector<double> &t, double r, double w, double h) {
  for (int i = 0; i < a.size(); i++) {
    for (int j = i + 1; j < a.size(); j++) {
      if (is_intersected_ll(a[i].first, a[i].second, a[j].first, a[j].second)) {
        complex<double> tmp =
            intersection_ll(a[i].first, a[i].second, a[j].first, a[j].second);
        if (isnan(tmp.real())) continue;
        if (check(make_pair(tmp, a[i].first), make_pair(tmp, a[j].first), b, t,
                  r, w, h) ||
            check(make_pair(tmp, a[i].first), make_pair(tmp, a[j].second), b, t,
                  r, w, h) ||
            check(make_pair(tmp, a[i].second), make_pair(tmp, a[j].first), b, t,
                  r, w, h) ||
            check(make_pair(tmp, a[i].second), make_pair(tmp, a[j].second), b,
                  t, r, w, h))
          return true;
      }
    }
  }
  return false;
}
complex<double> getnorm(complex<double> b, double t) {
  complex<double> ret = complex<double>(-b.imag(), b.real());
  ret = ret / abs(ret) * t;
  return ret;
}
int main() {
  int w, h, n;
  double r;
  while (cin >> w >> h >> n >> r && w) {
    if (n == 0) {
      cout << "Yes" << endl;
      continue;
    }
    vector<pair<complex<double>, complex<double> > > in;
    vector<pair<complex<double>, complex<double> > > in2(n);
    vector<double> tt(n);
    for (int i = 0; i < n; i++) {
      vector<complex<double> > tmp;
      complex<double> a[2];
      for (int j = 0; j < 2; j++) {
        double x, y;
        cin >> x >> y;
        a[j] = complex<double>(x, y);
      }
      double t;
      cin >> t;
      in2[i] = make_pair(a[0], a[1]);
      tt[i] = t;
      complex<double> norm = getnorm(a[1] - a[0], t);
      for (int j = 0; j < 2; j++) {
        tmp.push_back(a[j] + norm);
        tmp.push_back(a[j] - norm);
      }
      in.push_back(make_pair(tmp[0], tmp[2]));
      in.push_back(make_pair(tmp[1], tmp[3]));
    }
    in.push_back(make_pair(complex<double>(0, 0), complex<double>(w, 0)));
    in.push_back(make_pair(complex<double>(w, 0), complex<double>(w, h)));
    in.push_back(make_pair(complex<double>(w, h), complex<double>(0, h)));
    in.push_back(make_pair(complex<double>(0, h), complex<double>(0, 0)));
