            s[i] = '0' + ((i+1) % 2);
    } else if(type == "one_zero") {
        s = string(n, '1');
        int pos = rnd.next(0, n-1);
        s[pos] = '0';
    } else if(type == "one_one") {
        s = string(n, '0');
        int pos = rnd.next(0, n-1);
        s[pos] = '1';
