        string half = "";
        int m = n/2;
        for(int i = 0; i < m; ++i)
            half += '0' + rnd.next(2);
        s = half;
        if(n%2 ==1)
            s += '0' + rnd.next(2);
        reverse(half.begin(), half.end());
        s += half;
    } else if(type == "max_alternating") {
        s = "";
