    q: number of lines in the program Q (1 <= q <= 10)
    type: either "random" or "corner" (default "random")
*/

static const vector<char> OPEN = {'(', '{', '['};
static const vector<char> CLOSE = {')', '}', ']'};

/*
  Generate a random "fully matched" bracket sequence for up to 2 pairs of each
  bracket type (so up to 6 pairs total). The sequence is well-formed and properly
  nested.  We do a small depth-first search with backtracking to place opens
  and closes in a valid way. Then return exactly one random valid sequence.
*/
string genBalancedBrackets() {
    // Number of pairs for each bracket type: each is 0..2
    int p1 = rnd.wnext(3, 1); // random in [0..2]
    int p2 = rnd.wnext(3, 1);
    int p3 = rnd.wnext(3, 1);
    int totalPairs = p1 + p2 + p3;
    if (totalPairs == 0) {
        // no brackets at all
        return "";
    }

    // We'll store how many opens/closes left for each type
    // p1, p2, p3 for '()', '{}', '[]'
    // We'll perform a random DFS that tries to build a well-formed sequence.
    struct State {
        int o1, o2, o3;  // how many opens left to place for each bracket type
        int c1, c2, c3;  // how many closes left to place for each bracket type
        string seq;
        stack<char> st;  // track types for nesting
    };

    // We'll place 2*(p1+p2+p3) brackets in total
    // The idea: at each step, we can (a) open a bracket of any type if available
    //           (b) close a bracket if it matches the top of stack
    // We'll do a single random DFS until we find a valid sequence or exhaust tries.

    // We do just one random walk:
    State start{p1, p2, p3, p1, p2, p3, "", {}};

    // A quick function to check if we are done:
    auto isDone = [&](const State &s) {
        return (s.o1==0 && s.o2==0 && s.o3==0 && s.c1==0 && s.c2==0 && s.c3==0);
    };

    // We'll do a stack-based random search:
    State cur = start;
    // The maximum length is 2* (p1+p2+p3).
    int steps = 2*totalPairs;

    // We'll store the path of brackets in cur.seq as we go.
    // If we can't proceed, we backtrack. But to keep it simpler (and not blow up),
    // we might do repeated random restarts if we get stuck.

    // We'll attempt up to 300 random walks. If we can't find any, we give up and return no brackets.
    // It's unlikely we'll fail for small numbers of pairs, but just in case.
    bool success = false;
    string bestSeq = "";

    for (int attempt = 0; attempt < 300 && !success; ++attempt) {
        // reset
        cur = start;
        while (!cur.st.empty()) cur.st.pop();
        cur.seq.clear();

        bool stuck = false;
        for (int i = 0; i < steps; i++) {
            vector<int> candidates;
            // Let's see what moves are possible:
            // open bracket type 1?
            if (cur.o1 > 0) {
                candidates.push_back(0); // open '('
            }
            // open bracket type 2?
            if (cur.o2 > 0) {
                candidates.push_back(1); // open '{'
            }
            // open bracket type 3?
            if (cur.o3 > 0) {
                candidates.push_back(2); // open '['
            }
            // close bracket if top of stack matches
            if (!cur.st.empty()) {
                char top = cur.st.top();
                if (top == '(' && cur.c1 > 0) {
                    candidates.push_back(3); // close ')'
                }
                else if (top == '{' && cur.c2 > 0) {
                    candidates.push_back(4); // close '}'
                }
                else if (top == '[' && cur.c3 > 0) {
                    candidates.push_back(5); // close ']'
                }
            }

            if (candidates.empty()) {
                stuck = true;
                break;
            }
            // pick a random move
            int mv = candidates[rnd.next((int)candidates.size())];

            if (mv == 0) {
                // open '('
                cur.seq.push_back('(');
                cur.st.push('(');
                cur.o1--;
            }
            else if (mv == 1) {
                // open '{'
                cur.seq.push_back('{');
                cur.st.push('{');
                cur.o2--;
            }
            else if (mv == 2) {
                // open '['
                cur.seq.push_back('[');
                cur.st.push('[');
                cur.o3--;
            }
            else if (mv == 3) {
                // close ')'
                cur.seq.push_back(')');
                cur.st.pop();
                cur.c1--;
            }
            else if (mv == 4) {
                // close '}'
                cur.seq.push_back('}');
                cur.st.pop();
                cur.c2--;
            }
            else if (mv == 5) {
                // close ']'
                cur.seq.push_back(']');
                cur.st.pop();
                cur.c3--;
            }
        }
        if (!stuck && isDone(cur)) {
            success = true;
            bestSeq = cur.seq;
        }
    }

    if (!success) {
        // fallback: just return empty
        return "";
    }
    return bestSeq;
}

// Generate random "words" with [1..5] letters
string genRandomWord() {
    int len = rnd.next(1,5);
    string s;
    s.reserve(len);
    for(int i=0; i<len; i++){
        s.push_back((char)('a' + rnd.next(26)));
    }
    return s;
}

/*
  Build a master's well-indented program of p lines, using an (R,C,S) triple
  and a random well-formed bracket sequence.
  We do the following steps:
    1) Randomly pick R, C, S in [1..5] (to keep indentation within 80).
    2) Generate a bracket sequence with up to 6 pairs total using genBalancedBrackets().
    3) Insert random words among the brackets, forming a token list.
    4) Ensure we have at least p tokens; if not, append more random words.
    5) Distribute the tokens across p lines, each line >= 1 token.
    6) Compute each line's indentation based on the bracket counts before that line:
       indent = R*(#openParen-#closeParen) + C*(#openCurly-#closeCurly) + S*(#openSquare-#closeSquare).
       (Because grouping must be properly nested, #open >= #close at all times.)
    7) Output lines with that many leading '.' characters, then the tokens of that line
       separated by '.' (Stylish uses periods for separation).
    8) Return the lines.
*/
vector<string> genMasterProgram(int p, string ttype){
    // corner: if ttype == "corner", produce minimal or no bracket
    if (ttype == "corner") {
        // special corner: p lines each with 0 indentation, no bracket, random words
        // This is valid (R=any, but effectively indentation=0).
        // We'll do something very simple here for demonstration.
        vector<string> lines;
        for(int i=0; i<p; i++){
            // no leading periods
            // 1 or 2 random words with '.' between them
            int w = rnd.next(1,2);
            stringstream ss;
            for(int j=0; j<w; j++){
                if(j>0) ss << '.';
                ss << genRandomWord();
            }
            lines.push_back(ss.str());
        }
        return lines;
    }

    // Otherwise, "random" approach
    // 1) pick R, C, S in [1..5]
    int R = rnd.next(1,6);
    int C = rnd.next(1,6);
    int S = rnd.next(1,6);

    // 2) bracket sequence
    string brackets = genBalancedBrackets();

    // 3) insert random words among brackets
    // We'll build a vector of tokens, each token is either a single bracket or a word
    vector<string> tokens;
    for(int i=0; i<(int)brackets.size(); i++){
        // possibly insert a random word with prob ~ 1/2
        if(rnd.next(2) == 0){
            tokens.push_back(genRandomWord());
        }
        // bracket
        tokens.push_back(string(1, brackets[i]));
    }
    // chance to add another random word at the end
    if(rnd.next(2)==0) tokens.push_back(genRandomWord());

    // ensure tokens >= p
    while((int)tokens.size() < p){
        tokens.push_back(genRandomWord());
    }

    // 4) distribute tokens across p lines
    // We want each line >= 1 token. We'll do a simple random distribution or
    // an even distribution.
    int T = tokens.size();
    vector<int> dist(p,1);  // each line gets at least 1
    int remain = T - p;     // leftover tokens
    for(int i=0; i<p; i++){
        if(remain == 0) break;
        int give = rnd.next(0, remain+1); // random from 0..remain
        dist[i] += give;
        remain -= give;
    }

    // We'll build the p lines. We'll track the bracket counts so we know indentation.
    int idx = 0;
    long long ro=0, rc=0, co=0, cc=0, so=0, sc=0; // running counts for open/close
    vector<string> lines;

    for(int i=0; i<p; i++){
        // compute indentation = R*(ro-rc) + C*(co-cc) + S*(so-sc)
        // guaranteed >=0 if well-matched so far
        long long indent = R*(ro-rc) + C*(co-cc) + S*(so-sc);
        if(indent < 0) indent = 0; // just in case, but it should not happen in a matched scenario
        if(indent > 70) indent = 70; // clamp, to avoid exceeding 80 chars

        // gather dist[i] tokens
        vector<string> lineTokens;
        for(int j=0; j<dist[i]; j++){
            if(idx < T){
                lineTokens.push_back(tokens[idx++]);
            }
        }
        // build the line
        // leading indent '.' characters
        // then tokens separated by '.'
        // must ensure we do not exceed 80 chars
        // We'll do a simple approach: if we exceed, we cut it short (rarely).
        ostringstream oss;
        for(int sp=0; sp<(int)indent; sp++){
            oss << '.';
        }
        // now place the lineTokens separated by '.'
        for(int j=0; j<(int)lineTokens.size(); j++){
            if(j>0) oss << '.';
            oss << lineTokens[j];
        }
        string lineOutput = oss.str();
        if((int)lineOutput.size() > 80){
            // cut it off
            lineOutput.resize(80);
        }
        lines.push_back(lineOutput);

        // update bracket counters with the tokens from this line
        for(auto &tk: lineTokens){
            for(char c: tk){
                if(c=='(') ro++;
                if(c==')') rc++;
                if(c=='{') co++;
                if(c=='}') cc++;
                if(c=='[') so++;
                if(c==']') sc++;
            }
        }
    }

    return lines;
}

/*
  Generate q lines for program Q (not necessarily matched).
  Constraint: no line starts with a period.
  We'll produce a few random words/brackets for each line. Possibly unmatched.
*/
vector<string> genQProgram(int q){
    vector<string> lines;
    for(int i=0; i<q; i++){
        // 0..3 bracket tokens, plus random words
        // must not start with '.'
        // We'll just build them in a string, ensuring first char is not '.'
        // We'll do 1..3 tokens
        int tcount = rnd.next(1,4);
        // pick tokens
        vector<string> lineTokens;
        for(int j=0; j<tcount; j++){
            // 50% bracket, 50% word
            if(rnd.next(2)==0){
                // bracket
                int x = rnd.next(6); // 0..5
                string b(1, (x<3 ? OPEN[x] : CLOSE[x-3]));
                lineTokens.push_back(b);
            } else {
                lineTokens.push_back(genRandomWord());
            }
        }
        // join them with '.'
        ostringstream oss;
        for(int j=0; j<tcount; j++){
            if(j>0) oss << '.';
            oss << lineTokens[j];
        }
        string lineOutput = oss.str();
        if((int)lineOutput.size()>80) lineOutput.resize(80);
        // ensure it does not start with '.'
        // If it does (which might happen if tcount>1 and the first token is empty, but we never do empty),
        // or if lineOutput[0]=='.', we can forcibly fix it by adding a letter in front:
        if(!lineOutput.empty() && lineOutput[0]=='.'){
            lineOutput = genRandomWord() + "." + lineOutput;
            if(lineOutput.size()>80) lineOutput.resize(80);
        }
        lines.push_back(lineOutput);
    }
    return lines;
}

int main(int argc, char* argv[]){
    registerGen(argc, argv, 1);

    // Read p, q from arguments
    int p = opt<int>("p", 5);          // default 5
    int q = opt<int>("q", 4);          // default 4
    string ttype = opt<string>("type", "random");

    // clamp p,q to [1..10], just to be safe
    p = max(1, min(p, 10));
    q = max(1, min(q, 10));

    // Generate the master's program (p lines)
    vector<string> P = genMasterProgram(p, ttype);

    // Generate Q (q lines)
    vector<string> Q = genQProgram(q);

    // Output one dataset
    cout << p << " " << q << "\n";
    for(auto &ln : P){
        // each line non-empty, up to 80 chars, but we already handled that
        // just print
        cout << ln << "\n";
    }
    for(auto &ln : Q){
        cout << ln << "\n";
    }

    // Finally output "0 0"
    cout << "0 0\n";

    return 0;
}

