using namespace std;
int main(int argc, char* argv[]) {
    registerValidation(argc, argv);

    while (true) {
        int p = inf.readInt(0, 10, "p");
        inf.readSpace();
        int q = inf.readInt(0, 10, "q");
        inf.readEoln();

        if (p == 0 && q == 0)
            break;

        ensuref(p >= 1 && p <= 10, "p must be between 1 and 10, got %d", p);
        ensuref(q >= 1 && q <= 10, "q must be between 1 and 10, got %d", q);

        // Read p lines of P
        vector<string> P;
        for (int i = 0; i < p; i++) {
            string s = inf.readLine();
            ensuref(1 <= s.length() && s.length() <= 80, "Line length of P must be between 1 and 80, got %d", (int)s.length());
            P.push_back(s);
        }

        // Check that P is well-indented (grouping symbols match and are nested properly)
        stack<char> stk;
        for (const string& s : P) {
            for (char c : s) {
                if (c == '(' || c == '{' || c == '[') {
                    stk.push(c);
                } else if (c == ')' || c == '}' || c == ']') {
                    if (stk.empty()) {
                        ensuref(false, "Unmatched closing symbol '%c' in P", c);
                    } else {
                        char open = stk.top();
                        stk.pop();
                        bool matched = (open == '(' && c == ')') ||
                                       (open == '{' && c == '}') ||
                                       (open == '[' && c == ']');
                        ensuref(matched, "Mismatched symbols '%c' and '%c' in P", open, c);
                    }
                }
            }
        }
        ensuref(stk.empty(), "Unmatched opening symbols in P");

        // Read q lines of Q
        for (int i = 0; i < q; i++) {
            string s = inf.readLine();
            ensuref(1 <= s.length() && s.length() <= 80, "Line length of Q must be between 1 and 80, got %d", (int)s.length());
            ensuref(s[0] != '.', "Line %d of Q starts with a period.", i + 1);
        }
    }

    inf.readEof();
    return 0;
}

