        a.resize(n);
        for(int i = 0; i < n; ++i) {
            a[i] = 1;
        }
    }
    else if (type == "max_many_sticks") {
        // Maximal counts across many lengths: a_i = 1e9
        a.resize(n);
        for(int i = 0; i < n; ++i) {
            a[i] = 1000000000;
        }
    }
    else if (type == "equal_counts") {
        // All counts are equal to 'count'
        int count = opt<int>("count", 1);
        a.resize(n);
        for(int i = 0; i < n; ++i) {
            a[i] = count;
        }
    }
    else if (type == "all_ones") {
        // All counts are 1
        a.resize(n);
        for(int i = 0; i < n; ++i) {
            a[i] = 1;
        }
    }
    else if (type == "random_counts") {
        // Random counts in range [min_count, max_count]
        int min_count = opt<int>("min_count", 1);
        int max_count = opt<int>("max_count", 1000000000);
        a.resize(n);
        for(int i = 0; i < n; ++i) {
            a[i] = rnd.next(min_count, max_count);
        }
    }
    else if (type == "specific_case1") {
        // Specific case: counts designed to test triangle inequality
        n = 3;
        a.resize(n);
        a[0] = 1;         // Length 1
        a[1] = 2;         // Length 2
        a[2] = 1;         // Length 4
    }
    else if (type == "max_n_max_counts") {
        // Maximum n and counts: n = 300000, a_i = 1e9
        n = 300000;
        a.resize(n);
        for(int i = 0; i < n; ++i) {
            a[i] = 1000000000;
        }
    }
    else if (type == "min_n_min_counts") {
        // Minimum n and counts: n = 1, a_0 = 1
        n = 1;
        a.resize(n);
        a[0] = 1;
    }
    else if (type == "random") {
        // Random counts in full range
        a.resize(n);
        for(int i = 0; i < n; ++i) {
            a[i] = rnd.next(1, 1000000000);
        }
    }
    else {
        // Default case: random counts
        a.resize(n);
        for(int i = 0; i < n; ++i) {
            a[i] = rnd.next(1, 1000000000);
        }
    }

    // Output n
    printf("%d\n", n);

    // Output a_0 ... a_{n-1}
    for(int i = 0; i < n; ++i) {
        printf("%d", a[i]);
        if (i < n -1)
            printf(" ");
    }
    printf("\n");

    return 0;
}

