#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

long long readAnswer(InStream& stream, int n, int m, int k, const vector<long long>& a, const vector<long long>& b, const vector<int>& c) {
    // Read the verdict
    string verdict = stream.readToken();

    if (verdict != "YES" && verdict != "NO")
        stream.quitf(_pe, "Expected 'YES' or 'NO' but found '%s'", verdict.c_str());

    if (verdict == "NO") {
        return -1; // NO solution
    }

    // Read n lines: each line contains two positive integers: subject_i, x_i
    vector<int> subject(n);
    vector<long long> x(n);

    set<int> used_subjects;

    for (int i = 0; i < n; i++) {
        subject[i] = stream.readInt(1, m, format("subject[%d]", i + 1).c_str());

        if (used_subjects.count(subject[i]))
            stream.quitf(_wa, "Subject %d is used more than once", subject[i]);

        used_subjects.insert(subject[i]);

        x[i] = stream.readLong(a[subject[i] - 1], b[subject[i] - 1], format("x[%d]", i + 1).c_str());
    }

    // Validate the conditions.

    // Condition 1: the subjects should be in order of complexities strict increasing
    for (int i = 1; i < n; i++) {
        int prev_complexity = c[subject[i - 1] - 1];
        int curr_complexity = c[subject[i] - 1];

        if (curr_complexity <= prev_complexity)
            stream.quitf(_wa, "Subjects not in increasing order of complexities at day %d", i + 1);
    }

    // Condition 2: For each i > 1, xi = xi-1 + k or xi = xi-1 * k
    for (int i = 1; i < n; i++) {
        long long xi = x[i];
        long long xi_1 = x[i - 1];

        if (xi != xi_1 + k && xi != xi_1 * k)
            stream.quitf(_wa, "Invalid relation between x[%d]=%lld and x[%d]=%lld with k=%d", i + 1, xi, i, xi_1, k);
    }

    // Compute total exercises
    long long total = accumulate(x.begin(), x.end(), 0LL);

    return total;
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    // Read input data
    int n = inf.readInt(); // n days
    int m = inf.readInt(); // m subjects
    int k = inf.readInt(); // k parameter

    vector<long long> a(m), b(m);
    vector<int> c(m);

    for (int i = 0; i < m; i++) {
        a[i] = inf.readLong();
        b[i] = inf.readLong();
        c[i] = inf.readInt();
    }

    // Read jury's and participant's answers
    long long jury_total = readAnswer(ans, n, m, k, a, b, c);
    long long participant_total = readAnswer(ouf, n, m, k, a, b, c);

    if (jury_total == -1) {
        // Jury says NO
        if (participant_total == -1) {
            quitf(_ok, "No solution exists");
        } else {
            // Participant found a solution but jury didn't
            quitf(_fail, "Participant found a solution but jury didn't");
        }
    } else {
        // Jury says YES
        if (participant_total == -1) {
            // Participant says NO but a solution exists
            quitf(_wa, "Participant failed to find a solution");
        } else {
            // Both have YES
            if (participant_total < jury_total) {
                quitf(_wa, "Participant's total exercises %lld is less than jury's total %lld", participant_total, jury_total);
            } else if (participant_total == jury_total) {
                quitf(_ok, "Correct solution with total exercises %lld", participant_total);
            } else {
                // Participant's total greater than jury's total
                quitf(_fail, "Participant's total exercises %lld is greater than jury's total %lld", participant_total, jury_total);
            }
        }
    }
}

