            for (int j = 0; j < m; ++j) {
                if ((i + j) % 2 == 0)
                    grid[i][j] = '.';
                else
                    grid[i][j] = '*';
            }
        }
        grid[r - 1][c - 1] = '.';
    } else if (maze_type == "path") {
        // Path from starting cell
        for (int i = 0; i < n; ++i)
            grid[i] = string(m, '*');

        int x_pos = r - 1;
        int y_pos = c - 1;
        grid[x_pos][y_pos] = '.';

        int path_length = rnd.next(1, n * m);
        set<pair<int, int>> visited;
        visited.insert({x_pos, y_pos});

        for (int i = 0; i < path_length - 1; ++i) {
            vector<pair<int, int>> dirs;
            if (x_pos > 0 && visited.find({x_pos - 1, y_pos}) == visited.end())
                dirs.push_back({x_pos - 1, y_pos});
            if (x_pos + 1 < n && visited.find({x_pos + 1, y_pos}) == visited.end())
                dirs.push_back({x_pos + 1, y_pos});
            if (y_pos > 0 && visited.find({x_pos, y_pos - 1}) == visited.end())
                dirs.push_back({x_pos, y_pos - 1});
            if (y_pos + 1 < m && visited.find({x_pos, y_pos + 1}) == visited.end())
                dirs.push_back({x_pos, y_pos + 1});

            if (dirs.empty())
                break;

            int idx = rnd.next(0, (int)dirs.size() - 1);
            x_pos = dirs[idx].first;
            y_pos = dirs[idx].second;
            grid[x_pos][y_pos] = '.';
            visited.insert({x_pos, y_pos});
        }
    } else if (maze_type == "spiral") {
        // Spiral pattern
        for (int i = 0; i < n; ++i)
            grid[i] = string(m, '*');

        int x1 = 0, y1 = 0, x2 = n - 1, y2 = m - 1;
        while (x1 <= x2 && y1 <= y2) {
            for (int i = y1; i <= y2; ++i) grid[x1][i] = '.';
            for (int i = x1 + 1; i <= x2; ++i) grid[i][y2] = '.';
            if (x1 < x2) {
                for (int i = y2 - 1; i >= y1; --i) grid[x2][i] = '.';
            }
            if (y1 < y2) {
                for (int i = x2 - 1; i > x1; --i) grid[i][y1] = '.';
            }
            ++x1; ++y1; --x2; --y2;
        }
        grid[r - 1][c - 1] = '.';
    } else {
        // Default to empty maze
    }

    // Ensure starting cell is free
    grid[r - 1][c - 1] = '.';

    // Output the maze
    printf("%d %d\n", n, m);
    printf("%d %d\n", r, c);
    printf("%d %d\n", x, y);
    for (int i = 0; i < n; ++i) {
        printf("%s\n", grid[i].c_str());
    }

    return 0;
}

