#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

int n;
int w, h; // Card dimensions
vector<pair<int, int>> envelopes; // Envelopes dimensions

// This function receives stream as an argument, reads an answer from it,
// checks its correctness (i.e., that it is indeed a valid chain according to the problem),
// and returns the chain size. If the chain is incorrect, it stops the execution
// with _wa outcome if stream == ouf (participant) or with _fail outcome if stream == ans (jury).
int readAndCheckAns(InStream& stream) {
    int chainSize = stream.readInt(0, n, "chain size");
    if (chainSize == 0) {
        return 0; // No chain provided
    }

    vector<int> chain(chainSize);
    set<int> usedIndices; // To check for duplicate envelopes

    for (int i = 0; i < chainSize; ++i) {
        int idx = stream.readInt(1, n, format("chain[%d]", i + 1).c_str()) - 1; // Convert to 0-based index
        if (usedIndices.count(idx)) {
            stream.quitf(_wa, "Envelope %d is used more than once in the chain", idx + 1);
        }
        usedIndices.insert(idx);
        chain[i] = idx;
    }

    // Check that the first envelope is strictly larger than the card
    int envW = envelopes[chain[0]].first;
    int envH = envelopes[chain[0]].second;

    if (!(envW > w && envH > h)) {
        stream.quitf(_wa, "The first envelope in the chain is not strictly larger than the card");
    }

    // Check that each envelope is strictly larger than the previous one
    for (int i = 1; i < chainSize; ++i) {
        int prevIdx = chain[i - 1];
        int currIdx = chain[i];

        int prevW = envelopes[prevIdx].first;
        int prevH = envelopes[prevIdx].second;

        int currW = envelopes[currIdx].first;
        int currH = envelopes[currIdx].second;

        if (!(currW > prevW && currH > prevH)) {
            stream.quitf(_wa, "Envelope %d is not strictly larger than envelope %d", currIdx + 1, prevIdx + 1);
        }
    }

    return chainSize;
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    // Reading input data
    n = inf.readInt();
    w = inf.readInt();
    h = inf.readInt();

    envelopes.resize(n);
    for (int i = 0; i < n; ++i) {
        int wi = inf.readInt();
        int hi = inf.readInt();
        envelopes[i] = make_pair(wi, hi);
    }

    // Reading jury's answer
    int juryChainSize = readAndCheckAns(ans);

    // Reading participant's answer
    int participantChainSize = readAndCheckAns(ouf);

    if (participantChainSize > juryChainSize) {
        // Participant found a better answer than the jury
        quitf(_fail, "Participant has a chain size (%d) greater than the jury's chain size (%d)",
              participantChainSize, juryChainSize);
    } else if (participantChainSize < juryChainSize) {
        // Participant's chain is shorter than the jury's
        quitf(_wa, "Participant's chain size (%d) is less than the jury's chain size (%d)",
              participantChainSize, juryChainSize);
    } else {
        // Participant's chain size matches the jury's
        quitf(_ok, "Chain size is %d", participantChainSize);
    }
}

