            // Sign bit is 0, integer and decimal parts are maximal
            bits = (((1u << 24) -1) << 7) | ((1u << 7) -1);
        } else if (type == "maxnegative") {
            // Sign bit is 1, integer and decimal parts are maximal
            bits = (1u << 31) | (((1u << 24) -1) << 7) | ((1u << 7) -1);
        } else if (type == "maxint") {
            // Integer part is maximal
            bits = (((1u << 24) -1) << 7) | rnd.next(0u, (1u << 7) -1);
            bits |= rnd.next(0u,1u)<<31; // Random sign
        } else if (type == "maxdec") {
            // Decimal part is maximal
            bits = ((1u << 7) -1) | (rnd.next(0u, (1u << 24) -1) << 7);
            bits |= rnd.next(0u,1u)<<31; // Random sign
        } else if (type == "minint") {
            // Integer part is zero
            bits = rnd.next(0u, (1u << 7) -1);
            bits |= rnd.next(0u,1u)<<31; // Random sign
        } else if (type == "mindec") {
            // Decimal part is zero
