            bits |= rnd.next(0u,1u)<<31; // Random sign
        } else if (type == "smallpositive") {
            // Small positive numbers
            bits = rnd.next(1u, (1u << 7) -1);
        } else if (type == "smallnegative") {
            // Small negative numbers
            bits = (1u << 31) | rnd.next(1u, (1u << 7) -1);
        } else if (type == "alternating") {
            // Bits alternating between 1 and 0
            bits = 0;
            for(int k = 0; k < 32; ++k) {
                if (k % 2 == 0)
                    bits |= 1u << k;
            }
