    // Need to ensure that total_n ≤ 1e5
    int total_n = 0;
    int max_total_n = 100000; // total number of students over all test cases should not exceed 1e5
    t = min(t, max_total_n/2); // since n ≥ 2

    printf("%d\n", t);

    for (int test = 0; test < t; ++test) {
        int curr_n;
        if (min_n != max_n) {
            curr_n = rnd.next(min_n, max_n);
        } else {
            curr_n = n;
        }

        if (curr_n % 2 != 0)
            curr_n += 1;
        if (curr_n < 2)
            curr_n = 2;
        if (curr_n > 1000)
            curr_n = 1000;

        if (total_n + curr_n > max_total_n) {
            curr_n = max_total_n - total_n;
            if (curr_n < 2) curr_n = 2;
            if (curr_n % 2 != 0) curr_n -= 1;
        }

        total_n += curr_n;

        printf("%d\n", curr_n);

        // Now generate curr_n students according to the 'type'

        // Generate array of curr_n entries, each with 5 bits (integers 0 or 1), with at least one 1.

        vector<vector<int>> availability(curr_n, vector<int>(5));

        if (type == "all_available") {
            // All students have availability [1,1,1,1,1]
            for (int i = 0; i < curr_n; ++i) {
                for (int j = 0; j <5; ++j)
                    availability[i][j] = 1;
            }
        } else if (type == "only_one_day") {
            // All students are only available on one day, e.g., day 1
            for (int i = 0; i < curr_n; ++i) {
                for (int j = 0; j <5; ++j)
                    availability[i][j] = 0;
                availability[i][0] = 1; // Only available on day 1
            }
        } else if (type == "alternating") {
            // Students' availability alternates.
            // Students with even index are available on days 1,3,5
            // Students with odd index are available on days 2,4
            for (int i = 0; i < curr_n; ++i) {
                if (i % 2 == 0) {
                    availability[i] = {1,0,1,0,1};
                } else {
                    availability[i] = {0,1,0,1,0};
                }
            }
        } else if (type == "random") {
            // Random availability
            for (int i = 0; i < curr_n; ++i) {
                int ones = 0;
                do {
                    ones = 0;
                    for (int j = 0; j <5; ++j) {
                        availability[i][j] = rnd.next(0,1);
                        ones += availability[i][j];
                    }
                } while (ones == 0);
            }
        } else if (type == "unbalanced") {
            // Students such that it's impossible to divide
            // E.g., more than n/2 students are only available on day 1
            int must_fail = curr_n / 2 + 1;
            for (int i = 0; i < curr_n; ++i) {
                for (int j = 0; j <5; ++j)
                    availability[i][j] = 0;
                if (i < must_fail) {
                    availability[i][0] = 1; // Only available on day 1
                } else {
                    availability[i][1] = 1; // Only available on day 2
                }
            }
        }

        // Output the availability
        for (int i = 0; i < curr_n; ++i) {
            for (int j = 0; j <5; ++j)
                printf("%d%c", availability[i][j], j == 4 ? '\n' : ' ');
