            teleports.push_back({ai_list[i], bi_list[i]});
        }
    } else if (type == "NO" || type == "impossible" || type == "no") {
        // Create a gap where Pig cannot reach m
        vector<int> ai_list(n);
        vector<int> bi_list(n);
        ai_list[0] = rnd.next(0, m - 1);
        for (int i = 1; i < n; ++i) {
            // Next ai is between previous ai and m - 1
            ai_list[i] = rnd.next(ai_list[i - 1], m - 1);
        }
        for (int i = 0; i < n; ++i) {
            // bi is less than m
            bi_list[i] = rnd.next(ai_list[i], m - 1);
        }
        // Create a gap: set a bi that ends before ai of next teleport
        bool inserted_gap = false;
        for (int i = 0; i < n - 1; ++i) {
            if (!inserted_gap && rnd.next(0, 1) == 0) {
                // Reduce bi so that it's less than ai_list[i + 1]
                if (ai_list[i + 1] > ai_list[i]) {
