                }
                inserted_gap = true;
            }
        }
        // Ensure that last bi_list[n - 1] < m
        bi_list[n - 1] = rnd.next(ai_list[n - 1], m - 1);
        for (int i = 0; i < n; ++i) {
            teleports.push_back({ai_list[i], bi_list[i]});
        }
    } else if (type == "no_start") {
        // Teleports do not start at 0
        vector<int> ai_list(n);
        ai_list[0] = rnd.next(1, m);
        for (int i = 1; i < n; ++i) {
            ai_list[i] = rnd.next(ai_list[i - 1], m);
        }
        for (int i = 0; i < n; ++i) {
            int bi = rnd.next(ai_list[i], m);
            teleports.push_back({ai_list[i], bi});
        }
    } else {
        // Random test case
        vector<int> ai_list(n);
        ai_list[0] = rnd.next(0, m);
        for (int i = 1; i < n; ++i) {
            ai_list[i] = rnd.next(ai_list[i - 1], m);
        }
        for (int i = 0; i < n; ++i) {
