            vector<int> composites;
            for (int i = 4; i <= 255; i++) {
                bool isComposite = false;
                for (int j = 2; j*j <= i; j++) {
                    if (i%j == 0) {
                        isComposite = true;
                        break;
                    }
                }
                if (isComposite) {
                    composites.push_back(i);
                }
            }
            n = composites[rnd.next(0, (int)composites.size()-1)];
        } else if (type == "prime") {
            vector<int> primes;
            for (int i = 2; i <= 255; i++) {
                bool isPrime = true;
                for (int j = 2; j*j <= i; j++) {
                    if (i%j == 0) {
                        isPrime = false;
                        break;
