#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

const int MAXN = 100005;
const int MAXM = 10005;
const int MAXLOG = 17; // since 2^17 > 1e5

int n, m;
vector<int> adj[MAXN];
int parent[MAXN][MAXLOG]; // parent[node][k] = 2^k-th ancestor of node
int depth[MAXN];

void dfs(int u, int p) {
    parent[u][0] = p;
    if (p != -1)
        depth[u] = depth[p] + 1;
    else
        depth[u] = 0;
    for (int k = 1; k < MAXLOG; k++) {
        if (parent[u][k - 1] != -1)
            parent[u][k] = parent[parent[u][k - 1]][k - 1];
        else
            parent[u][k] = -1;
    }
    for (int v : adj[u]) {
        if (v != p) {
            dfs(v, u);
        }
    }
}

int getLCA(int u, int v) {
    if (depth[u] < depth[v])
        swap(u, v);
    // Lift u up so that depth[u] == depth[v]
    for (int k = MAXLOG - 1; k >= 0; k--) {
        if (parent[u][k] != -1 && depth[parent[u][k]] >= depth[v])
            u = parent[u][k];
    }
    if (u == v)
        return u;
    // Lift u and v up together
    for (int k = MAXLOG - 1; k >= 0; k--) {
        if (parent[u][k] != -1 && parent[u][k] != parent[v][k]) {
            u = parent[u][k];
            v = parent[v][k];
        }
    }
    return parent[u][0];
}

void addPathEdges(int u, int v, int lca, int antColor, map<pair<int, int>, int> &edgeColor, InStream& ouf) {
    // From u up to lca
    while (u != lca) {
        int p = parent[u][0];
        int a = min(u, p);
        int b = max(u, p);
        pair<int, int> edge = make_pair(a, b);
        if (edgeColor.find(edge) != edgeColor.end()) {
            if (edgeColor[edge] != antColor) {
                ouf.quitf(_wa, "Edge (%d, %d) is assigned to multiple ants", a, b);
            }
        } else {
            edgeColor[edge] = antColor;
        }
        u = p;
    }
    // From v up to lca
    while (v != lca) {
        int p = parent[v][0];
        int a = min(v, p);
        int b = max(v, p);
        pair<int, int> edge = make_pair(a, b);
        if (edgeColor.find(edge) != edgeColor.end()) {
            if (edgeColor[edge] != antColor) {
                ouf.quitf(_wa, "Edge (%d, %d) is assigned to multiple ants", a, b);
            }
        } else {
            edgeColor[edge] = antColor;
        }
        v = p;
    }
}

