int main(int argc, char* argv[]) {
    registerValidation(argc, argv);
    int n = inf.readInt(2, 100000, "n");
    inf.readEoln();

    vector<int> parent(n + 1);
    for (int i = 1; i <= n; ++i) parent[i] = i;

    function<int(int)> find = [&](int x) {
        if (parent[x] != x) parent[x] = find(parent[x]);
        return parent[x];
    };

    auto unite = [&](int x, int y) {
        x = find(x);
        y = find(y);
        if (x == y) return false;
        parent[y] = x;
        return true;
    };

    set<pair<int, int>> edgeSet;

    for (int i = 0; i < n - 1; ++i) {
        int u = inf.readInt(1, n, "u_i");
        inf.readSpace();
        int v = inf.readInt(1, n, "v_i");
        inf.readEoln();

        ensuref(u != v, "Graph can't contain self-loops between %d and %d", u, v);

        int x = min(u, v);
        int y = max(u, v);
        ensuref(edgeSet.count({x, y}) == 0, "Multiple edges between %d and %d", x, y);
        edgeSet.insert({x, y});

        ensuref(unite(u, v), "Graph can't contain cycles");
    }

    set<int> roots;
    for (int i = 1; i <= n; ++i) {
        roots.insert(find(i));
    }
    ensuref(roots.size() == 1, "Graph must be connected");

    int m = inf.readInt(1, 10000, "m");
    inf.readEoln();

    for (int i = 0; i < m; ++i) {
        int a_i = inf.readInt(1, n, "a_i");
        inf.readSpace();
        int b_i = inf.readInt(1, n, "b_i");
