using namespace std;

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int m = opt<int>("m", -1); // If m is -1, it will be adjusted accordingly.
    string type = opt<string>("type", "random_sparse");
    int layers = opt<int>("layers", 2); // Used for 'maximal_rhombi' type.

    vector<pair<int,int>> edges; // List of edges.
    set<pair<int,int>> edgeSet;  // To ensure no duplicate edges.

    if (type == "empty") {
        // Empty graph with no edges.
        m = 0;
        // Nothing to do.
    } else if (type == "chain") {
        // Chain graph: Nodes connected in a line.
        m = n - 1;
        for(int i = 1; i < n; ++i) {
            edges.push_back({i, i+1});
            edgeSet.insert({i, i+1});
        }
    } else if (type == "star_in") {
        // Star graph with edges from center to leaves.
        int center = 1;
        m = n - 1;
        for(int i = 2; i <= n; ++i) {
            edges.push_back({center, i});
            edgeSet.insert({center, i});
        }
    } else if (type == "star_out") {
        // Star graph with edges from leaves to center.
        int center = 1;
        m = n - 1;
        for(int i = 2; i <= n; ++i) {
            edges.push_back({i, center});
            edgeSet.insert({i, center});
        }
    } else if (type == "full") {
        // Fully connected graph (excluding self-loops).
        m = n * (n - 1);
        for(int i = 1; i <= n; ++i) {
            for(int j = 1; j <= n; ++j) {
                if (i != j) {
                    edges.push_back({i, j});
                    edgeSet.insert({i, j});
                }
            }
        }
    } else if (type == "random_sparse" || type == "random_dense") {
        // Random graph with specified density.
        int maxEdges = n * (n - 1);
        if (m == -1) {
            if (type == "random_sparse") {
                m = rnd.next(n, min(maxEdges, n * 10)); // Sparse graph.
            } else {
                m = rnd.next(min(maxEdges, n * 10), maxEdges); // Dense graph.
            }
        } else {
            m = min(m, maxEdges);
        }
        while ((int)edges.size() < m) {
            int a = rnd.next(1, n);
            int b = rnd.next(1, n);
            if (a != b && edgeSet.find({a, b}) == edgeSet.end()) {
                edges.push_back({a, b});
                edgeSet.insert({a, b});
            }
        }
    } else if (type == "maximal_rhombi") {
        // Generate a graph designed to maximize the number of rhombi.
        // Create layers and connect every node in a layer to every node in the next layer.
        if (layers < 2 || layers > n) layers = 2;
        vector<vector<int>> layerNodes(layers);
        int idx = 1;
        for(int l = 0; l < layers; ++l) {
            int layerSize = n / layers + (l < n % layers);
            for(int i = 0; i < layerSize; ++i) {
                layerNodes[l].push_back(idx++);
            }
        }
        for(int l = 0; l < layers - 1; ++l) {
            for(int u : layerNodes[l]) {
                for(int v : layerNodes[l + 1]) {
                    edges.push_back({u, v});
                    edgeSet.insert({u, v});
                }
            }
        }
        m = edges.size();
    } else if (type == "minimal_rhombi") {
        // Generate a graph designed to minimize the number of rhombi.
        // Use a chain graph (no rhombi).
        m = n - 1;
        for(int i = 1; i < n; ++i) {
            edges.push_back({i, i + 1});
            edgeSet.insert({i, i + 1});
        }
    } else {
        // Default to random_sparse if unknown type.
        type = "random_sparse";
        int maxEdges = n * (n - 1);
        if (m == -1) {
            m = rnd.next(n, min(maxEdges, n * 10));
        } else {
            m = min(m, maxEdges);
        }
        while ((int)edges.size() < m) {
            int a = rnd.next(1, n);
            int b = rnd.next(1, n);
            if (a != b && edgeSet.find({a, b}) == edgeSet.end()) {
                edges.push_back({a, b});
                edgeSet.insert({a, b});
            }
        }
    }

    // Output the graph.
    printf("%d %d\n", n, m);
    for(auto e : edges) {
        printf("%d %d\n", e.first, e.second);
    }

    return 0;
}

