#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
  This generator produces input for the following problem:

  We have multiple test cases. Each test case consists of:
    n m
    p0 p1 ... p(m-1)

  with the constraints:
    - 2 <= n <= 2,000,000,000
    - 1 <= m <= 20
    - Each pi is a positive integer divisor of n (i.e. n % pi == 0).
    - The number of test cases does not exceed 200.
  The end of input is indicated by "0 0".

  We provide two generation modes via the "type" argument:
    1) type = "random" : Generate T random testcases
    2) type = "hand"   : Generate a small, fixed set of "corner / special" testcases

  After generating all testcases, the program will print "0 0" to end.
*/

/* 
   A helper function to factor a positive integer n up to 2e9 into its
   prime factors. Returns a vector of (primeFactor, exponent). 
   Complexity is O(sqrt(n)) in the worst case, which is feasible for 
   n ≤ 2e9 if used carefully (especially with up to 200 testcases total).
*/
static vector<pair<long long,int>> factor(long long n) {
    vector<pair<long long,int>> res;
    // Handle factor 2 separately
    int count2 = 0;
    while(n % 2 == 0) {
        n /= 2; 
        count2++;
    }
    if(count2>0) {
        res.push_back({2, count2});
    }

    // Handle odd factors
    for(long long i=3; i*i <= n; i+=2){
        int cnt = 0;
        while(n % i == 0) {
            n /= i;
            cnt++;
        }
        if(cnt>0){
            res.push_back({i, cnt});
        }
    }

    // If n > 1 here, then n itself is prime
    if(n > 1){
        res.push_back({n, 1});
    }
    return res;
}

/*
   Given the prime factorization of n, recursively construct
   the set of all divisors of n. This is a standard backtracking approach.
*/
static void getAllDivisors(
    const vector<pair<long long,int>>& f,
    int idx,
    long long current,
    vector<long long>& divisors
){
    if(idx == (int)f.size()){
        divisors.push_back(current);
        return;
    }
    // We can use prime factor f[idx].first from 0 times up to f[idx].second times
    auto prime = f[idx].first;
    auto exponent = f[idx].second;
    for(int e=0; e<=exponent; e++){
        getAllDivisors(f, idx+1, current, divisors);
        current *= prime;
    }
}

/*
   Generate *one* random test case:
     1) Pick n
     2) Factor it
     3) Get all divisors
     4) Pick m in [1..min(20, number_of_divisors)]
     5) Shuffle divisors and pick the first m
     6) Print them
*/
void generateRandomCase() {

    // We'll sometimes pick "small" n, sometimes pick a "large" n
    // so that factorization and divisor listing can test some extremes.
    // You can adjust the distribution to taste.
    // 50% chance for small n, 50% chance for large n.
    long long n;
    if(rnd.next(2) == 0) {
        // small range: [2..1e6]
        n = rnd.next(2LL, 1000000LL);
    } else {
        // large range: [1e9..2e9]
        long long lower = 1000000000LL;
        long long upper = 2000000000LL;
        n = rnd.next(lower, upper);
    }

    // Factor n
    vector<pair<long long,int>> fac = factor(n);
    // Generate all divisors
    vector<long long> divisors;
    divisors.reserve(1 << 20); // Just a large enough reserve
    getAllDivisors(fac, 0, 1, divisors);

    // Now we have all divisors of n. Shuffle them.
    shuffle(divisors.begin(), divisors.end());

    // We must pick m <= 20 and also m <= divisors.size().
    // If divisors.size() < 1 (theoretically shouldn't happen), skip.
    // Typically divisors.size() >= 1 because n >= 2.
    int dsz = (int)divisors.size();
    if(dsz == 0) {
        // Extremely unlikely (would only happen if n=1, but n>=2).
        // Just artificially do n=2
        n = 2;
        cout << n << " 1\n" << 1 << "\n";
        return;
    }

    int m = rnd.next(1, min(20, dsz));

    // Output
    cout << n << " " << m << "\n";
    for(int i=0; i<m; i++){
        cout << divisors[i];
        if(i+1 < m) cout << " ";
    }
    cout << "\n";
}

/*
   Produce "corner / special" testcases.
   We'll just print a fixed set of interesting inputs,
   ending with "0 0".
   - Some with minimal n
   - Some with p=1 to ensure no valid years
   - Some from the sample
   - Some large n
*/
void generateHandCases() {
    // 1) n=2, m=1, p=1 => no valid years => expected value=0
    cout << 2 << " " << 1 << "\n";
    cout << 1 << "\n";   // p=1 divides 2

    // 2) n=2, m=1, p=2 => only valid year is 1 => expected=1
    cout << 2 << " " << 1 << "\n";
    cout << 2 << "\n";

    // 3) From the sample: n=12, m=3, p=2 3 6 => expected=6
    cout << 12 << " " << 3 << "\n";
    cout << 2 << " " << 3 << " " << 6 << "\n";

    // 4) From the sample: n=12, m=4, p=1 2 3 6 => expected=0
    cout << 12 << " " << 4 << "\n";
    cout << 1 << " " << 2 << " " << 3 << " " << 6 << "\n";

    // 5) Larger corner: n=10, m=2, p=2 5 => random small
    //    (just to add variety)
    cout << 10 << " " << 2 << "\n";
    cout << 2 << " " << 5 << "\n";

    // 6) n=100, m=3, p=10 20 25 => all divisors of 100
    cout << 100 << " " << 3 << "\n";
    cout << 10 << " " << 20 << " " << 25 << "\n";

    // 7) n=2000000000 (2e9), m=1, p=1 => no valid years
    cout << 2000000000 << " " << 1 << "\n";
    cout << 1 << "\n";

    // 8) n=2000000000, m=1, p=2 => checks large n, single divisor
    //    (2 divides 2e9)
    cout << 2000000000 << " " << 1 << "\n";
    cout << 2 << "\n";

    // You can add more hand-crafted cases if desired.
    // End of "hand" set: now we stop by printing "0 0"
    cout << 0 << " " << 0 << "\n";
}

int main(int argc, char* argv[]) {
    // Initialize testlib
    registerGen(argc, argv, 1);

    // Number of random testcases to generate (if type = "random")
    int T = opt<int>("T", 1);
    // The mode of generation: "random" or "hand"
    string type = opt<string>("type", "random");

    if(type == "hand") {
        // Print a fixed set of special testcases, then 0 0
        generateHandCases();
        return 0;
    }

    // Otherwise, type == "random"
    // We'll generate T testcases, then end with 0 0
    // Make sure T <= 200 to satisfy the problem's limit.
    T = min(T, 200);

    for(int i=0; i<T; i++){
        generateRandomCase();
    }
    // At the end, print 0 0
    cout << 0 << " " << 0 << "\n";
    return 0;
}

