bool isPrime(long long num) {
    // Simple primality check for numbers > 1e8 and < 1e9
    if (num <= 1)
        return false;
    if (num <= 3)
        return true;
    if (num % 2 == 0 || num % 3 == 0)
        return false;
    for (long long i = 5; i * i <= num; i += 6) {
        if (num % i == 0 || num % (i + 2) == 0)
            return false;
    }
    return true;
}

long long nextPrime(long long n) {
    if (n <= 2) return 2;
    if (n % 2 == 0) n++;
    while (!isPrime(n)) {
        n += 2;
    }
    return n;
}

long long prevPrime(long long n) {
    if (n <= 2) return 2;
    if (n % 2 == 0) n--;
    while (n > 2 && !isPrime(n)) {
        n -= 2;
    }
    return n;
}

