using namespace std;

long long mod_mul(long long a, long long b, long long mod) {
    // a, b can be up to 1e9, so a*b up to 1e18, which fits in long long
    return (a % mod) * (b % mod) % mod;
}

long long mod_pow(long long a, long long b, long long mod) {
    long long res = 1;
    a %= mod;
    while (b > 0) {
        if (b % 2 == 1)
            res = mod_mul(res, a, mod);
        a = mod_mul(a, a, mod);
        b /= 2;
    }
    return res;
}

bool miller_rabin(int n) {
    if (n <= 1) return false;
    if (n == 2 || n == 3) return true;
    if (n % 2 == 0) return false;
    int d = n - 1;
    int s = 0;
    while (d % 2 == 0) {
        d /= 2;
        s++;
    }
    int bases[] = {2, 3};
    for (int a : bases) {
        if (a >= n) continue;
        long long x = mod_pow(a, d, n);
        if (x == 1 || x == n - 1)
            continue;
        bool composite = true;
        for (int r = 1; r < s; ++r) {
            x = mod_mul(x, x, n);
            if (x == n - 1) {
                composite = false;
                break;
            }
        }
        if (composite)
            return false;
    }
    return true;
}

