#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
  We have an array m[1..n]. The participant must output an array a[1..n] such that:
    1) 1 <= a[i] <= m[i]
    2) There is no index i for which there exist j < i < k
       with a[j] > a[i] and a[k] > a[i]. (No "valley" overshadowed by bigger heights on both sides.)
    3) The sum of a[i] is as large as possible (ties are allowed).

  Since there can be multiple valid answers with the same maximum sum, we compare the
  participant's sum to the jury's sum. If participant's sum is smaller, we report WA
  because it's not optimal. If it is equal, we accept (_ok). If it is larger, we report _fail
  because that would imply the jury's official solution wasn't maximum.
*/

// Reads and checks one solution (either jury's or participant's).
// The InStream object "stream" will be ans (jury's) or ouf (participant's).
long long readAndCheckSolution(
    InStream &stream,
    int n,
    const vector<long long> &m,
    bool isParticipant // true if reading participant's output
) {
    // Read n integers from the stream: a[1..n].
    vector<long long> a(n);
    for (int i = 0; i < n; i++) {
        // We must ensure 1 <= a[i] <= m[i].
        a[i] = stream.readLong(1LL, m[i], 
                 ("a[" + to_string(i+1) + "]").c_str());
    }

    // Check the "no overshadow" requirement:
    // We do this in O(n) by keeping track of max to the left and max to the right.
    // Condition: don't allow a[i] to be strictly less than a larger element to the left
    //            AND strictly less than a larger element to the right.
    // Equivalently, for no i should we have a[i] < maxLeft[i-1] and a[i] < maxRight[i+1].
    // We'll build maxLeft and maxRight arrays.
    vector<long long> maxLeft(n), maxRight(n);
    maxLeft[0] = a[0];
    for (int i = 1; i < n; i++) {
        maxLeft[i] = max(maxLeft[i-1], a[i]);
    }
    maxRight[n-1] = a[n-1];
    for (int i = n - 2; i >= 0; i--) {
        maxRight[i] = max(maxRight[i+1], a[i]);
    }

    for (int i = 1; i + 1 < n; i++) {
        if (a[i] < maxLeft[i-1] && a[i] < maxRight[i+1]) {
            if (isParticipant) {
                stream.quitf(_wa,
                    "The skyscraper at position %d is overshadowed by taller skyscrapers on both sides.",
                    i + 1
                );
            } else {
                // If it's the jury answer that's invalid, we use _fail.
                stream.quitf(_fail,
                    "Jury's answer is invalid at position %d.",
                    i + 1
                );
            }
        }
    }

    // If we passed all checks, return the sum of heights.
    long long sumHeights = 0;
    for (auto &val : a) sumHeights += val;

    return sumHeights;
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    // Read input data from inf.
    int n = inf.readInt(1, 500000, "n");
    vector<long long> m(n);
    for (int i = 0; i < n; i++) {
        // We only store these, no need to do extra checks here.
        m[i] = inf.readLong(1LL, 1000000000LL, ("m[" + to_string(i+1) + "]").c_str());
    }

    // Read and check the jury's official solution.
    long long jurySum = readAndCheckSolution(ans, n, m, /*isParticipant=*/false);

    // Read and check the participant's solution.
    long long partSum = readAndCheckSolution(ouf, n, m, /*isParticipant=*/true);

    // Compare sums.
    if (partSum < jurySum) {
        quitf(_wa, "Participant's total floors %lld is smaller than jury's %lld (not optimal).", partSum, jurySum);
    } else if (partSum == jurySum) {
        quitf(_ok, "Accepted. Total floors = %lld.", partSum);
    } else {
        // partSum > jurySum
        quitf(_fail, "Participant's total floors %lld exceeds jury's %lld.", partSum, jurySum);
    }
}

