using namespace std;

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    int t = inf.readInt();
    long long total_n = 0;
    for (int tc = 1; tc <= t; tc++) {
        // Read n, x, y from input file
        int n = inf.readInt();
        int x_give = inf.readInt();
        int y_give = inf.readInt();

        total_n += n;
        if (total_n > 100000)
            quitf(_fail, "Total n exceeds 1e5");

        // Read Bob's guess
        vector<int> bob_guess(n);
        for (int i = 0; i < n; i++) {
            bob_guess[i] = inf.readInt(1, n + 1);
        }

        // Read jury's answer
        string ans_s = ans.readToken();
        string ans_s_lower = ans_s;
        transform(ans_s_lower.begin(), ans_s_lower.end(), ans_s_lower.begin(), ::tolower);

        // Read participant's answer
        string ouf_s = ouf.readToken();
        string ouf_s_lower = ouf_s;
        transform(ouf_s_lower.begin(), ouf_s_lower.end(), ouf_s_lower.begin(), ::tolower);

        if (ouf_s_lower == "no") {
            // Participant outputs NO
            if (ans_s_lower == "no") {
                // Both say NO, acceptable
                continue;
            } else {
                // Jury says YES, participant says NO, wrong
                quitf(_wa, "Test case #%d: participant outputs NO while a solution exists", tc);
            }
        } else if (ouf_s_lower == "yes") {
            // Participant outputs YES

            // Check for extra tokens on the line after YES
            if (!ouf.seekEoln() && !ouf.eof()) {
                quitf(_wa, "Test case #%d: extra tokens on the line after YES", tc);
            }

            // Read participant's code
            vector<int> participant_code(n);
            for (int i = 0; i < n; i++) {
                participant_code[i] = ouf.readInt(1, n + 1, format("participant_code[%d]", i + 1).c_str());
            }

            // Check for extra tokens after reading the code
            if (!ouf.seekEoln() && !ouf.eof())
                quitf(_wa, "Test case #%d: extra tokens after reading participant's code", tc);

            // Calculate x and y based on participant's code and Bob's guess
            int x_count = 0;
            for (int i = 0; i < n; i++) {
                if (participant_code[i] == bob_guess[i]) {
                    x_count++;
                }
            }

            map<int, int> freq_bob, freq_participant;
            for (int i = 0; i < n; i++) {
                freq_bob[bob_guess[i]]++;
                freq_participant[participant_code[i]]++;
            }
            int y_count = 0;
            for (auto& p : freq_bob) {
                int color = p.first;
                int count_bob = p.second;
                int count_participant = freq_participant[color];
                y_count += min(count_bob, count_participant);
            }

            if (x_count != x_give) {
                quitf(_wa, "Test case #%d: participant's code gives x=%d, expected x=%d", tc, x_count, x_give);
            }
            if (y_count != y_give) {
                quitf(_wa, "Test case #%d: participant's code gives y=%d, expected y=%d", tc, y_count, y_give);
            }

            // All good

        } else {
            quitf(_wa, "Test case #%d: participant's answer is neither YES nor NO", tc);
        }

        // Consume any remaining lines in jury's output
        if (ans_s_lower == "yes") {
            // Jury's answer is YES
            // Read and skip the jury's code
            for (int i = 0; i < n; i++) {
                ans.readInt(); // Read but don't need to store
            }
        }

    }

    // All test cases passed
    quitf(_ok, "All test cases passed");
}

