def rearrange(array):
    from collections import deque
    array2 = []
    queue = deque(array)
    cur = 0
    while cur < len(array):
        if queue[0] != array[cur]:
            array2.append(queue.popleft())
            cur += 1
        else:
            temp = queue.popleft()
            queue.append(temp)
    return array2


def findout(perm, want, fixed):
    from collections import deque
    n_len = len(perm)
    positions = [[] for _ in range(n_len + 2)]

    for i, val in enumerate(perm):
        positions[val].append(i)
    missing_number = 0

    for i in range(1, n_len + 2):
        if not positions[i]:
            missing_number = i
            break

    vals = [0] * (n_len + 2)
    remain = want
    for i in range(len(positions)):
        if not positions[i]:
            continue
        used = min(want // 2, remain, len(positions[i]))
        vals[i] = used
        remain -= used
        if not remain:
            break

    if remain > 0:
        return []

    check = []
    for i in range(1, n_len + 2):
        check.append((vals[i], i))

    check = sorted(check)[::-1]
    array = []
    for val_count, color in check:
        array += [color] * val_count

    array2 = rearrange(array)

    indices1 = []
    for val_count, color in check:
        indices1 += positions[color][:val_count]

    changed = [0] * (n_len + 2)
    indices2 = []

    for color_val in array2:
        indices2.append(positions[color_val][changed[color_val]])
        changed[color_val] += 1

    indices_label = [0] * len(perm)
    for idx in indices1:
        indices_label[idx] = 1
    count = 0
    for i, label in enumerate(indices_label):
        if not label:
            count += 1
            indices_label[i] = 2
        if count == fixed:
            break

    new_perm = perm[:]

    for i, idx in enumerate(indices2):
        new_perm[idx] = perm[indices1[i]]

    for i, label in enumerate(indices_label):
        if not label:
            new_perm[i] = missing_number
    return new_perm


answers = []
for _ in range(int(input())):
    n_len, x_val, y_val = list(map(int, input().strip().split()))
    perm = list(map(int, input().strip().split()))
    fixed = x_val
    want = y_val - x_val
    ans = findout(perm, want, fixed)
    if not ans:
        answers.append("NO")
    else:
        answers.append("YES")
        ans = [str(x) for x in ans]
        ans = " ".join(ans)
        answers.append(ans)
print("\n".join(answers))

