using namespace std;

int main(int argc, char* argv[]) {
    // Register the generator
    registerGen(argc, argv, 1);

    // Parse command-line arguments
    int t = opt<int>("t");
    int max_n = opt<int>("max_n");
    string x_type = opt<string>("x_type", "random");

    // Maximum total sum of n over all test cases
    const int total_allowed_n = 50000;

    // Ensure t is within the constraints
    t = min(t, 10000);

    // Generate n for each test case
    vector<int> ns(t);
    int total_n = 0;

    if (x_type == "max_n") {
        // Use maximum n for each test case without exceeding total_allowed_n
        int per_n = min(max_n, total_allowed_n / t);
        for (int i = 0; i < t; ++i) {
            ns[i] = per_n;
            total_n += per_n;
        }
    } else if (x_type == "min_n") {
        // Set n = 1 for each test case
        for (int i = 0; i < t; ++i) {
            ns[i] = 1;
            total_n += 1;
        }
    } else {
        // Random n for each test case
        int remaining_n = total_allowed_n;
        for (int i = 0; i < t; ++i) {
            int min_allowed_n = 1;
            int max_allowed_n = min(max_n, remaining_n - (t - i - 1)); // Ensure enough n for remaining test cases
            ns[i] = rnd.next(min_allowed_n, max_allowed_n);
            remaining_n -= ns[i];
            total_n += ns[i];
        }
    }

    // Output number of test cases
    printf("%d\n", t);

    // Generate and output each test case
    for (int i = 0; i < t; ++i) {
        int n = ns[i];
