bool isValid(string s, int n) {
    if (s.length() != n)
        return false;
    if (s[0] == '0')
        return false;
    for (char c : s) {
        if (c != '0' && c != '1' && c != '2')
            return false;
    }
    return true;
}

bool checkXOR(string a, string b, string x) {
    int n = a.length();
    for (int i = 0; i < n; ++i) {
        int ai = a[i] - '0';
        int bi = b[i] - '0';
        int ci = x[i] - '0';
        if ((ai + bi) % 3 != ci)
            return false;
    }
    return true;
}

int compareBase3(string a, string b) {
    if (a.length() > b.length())
        return 1;
    if (a.length() < b.length())
        return -1;
    for (int i = 0; i < a.length(); ++i) {
        if (a[i] > b[i])
            return 1;
        if (a[i] < b[i])
            return -1;
    }
    return 0;
}

string maxBigInt(string a, string b) {
    int cmp = compareBase3(a, b);
    if (cmp >= 0)
        return a;
    else
        return b;
}

void readAnswer(InStream& stream, string& a, string& b, string x, int n, int testcase) {
    // Reading a and b from the stream
    a = stream.readToken();
    b = stream.readToken();

