import itertools

class Cube:
    def __init__(self, v):
        self.s = v
    def rotate_h(self):
        s = self.s
        self.s = s[0:1] + s[2:5] + s[1:2] + s[5:6]
    def rotate_v1(self):
        s = self.s
        self.s = s[1:2] + s[5:6] + s[2:3] + s[0:1] + s[4:5] + s[3:4]
    def rotate_v2(self):
        s = self.s
        self.s = s[2:3] + s[1:2] + s[5:6] + s[3:4] + s[0:1] + s[4:5]
    def get(self):
        return ''.join(self.s)

s = list(input())
ans = 0
used = set()
for v in itertools.permutations(s):
    c = Cube(v)
    tmp = set()
    ok = True
    for i in range(3):
        for j in range(4):
            state = c.get()
            if state in used:
                ok = False
                break
            tmp.add(state)
            c.rotate_h()
        if not ok:
            break
        c.rotate_v1()
        for j in range(4):
            state = c.get()
            if state in used:
                ok = False
                break
            tmp.add(state)
            c.rotate_h()
        if not ok:
            break
        c.rotate_v2()
    if ok:
        ans += 1
        used.update(tmp)

print(ans)

