        """Perform a horizontal rotation."""
        s_val = self.s
        self.s = s_val[0:1] + s_val[2:5] + s_val[1:2] + s_val[5:6]

    def rotate_v1(self):
        """Perform the first vertical rotation."""
        s_val = self.s
        self.s = s_val[1:2] + s_val[5:6] + s_val[2:3] + s_val[0:1] + s_val[4:5] + s_val[3:4]

