        // Now generate sequence
        vector<char> sequence(n);

        // Ensure that the first occurrence of each letter happens before any repeats
        // So we put each letter once in the sequence first
        for (int i = 0; i < d; ++i) {
            sequence[i] = used_letters[i];
        }

        // Now fill the rest of the sequence with letters chosen randomly from used_letters
        for (int i = d; i < n; ++i) {
            sequence[i] = used_letters[rnd.next(0, d - 1)];
