        vector<char> used_letters(letters.begin(), letters.begin() + d);

        vector<char> sequence;

        // Let's divide the sequence into parts, each using one letter, to ensure doors close before new ones open
        int per_letter = n / d;
        int extra = n % d;

        for (int i = 0; i < d; ++i) {
            int count = per_letter + (i < extra ? 1 : 0);
            for (int j = 0; j < count; ++j) {
                sequence.push_back(used_letters[i]);
            }
        }

