    registerTestlibCmd(argc, argv);

    // Read input data from 'inf'
    int n = inf.readInt(2, 1000, "n");
    vector<pair<int, int>> points(n);
    for (int i = 0; i < n; ++i) {
        int x = inf.readInt(-1000000, 1000000, format("x[%d]", i + 1).c_str());
        int y = inf.readInt(-1000000, 1000000, format("y[%d]", i + 1).c_str());
        points[i] = make_pair(x, y);
    }

    // Read participant's output from 'ouf'
    int a = ouf.readInt(1, n - 1, "a");
    vector<int> A_indices = ouf.readInts(a, 1, n, "indices of group A");

    // Check that indices are unique
    set<int> A_set(A_indices.begin(), A_indices.end());
    if ((int)A_set.size() != a) {
        ouf.quitf(_wa, "Group A indices are not unique");
    }

    // Build groups A and B
    vector<int> group(n, 1); // Default all to group B (1)
    for (int idx : A_indices) {
        int index = idx - 1; // Convert to 0-based index
        group[index] = 0; // Assign to group A (0)
    }

    // Compute distances and store in sets to check for conflicts
    set<long long> yellow_dists, blue_dists;
    for (int i = 0; i < n; ++i) {
        for (int j = i + 1; j < n; ++j) {
            long long dx = points[i].first - points[j].first;
            long long dy = points[i].second - points[j].second;
            long long dist2 = dx * dx + dy * dy; // Squared distance
            if (group[i] == group[j]) {
                // Same group (yellow)
                if (blue_dists.count(dist2)) {
                    ouf.quitf(_wa, "Distance %.15f between points %d and %d appears both in yellow and blue distances", sqrtl(dist2), i + 1, j + 1);
                }
                yellow_dists.insert(dist2);
            } else {
                // Different groups (blue)
                if (yellow_dists.count(dist2)) {
                    ouf.quitf(_wa, "Distance %.15f between points %d and %d appears both in yellow and blue distances", sqrtl(dist2), i + 1, j + 1);
                }
                blue_dists.insert(dist2);
            }
        }
    }

    // If no conflicts, the partition is valid
    quitf(_ok, "Participant's output is correct");
}

