int inv[17];
int po[17][17 << 1], B[17 << 1][17];
int odd[32];
int pre[1 << 16], all[1 << 16];
namespace modular {
int dec(int a, int b) { return a - b < 0 ? a - b + Mod : a - b; }
int add(int a, int b) { return a + b >= Mod ? a + b - Mod : a + b; }
int mul(int a, int b) { return 1ll * a * b % Mod; }
int Fast_Pow(int a, int b) {
  int res = 1;
  while (b) {
    if (b & 1) res = 1ll * res * a % Mod;
    a = 1ll * a * a % Mod;
    b >>= 1;
  }
  return res;
}
}  // namespace modular
using namespace modular;
void init(int i, int z) {
  for (int j = 0; j < (1 << (D + 1)); ++j)
    if (odd[((1 << (D + 1)) - 1 - j) & z])
      po[i][j] = dec(0, inv[i]);
    else
      po[i][j] = inv[i];
}
int to[17];
void Mul(int *A, int *B, int *C) {
  memset(to, 0, sizeof(int) * (K + 1));
  for (int i = 0; i <= K; ++i)
    for (int j = 0; j <= K - i; ++j)
      to[i + j] = add(to[i + j], mul(A[i], B[j]));
  memcpy(C, to, sizeof(int) * (K + 1));
}
void Div(int *A, int *B, int *C) {
  int t = Fast_Pow(B[0], Mod - 2);
  for (int i = 0; i <= K; ++i) {
    int tmp = A[i];
    for (int j = 1; j <= i; ++j) tmp = dec(tmp, mul(B[j], to[i - j]));
    to[i] = mul(tmp, t);
  }
  memcpy(C, to, sizeof(int) * (K + 1));
}
void Fast_Pow(int *res, int *a, int b) {
  while (b) {
    if (b & 1) Mul(res, a, res);
    Mul(a, a, a);
    b >>= 1;
  }
}
int cnt[16][17];
void solve(int tmp, int c) {
  if (!cnt[tmp][c]) return;
  int zjr = cnt[tmp][c];
  tmp += (1 << (c + D));
  int pre = tmp;
  for (int i = 0; i <= K; ++i) {
    int z = (pre ^ tmp) & ((1 << D) - 1);
    if (!(tmp & (1 << (c + D)))) z += (1 << D);
