#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

int main(int argc, char* argv[]) {

    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int k = opt<int>("k");
    int c = opt<int>("c");
    string type = opt<string>("type", "random");

    // Ensure constraints
    ensure(1 <= n && n <= (1 << c) - k);
    ensure(1 <= k && k <= 16);
    ensure(1 <= c && c <= 16);

    int max_value = (1 << c) - 1;

    vector<int> a(n);

    if (type == "random") {
        /* Generate n random distinct integers in [k, 2^c -1] */
        vector<int> possible_values;
        for (int i = k; i <= max_value; ++i)
            possible_values.push_back(i);
        shuffle(possible_values.begin(), possible_values.end());
        a.assign(possible_values.begin(), possible_values.begin() + n);
    } else if (type == "min") {
        /* Generate a_i = k, k+1, ..., k+n-1 */
        for (int i = 0; i < n; ++i)
            a[i] = k + i;
    } else if (type == "max") {
        /* Generate a_i = (2^c - n), ..., (2^c -1) */
        for (int i = 0; i < n; ++i)
            a[i] = max_value - n + 1 + i;
    } else {
        /* Unknown type */
        fprintf(stderr, "Unknown type '%s'\n", type.c_str());
        return 1;
    }

    /* Output n, k, c */
    printf("%d %d %d\n", n, k, c);

    /* Output a_i */
    for (int i = 0; i < n; ++i) {
        printf("%d", a[i]);
        if (i + 1 < n)
            printf(" ");
        else
            printf("\n");
    }

    return 0;
}

