    } else if (type == "all_same") {
        /* Generate a sequence where all elements are the same */
        int val = rnd.next(1, 150000);
        for (int i = 0; i < n; ++i)
            t[i] = val;
    } else if (type == "alternating") {
        /* Generate a sequence where the inequalities are the opposite of a nice sequence */
        for (int i = 0; i < n; ++i) {
            t[i] = rnd.next(1, 150000);
        }
        for (int i = 0; i + 1 < n; ++i) {
            if (i % 2 == 0) { // i even, position i+1 odd
                // Need t_i > t_{i+1}
                if (t[i] <= t[i + 1]) {
                    t[i + 1] = t[i] - 1;
                    if (t[i + 1] < 1) t[i + 1] = 1;
                }
            } else { // i odd, position i+1 even
                // Need t_i < t_{i+1}
                if (t[i] >= t[i + 1]) {
                    t[i + 1] = t[i] + 1;
                    if (t[i + 1] > 150000) t[i + 1] = 150000;
                }
            }
        }
    } else if (type == "one_swap_needed") {
        /* Generate a sequence that can be fixed by exactly one swap */
        for (int i = 0; i < n; ++i) {
            t[i] = i + 1; // Nice sequence
        }
        int pos = rnd.next(0, n - 2);
        swap(t[pos], t[pos + 1]); // Introduce an error
    } else if (type == "no_swap_possible") {
        /* Generate a sequence where no swap can make it nice */
        for (int i = 0; i < n; ++i)
            t[i] = n - i; // Decreasing sequence
    } else {
        /* Default case: random sequence */
        for (int i = 0; i < n; ++i)
            t[i] = rnd.next(1, 150000);
