    int k = opt<int>("k", 1);  // number of swaps for 'few_swaps' type

    vector<int> p(n);
    for (int i = 0; i < n; ++i)
        p[i] = i + 1;

    if (type == "sorted") {
        // Already sorted
    } else if (type == "reversed") {
        reverse(p.begin(), p.end());
    } else if (type == "random") {
        shuffle(p.begin(), p.end());
    } else if (type == "almost_sorted") {
        // Swap some adjacent pairs
        int swaps = min(k, n-1);
        for (int i = 0; i < swaps; ++i) {
            int idx = rnd.next(0, n - 2);
            swap(p[idx], p[idx + 1]);
        }
    } else if (type == "almost_reversed") {
        reverse(p.begin(), p.end());
        int swaps = min(k, n-1);
        for (int i = 0; i < swaps; ++i) {
            int idx = rnd.next(0, n - 2);
            swap(p[idx], p[idx + 1]);
        }
    } else if (type == "few_swaps") {
        int swaps = min(k, n*(n-1)/2);
        for (int i = 0; i < swaps; ++i) {
            int idx1 = rnd.next(0, n - 1);
            int idx2 = rnd.next(0, n - 1);
            while (idx2 == idx1) idx2 = rnd.next(0, n - 1);
            swap(p[idx1], p[idx2]);
        }
    } else if (type == "sawtooth") {
        vector<int> small, large;
        for (int i = 1; i <= n/2; ++i)
            small.push_back(i);
        for (int i = n/2 + 1; i <= n; ++i)
            large.push_back(i);
        shuffle(small.begin(), small.end());
        shuffle(large.begin(), large.end());
        p.clear();
        int i = 0, j = 0;
        while (i < small.size() && j < large.size()) {
            p.push_back(large[j++]);
            p.push_back(small[i++]);
        }
        while (i < small.size())
            p.push_back(small[i++]);
        while (j < large.size())
            p.push_back(large[j++]);
    } else {
        // Default to random
        shuffle(p.begin(), p.end());
    }

    printf("%d\n", n);
    for(int i = 0; i < n; ++i){
        printf("%d", p[i]);
        if (i + 1 != n) printf(" ");
    }
