def merge_sort(arr, left, right):
    """Sorts the array and counts inversions."""
    res = 0

    if left < right:
        mid = (left + right) // 2

        res += merge_sort(arr, left, mid)
        res += merge_sort(arr, mid + 1, right)

        i = left
        j = mid + 1
        b = []
        while i <= mid and j <= right:
            if arr[i] <= arr[j]:
                b.append(arr[i])
                i += 1
            else:
                b.append(arr[j])
                j += 1
                res += mid - i + 1

        while i <= mid:
            b.append(arr[i])
            i += 1

        while j <= right:
            b.append(arr[j])
            j += 1

        for idx, val in enumerate(b):
            arr[idx + left] = val

    return res


