#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
   Generator for the "Furoshiki Knapsack" problem.
   It produces up to T datasets. Each dataset is formatted as:
       W
       N
       v1,w1
       v2,w2
       ...
       vN,wN
   After T datasets are printed, a single 0 is printed as the
   last line to mark the end of all datasets.

   Parameters:
     -T       : The number of datasets to generate (default 1, up to 50).
     -minW    : The minimum W in each dataset (default 1).
     -maxW    : The maximum W in each dataset (default 1000).
                Must satisfy minW <= maxW <= 1000.
     -minN    : The minimum N in each dataset (default 1).
     -maxN    : The maximum N in each dataset (default 1000).
                Must satisfy minN <= maxN <= 1000.
     -type    : The type of dataset to generate (default "random").
                Possible values for "type" in this sample:
                  1) "random"    (random values & weights)
                  2) "zeroVal"   (all treasures have value 0, random weights)
                  3) "zeroWeight"(all treasures have weight 0, random values)
                  4) "maxVal"    (all treasures have value=10000, random weights)

   NOTE:
   - We do not set any random seed here. The testlib library supplies
     its own seed, so each run can give a different random set unless
     you override the environment from outside.
   - We respect all constraints in the problem statement:
     1 <= W <= 1000,
     1 <= N <= 1000,
     0 <= v_i <= 10000,
     0 <= w_i <= W,
     The number of datasets T <= 50.

   Usage example:
       ./gen -T 2 -minW 1 -maxW 10 -minN 1 -maxN 5 -type random
     This will produce 2 datasets, each with:
       W in [1..10],
       N in [1..5],
       random v_i and w_i within constraints,
     followed by a 0 at the end.

   Then you can concatenate outputs of multiple runs into one file
   if you wish, or keep them separate as multiple input files.
*/

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // Parameters
    int T       = opt<int>("T", 1);          // Number of datasets to generate
    int minW    = opt<int>("minW", 1);
    int maxW    = opt<int>("maxW", 1000);
    int minN    = opt<int>("minN", 1);
    int maxN    = opt<int>("maxN", 1000);
    string type = opt<string>("type", "random");

    // Safety checks (not strictly necessary, but recommended)
    T       = max(1, min(T, 50));
    minW    = max(1, min(minW, 1000));
    maxW    = max(minW, min(maxW, 1000));
    minN    = max(1, min(minN, 1000));
    maxN    = max(minN, min(maxN, 1000));

    for (int dataset = 0; dataset < T; dataset++) {
        // Randomly choose W in [minW, maxW]
        int W = rnd.next(minW, maxW);
        // Randomly choose N in [minN, maxN]
        int N = rnd.next(minN, maxN);

        // Print W
        cout << W << "\n";
        // Print N
        cout << N << "\n";

        // Generate N lines of "value,weight"
        for (int i = 0; i < N; i++) {
            int v = 0, w = 0;
            if (type == "random") {
                v = rnd.next(0, 10000);
                w = rnd.next(0, W);
            }
            else if (type == "zeroVal") {
                // All values are 0, random weights
                v = 0;
                w = rnd.next(0, W);
            }
            else if (type == "zeroWeight") {
                // All weights are 0, random values
                v = rnd.next(0, 10000);
                w = 0;
            }
            else if (type == "maxVal") {
                // All values are 10000, random weight
                v = 10000;
                w = rnd.next(0, W);
            }
            else {
                // Default fallback: random
                v = rnd.next(0, 10000);
                w = rnd.next(0, W);
            }
            cout << v << "," << w << "\n";
        }
    }

    // After printing T datasets, print 0 to end input.
    cout << "0\n";

    return 0;
}

