#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
  This generator produces a single dataset for the "crop circles" problem,
  followed by a terminating "0". The dataset consists of n circles, each
  given by (x, y, r). Real values are allowed for x, y, and r.

  Parameters:
    -n <int>          (number of circles, 1 <= n <= 100)
    -type <string>    (type of dataset to generate, default = "random")

  The supported types are:
    1) random      - fully random circles within constraints.
    2) nested      - all circles are nested inside one large circle.
    3) tangent     - circles arranged in a chain, each tangent to the next.
    4) overlap     - all circles guaranteed to overlap (pairwise).
    5) coincide    - all circles have exactly the same center and radius.
    6) corner      - circles placed at extreme coordinates/radii to test boundaries.
*/

static const double EPS = 1e-9;

int main(int argc, char* argv[]) {
    // Register generator.
    registerGen(argc, argv, 1);

    // Parse parameters.
    int n = opt<int>("n");
    string type = opt<string>("type", "random");

    // Make sure n is within constraints.
    // (Although the problem states n <= 100, we won't strictly refuse
    // bigger here. But in a real setting you might clamp or exit.)
    if (n <= 0) {
        // No data to emit, so just end with 0.
        cout << 0 << "\n";
        return 0;
    }

    // Print n to start the dataset
    cout << n << "\n";

    if (type == "random") {
        /*
          Generate n random circles:
            x in [-1000, 1000], y in [-1000, 1000], r in (0, 100].
        */
        for (int i = 0; i < n; i++) {
            double x = rnd.next(-1000.0, 1000.0);
            double y = rnd.next(-1000.0, 1000.0);
            // ensure radius > 0
            double r = rnd.next(0.001, 100.0);
            cout << fixed << setprecision(6) << x << " " << y << " " << r << "\n";
        }
    }

    else if (type == "nested") {
        /*
          1. Create a large "outer" circle c0.
          2. Place the other (n-1) circles entirely inside c0, so that they are nested.
             - pick the big circle center in [-1000,1000], radius in [50,100].
             - for each smaller circle:
               * pick a random radius r_i in (0, c0_radius).
               * pick a random direction & distance so that it stays inside c0.
        */
        double X0 = rnd.next(-1000.0, 1000.0);
        double Y0 = rnd.next(-1000.0, 1000.0);
        double R0 = rnd.next(50.0, 100.0); // outer circle radius
        // First circle: the big one
        cout << fixed << setprecision(6) << X0 << " " << Y0 << " " << R0 << "\n";

        for (int i = 1; i < n; i++) {
            // pick radius < R0
            double r_i = rnd.next(0.001, R0 - 0.001);
            // pick a random distance from center in [0, R0 - r_i]
            double maxDist = R0 - r_i;
            double dist = rnd.next(0.0, maxDist);
            // pick random angle
            double angle = rnd.next(0.0, 2.0 * M_PI);
            double x = X0 + dist * cos(angle);
            double y = Y0 + dist * sin(angle);
            cout << fixed << setprecision(6) << x << " " << y << " " << r_i << "\n";
        }
    }

    else if (type == "tangent") {
        /*
          Arrange n circles along the x-axis so that each circle i (except i=0)
          is tangent to the previous one. We pick radii in [1,10] to keep them
          from exploding in coordinate size. The center of circle i is offset
          from the center of circle i-1 by (r_{i-1} + r_i) along the x-axis.
        */
        double sx = rnd.next(-500.0, 500.0); // start x
        double sy = rnd.next(-500.0, 500.0);

        // Create and store (r_i) first
        vector<double> radii(n);
        for (int i = 0; i < n; i++) {
            radii[i] = rnd.next(1.0, 10.0);
        }

        // Print circles in a chain
        cout << fixed << setprecision(6) << sx << " " << sy << " " << radii[0] << "\n";
        double lastRight = sx + radii[0];
        for (int i = 1; i < n; i++) {
            double leftEdge = lastRight + radii[i]; // tangent point
            // center for i
            double centerX = leftEdge;
            cout << centerX << " " << sy << " " << radii[i] << "\n";
            lastRight = centerX + radii[i];
        }
    }

    else if (type == "overlap") {
        /*
          Guarantee pairwise overlap among all circles.
          We can do this by:
            - choose a random center/ radius for circle0.
            - for each subsequent circle,
              pick center close enough so that it definitely overlaps circle0.
              ( e.g. distance < (r0 + r_i) ), also random radius in [10..30], etc.
        */
        // Circle0
        double x0 = rnd.next(-500.0, 500.0);
        double y0 = rnd.next(-500.0, 500.0);
        double r0 = rnd.next(10.0, 30.0);

        cout << fixed << setprecision(6) << x0 << " " << y0 << " " << r0 << "\n";

        for (int i = 1; i < n; i++) {
            double r_i = rnd.next(10.0, 30.0);
            // ensure overlap: distance between centers < r0 + r_i
            double maxDist = r0 + r_i - 0.001; // subtract a bit so definitely within
            // pick distance from 0..maxDist
            double dist = rnd.next(0.0, maxDist);
            double angle = rnd.next(0.0, 2.0 * M_PI);
            double x = x0 + dist * cos(angle);
            double y = y0 + dist * sin(angle);
            cout << x << " " << y << " " << r_i << "\n";
        }
    }

    else if (type == "coincide") {
        /*
          All n circles have exactly the same center and same radius.
        */
        double cx = rnd.next(-1000.0, 1000.0);
        double cy = rnd.next(-1000.0, 1000.0);
        double cr = rnd.next(1.0, 100.0);
        for (int i = 0; i < n; i++) {
            cout << fixed << setprecision(6) << cx << " " << cy << " " << cr << "\n";
        }
    }

    else if (type == "corner") {
        /*
          Place circles at extreme corners or with extreme radii.
          We'll distribute them among corners and random extremes.
        */
        // We define some corner spots: (-1000, -1000), (1000, -1000),
        // (1000, 1000), (-1000, 1000)
        // We'll pick among these, and set radius to either 0.1 or 100.0
        vector<pair<double, double>> corners = {
            {-1000.0, -1000.0},
            {1000.0, -1000.0},
            {1000.0, 1000.0},
            {-1000.0, 1000.0}
        };
        for (int i = 0; i < n; i++) {
            auto c = corners[rnd.next(0, (int)corners.size() - 1)];
            double rr = (i % 2 == 0) ? 100.0 : 0.1; 
            // with a tiny random tweak
            double x = c.first  + rnd.next(-0.5, 0.5);
            double y = c.second + rnd.next(-0.5, 0.5);
            cout << fixed << setprecision(6) << x << " " << y << " " << rr << "\n";
        }
    }

    else {
        // Default back to random if unknown type
        for (int i = 0; i < n; i++) {
            double x = rnd.next(-1000.0, 1000.0);
            double y = rnd.next(-1000.0, 1000.0);
            double r = rnd.next(0.001, 100.0);
            cout << fixed << setprecision(6) << x << " " << y << " " << r << "\n";
        }
    }

    // Finally, print 0 to denote the end of input
    cout << 0 << "\n";

    return 0;
}

