"""Solution for the problem using matrix exponentiation modulo 10**6+3."""

MOD = 10 ** 6 + 3


def prod(a, b):
    """Multiply two matrices modulo MOD."""
    return [
        [
            sum(a[i][k] * b[k][j] for k in range(len(b))) % MOD
            for j in range(len(b[0]))
        ]
        for i in range(len(a))
    ]


def main():
    """Main function."""
    c, w, h = map(int, input().split())

    mat = [[0] * (w + 1) for _ in range(w + 1)]
    for i in range(w):
        mat[i][i + 1] = 1

    for cnt in range(0, w + 1):
        mat[-1][-1 - cnt] = h ** cnt

    ans = [[0] for _ in range(w + 1)]
    ans[-1][0] = 1
    ans[-2][0] = 1

    power = c
    while power > 0:
        if power % 2 == 1:
            ans = prod(mat, ans)
        power = power // 2
        if power > 0:
            mat = prod(mat, mat)

    print(ans[-1][0])


if __name__ == "__main__":
    main()

