    set<pair<int, int>> matches_set;

    string num_pattern = "(0|[1-9][0-9]?|100)";
    string match_line_pattern = team_name_pattern + "-" + team_name_pattern + " " + num_pattern + ":" + num_pattern;
    for (int i = 0; i < m; ++i) {
        string line = inf.readLine(match_line_pattern, "match_line");

        // Now parse the line to extract parts
        size_t dash_pos = line.find('-');
        ensuref(dash_pos != string::npos, "Invalid match line format; missing '-'");

        string name1 = line.substr(0, dash_pos);
        size_t space_pos = line.find(' ', dash_pos + 1);
        ensuref(space_pos != string::npos, "Invalid match line format; missing space after team names");

        string name2 = line.substr(dash_pos + 1, space_pos - dash_pos - 1);

        string scores_str = line.substr(space_pos + 1);
        size_t colon_pos = scores_str.find(':');
        ensuref(colon_pos != string::npos, "Invalid match line format; missing ':' in scores");

        string num1_str = scores_str.substr(0, colon_pos);
        string num2_str = scores_str.substr(colon_pos + 1);

        ensuref(team_names_set.count(name1) == 1, "Team name1 '%s' not found in the team list", name1.c_str());
        ensuref(team_names_set.count(name2) == 1, "Team name2 '%s' not found in the team list", name2.c_str());
        ensuref(name1 != name2, "Team cannot play against itself: %s vs %s", name1.c_str(), name2.c_str());

        int idx1 = team_name_to_index[name1];
        int idx2 = team_name_to_index[name2];

        ensuref(idx1 != idx2, "Team cannot play against itself");

        int a = min(idx1, idx2);
