    if(type == "line") {
        // Generate points along line y=0
        for(int i = 0; i < n; ++i) {
            points.push_back({i, 0});
        }
    } else if(type == "rectangle") {
        // Generate a rectangle of points
        int x_max = floor(sqrt(n)) - 1;
        int y_max = floor(sqrt(n)) - 1;
        while ((x_max + 1) * (y_max + 1) < n && x_max < 100000 && y_max < 100000) {
            if (x_max <= y_max) ++x_max;
            else ++y_max;
        }
        for(int x = 0; x <= x_max; ++x) {
            for(int y = 0; y <= y_max; ++y) {
                points.push_back({x, y});
                if (points.size() == n) break;
            }
            if (points.size() == n) break;
        }
    } else if(type == "random") {
        // Generate random points with closure property
        int x_max = min(100000, n);
        int y_max = min(100000, n);
        vector<int> xs, ys;
        for (int i = 0; i < n; ++i) {
            xs.push_back(rnd.next(0, x_max));
            ys.push_back(rnd.next(0, y_max));
        }
        sort(xs.begin(), xs.end());
        sort(ys.begin(), ys.end());
        set<pair<int,int>> point_set;
        for (int i = 0; i < n; ++i) {
            int x = xs[i];
            int y = ys[i];
            for (int xi = 0; xi <= x; ++xi) {
                for (int yi = 0; yi <= y; ++yi) {
                    point_set.insert({xi, yi});
                    if (point_set.size() == n) break;
                }
                if (point_set.size() == n) break;
            }
            if (point_set.size() == n) break;
        }
        points.assign(point_set.begin(), point_set.end());
    }

    // Ensure we have exactly n points
    while (points.size() > n) points.pop_back();

    // Output n
