            int m = rnd.next(1,12);

            int Gy = 1988 + Hy;
            int max_day = max_days_in_month(Gy, m);
            int d = rnd.next(1, max_day);
            if (Hy ==1 && m ==1 && d <8) continue; // date before Heisei era starts

            dates.emplace_back(Hy, m, d);
        }
    } else if (type == "before_transition") {
        while ((int)dates.size() < n) {
            int Hy = rnd.next(1,31); // Heisei 1 to 31
            int m = rnd.next(1,12);
            int Gy = 1988 + Hy;
            int max_day = max_days_in_month(Gy, m);
            int d = rnd.next(1, max_day);
            if (Hy ==31 && m>=5) continue; // Exclude date after Apr 30,2019
            if (Hy ==31 && m==4 && d>30) continue; // Exclude date after Apr 30,2019
            if (Hy ==1 && m ==1 && d <8) continue;
            dates.emplace_back(Hy, m, d);
        }
    } else if (type == "after_transition") {
        while ((int)dates.size() < n) {
            int Hy = rnd.next(31,100); // Starting from Heisei 31
            int m = rnd.next(1,12);
            int Gy = 1988 + Hy;
            int max_day = max_days_in_month(Gy, m);
            int d = rnd.next(1, max_day);
            if (Hy ==31 && m<=4) continue; // Before or on April, Heisei 31
            dates.emplace_back(Hy, m, d);
        }
    } else if (type == "transition") {
        // Dates around transition date
        int count = 0;
        int Hy = 31;

        for (int i=-2; i<=2; ++i) {
            int m = 4;
            int d = 30 + i;
            int curr_m = m;
            int curr_d = d;
            if (d < 1) {
                curr_m = m -1;
                if (curr_m <1) continue;
                curr_d = max_days_in_month(1988+Hy, curr_m) + d;
            } else if (d > max_days_in_month(1988+Hy, m)) {
                curr_m = m + 1;
                curr_d = d - max_days_in_month(1988+Hy, m);
                if (curr_m >12) continue;
            }
