int N, Y;

bool solutionExists() {
    // Try to find x, y, z such that:
    // x + y + z = N
    // 10000x + 5000y + 1000z = Y
    // x, y, z >= 0 and integers
    for (int x = 0; x <= N; x++) {
        int remaining_bills = N - x;
        int remaining_amount = Y - 10000 * x;
        if (remaining_amount < 0) continue;
        for (int y = 0; y <= remaining_bills; y++) {
            int z = remaining_bills - y;
            int total = 10000 * x + 5000 * y + 1000 * z;
            if (total == Y) {
                return true;
            }
        }
    }
    return false;
}

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);
    N = inf.readInt(1, 2000, "N");
    Y = inf.readInt(1000, 20000000, "Y");

    int x = ouf.readInt(-1, N, "x");
    int y = ouf.readInt(-1, N, "y");
