int sx2 = 3, sy2 = 0, ex2 = 0, ey2;
int dx[4] = {1, -1, 0, 0};
int dy[4] = {0, 0, 1, -1};

// Function to check if a cell is inside the grid
bool inside(int x, int y) {
    return x >= 0 && x < 4 && y >= 0 && y < n;
}

// Function to compute the number of shortest paths using BFS
int bfs(vector<string>& grid, int sx, int sy, int ex, int ey) {
    vector<vector<int>> dist(4, vector<int>(n, INT_MAX));
    vector<vector<int>> cnt(4, vector<int>(n, 0));
    queue<pair<int, int>> q;
    dist[sx][sy] = 0;
    cnt[sx][sy] = 1;
    q.push({sx, sy});
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];
            if (inside(nx, ny) && grid[nx][ny] == '.') {
                if (dist[nx][ny] > dist[x][y] + 1) {
                    dist[nx][ny] = dist[x][y] + 1;
                    cnt[nx][ny] = cnt[x][y];
                    q.push({nx, ny});
                } else if (dist[nx][ny] == dist[x][y] + 1) {
                    cnt[nx][ny] += cnt[x][y];
                }
            }
        }
    }
    if (dist[ex][ey] == INT_MAX)
        return 0;
    else
        return cnt[ex][ey];
}

