        int num_chains = opt<int>("chains", max(1, n / 100 + 1));
        int curr = 0;
        for (int k = 0; k < num_chains; ++k) {
            int remaining_chains = num_chains - k;
            int remaining_nodes = n - curr;
            int chain_length = (remaining_nodes + remaining_chains - 1) / remaining_chains;
            if(chain_length == 0) chain_length = 1;

            if(curr >= n) break;

            p[curr] = -1; // root of the chain
            for(int i = curr + 1; i < curr + chain_length; ++i) {
                if(i < n)
                    p[i] = i - 1; // Employee i+1 has manager i
            }
            curr += chain_length;
