            } else if(color[v]==1){
                // Found back edge, cycle detected
                has_cycle = true;
                return;
            }
        }
        color[u]=2; // visited
    };
    for(int i = 1; i <= n; ++i){
        if(color[i]==0){
            dfs(i);
            if(has_cycle) break;
        }
    }
    ensuref(!has_cycle, "The manager graph contains a cycle");

    inf.readEof();
    return 0;
}

