using namespace std;

static const long long COORD_LIMIT = 100000000LL;

// Returns 2 * (area of the triangle p0->p1->p2).
// > 0 if counter-clockwise, < 0 if clockwise, = 0 if collinear.
long long cross(
    long long x0, long long y0,
    long long x1, long long y1,
    long long x2, long long y2)
{
    return (x1 - x0) * (y2 - y0) - (y1 - y0) * (x2 - x0);
}

// Build the convex hull using the standard Andrew's monotone chain algorithm
// and return the indices of the hull (in terms of the original order in 'pts').
vector<int> buildHull(const vector<pair<long long, long long>>& pts)
{
    int n = (int)pts.size();
    // Pair up each point with its index
    vector<pair<pair<long long, long long>, int>> arr(n);
    for (int i = 0; i < n; i++)
        arr[i] = {{pts[i].first, pts[i].second}, i};

    // Sort by x, then by y
    sort(arr.begin(), arr.end(), [](auto &a, auto &b) {
        if (a.first.first != b.first.first)
            return a.first.first < b.first.first;
        return a.first.second < b.first.second;
    });

    // Build lower hull
    vector<int> hull;
    for (int i = 0; i < n; i++) {
        while (hull.size() >= 2) {
            auto &p1 = arr[hull[hull.size() - 2]].first;
            auto &p2 = arr[hull[hull.size() - 1]].first;
            auto &p3 = arr[i].first;
            if (cross(p1.first, p1.second, p2.first, p2.second, p3.first, p3.second) <= 0)
                hull.pop_back();
            else
                break;
        }
        hull.push_back(i);
    }
    // Build upper hull
    int lowerSize = (int)hull.size();
    for (int i = n - 2, t = lowerSize + 1; i >= 0; i--) {
        while ((int)hull.size() >= t) {
            auto &p1 = arr[hull[hull.size() - 2]].first;
            auto &p2 = arr[hull[hull.size() - 1]].first;
            auto &p3 = arr[i].first;
            if (cross(p1.first, p1.second, p2.first, p2.second, p3.first, p3.second) <= 0)
                hull.pop_back();
            else
                break;
        }
        hull.push_back(i);
    }
    hull.pop_back(); // Remove the duplicated starting point

    // Convert from sorted-array indices back to original input indices
    vector<int> result;
    for (int idx : hull) {
        result.push_back(arr[idx].second);
    }
    return result;
}

// Parse a string as a 64-bit integer within [minVal, maxVal] or quit with _wa if invalid.
long long parseLongLong(InStream &stream, const string &s, long long minVal, long long maxVal)
{
    // Quick check for valid integer characters
    // (We allow leading '+' or '-' and digits.)
    for (int i = 0; i < (int)s.size(); i++) {
        char c = s[i];
        if (!( (c >= '0' && c <= '9') || (c == '-' && i == 0) || (c == '+' && i == 0) )) {
            stream.quitf(_wa, "Expected an integer, got '%s'", s.c_str());
        }
    }
    long long val;
    try {
        val = stoll(s);
    } catch (...) {
        stream.quitf(_wa, "Expected an integer, got '%s'", s.c_str());
    }
    if (val < minVal || val > maxVal) {
        stream.quitf(_wa, "Integer '%s' out of range [%lld, %lld]",
                     s.c_str(), minVal, maxVal);
    }
    return val;
}

// Read and validate a solution from 'stream'. If it is "-1", hasSolution=false.
// Otherwise, read n pairs and check no three collinear & hull size == m.
// Return the points if a solution is given, or an empty vector if no solution.
vector<pair<long long, long long>> readSolution(InStream &stream, int n, int m, bool &hasSolution)
{
    string firstToken = stream.readToken();
    if (firstToken == "-1") {
        // The stream claims no solution
        hasSolution = false;
        return {};
    }

    // Otherwise, firstToken should be x-coordinate of the first point
    hasSolution = true;
    long long firstX = parseLongLong(stream, firstToken, -COORD_LIMIT, COORD_LIMIT);
    long long firstY = stream.readLong(-COORD_LIMIT, COORD_LIMIT, "y");

    vector<pair<long long, long long>> pts;
    pts.push_back({firstX, firstY});

    // read the rest n-1 points
    for (int i = 1; i < n; i++) {
        long long x = stream.readLong(-COORD_LIMIT, COORD_LIMIT, "x");
        long long y = stream.readLong(-COORD_LIMIT, COORD_LIMIT, "y");
        pts.push_back({x, y});
    }

    // Check that no three points are collinear
    // O(n^3) is fine for n <= 200 (given constraints: n <= 2m, m <= 100 => n <= 200)
    for (int i = 0; i < n; i++) {
        for (int j = i + 1; j < n; j++) {
            for (int k = j + 1; k < n; k++) {
                long long c = cross(
                    pts[i].first, pts[i].second,
                    pts[j].first, pts[j].second,
                    pts[k].first, pts[k].second
                );
                if (c == 0) {
                    stream.quitf(_wa,
                        "Three collinear points found: indices %d, %d, %d",
                        i+1, j+1, k+1);
                }
            }
        }
    }

    // Build convex hull and check its size
    vector<int> hullIdx = buildHull(pts);
    int hullSize = (int)hullIdx.size();
    if (hullSize != m) {
        stream.quitf(_wa, "Convex hull size %d != m = %d", hullSize, m);
    }

    return pts;
}

int main(int argc, char* argv[])
{
    registerTestlibCmd(argc, argv);

    // Read n, m from input
    int n = inf.readInt(3, 200, "n");
    int m = inf.readInt(3, 100, "m");
    // (Given constraints: m <= n <= 2m, etc.)

    bool juryHasSolution = false, partHasSolution = false;
    vector<pair<long long, long long>> juryPoints, partPoints;

    // 1) Read the jury's answer
    try {
        juryPoints = readSolution(ans, n, m, juryHasSolution);
    } catch (...) {
        quitf(_fail, "Unexpected error while reading jury's solution");
    }

    // 2) Read the participant's answer
    try {
        partPoints = readSolution(ouf, n, m, partHasSolution);
    } catch (...) {
        // If there's an error, testlib will already have set WA for participant
        return 0;
    }

    // Compare
    if (!juryHasSolution && !partHasSolution) {
        // Both say "-1"
        quitf(_ok, "Both claim no solution");
    }
    else if (!juryHasSolution && partHasSolution) {
        // Jury: no solution; Participant: found a solution => jury is wrong => fail
        quitf(_fail, "Jury claims no solution, but participant found one");
    }
    else if (juryHasSolution && !partHasSolution) {
        // Jury: has a solution; Participant: says -1 => WA
        quitf(_wa, "Participant claims no solution while jury provided one");
    }
    else {
        // Both have solutions => we have already validated correctness => OK
        quitf(_ok, "Both solutions are valid");
    }
}

