#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
  This generator produces multiple datasets for the "Cat Mansion" problem,
  all in a single output. The first printed line is the number of datasets T.
  Then, for each dataset, it prints:

    1) xEntry yEntry
    2) xExit yExit
    3) StartTime in HH:MM:SS
    4) EndTime in HH:MM:SS
    5) m (number of cats)
    6) For each cat i in [1..m]:
       - ki (number of points in the cat's patrol route)
       - x0 y0 x1 y1 ... x_{ki-1} y_{ki-1}

  Constraints enforced by the generator:
    - 1 <= m <= 14
    - 2 <= ki <= pointMax
    - |xi|, |yi| <= coordMax
    - startTime < endTime, both on the same day (seconds < 86400)
    - Enough time is given so that Natsume (speed 80 m/min) can always
      travel from entry to exit at least once (so there's "always a way
      to escape").
    - Consecutive cat-route points are never identical.

  Command-line arguments (via testlib's opt):
    - t: number of datasets to generate in one run (default 1)
    - catMax: maximum number of cats in one dataset (default 5)
    - pointMax: maximum patrol-route length for each cat (default 5)
    - coordMax: maximum absolute value for coordinates (default 10)
    - type: scenario type ("random", "special", etc.) to allow various
      ways of creating data. (default "random")

  NOTE: We do NOT set a random seed explicitly. 
        We do NOT accept a random seed in the command line.
        The testlab manager will supply seeds if desired.

  Usage example:
    ./gen -t 3 -catMax 5 -pointMax 10 -coordMax 100 -type random
*/

static const double NATSUME_SPEED = 80.0 / 60.0; // meters per second
                                                  // (80 m/min = 80/60 m/sec)

struct TimeHMST {
    int h, m, s;
};

static inline int toSeconds(const TimeHMST &T) {
    return T.h * 3600 + T.m * 60 + T.s;
}

static inline TimeHMST fromSeconds(int sec) {
    TimeHMST t;
    t.h = sec / 3600; sec %= 3600;
    t.m = sec / 60;   sec %= 60;
    t.s = sec;
    return t;
}

// Print time in HH:MM:SS format
static void printTime(const TimeHMST &tt) {
    // Ensure two-digit hours, minutes, seconds
    printf("%02d:%02d:%02d\n", tt.h, tt.m, tt.s);
}

// Euclidean distance
static double dist(double x1, double y1, double x2, double y2) {
    double dx = x2 - x1;
    double dy = y2 - y1;
    return sqrt(dx * dx + dy * dy);
}

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // We parse command-line options
    int T         = opt<int>("t", 1);        // number of datasets
    int catMax    = opt<int>("catMax", 5);   // maximum number of cats
    int pointMax  = opt<int>("pointMax", 5); // maximum number of points per route
    int coordMax  = opt<int>("coordMax", 10);// maximum absolute coordinate
    string mytype = opt<string>("type", "random");

    // Print the number of datasets first
    printf("%d\n", T);

    for(int dataset_i = 0; dataset_i < T; dataset_i++) {
        // 1) Generate random (or special) entry and exit points
        // We'll do it in a loop to ensure we have enough time to travel between them
        // at least once within the day.
        int xEntry, yEntry, xExit, yExit;
        int startSec, endSec;

        // We'll allow up to 10 attempts to find a valid (entry, exit, startTime, endTime).
        // It's enough for random usage. If all fail, we keep the last one anyway.
        bool valid = false;
        for (int attempt = 0; attempt < 10 && !valid; attempt++) {
            // random coordinates
            xEntry = rnd.next(-coordMax, coordMax);
            yEntry = rnd.next(-coordMax, coordMax);
            xExit  = rnd.next(-coordMax, coordMax);
            yExit  = rnd.next(-coordMax, coordMax);

            // random start time in [0..72000] => up to 20 hours
            startSec = rnd.next(0, 72000); 

            // We'll pick a duration in [600..10800], i.e. from 10 min to 3 hours
            int duration = rnd.next(600, 10800);
            endSec = startSec + duration;

            // If endSec >= 86400, skip and try again
            if (endSec >= 86400) {
                continue; 
            }

            // Check if we can travel from (xEntry,yEntry) to (xExit,yExit) at least once
            // distance in meters
            double d = dist(xEntry, yEntry, xExit, yExit);
            // time needed at Natsume speed
            double needed = d / NATSUME_SPEED;
            // If the difference endSec - startSec is >= needed, we are good
            if ( (endSec - startSec) >= needed - 1e-9 ) {
                valid = true;
            }
