int parseTime(const string& s) {
    int h, m, sec;
    ensuref(sscanf(s.c_str(), "%d:%d:%d", &h, &m, &sec) == 3, "Invalid time format");
    ensuref(0 <= h && h <= 23, "Hour out of range");
    ensuref(0 <= m && m <= 59, "Minute out of range");
    ensuref(0 <= sec && sec <= 59, "Second out of range");
    return h * 3600 + m * 60 + sec;
}

int parseInt(const string& s, int min_value, int max_value, const char* name) {
    // Check if s is a valid integer
    bool negative = false;
    size_t idx = 0;
    if (s[0] == '-') {
        negative = true;
        idx = 1;
    }
    ensuref(idx < s.size(), "Invalid integer for %s", name);
    ensuref(s.substr(idx).find_first_not_of("0123456789") == string::npos, "Invalid integer for %s", name);

    long long value = atoll(s.c_str());
    ensuref(value >= min_value && value <= max_value, "%s out of range: %lld", name, value);
    return (int)value;
}

