    if (type == "random") {
        // Random distribution of programs among channels
        vector<int> per_channel_counts(c, 0);
        // Distribute n programs among c channels randomly
        for (int i = 0; i < n; ++i) {
            int ch = rnd.next(0, c - 1);
            per_channel_counts[ch]++;
        }
        // For each channel, generate non-overlapping intervals
        for (int ch = 0; ch < c; ++ch) {
            int cnt = per_channel_counts[ch];
            vector<int> s(cnt), t(cnt);
            int last_t = 1;
            for (int i = 0; i < cnt; ++i) {
                int max_gap = 10;
                int max_duration = 10;
                int s_i = last_t + rnd.next(0, max_gap);
                if (s_i >= maxT) break;
                int max_t_i = min(s_i + max_duration, maxT);
                if (s_i + 1 > max_t_i) break;
                int t_i = rnd.next(s_i + 1, max_t_i);
                s[i] = s_i;
                t[i] = t_i;
                last_t = t_i;
            }
            for (int i = 0; i < s.size(); ++i) {
                programs.emplace_back(s[i], t[i], ch + 1);
            }
        }
    } else if (type == "max_recorder") {
        // Generate programs that start at the same time to maximize recorder usage
        int groups = n / c;
        int remainder = n % c;
        int time = 1;
        for (int g = 0; g < groups; ++g) {
            for (int ch = 1; ch <= c; ++ch) {
                int s_i = time;
                int t_i = s_i + rnd.next(1, 10);
                programs.emplace_back(s_i, t_i, ch);
            }
            time += rnd.next(1, 10); // Increase time for next group
        }
        // Add remaining programs
        for (int i = 0; i < remainder; ++i) {
            int ch = rnd.next(1, c);
            int s_i = time;
            int t_i = s_i + rnd.next(1, 10);
            programs.emplace_back(s_i, t_i, ch);
            time += rnd.next(1, 10);
        }
    } else if (type == "min_recorder") {
        // Generate programs with no overlap to minimize recorder usage
        int per_ch = n / c;
        int remainder = n % c;
        for (int ch = 1; ch <= c; ++ch) {
            int cnt = per_ch + (ch <= remainder);
            int last_t = 1;
            for (int i = 0; i < cnt; ++i) {
                int s_i = last_t + rnd.next(1, 10);
                if (s_i >= maxT) break;
                int t_i = s_i + rnd.next(1, 10);
                if (t_i > maxT) break;
                last_t = t_i;
                programs.emplace_back(s_i, t_i, ch);
            }
        }
    } else {
        // Default to random if unknown type
        // Same as "random" type
    }

    // Shuffle programs
    shuffle(programs.begin(), programs.end());

    // Output
    printf("%d %d\n", (int)programs.size(), c);
    for (auto& prog : programs) {
        int s_i, t_i, c_i;
        tie(s_i, t_i, c_i) = prog;
