from collections import deque

n, m = map(int, stdin.readline().split())
pc = {}
ph = {}
costs = []


class Cost:
    """Represents a cost entry for a party."""
    def __init__(self, identifier, cost_val, party) -> None:
        self.identifier = identifier
        self.cost = cost_val
        self.party = party
        self.removed = False


for i in range(n):
    p, c = map(int, stdin.readline().split())
    if p != 1:
        cost_entry = Cost(i, c, p)
        costs.append(cost_entry)
        pc.setdefault(p, []).append(cost_entry)
    ph[p] = ph.setdefault(p, 0) + 1

max_h = 0
for p, pa in pc.items():
    pa.sort(reverse=True, key=lambda x: x.cost)
    max_h = max(max_h, len(pa))

hp = [[] for _ in range(max_h + 2)]
for p, h in ph.items():
    if p != 1:
        hp[h].append(p)

ans = [0] * (max_h + 2)
costs.sort(key=lambda x: x.cost)
dq = deque(costs)
p_set = set()
height_p1 = ph[1] if 1 in ph else 0
top_sum = 0
top_count = 0

for i in range(max_h + 1, -1, -1):
    if len(costs) < i:
        ans[i] = float('inf')
        continue
    for p in hp[i]:
        p_set.add(p)
    for p in p_set:
        if pc[p]:
            min_cost = pc[p].pop()
            min_cost.removed = True
            top_sum += min_cost.cost
            top_count += 1
    ans[i] += top_sum
    if height_p1 + top_count < i:
        for j in range(i - height_p1 - top_count):
            while dq[0].removed:
                dq.popleft()
            ans[i] += dq[0].cost
            dq.rotate(-1)
        dq.rotate(i - height_p1 - top_count)

print(min(ans))

