    registerGen(argc, argv, 1);

    int t = opt<int>("t", 1); // number of test cases
    int n_max = opt<int>("n", 10); // maximum n per test case
    long long l_val = opt<long long>("l", 1);
    long long r_val = opt<long long>("r", 1000000000);
    string type = opt<string>("type", "random");

    // Ensure l ≤ r and 1 ≤ l, r ≤ 1e9
    if (l_val < 1 || l_val > 1000000000LL || r_val < 1 || r_val > 1000000000LL || l_val > r_val) {
        fprintf(stderr, "Invalid l and r values: l=%lld, r=%lld\n", l_val, r_val);
        exit(1);
    }

    // Ensure that total sum of n over t test cases ≤ 2e5
    long long total_n = 0;

    vector<int> n_list(t);

    for (int i = 0; i < t; i++) {
        int n_i = n_max;
        int remaining = 200000 - total_n;
        int remaining_tests = t - i;

        // Max n_i allowed is remaining / remaining_tests
        n_i = min(n_i, remaining / remaining_tests);

        if (n_i <= 0) n_i = 1;
        total_n += n_i;
        n_list[i] = n_i;
    }

    printf("%d\n", t);

    for (int test = 0; test < t; test++) {
        int n_i = n_list[test];

        printf("%d %lld %lld\n", n_i, l_val, r_val);

        vector<long long> a(n_i);

        if (type == "random") {
            for (int i = 0; i < n_i; i++) {
                a[i] = rnd.next(1LL, 1000000000LL);
            }
        } else if (type == "max") {
            for (int i = 0; i < n_i; i++) {
                a[i] = 1000000000LL;
            }
        } else if (type == "min") {
            for (int i = 0; i < n_i; i++) {
                a[i] = 1LL;
            }
        } else if (type == "equal") {
            long long val = rnd.next(1LL, 1000000000LL);
            for (int i = 0; i < n_i; i++) {
                a[i] = val;
            }
        } else if (type == "ascending") {
            // Increasing sequence
            long long current = 1LL;
            for (int i = 0; i < n_i; i++) {
                a[i] = current;
                current += rnd.next(0LL, 1000LL);
                if (a[i] > 1000000000LL) a[i] = 1000000000LL;
            }
        } else if (type == "descending") {
            // Decreasing sequence
            long long current = 1000000000LL;
            for (int i = 0; i < n_i; i++) {
                a[i] = current;
                current -= rnd.next(0LL, 1000LL);
                if (a[i] < 1LL) a[i] = 1LL;
            }
        } else if (type == "special_l") {
            // a_i + a_j >= l
            long long val1 = l_val / 2;
            long long val2 = l_val - val1;

            if (val1 < 1LL) val1 = 1LL;
            if (val2 < 1LL) val2 = 1LL;

            for (int i = 0; i < n_i; i++) {
                if (i % 2 == 0)
                    a[i] = val1;
                else
                    a[i] = val2;
            }
        } else if (type == "special_r") {
            // a_i + a_j ≤ r
            long long val1 = r_val / 2;
            long long val2 = r_val - val1;

            if (val1 > 1000000000LL) val1 = 1000000000LL;
            if (val2 > 1000000000LL) val2 = 1000000000LL;

            for (int i = 0; i < n_i; i++) {
                if (i % 2 == 0)
                    a[i] = val1;
                else
                    a[i] = val2;
            }
        } else {
            // Default to random
            for (int i = 0; i < n_i; i++) {
                a[i] = rnd.next(1LL, 1000000000LL);
            }
        }

        for (int i = 0; i < n_i; i++) {
            printf("%lld%c", a[i], i == n_i - 1 ? '\n' : ' ');
        }
    }

    return 0;
}

