    int t = opt<int>("t", 1); // default T = 1
    int e = opt<int>("e", 1000000000); // default E = 1e9
    string type = opt<string>("type", "random"); // default type = random

    vector<int> x(n);

    if (type == "random") {
        // Generate n unique random integers in range [1, E-1]
        set<int> positions;
        while (positions.size() < n) {
            int pos = rnd.next(1, e - 1);
            positions.insert(pos);
        }
        int idx = 0;
        for (int pos : positions) {
            x[idx++] = pos;
        }
        // x is sorted automatically
    } else if (type == "clustered_zero") {
        // Positions clustered near 1
        int max_cluster = min(e / 1000, e - n);
        for(int i = 0; i < n; ++i)
            x[i] = rnd.next(1, max_cluster) + i;
    } else if (type == "clustered_e") {
        // Positions clustered near E-1
        int min_cluster = max(e - e / 1000 - n, 1);
        for(int i = 0; i < n; ++i)
            x[i] = min_cluster + i;
        shuffle(x.begin(), x.end());
    } else if (type == "arithmetic") {
        // Positions in arithmetic progression
        int start = 1;
        int end = e - n;
        int diff = max(1, (end - start) / n);
        x[0] = start;
        for(int i = 1; i < n; ++i)
            x[i] = x[i-1] + diff;
    } else if (type == "geometric") {
        // Positions in geometric progression
        double start = 1;
        double end = e - 1;
        double ratio = pow(end / start, 1.0 / (n - 1));

        x[0] = (int)start;
        for(int i = 1; i < n; ++i) {
            x[i] = (int)(start * pow(ratio, i));
            if (x[i] <= x[i-1]) x[i] = x[i-1] + 1;
            if (x[i] >= e) x[i] = e - n + i;
        }
    } else if (type == "alternately_large_small") {
        // Alternate between small and large positions
        for(int i = 0; i < n; ++i) {
            if (i % 2 == 0)
                x[i] = rnd.next(1, e / 2 - n);
            else
                x[i] = rnd.next(e / 2 + n, e - 1);
        }
        sort(x.begin(), x.end());
        for (int i = 1; i < n; ++i)
            if (x[i] <= x[i - 1])
                x[i] = x[i - 1] + 1;
    } else {
        // Default to random
        set<int> positions;
        while (positions.size() < n) {
            int pos = rnd.next(1, e - 1);
            positions.insert(pos);
        }
        int idx = 0;
        for (int pos : positions) {
            x[idx++] = pos;
        }
    }

    // Output N E T
    printf("%d %d %d\n", n, e, t);

    // Output x_1 x_2 ... x_N
    for(int i = 0; i < n; ++i) {
        printf("%d%c", x[i], i == n - 1 ? '\n' : ' ');
