int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    int H = opt<int>("H");
    int W = opt<int>("W");
    string type = opt<string>("type", "random");

    vector<string> grid(H, string(W, '.'));

    if (type == "random") {
        // Random grid
        for(int i = 0; i < H; ++i)
            for(int j = 0; j < W; ++j)
                if (rnd.next(2)) grid[i][j] = '#';
    } else if (type == "good") {
        // Create a good grid with a path from (0,0) to (H-1,W-1)
        // Start with all black squares
        for(int i = 0; i < H; ++i)
            fill(grid[i].begin(), grid[i].end(), '#');
        // Build a path
        int r = 0, c = 0;
        grid[r][c] = '.';
        while (r < H -1 || c < W -1) {
            if (r == H -1)
                ++c;
            else if (c == W -1)
                ++r;
            else {
                if (rnd.next(2)) ++r; else ++c;
            }
            grid[r][c] = '.';
        }
        // Fill the rest randomly
        for(int i = 0; i < H; ++i)
            for(int j = 0; j < W; ++j)
                if (grid[i][j] != '.')
                    grid[i][j] = (rnd.next(2) ? '#' : '.');
    } else if (type == "blocked_path") {
        // Start with all white squares
        for(int i = 0; i < H; ++i)
            fill(grid[i].begin(), grid[i].end(), '.');
        // Block the path from (0,0) to (H-1,W-1)
        int num_blocks = rnd.next(1, H + W); // Random number of blocks
        for(int k = 0; k < num_blocks; ++k) {
            int r = rnd.next(0, H - 1);
            int c = rnd.next(0, W - 1);
            // Do not block start or end
            if ((r == 0 && c == 0) || (r == H -1 && c == W -1)) continue;
            grid[r][c] = '#';
        }
    } else if (type == "start_black") {
        // Random grid with start cell black
        for(int i = 0; i < H; ++i)
            for(int j = 0; j < W; ++j)
                if (rnd.next(2)) grid[i][j] = '#';
        grid[0][0] = '#'; // Start cell is black
    } else if (type == "end_black") {
        // Random grid with end cell black
        for(int i = 0; i < H; ++i)
            for(int j = 0; j < W; ++j)
                if (rnd.next(2)) grid[i][j] = '#';
        grid[H-1][W-1] = '#'; // End cell is black
    } else if (type == "full_black") {
        // Grid completely black
        for(int i = 0; i < H; ++i)
            fill(grid[i].begin(), grid[i].end(), '#');
    } else if (type == "full_white") {
        // Grid completely white
        // Already initialized as white
    } else if (type == "zigzag") {
        // Create a zigzag path
        for(int i = 0; i < H; ++i)
            fill(grid[i].begin(), grid[i].end(), '#');
        int r = 0, c = 0;
        grid[r][c] = '.';
        bool dir = true; // true for moving right, false for moving left
        while (r < H - 1) {
            if (dir) {
                while (c < W - 1) {
                    ++c;
                    grid[r][c] = '.';
                }
            } else {
                while (c > 0) {
                    --c;
                    grid[r][c] = '.';
                }
            }
            ++r;
            grid[r][c] = '.';
            dir = !dir;
        }
        // Randomly fill other squares
        for(int i = 0; i < H; ++i)
            for(int j = 0; j < W; ++j)
                if (grid[i][j] != '.')
                    grid[i][j] = (rnd.next(2) ? '#' : '.');
    } else {
        // Default to random grid
        for(int i = 0; i < H; ++i)
            for(int j = 0; j < W; ++j)
                if (rnd.next(2)) grid[i][j] = '#';
    }

    // Output H W
    printf("%d %d\n", H, W);
    // Output the grid
    for(int i = 0; i < H; ++i) {
        printf("%s\n", grid[i].c_str());
    }

    return 0;
}

