        n1 = n2 = n3 = 1;
        t1 = t2 = t3 = 1;
    } else if (type == "max") {
        // Maximal edge case
        k = 10000;
        n1 = n2 = n3 = 1000;
        t1 = t2 = t3 = 1000;
    } else if (type == "random") {
        // Random values within specified limits
        if (k == -1) k = rnd.next(1, k_max);
        if (n1 == -1) n1 = rnd.next(1, n_max);
        if (n2 == -1) n2 = rnd.next(1, n_max);
