        int t = rnd.next(t_min, t_max);
        n1 = n2 = n3 = n;
        t1 = t2 = t3 = t;
    } else if (type == "machine_limit") {
        // Number of machines is less than k
        k = k_max;
        n1 = rnd.next(1, min(k - 1, n_max));
