"""Module for calculating optimal bribe distribution."""

n, k, A = map(int, input().rstrip().split())
senators = []
mx_bribe = 0

for idx in range(n):
    lvl, loy = map(int, input().rstrip().split())
    senators.append((lvl, loy))
    mx_bribe += (100 - loy) // 10

bribe = [0] * n


def calc(votes):
    """Calculate probability for a given vote configuration."""
    bsum, cnt, p = 0, 0, 1.0
    for j, s in enumerate(senators):
        if votes & (1 << j):
            p *= (s[1] + bribe[j]) / 100
            cnt += 1
        else:
            p *= (100 - s[1] - bribe[j]) / 100
            bsum += s[0]

    if cnt > (n / 2):
        return p
    return p * A / (A + bsum)


def dfs(cur, rk):
    """Depth-first search for optimal bribe distribution."""
    if cur >= n:
        if rk > 0:
            return 0.0
        sm = 0.0
        for mask in range(1 << n):
            sm += calc(mask)

        return sm

    mx = 0.0
    for i in range(rk + 1):
        if i * 10 + senators[cur][1] > 100:
            break
        bribe[cur] = i * 10
        tmp = dfs(cur + 1, rk - i)
        mx = max(tmp, mx)
    return mx


