        } else if (type == "reverse") {
            reversePuzzle(puzzle);
        } else if (type == "random") {
            int moves = rnd.next(minMoves, maxMoves);
            applyRandomMoves(puzzle, moves);
        } else if (type == "hard") {
            int moves = rnd.next(21, 40); // Moves greater than 20 to make it likely unsolvable within 20 steps
            applyRandomMoves(puzzle, moves);
        }
