const double EPS = 1e-8;

bool is_point_on_line_segment(double x0, double y0,
                              double x1, double y1,
                              double x2, double y2){
    double cross = (x2 - x1)*(y0 - y1) - (y2 - y1)*(x0 - x1);
    if(fabs(cross) > EPS)
        return false;
    double dot = (x0 - x1)*(x2 - x1) + (y0 - y1)*(y2 - y1);
    if(dot < 0)
        return false;
    double sq_length = (x2 - x1)*(x2 - x1) + (y2 - y1)*(y2 - y1);
    if(dot > sq_length)
        return false;
    return true;
}

bool is_point_on_edge_or_vertex(double x, double y,
                                double x1, double y1,
                                double x2, double y2,
                                double x3, double y3) {
    // Check if point is on any of the triangle's edges
    if(is_point_on_line_segment(x, y, x1, y1, x2, y2))
        return true;
    if(is_point_on_line_segment(x, y, x2, y2, x3, y3))
        return true;
    if(is_point_on_line_segment(x, y, x3, y3, x1, y1))
        return true;
    // Check if point is at the triangle's vertices
    if((fabs(x - x1) < EPS && fabs(y - y1) < EPS) ||
       (fabs(x - x2) < EPS && fabs(y - y2) < EPS) ||
       (fabs(x - x3) < EPS && fabs(y - y3) < EPS))
        return true;
    return false;
}

bool is_point_in_triangle(double x, double y,
                          double x1, double y1,
                          double x2, double y2,
                          double x3, double y3) {
    // Barycentric coordinates
    double denominator = ((y2 - y3)*(x1 - x3) + (x3 - x2)*(y1 - y3));
    if(fabs(denominator) < EPS)
        return false; // Degenerate triangle

    double a = ((y2 - y3)*(x - x3) + (x3 - x2)*(y - y3)) / denominator;
    double b = ((y3 - y1)*(x - x3) + (x1 - x3)*(y - y3)) / denominator;
    double c = 1.0 - a - b;
    if(a > EPS && b > EPS && c > EPS)
        return true;
    else
        return false;
}

