using namespace std;

bool point_on_segment(int x1, int y1, int x2, int y2, int x, int y) {
    // Check if (x,y) is colinear with (x1,y1)-(x2,y2)
    int cross = (x - x1)*(y2 - y1) - (y - y1)*(x2 - x1);
    if (cross != 0) return false; // Not colinear

    // Now check if (x,y) lies between (x1,y1)-(x2,y2)
    int dot = (x - x1)*(x2 - x1) + (y - y1)*(y2 - y1);
    if (dot < 0) return false; // Not between
    int len_sq = (x2 - x1)*(x2 - x1) + (y2 - y1)*(y2 - y1);
    if (dot > len_sq) return false; // Not between

    return true;
}

