#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
  This problem admits multiple correct answers because there can be many ways
  to assign wins, losses, and draws to meet all players' expectations.

  The checker below does the following for each test case:
  1. Reads n and the expectation string s from the input (inf).
  2. Checks the participant's answer from (ouf), which must be either "YES" or "NO".
  3. If the participant prints "NO":
      - We verify whether a valid arrangement of outcomes is actually possible.
      - For this problem, a valid arrangement exists if and only if
        the number of type-2 players (who want at least one win) is either 0 or >= 3.
      - If such an arrangement is possible (0 or >= 3 type-2 players), but participant
        says "NO", we verdict Wrong Answer.
      - Otherwise, we accept "NO".
  4. If the participant prints "YES":
      - We read an n x n matrix describing the results:
         * 'X' on the diagonal (i == j).
         * One of {'+', '-', '='} elsewhere.
         * '+', '-' must be opposites across the diagonal, '=' must be symmetric.
      - We then check that each type-1 player (s_i == '1') has no losing symbol ('-')
        in their entire row.
      - We check that each type-2 player (s_i == '2') has at least one winning symbol ('+')
        in their row.
      - Finally, if the known criterion says there's no solution (number of type-2 players == 1 or 2),
        but participant still outputs a valid matrix, we must reject, since the official logic
        deems such cases impossible.
  5. If all test cases pass these checks, we verdict _ok, otherwise the first failing check
     issues _wa.

  Note: This checker enforces the *officially deduced* necessary-and-sufficient condition
  for feasibility: #type2 == 0 or #type2 >= 3 => solution possible; #type2 == 1 or #type2 == 2 => impossible.
*/

int main(int argc, char* argv[]) {
    registerTestlibCmd(argc, argv);

    int t = inf.readInt(1, 200, "t"); // number of test cases
    for(int _case = 1; _case <= t; _case++){
        int n = inf.readInt(2, 50, "n");
        string s = inf.readToken("[12]{"+ to_string(n) +"}", "s"); // read the expectation string
        // Count how many players want at least one win (type-2)
        int cntType2 = count(s.begin(), s.end(), '2');

        // Read the participant's verdict: either "YES" or "NO".
        // If they provide something else, we will fail (readToken would throw).
        string ansVerdict = ouf.readToken("YES|NO", "answerVerdict");

        // The official feasibility criterion:
        // feasible if cntType2 == 0 or cntType2 >= 3,
        // impossible if cntType2 == 1 or cntType2 == 2.
        bool isFeasible = (cntType2 == 0 || cntType2 >= 3);

        if(ansVerdict == "NO") {
            // If the participant's answer is NO, but we believe a solution is feasible => WA
            if(isFeasible) {
                ouf.quitf(_wa,
                    "Test case #%d: solution is possible (#type2=%d), but participant answered NO",
                    _case, cntType2
                );
            }
            // else (#type2 in {1, 2}), we accept "NO".
            continue;
        } else {
            // ansVerdict == "YES". Then the participant must provide an n x n matrix
            // describing match results.

            // If we believe it's impossible (#type2 in {1,2}), but the participant still
            // claims YES, we must read the matrix anyway (to avoid messing up file pointer),
            // then we'll mark WA afterwards if it somehow passes all local checks.
            vector<string> mat(n);
            for(int i = 0; i < n; i++){
                mat[i] = ouf.readToken(format("[X\\+\\-=]{%d}", n).c_str(),
                                       format("matrix row %d", i+1).c_str());
            }

            // Check the matrix:
            // 1) Diagonal must be 'X'
            // 2) For i != j, must be in {'+','-','='}, and must be consistent:
            //    mat[i][j] == '+' => mat[j][i] == '-'
            //    mat[i][j] == '-' => mat[j][i] == '+'
            //    mat[i][j] == '=' => mat[j][i] == '='
            for(int i = 0; i < n; i++){
                if(mat[i][i] != 'X'){
                    ouf.quitf(_wa,
                        "Test case #%d: matrix[%d][%d] != 'X'", _case, i+1, i+1);
                }
            }
            for(int i = 0; i < n; i++){
                for(int j = 0; j < n; j++){
                    if(i == j) continue;
                    if(string("+-=").find(mat[i][j]) == string::npos){
                        ouf.quitf(_wa,
                            "Test case #%d: matrix[%d][%d] is not one of {+,-,=}",
                            _case, i+1, j+1
                        );
                    }
                    char c1 = mat[i][j], c2 = mat[j][i];
                    if(c1 == '+'){
                        if(c2 != '-'){
                            ouf.quitf(_wa,
                                "Test case #%d: matrix[%d][%d] = '+', but matrix[%d][%d] != '-'",
                                _case, i+1, j+1, j+1, i+1
                            );
                        }
                    } else if(c1 == '-'){
                        if(c2 != '+'){
                            ouf.quitf(_wa,
                                "Test case #%d: matrix[%d][%d] = '-', but matrix[%d][%d] != '+'",
                                _case, i+1, j+1, j+1, i+1
                            );
                        }
                    } else { // c1 == '='
                        if(c2 != '='){
                            ouf.quitf(_wa,
                                "Test case #%d: matrix[%d][%d] = '=', but matrix[%d][%d] != '='",
                                _case, i+1, j+1, j+1, i+1
                            );
                        }
                    }
                }
            }

            // Now check each player's constraints:
            // type-1 => no '-' in that row
            // type-2 => at least one '+' in that row
            for(int i = 0; i < n; i++){
                if(s[i] == '1') {
                    // must have zero losses => no '-' in row i
                    for(int j = 0; j < n; j++){
                        if(mat[i][j] == '-'){
                            ouf.quitf(_wa,
                                "Test case #%d: type-1 player %d has a loss in column %d",
                                _case, i+1, j+1
                            );
                        }
                    }
                } else {
                    // s[i] == '2': at least one '+' in row i
                    bool hasPlus = false;
                    for(int j = 0; j < n; j++){
                        if(mat[i][j] == '+'){
                            hasPlus = true;
                            break;
                        }
                    }
                    if(!hasPlus){
                        ouf.quitf(_wa,
                            "Test case #%d: type-2 player %d does not have any '+' in their row",
                            _case, i+1
                        );
                    }
                }
            }

            // If #type2 in {1,2} but participant claimed "YES" and passed
            // the local consistency checks, that would mean they found an arrangement
            // which the official logic considers impossible. We reject.
            if(!isFeasible) {
                ouf.quitf(_wa,
                    "Test case #%d: #type2 = %d => officially impossible, but participant provided a matrix",
                    _case, cntType2
                );
            }
        }
    }

    // If we reach here, all test cases have been verified successfully.
    quitf(_ok, "All test cases passed.");
}

