public class meramainmahan {

	public static int solve(int n,String s[]){
		String c[],com;
		int res=0,rem=1,count=1,num=0;
		boolean flag=false;
		for(int i=0;i<2*n;i++){
			c=s[i].split(" ");
			if(c[0].equals("add"))num=Integer.parseInt(c[1]);
			if(c[0].equals("remove")&&num!=rem){
				if(i+1<2*n){
					c=s[i+1].split(" ");
					if(c[0].equals("remove")){
						rem++;
						flag=true;
						continue;
					}
					else res++;
				}
				if(i+1==2*n)res++;
			}
			else if(c[0].equals("remove")&&num==rem){
				if(flag){
					res++;
					flag=false;
				}
				rem++;
			}
		}
		return res;
	}

	public static void main(String[] args) throws  IOException {
		BufferedReader br=new BufferedReader(new InputStreamReader(System.in));
		int n=Integer.parseInt(br.readLine());
		String ar[]=new String[2*n];
		for(int i=0;i<2*n;i++)
			ar[i]=br.readLine();
		System.out.println(solve(n,ar));
	}

}

