    vector<int> test_cases;

    if (type == "random") {
        for (int i = 0; i < n; ++i) {
            int num = rnd.next(minVal, maxVal);
            test_cases.push_back(num);
        }
    } else if (type == "max") {
        for (int i = 0; i < n; ++i) {
            test_cases.push_back(maxVal);
        }
    } else if (type == "min") {
        for (int i = 0; i < n; ++i) {
            test_cases.push_back(minVal);
        }
    } else if (type == "palindrome") {
        for (int i = 0; i < n; ++i) {
            int len = rnd.next(1, 5);
            string half = "";
            for (int j = 0; j < (len + 1) / 2; ++j) {
                int d = rnd.next(0, 9);
                half += char('0' + d);
            }
            string rev_half = half.substr(0, len / 2);
            reverse(rev_half.begin(), rev_half.end());
            string num_str = half + rev_half;
            int num = stoi(num_str);
            if (num >= minVal && num <= maxVal)
                test_cases.push_back(num);
            else
                --i; // Retry
        }
    } else if (type == "alternating") {
        for (int i = 0; i < n; ++i) {
            int len = rnd.next(1, 5);
            int d1 = rnd.next(0, 9);
            int d2 = rnd.next(0, 9);
            while (d2 == d1)
                d2 = rnd.next(0, 9);
            string num_str = "";
            for (int j = 0; j < len; ++j) {
                num_str += char('0' + (j % 2 == 0 ? d1 : d2));
            }
            int num = stoi(num_str);
            if (num >= minVal && num <= maxVal)
                test_cases.push_back(num);
            else
                --i; // Retry
        }
    } else if (type == "ascending") {
        int cur = minVal;
        for (int i = 0; i < n; ++i) {
            if (cur > maxVal) cur = minVal;
            test_cases.push_back(cur++);
        }
    } else if (type == "descending") {
        int cur = maxVal;
        for (int i = 0; i < n; ++i) {
            if (cur < minVal) cur = maxVal;
            test_cases.push_back(cur--);
        }
    }

