        long long pos = 0;
        long long max_gap = max(1LL, L / (2 * n + 1));
        long long max_interval = max(1LL, L / (2 * n + 1));
        while (pos < L && (int)intervals.size() < n) {
            long long gap = rnd.next(1LL, max_gap);
            pos += gap;
            if (pos >= L) break;
            long long interval_length = rnd.next(1LL, min(L - pos, max_interval));
            if (interval_length <= 0) break;
            long long li = pos;
            long long ri = li + interval_length;
            intervals.push_back({li, ri});
            pos = ri;
        }
    }
    else if (type == "full_light") {
        intervals.push_back({0, L});
    }
    else if (type == "no_light") {
        // intervals remain empty
    }
    else if (type == "small_segments") {
        // Segments shorter than p
        long long pos = 0;
        long long max_gap = max(1LL, L / (2 * n + 1));
        long long max_interval = min(p - 1, L / (2 * n + 1));
        if (max_interval < 1) max_interval = 1;
        while (pos < L && (int)intervals.size() < n) {
            long long gap = rnd.next(1LL, max_gap);
