            long long li = pos;
            long long ri = li + interval_length;
            intervals.push_back({li, ri});
            pos = ri;
        }
    }
    else if (type == "edge_case1") {
        // Create specific intervals to test 't' pause condition
        if (L >= 2 * p + t) {
            intervals.push_back({0, p});
            intervals.push_back({p + t - 1, p + t - 1 + p});
        } else if (L >= p) {
            intervals.push_back({0, p});
        }
    }
    else {
        // Default: random
