        int center = H / 2;
        for (int j = 1; j < W - 1; ++j)
            grid[center][j] = '#';
    } else if (type == "checkerboard") {
        // Checkerboard pattern
        for (int i = 1; i < H - 1; ++i)
            for (int j = 1; j < W - 1; ++j)
                if ((i + j) % 2 == 0)
                    grid[i][j] = '#';
    } else if (type == "large_connected") {
        // A large connected area of '#' cells
        int minH = H / 4, maxH = 3 * H / 4;
        int minW = W / 4, maxW = 3 * W / 4;
        for (int i = minH; i <= maxH; ++i)
