// Function to check if the grid of '#' cells is 4-connected
bool isConnected(vector<string>& grid) {
    int H = grid.size();
    int W = grid[0].size();
    vector<vector<bool>> visited(H, vector<bool>(W, false));
    queue<pair<int, int>> q;

    // Find the first '#' cell
    bool found = false;
    for (int i = 0; i < H && !found; i++) {
        for (int j = 0; j < W && !found; j++) {
            if (grid[i][j] == '#') {
                q.push({i, j});
                visited[i][j] = true;
                found = true;
            }
        }
    }
    if (!found) {
        // If there are no '#' cells, it's trivially connected
        return true;
    }

    // BFS to check connectivity
    int dx[] = {-1, 0, 1, 0};
    int dy[] = {0, 1, 0, -1};
    while (!q.empty()) {
        int x = q.front().first;
        int y = q.front().second;
        q.pop();
        for (int dir = 0; dir < 4; dir++) {
            int nx = x + dx[dir];
            int ny = y + dy[dir];
            if (nx >= 0 && nx < H && ny >= 0 && ny < W) {
                if (!visited[nx][ny] && grid[nx][ny] == '#') {
                    visited[nx][ny] = true;
                    q.push({nx, ny});
                }
            }
        }
    }

    // Check if all '#' cells are visited
    for (int i = 0; i < H; i++) {
        for (int j = 0; j < W; j++) {
            if (grid[i][j] == '#' && !visited[i][j]) {
                return false;
            }
        }
    }

    return true;
}

