import java.util.Arrays;


public class Main {

    public static boolean[] distribute(long n) {
        final int bitAmount = 64;
        boolean[] bits = new boolean[bitAmount];
        for (int i = 0; i < bitAmount; i++) {
            bits[i] = ((n & ((long)1 << i)) != 0);
        }
        return bits;

    }

    public static long[] initializing() {
        long[] result = new long[64];
        result[0] = 1;
        for (int i = 1; i < 64; i++) {
            result[i] = result[i-1]*2;
        }
        return result;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        int n = Integer.parseInt(line);
        long[][] A = new long[n][2];
        for (int i = 0; i < n; i++) {
            line = br.readLine();
            String[] values = line.split(" ");
            A[i][0] = Long.parseLong(values[0]);
            A[i][1] = Long.parseLong(values[1]);
        }

        long[] pow2 = initializing(); 

        for (int i = 0; i < n; i++) {
            boolean[] first = distribute(A[i][0]);
            boolean[] second = distribute(A[i][1]);
            int counter = 0; long val = 0;
            int counterM = 0; boolean found = false;

            for (int j = first.length-1; j >= 0; j--) {
                if (second[j] || found) {
                    val += pow2[j];
//                  System.out.println("j: " + j + " val: " + val);
                }
                counter = (second[j]) ? counter+1 : counter;
                if (!found && second[j] && !first[j]) {
                    counterM = counter + j - 1;
                    val -= pow2[j];
                    found = true;
                }
            }
            if (counter > counterM) {
                val = A[i][1];
            }
            System.out.println(val);
        }
    }
}

