		BigInteger lhs = val(y2 - bY).pow(2).multiply(val(ny).pow(2));
		BigInteger rhs = val(r).pow(2).multiply(val(nx * nx + ny * ny));
		if (lhs.compareTo(rhs) <= 0) {
			writer.println(-1);
			return;
		}
		writer.println(xw);
