#include "testlib.h"
#include <bits/stdc++.h>
using namespace std;

/*
   This problem admits infinitely many valid solutions for some inputs
   (since any valid bounce point on the top wall that still sends the ball
   through the goal is acceptable).  Hence we need a custom checker.

   Checker logic:

   1) We read the official input (y1, y2, yw, xb, yb, r).

   2) We read the jury's answer (ans).  If it is "-1", we infer the jury
      believes there is NO valid bounce; otherwise it is a real number.

   3) We read the participant's answer (ouf).  If it is "-1", the participant
      claims no valid solution.  Otherwise, the participant claims there is
      a valid bounce point on the wall and provides its x-coordinate.

   4) If the jury's answer indicates "no solution" but the participant
      produces a numerical bounce point, we report Wrong Answer.
      If the jury's answer indicates "there is a solution" (ans != -1)
      but the participant says "-1", we also report Wrong Answer.

   5) If both the jury and participant say "-1", we accept immediately.

   6) If the participant gives a real number xw, we check whether that xw
      indeed corresponds to a *single* bounce on the wall y = yw, leading
      strictly to the goal region between (0, y1) and (0, y2), *without*
      worrying about collisions with the other walls.  (A fully rigorous
      checker would also verify that the ball does not hit other walls or
      corners, but we omit that for brevity.)

      The minimal reflection-law check for a bounce on a *horizontal* wall:

         Let (xb, yb) be the ball, r be the ball's radius, and the top wall
         is effectively at y = yw - r for the ball's center (because it
         "touches" at distance r).  Suppose participant claims the bounce
         occurs at (xw, yw - r).

         Then the travel segments are:
            1) (xb, yb) -> (xw, yw - r)   (incidence)
            2) (xw, yw - r) -> the goal on x=0 (reflection)

         If the wall is horizontal, reflection reverses the vertical velocity
         but keeps horizontal velocity the same.  So if the first segment is
            dx = xw - xb,
            dy = (yw - r) - yb,
         the second segment (reflection) has direction
            ( dx, -dy ).

         We want it to cross x=0 exactly once.  Solve for t > 0 so that
            x(t) = xw + dx * t = 0
         =>   t = -xw/dx.
         Then
            y(t) = (yw - r) + (-dy)*t.

         We check two things:
            - dx < 0 (so that we indeed travel back to x=0).
            - t > 0 (so the crossing is "forward" in time).
            - The crossing's y(t) must lie strictly between y1 and y2.
              (Because the problem states the goal is at x=0, y in (y1, y2).)

      If all those checks pass, we accept.  Otherwise we reject.

   7) We compare using an absolute tolerance 1e-8 only for reading participant's real number.
      (If the participant's xw parses correctly, we do not forcibly check it
       against the jury's real solution, because multiple solutions are possible.)

   NOTE: This simplified checker does NOT rigorously verify that the path
   avoids hitting other walls or corners, which the problem statement requires.
   In a real contest environment, one would implement those additional
   geometric collision checks.  However, this example demonstrates the
   main idea of building a custom checker for multiple correct answers.
*/

static const long double EPS = 1e-8;

/*
   Attempt to parse a string as a real number with standard C++ libraries,
   returning false if it fails.  On success, store the result in val.
*/
bool tryParseLD(const string &s, long double &val) {
    // strip leading/trailing spaces just in case
    // (testlib should have done that, but let's be safe)
    string tmp;
    {
        int start = 0, end = (int)s.size()-1;
        while (start <= end && isspace((unsigned char)s[start])) start++;
        while (end >= start && isspace((unsigned char)s[end])) end--;
        if (start > end) return false;
        tmp = s.substr(start, end - start + 1);
    }
    try {
        val = stold(tmp);
        return true;
    } catch(...) {
        return false;
    }
}

/*
   Returns true iff xw is a valid bounce coordinate (by the simplified reflection check).
*/
bool checkSingleBounce(long long y1, long long y2, long long yw,
                       long long xb, long long yb, long long r,
                       long double xw)
{
    // The bounce point for the ball's center is (xw, yw - r).
    // The incidence vector = (dx, dy).
    long double dx = xw - xb;
    long double dy = ( (long double)yw - r ) - yb;

    // Must go leftwards to reach x=0 eventually:
    if (dx >= 0.0L) return false;

    // Next, after bouncing, horizontal velocity stays dx, vertical becomes -dy.
    // We want x(t) = xw + dx*t = 0 => t = -xw/dx.  Must be t>0 to be a forward path.
    long double t = -xw / dx;
    if (t <= 0.0L) return false;

    // The y-coordinate at that crossing is y(t) = (yw - r) + (-dy)*t
    long double bounceY = ((long double)yw - r) - dy * t;

    // Must be strictly between y1 and y2 to score.
    if (bounceY <= (long double)y1 + EPS) return false;
    if (bounceY >= (long double)y2 - EPS) return false;

    // Passed our minimal reflection test
    return true;
}

int main(int argc, char* argv[])
{
    registerTestlibCmd(argc, argv);

    // Read official input
    long long y1 = inf.readLong();
    long long y2 = inf.readLong();
    long long yw = inf.readLong();
    long long xb = inf.readLong();
    long long yb = inf.readLong();
    long long r  = inf.readLong();

    // Read jury's answer
    string juryAns = ans.readToken(); // either -1 or a real number
    bool jurySaysNoSolution = (juryAns == "-1");

    // Read participant's answer
    string partAns = ouf.readToken();
    bool partSaysNoSolution = (partAns == "-1");

    // If participant and jury disagree on "no solution" vs "some solution", WA
    if (partSaysNoSolution && !jurySaysNoSolution) {
        // Jury found a solution, but participant says -1
