using namespace std;

static const char OBSTACLE = '*';
static const char PAWN = 'o';
static const char KING = 'X';
static const char OPEN = '.';

/*
  This generator produces exactly ONE dataset followed by
  a "0 0" line. Each run can thus form a complete input file
  for the problem.

  Parameters:
    -H (int) : height of the board [3..50]
    -W (int) : width of the board [3..50]
    -type (string) : one of {"random", "corner", "noSolution"}
                     default = "random"

  Exactly one 2x2 king piece is placed, exactly 2 open squares,
  some obstacles, and some pawns. The distribution of obstacles
  vs pawns depends on 'type'.

  NOTE: We do NOT set the random seed, and we do NOT provide
        a seed parameter. We rely on testlib's built-in generator.
*/

int main(int argc, char* argv[]) {
    registerGen(argc, argv, 1);

    // Read parameters.
    int H = opt<int>("H", 3);
    int W = opt<int>("W", 3);
    string type = opt<string>("type", "random");

    // Constrain H and W.
    // (Problem requires 3 ≤ H ≤ 50 and 3 ≤ W ≤ 50.)
    // In practice, if H or W are out of range, we could clamp or exit.
    // For simplicity, assume user gives valid H,W in [3..50].
    H = max(3, min(H, 50));
    W = max(3, min(W, 50));

    // Board initialization: fill with a placeholder for now (will fill later).
    // We'll finalize each cell with: 'X' (king), 'o' (pawn), '*' (obstacle), '.' (open).
    vector<vector<char>> board(H, vector<char>(W, '?'));

    // A helper to place the king in a 2x2 block at (r,c).
    auto placeKing = [&](int r, int c) {
        board[r][c]         = KING;
        board[r][c+1]       = KING;
        board[r+1][c]       = KING;
        board[r+1][c+1]     = KING;
    };

    // We want to place exactly one 2x2 king, so let's pick its position
    // depending on "type", or randomly if type == "random".

    // A function to fill every cell (that is still '?') with pawns or obstacles randomly,
    // then force exactly 2 of them to be '.' (open).
    auto fillRandomRest = [&](bool doShuffle) {
        // First collect all free cells (still '?').
        vector<pair<int,int>> freeCells;
        for(int r = 0; r < H; r++) {
            for(int c = 0; c < W; c++) {
                if(board[r][c] == '?') {
                    freeCells.push_back({r,c});
                }
            }
        }
        // We will shuffle them if doShuffle is true
        if(doShuffle) {
            shuffle(freeCells.begin(), freeCells.end());
        }

        // We need at least 2 free cells (the problem states we always have at least 2 open squares).
        // If there's fewer than 2 free cells, it means the user asked for a very constrained puzzle.
        // We'll just handle that by turning all we can into '.' or reduce the puzzle dimension.
        // The problem constraints should ensure there's enough space in typical usage (H*W >= 9).
        // But let's be safe.

        // Reserve exactly 2 open squares:
        int neededOpens = 2;
        int index = 0;
        for(; index < (int)freeCells.size() && index < neededOpens; index++) {
            auto [r,c] = freeCells[index];
            board[r][c] = OPEN; 
        }

        // The rest become either pawn or obstacle
        for(; index < (int)freeCells.size(); index++) {
            auto [r,c] = freeCells[index];
            // Let's pick randomly: 50% obstacle, 50% pawn
            int coin = rnd.next(2); 
            if(coin == 0) {
                board[r][c] = OBSTACLE; 
            } else {
                board[r][c] = PAWN;
            }
        }
    };

    // For simpler usage, a function to fill everything with pawns except for
    // the squares that are not '?' (the king squares or forced placeholders).
    // Then we choose exactly 2 squares to be '.' among '?' squares.
    auto fillMostlyPawns = [&]() {
        // Mark all '?' as pawns first.
        vector<pair<int,int>> freeCells;
        for(int r = 0; r < H; r++) {
            for(int c = 0; c < W; c++) {
                if(board[r][c] == '?') {
                    board[r][c] = PAWN;
                    freeCells.push_back({r,c});
                }
            }
        }
        // Shuffle, pick exactly 2 as '.' open squares
        shuffle(freeCells.begin(), freeCells.end());
        int neededOpens = 2;
        for(int i = 0; i < (int)freeCells.size() && i < neededOpens; i++) {
            int rr = freeCells[i].first;
            int cc = freeCells[i].second;
            board[rr][cc] = OPEN;
        }
    };

    // Create the board, depending on "type".
    if(type == "random") {
        // 1) place king in a random valid position
        int r = rnd.next(H-1); // range [0..H-2]
        int c = rnd.next(W-1); // range [0..W-2]
        placeKing(r,c);

        // 2) fill the rest with random obstacles/pawns, but exactly 2 squares remain open '.'
        //    We'll shuffle so we place '.' in random spots.
        fillRandomRest(true);

    } else if(type == "corner") {
        // Place the king in the top-left corner
        placeKing(0,0);

        // Then fill the rest with random distribution
        fillRandomRest(true);

    } else if(type == "noSolution") {
        // We try to create a puzzle that is obviously unsolvable by blocking the king behind a barrier.
        // Strategy:
        //   - place the king near bottom-right corner (anywhere that fits 2x2).
        //   - place a full row of obstacles to block the entire row (except for king squares if they happen to overlap).
        //   - place exactly 2 open squares on the king side of the barrier,
        //     the rest are pawns.

        // King near bottom right. For safety, take r = H-2, c = W-2.
        placeKing(H-2, W-2);

        // Let's pick a "barrier row" = H/2 (integer division).
        // Fill that entire row with obstacles '*', ignoring any squares that might be
        // part of the king. (But the king is at bottom anyway, so it won't overlap.)
        int barrierRow = H / 2;
        for(int col = 0; col < W; col++) {
            // If not already 'X', place '*'
            if(board[barrierRow][col] == '?') {
                board[barrierRow][col] = OBSTACLE;
            }
        }

        // Next, everything else that's still '?' => we fill with pawns
        // Then pick exactly 2 squares (preferably near the king) to be '.'.
        fillMostlyPawns();

    } else {
        // Default fallback: treat unknown type as random
        int r = rnd.next(H-1);
        int c = rnd.next(W-1);
        placeKing(r,c);
        fillRandomRest(true);
    }

    // Now we print the dataset:
    //  First line: H W
    //  Then H lines of W characters
    //  Then a line "0 0"
    //
    // Make sure there is exactly one 2x2 block of 'X' and exactly 2 '.' total.
    // Our fill functions should have ensured that.

    // Output
    printf("%d %d\n", H, W);
    for(int r = 0; r < H; r++) {
        for(int c = 0; c < W; c++) {
            // If any leftover '?' (shouldn't happen), turn it into an obstacle for safety.
            if(board[r][c] == '?') {
                board[r][c] = OBSTACLE;
            }
        }
    }

    for(int r = 0; r < H; r++) {
        for(int c = 0; c < W; c++) {
            printf("%c", board[r][c]);
        }
        printf("\n");
    }
    // End of input marker
    printf("0 0\n");

    return 0;
}

