            ensuref(int(grid[i].size()) == W, "Line %d should have exactly W=%d characters, but has length %d", i + 1, W, int(grid[i].size()));
            for (int j = 0; j < W; j++) {
                char c = grid[i][j];
                ensuref(c == 'X' || c == 'o' || c == '*' || c == '.', "Invalid character '%c' at line %d position %d", c, i + 1, j + 1);

                if (c == '.') {
                    dotCount++;
                } else if (c == 'X') {
                    xPositions.emplace_back(i, j);
                }
            }
        }

        ensuref(dotCount == 2, "There must be exactly two '.'s (open squares), but found %d", dotCount);
        ensuref(int(xPositions.size()) == 4, "There must be exactly 4 'X's forming the king piece, but found %d", int(xPositions.size()));

        int minRow = H, maxRow = -1, minCol = W, maxCol = -1;
        for (auto p : xPositions) {
            int i = p.first, j = p.second;
            minRow = min(minRow, i);
            maxRow = max(maxRow, i);
            minCol = min(minCol, j);
            maxCol = max(maxCol, j);
        }

        ensuref(maxRow - minRow == 1, "The 'X's must form a 2x2 square, but row indices range from %d to %d", minRow + 1, maxRow + 1);
        ensuref(maxCol - minCol == 1, "The 'X's must form a 2x2 square, but column indices range from %d to %d", minCol + 1, maxCol + 1);

        for (int i = minRow; i <= maxRow; i++) {
            for (int j = minCol; j <= maxCol; j++) {
                ensuref(grid[i][j] == 'X', "The 'X's must form a 2x2 square, but position (%d,%d) is '%c'", i + 1, j + 1, grid[i][j]);
            }
        }
    }

    inf.readEof();
    return 0;
}

