        // For each dataset, generate H, W, and the grid
        int H = h;
        int W = w;

        printf("%d %d\n", H, W);

        vector<string> grid(H);

        if (type == "safe") {
            // Generate a grid where all materials form rectangles

            // Decide the number of materials (up to 7)
            int num_materials = rnd.next(1, 7);

            // Generate rectangles for each material
            vector<char> materials;
            for(int i = 0; i < num_materials; ++i) {
                materials.push_back('A' + i);
            }

            // For each material, generate a rectangle
            vector<vector<int>> rectangles;

            for(int m = 0; m < num_materials; ++m) {
                // Randomly choose the rectangle parameters
                int min_h = H / 5;
                int min_w = W / 5;
                min_h = max(1, min_h);
                min_w = max(1, min_w);
                int rect_h = rnd.next(min_h, H);
                int rect_w = rnd.next(min_w, W);

                int y = rnd.next(0, H - rect_h);
                int x = rnd.next(0, W - rect_w);

                rectangles.push_back({y, x, y + rect_h - 1, x + rect_w -1, m});
            }

            // Now, simulate overlapping by assigning x-coordinates (depth) to materials
            vector<int> x_coords(num_materials);
            set<int> used_x;
            for(int m = 0; m < num_materials; ++m) {
                int xc;
                do {
                    xc = rnd.next(1, 1000);  // Arbitrary range
                } while (used_x.count(xc));
                used_x.insert(xc);
                x_coords[m] = xc;
            }

