        for (auto pos : positions) {
            grid[pos.first][pos.second] = 'w';
        }
    } else if (type == "checkerboard") {
        // Place 'w's in a checkerboard pattern
        for (int x = 0; x < n; ++x)
            for (int y = 0; y < m; ++y)
                if ((x + y) % 2 == 0)
                    grid[x][y] = 'w';
    } else if (type == "edge_w") {
        // Place 'w's along the edges
        for (int y = 0; y < m; ++y) {
            grid[0][y] = 'w';          // Top row
            grid[n - 1][y] = 'w';      // Bottom row
        }
        for (int x = 0; x < n; ++x) {
            grid[x][0] = 'w';          // Left column
            grid[x][m - 1] = 'w';      // Right column
        }
    } else {
        // If type is unknown
        fprintf(stderr, "Unknown type: %s\n", type.c_str());
        return 1;
    }

    // Ensure there is at least one 'w'
    bool has_w = false;
    for (int x = 0; x < n && !has_w; ++x)
        for (int y = 0; y < m && !has_w; ++y)
            if (grid[x][y] == 'w')
                has_w = true;
    if (!has_w) {
        // Place a single 'w' randomly
        int x = rnd.next(0, n - 1);
        int y = rnd.next(0, m - 1);
        grid[x][y] = 'w';
    }

    // Output the grid
    printf("%d %d\n", n, m);
    for (int x = 0; x < n; ++x)
        printf("%s\n", grid[x].c_str());

    return 0;
}

