bool check_frame(int si, int sj, int d) {
    if (si < 0 || sj < 0 || si + d > n || sj + d > m)
        return false;
    for (auto [i, j] : whites) {
        if (i < si || i >= si + d || j < sj || j >= sj + d)
            return false;
        bool on_border = (i == si || i == si + d - 1 || j == sj || j == sj + d -1);
        if (!on_border)
            return false;
    }
    return true;
}

int compute_min_d() {
    int min_i = n, max_i = -1, min_j = m, max_j = -1;
    for (auto [i, j] : whites) {
        min_i = min(min_i, i);
        max_i = max(max_i, i);
        min_j = min(min_j, j);
        max_j = max(max_j, j);
    }
    int d_min = max(max_i - min_i + 1, max_j - min_j + 1);
    for (int d = d_min; d <= max(n, m); d++) {
        for (int si = max(0, min_i - (d - 1)); si <= min(min_i, n - d); si++) {
            for (int sj = max(0, min_j - (d - 1)); sj <= min(min_j, m - d); sj++) {
                if (check_frame(si, sj, d)) {
                    return d;
                }
            }
        }
    }
    return -1; // No frame exists
}

bool frame_exists() {
    return compute_min_d() != -1;
}

