        if (max_i - min_i != d - 1 || max_j - min_j != d -1) {
            quitf(_wa, "Frame is not a square of size %d", d);
        }
        if (min_i < 0 || min_j < 0 || max_i >= n || max_j >= m) {
            quitf(_wa, "Frame goes outside the screen boundaries");
        }

        // Check frame's width is 1 pixel
        for (int i = min_i; i <= max_i; i++) {
            for (int j = min_j; j <= max_j; j++) {
                bool on_border = (i == min_i || i == max_i || j == min_j || j == max_j);
                char expected_char;
                if (grid[i][j] == 'w') {
                    expected_char = 'w';
                } else if (on_border) {
                    expected_char = '+';
                } else {
                    expected_char = '.'; // Inside the frame
                }
                if (pgrid[i][j] != expected_char) {
                    quitf(_wa, "Pixel (%d, %d): Expected '%c', found '%c'", i + 1, j + 1, expected_char, pgrid[i][j]);
                }
            }
        }

        // All 'w's should be on the frame's border
        for (auto [i, j] : whites) {
            if (i < min_i || i > max_i || j < min_j || j > max_j) {
                quitf(_wa, "White pixel (%d, %d) is outside the frame", i + 1, j + 1);
            }
            bool on_border = (i == min_i || i == max_i || j == min_j || j == max_j);
            if (!on_border) {
                quitf(_wa, "White pixel (%d, %d) is inside the frame, not on the border", i + 1, j + 1);
            }
        }

        // Check that the frame size is minimal
        int min_d = compute_min_d();
        if (min_d == -1) {
            quitf(_fail, "Participant outputs a frame but no frame exists according to the checker");
        }
        if (d > min_d) {
            quitf(_wa, "Participant's frame size %d is larger than minimal possible size %d", d, min_d);
        }

        quitf(_ok, "Accepted");
    }
}

