class TaskD {

    int n;
    int[] a;
    long[][] p;
    IntStack stack;

    public void solve(int testNumber, Scanner3 in, PrintWriter out) {
        try {
            n = in.nextInt();
            a = new int[n + 1];
            for (int i = 2; i <= n; i++)
                a[i] = in.nextInt();

            p = new long[3][];
            p[0] = new long[n + 1];
            p[2] = new long[n + 1];
            Arrays.fill(p[0], 0);
            Arrays.fill(p[2], 0);
            stack = new IntStack(n);

            StringBuilder res = new StringBuilder();
            for (int i = 1; i < n; i++) {
                a[1] = i;
                res.append(doit()).append('\n');
            }
            out.print(res.toString());
        } catch (Throwable e) {
            e.printStackTrace();
        }
    }

    long doit() {
        stack.clear();
        int x = 1;
        int side = 1;
        long res;
        while (true) {
            if (x <= 0 || x > n) {
                res = 0;
                break;
            }
            if (p[side + 1][x] != 0) {
                res = p[side + 1][x];
                break;
            }
            p[side + 1][x] = -1;
            stack.push(x);
            x += side * a[x];
            side *= -1;
        }

        for (int i = stack.size(); i > 0; i--) {
            x = stack.pop();
            side *= -1;
            if (res == -1) {
                if (x != 1)
                    p[side + 1][x] = -1;
            } else {
                res += a[x];
                if (x != 1)
                    p[side + 1][x] = res;
            }
        }
        p[2][1] = 0;
        return res;
    }

}

class IntStack {

    private int[] p;
    private int head;

    public IntStack(int capacity) {
        p = new int[capacity];
        head = -1;
    }

    public int size() {
        return head + 1;
    }

    public void push(int x) {
        p[++head] = x;
    }

    public int pop() {
        return p[head--];
    }

    public void clear() {
        head = -1;
    }
