    int T = opt<int>("T", 10);

    // Print T first
    cout << T << "\n";

    // A small array of primes for "large LCM" cases
    vector<int> primes = {31, 37, 41, 43, 47, 53, 59, 61};

    // We'll generate T datasets
    // Each dataset is:
    //  N (1 <= N <= 8)
    //  followed by N lines of chord expressions
    //
    // Old product chord expressions can only be "00","01","02","04","08","10","20","40","80".
    // We'll ensure that pattern i only uses "00" or exactly one sound bit (depending on i),
    // so that there is no overlap of the same sound at the same timing in different patterns.
    for (int _ds = 0; _ds < T; _ds++) {
        // Randomly pick a scenario type:
        //   0 => large LCM
        //   1 => all "00"
        //   2,3,4 => random
        int scenarioType = rnd.next(5);

        if (scenarioType == 0) {
            // Large LCM scenario
            // We'll pick N up to 4, each pattern length is a distinct prime from "primes".
            // That should easily produce a large LCM for the solution to handle.
            int N = rnd.next(1, 4); 
            cout << N << "\n";

            // Shuffle the prime indices to pick distinct ones
            vector<int> idx(primes.size());
            iota(idx.begin(), idx.end(), 0);
            shuffle(idx.begin(), idx.end());

            // For each pattern:
            for (int i = 0; i < N; i++) {
                int L = primes[idx[i]];  // length of the pattern

                // Decide which single-sound chord to use for pattern i
                // i=0 => "01", i=1 => "02", i=2 => "04", i=3 => "08", etc.
                // If i >= 8 (which shouldn't happen in practice if N<=8), we still won't break.
                static vector<string> singleSounds = {"01","02","04","08","10","20","40","80"};
                string single = singleSounds[i % 8];

                // Generate the chord sequence
                // We pick either "00" or single for each position with ~50% probability
                string pattern;
                pattern.reserve(L * 2);
                for (int j = 0; j < L; j++) {
                    if (rnd.next(2) == 0) {
                        pattern += "00";
                    } else {
                        pattern += single;
                    }
                }

                cout << pattern << "\n";
            }

        } else if (scenarioType == 1) {
            // All "00" scenario
            // N from 1..8, each pattern has length from 1..10, but all are "00".
            int N = rnd.next(1, 8);
            cout << N << "\n";
            for (int i = 0; i < N; i++) {
                int L = rnd.next(1, 10);
                string pattern;
                pattern.reserve(L * 2);
                for (int j = 0; j < L; j++) {
                    pattern += "00";
                }
                cout << pattern << "\n";
            }

        } else {
            // Random scenario
            // N from 1..8, length from 1..30, each chord is "00" or one particular single-sound bit.
            int N = rnd.next(1, 8);
            cout << N << "\n";
            for (int i = 0; i < N; i++) {
                int L = rnd.next(1, 30);

                // Single-sound chord for pattern i
                static vector<string> singleSounds = {"01","02","04","08","10","20","40","80"};
                string single = singleSounds[i % 8];

                // Build the pattern
                string pattern;
                pattern.reserve(L * 2);
                for (int j = 0; j < L; j++) {
                    if (rnd.next(2) == 0) {
                        pattern += "00";
                    } else {
                        pattern += single;
                    }
                }
                cout << pattern << "\n";
            }
        }
    }

    return 0;
}

