import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Scanner;

//Rhythm Machine
public class Main {

    // Nested class R
    class R implements Comparable<R> {
        int k, c;
        public R(int k, int c) {
            this.k = k;
            this.c = c;
        }
        @Override
        public int compareTo(R o) {
            return k - o.k;
        }
    }

    private int gcd(int a, int b) {
        return b == 0 ? a : gcd(b, a % b);
    }
    private int lcm(int a, int b) {
        int g = gcd(a, b);
        return a / g * b;
    }

    private void run() {
        Scanner sc = new Scanner(System.in);
        int testCases = sc.nextInt();
        while (testCases-- != 0) {
            int n = sc.nextInt();
            int[] lengths = new int[n];
            List<R>[] lists = new List[n];
            for (int i = 0; i < n; i++) {
                lists[i] = new ArrayList<>();
                char[] s = sc.next().toCharArray();
                lengths[i] = s.length / 2;
                int g = lengths[i];
                for (int k = 0; k < lengths[i]; k++) {
                    int c = (s[k * 2] - '0') * 16 + s[k * 2 + 1] - '0';
                    if (c == 0) {
                        continue;
                    }
                    lists[i].add(new R(k, c));
                    if (k != 0) {
                        g = gcd(g, k);
                    }
                }
                if (lists[i].isEmpty()) {
                    continue;
                }
                lengths[i] /= g;
                for (R r : lists[i]) {
                    r.k /= g;
                }
            }
            int lcm = 1;
            for (int i = 0; i < n; i++) {
                if (1024 < lcm || lists[i].isEmpty()) {
                    continue;
                }
                lcm = lcm(lcm, lengths[i]);
            }
            if (1024 < lcm) {
                System.out.println("Too complex.");
                continue;
            }
            List<R> res = new ArrayList<>();
            for (int i = 0; i < n; i++) {
                int mul = lcm / lengths[i];
                for (R r : lists[i]) {
                    res.add(new R(r.k * mul, r.c));
                }
            }
            if (res.isEmpty()) {
                System.out.println("00");
            } else {
                Collections.sort(res);
                int[] a = new int[lcm];
                for (R r : res) {
                    a[r.k] += r.c;
                }
                StringBuilder sb = new StringBuilder();
                for (int i = 0; i < lcm; i++) {
                    sb.append(String.format("%02X", a[i]));
                }
                System.out.println(sb);
            }
        }
    }

