    set<pair<int,int>> edges; // to avoid duplicates

    if (type == "random") {
        if (m == -1) {
            fprintf(stderr, "Please provide -m for random type.\n");
            return 1;
        }
        // Generate m random edges
        while ((int)edges.size() < m) {
            int a = rnd.next(1, n);
            int b = rnd.next(1, n);
            if (a == b) continue;
            if (a > b) swap(a, b);
            edges.insert({a, b});
        }
    } else if (type == "max_components") {
        // Try to create as many components in G0 as possible

        // For small n, include all edges to make G0 empty
        if (n * (n - 1LL) / 2 > 100000) {
            fprintf(stderr, "For max_components type, n should be less or equal to %d\n", 
                    int( ( sqrt(1 + 8e5) -1 )/2) ); // roughly n <= 447
            return 1;
        }
        m = n * (n - 1) / 2;
        for (int a = 1; a <= n; ++a) {
            for (int b = a + 1; b <= n; ++b) {
                edges.insert({a, b});
            }
        }
    } else if (type == "connected_G0") {
        if (m == -1) {
            fprintf(stderr, "Please provide -m for connected_G0 type.\n");
            return 1;
        }
        // Generate m random edges such that G0 remains connected.

        // Generate a random spanning tree (edges not included in the input)
        vector<pair<int, int>> treeEdges;
        for (int i = 2; i <= n; ++i) {
            int u = i;
            int v = rnd.next(1, i - 1);
            treeEdges.push_back({u, v});
        }
        shuffle(treeEdges.begin(), treeEdges.end());

        // Edges in the spanning tree are weight-0 edges (not included in input)
        // Now, include other edges as weight-1 edges in the input

        int totalEdges = n * (n - 1LL) / 2;
        set<pair<int, int>> forbiddenEdges;
        for (auto e : treeEdges) {
            int a = e.first;
            int b = e.second;
            if (a > b) swap(a, b);
            forbiddenEdges.insert({a, b});
        }
        // Now we can generate edges not in forbiddenEdges
        int edgesNeeded = min(m, (int)(totalEdges - treeEdges.size()));
        while ((int)edges.size() < edgesNeeded) {
            int a = rnd.next(1, n);
            int b = rnd.next(1, n);
            if (a == b) continue;
            if (a > b) swap(a, b);
            if (forbiddenEdges.count({a, b})) continue; // don't include edges in G0's spanning tree
            edges.insert({a, b});
        }
    } else {
        fprintf(stderr, "Unknown type: %s\n", type.c_str());
        return 1;
    }

    printf("%d %d\n", n, (int)edges.size());
    for (auto e : edges) {
        printf("%d %d\n", e.first, e.second);
    }
    return 0;
