/**
 * Built using CHelper plug-in
 * Actual solution is at the top
 * @author Sheng Cao
 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        InputReader in = new InputReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        AlmostAritmeticalProgression solver = new AlmostAritmeticalProgression();
        solver.solve(1, in, out);
        out.close();
    }
}

class AlmostAritmeticalProgression {

    public void solve(int testNumber, InputReader in, PrintWriter out) {
        int n1 = in.nextInt();
        int[] l1 = new int[n1];
        for (int i = 0; i < n1; i++) {
            l1[i] = in.nextInt();
        }
        int[] vals = ArrayUtil.sortUnique(l1);
        for (int i = 0; i < l1.length; i++) {
            l1[i] = Arrays.binarySearch(vals, l1[i]);
        }

        int[][] dp = new int[vals.length][vals.length];
        for (int i = 0; i < n1; i++) {
            int cur = l1[i];
            int[] newValueList = new int[vals.length];
            for (int from = 0; from < vals.length; from++) {
                int temp = dp[cur][from] + 1;
                dp[from][cur] = temp;
            }
        }
        int ans = 1;
        for (int[] e: dp) for (int f: e) if (f > ans) ans = f;
        out.println(ans);
    }
}

class InputReader {
    public BufferedReader in = null;
    public StringTokenizer st = null;

    public InputReader(InputStream usingStream) {
        in = new BufferedReader(new InputStreamReader(usingStream));

    }
    public String next(){
        for (;st == null || !st.hasMoreTokens();){
            String currentLine = null;
            try {
                currentLine = in.readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
            if (currentLine == null) return null;
            st = new StringTokenizer(currentLine);
        }
        return st.nextToken();
    }
    public int nextInt(){
        return Integer.parseInt(next());
    }

}

class ArrayUtil {
    public static int[] sortUnique(int[] l1) {
        int[] copy = l1.clone();
        Arrays.sort(copy);
        int size = 0;
        for (int i = 0; i < copy.length; i++) {
            if (i == 0 || copy[i] != copy[i - 1]) {
                copy[size++] = copy[i];
            }
        }
        return Arrays.copyOf(copy, size);
    }

}

