		}

		return pp;
	}

	int dx[] = {-1,0,1,0};
	int dy[] = {0,-1,0,1};

	int bfs(PriorityQueue<P> que, int lev) {
		int cnt = 1;
		if(que.isEmpty()) return cnt;
		for(;;) {
