        int size = pairs.size();
        for (int i = 1; i <= size; i++) {
            Pair pair = pairs.remove(0);
            pp[i] = new Pair(pair.f, pair.s + pp[i - 1].s);
        }

        return pp;
    }

    int bfs(Queue<P> que, int lev) {
        int cnt = 1;
        if (que.isEmpty()) {
            return cnt;
        }
        for (;;) {
            P p = que.remove();
            if (map[p.y][p.x] > lev) {
                que.add(p);
                break;
            }
            cnt++;
            for (int i = 0; i < 4; i++) {
                if (!visited[p.y + dy[i]][p.x + dx[i]]) {
                    que.add(new P(p.x + dx[i], p.y + dy[i]));
                    visited[p.y + dy[i]][p.x + dx[i]] = true;
                }
            }
        }

        return cnt;
    }

    class Pair {
        int f;
        int s;
        Pair(int f, int s) {
            this.f = f;
            this.s = s;
        }
    }

    class Comp implements Comparator<P> {

        Comp() {
            // default constructor
        }

        @Override
        public int compare(P o1, P o2) {
            return map[o1.y][o1.x] - map[o2.y][o2.x];
        }
    }

    class P {
        int x;
        int y;
        P(int x, int y) {
            this.x = x;
            this.y = y;
        }
    }

    public static void main(String[] args) {
        new Main().run();
    }

    void debug(Object... os) {
        System.err.println(Arrays.deepToString(os));
    }
