 */
public class Main {
    public static void main(String[] args) {
        InputStream inputStream = System.in;
        OutputStream outputStream = System.out;
        FastReader in = new FastReader(inputStream);
        PrintWriter out = new PrintWriter(outputStream);
        CRoundCorridor solver = new CRoundCorridor();
        solver.solve(1, in, out);
        out.close();
    }

    static class CRoundCorridor {
        public void solve(int testNumber, FastReader in, PrintWriter out) {
            long n = in.nextLong();
            long m = in.nextLong();
            int Q = in.nextInt();
            long gcd = NT.gcd(n, m);
            long nn = n / gcd;
            long mm = m / gcd;
            for (int q = 0; q < Q; ++q) {
                long sx = in.nextLong();
                long sy = in.nextLong();
                long ex = in.nextLong();
                long ey = in.nextLong();
                long seg1, seg2;
                if (sx == 1) {
                    seg1 = (sy + nn - 1) / nn;
                } else {
                    seg1 = (sy + mm - 1) / mm;
                }
                if (ex == 1) {
                    seg2 = (ey + nn - 1) / nn;
                } else {
                    seg2 = (ey + mm - 1) / mm;
                }
                if (seg1 == seg2) {
                    out.println("YES");
                } else {
                    out.println("NO");
                }
            }
        }

    }

    static class NT {
        public static long gcd(long a, long b) {
            a = Math.abs(a);
            b = Math.abs(b);
            while (b > 0) {
                long c = a;
                a = b;
                b = c % b;
            }
            return a;
        }

    }

    static class FastReader {
        private InputStream stream;
        private byte[] buf = new byte[8192];
        private int curChar;
        private int pnumChars;

        public FastReader(InputStream stream) {
            this.stream = stream;
        }

        private int pread() {
            if (pnumChars == -1) {
                throw new InputMismatchException();
            }
            if (curChar >= pnumChars) {
                curChar = 0;
                try {
                    pnumChars = stream.read(buf);
                } catch (IOException e) {
                    throw new InputMismatchException();
                }
                if (pnumChars <= 0) {
                    return -1;
                }
            }
            return buf[curChar++];
        }

        public int nextInt() {
            int c = pread();
            while (isSpaceChar(c))
                c = pread();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = pread();
            }
            int res = 0;
            do {
                if (c == ',') {
                    c = pread();
                }
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = pread();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        public long nextLong() {
            int c = pread();
            while (isSpaceChar(c))
                c = pread();
            int sgn = 1;
            if (c == '-') {
                sgn = -1;
                c = pread();
            }
            long res = 0;
            do {
                if (c < '0' || c > '9') {
                    throw new InputMismatchException();
                }
                res *= 10;
                res += c - '0';
                c = pread();
            } while (!isSpaceChar(c));
            return res * sgn;
        }

        private boolean isSpaceChar(int c) {
            return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
        }

    }
}

