    public static int upperBound(int[] a, int val) {
        int f = 0;
        int l = a.length;
        int len = l - f;
        while (len > 0) {
            int half = len >> 1;
            int mid = f + half;
            if (val < a[mid]) {
                len = half;
            } else {
                f = mid;
                ++f;
                len = len - half - 1;
            }
        }
        return f;
    }

    public static int lowerBound(int[] a, int val) {
        int f = 0;
        int l = a.length;
        int len = l - f;
