    public static boolean poss(long t){
        long count = 0;
        for(int i = 0; i<food.length; i++){
            if(food[i]*team[i] > t){
                count += team[i] - t/food[i];
            }
        }
        if(count > k){
            return false;
        }
        return true;
    }

