        fillRandom(A, 1000000);
        fillRandom(F, 1000000);
        sort(A.begin(), A.end(), greater<long long>());
        sort(F.begin(), F.end(), greater<long long>());

    } else if (type == "allOne") {
        // Every A_i = 1, every F_i = 1
