string generate_natural_sequence(int n) {
    string s;
    s.reserve(n);
    char prev = '\0';
    for (int i = 0; i < n; ++i) {
        int foot = i % 2;
        vector<char> possible_arrows;
        if (foot == 0) { // left foot
            possible_arrows.assign(left_foot_panels, left_foot_panels + 3);
        } else { // right foot
            possible_arrows.assign(right_foot_panels, right_foot_panels + 3);
        }
        // Remove previous arrow if same
        possible_arrows.erase(remove(possible_arrows.begin(), possible_arrows.end(), prev), possible_arrows.end());
        // Randomly select one
