// Generate a regular polygon with n vertices
void generate_regular_polygon(int n, vector<pair<int,int>> &polygon) {
    double R = rnd.next(5000.0, 10000.0);
    double angle_offset = rnd.next(0.0, 2*M_PI);
    polygon.clear();
    for (int i = 0; i < n; ++i) {
        double angle = angle_offset + 2 * M_PI * i / n;
        double x = R * cos(angle);
        double y = R * sin(angle);
        int xi = round(x);
        int yi = round(y);
        polygon.push_back(make_pair(xi, yi));
    }
}

// Generate a random convex polygon with n vertices
void generate_random_convex_polygon(int n, vector<pair<int,int>> &polygon) {
    vector<double> angles(n);
    for (int i = 0; i < n; ++i) {
        angles[i] = rnd.next(0.0, 2*M_PI);
    }
    sort(angles.begin(), angles.end());
    double R_min = 5000.0, R_max = 10000.0;
    polygon.clear();
    set<pair<int,int>> point_set;
    for (int i = 0; i < n; ++i) {
        double r = rnd.next(R_min, R_max);
        double x = r * cos(angles[i]);
        double y = r * sin(angles[i]);
        int xi = round(x);
        int yi = round(y);
        point_set.insert({xi, yi});
    }
    // Ensure we have exactly n unique points
    while ((int)point_set.size() < n) {
        double angle = rnd.next(0.0, 2*M_PI);
        double r = rnd.next(R_min, R_max);
        double x = r * cos(angle);
        double y = r * sin(angle);
        int xi = round(x);
        int yi = round(y);
        point_set.insert({xi, yi});
    }
    polygon.assign(point_set.begin(), point_set.end());
    // Points are in counter-clockwise order
}

// Generate polygon based on type
void generate_polygon(int n, string polygon_type, vector<pair<int, int>> &polygon) {
    if (polygon_type == "regular") {
        generate_regular_polygon(n, polygon);
    } else if (polygon_type == "random") {
        generate_random_convex_polygon(n, polygon);
    } else if (polygon_type == "thin") {
        // Generate a thin rectangle polygon
        int x0 = rnd.next(-5000, 5000);
        int y0 = rnd.next(-5000, 5000);
        int dx = rnd.next(9000, 10000);
        int dy = rnd.next(1, 1000); // Thin in y-direction
        polygon.clear();
        polygon.push_back({x0, y0});
        polygon.push_back({x0 + dx, y0});
        polygon.push_back({x0 + dx, y0 + dy});
        polygon.push_back({x0, y0 + dy});
        // If n > 4, we can add more points along the edges
        for (int i = 4; i < n; ++i) {
            int t = rnd.next(0, dx);
            polygon.insert(polygon.begin() + 1, {x0 + t, y0});
        }
    } else if (polygon_type == "colinear") {
        // Generate a convex polygon where some points are nearly colinear
        double R = rnd.next(5000.0, 10000.0);
        polygon.clear();
        for (int i = 0; i < n; ++i) {
            double angle = 2 * M_PI * i / n;
            if (i == n / 2) {
                // Slightly perturb the angle to make points nearly colinear
                angle += rnd.next(-0.00001, 0.00001);
            }
            double x = R * cos(angle);
            double y = R * sin(angle);
            int xi = round(x);
            int yi = round(y);
            polygon.push_back({xi, yi});
        }
    } else {
        // Default to random
        generate_random_convex_polygon(n, polygon);
    }

    // Ensure polygon has exactly n points (already handled)
}

// Generate queries based on type
void generate_queries(int q, string query_type, vector<pair<int,int>> &polygon,
                      vector<pair<pair<int,int>, pair<int,int>>> &queries)
{
    int n = (int)polygon.size();
    queries.clear();
    for(int i = 0; i < q; ++i) {
        pair<int,int> p1, p2;
        if (query_type == "random") {
            do {
                p1.first = rnd.next(-10000, 10000);
                p1.second = rnd.next(-10000, 10000);
                p2.first = rnd.next(-10000, 10000);
                p2.second = rnd.next(-10000, 10000);
            } while (p1 == p2);
        } else if (query_type == "vertex") {
            int idx1 = rnd.next(0, n-1);
            int idx2 = rnd.next(0, n-1);
            while (idx2 == idx1) idx2 = rnd.next(0, n-1);
            p1 = polygon[idx1];
            p2 = polygon[idx2];
        } else if (query_type == "edge") {
            int idx = rnd.next(0, n-1);
            p1 = polygon[idx];
            p2 = polygon[(idx + 1) % n];
        } else if (query_type == "tangent") {
            int idx = rnd.next(0, n-1);
            int prev = (idx - 1 + n) % n;
            int next = (idx + 1) % n;
            int x1 = polygon[idx].first;
            int y1 = polygon[idx].second;
            int x2 = polygon[next].first;
            int y2 = polygon[next].second;
            int dx = x2 - x1;
            int dy = y2 - y1;
            int pdx = -dy;
            int pdy = dx;
            p1 = polygon[idx];
            p2 = {p1.first + pdx, p1.second + pdy};
        } else if (query_type == "outside") {
            int x_offset = (polygon[0].first > 0) ? -20000 : 20000;
            int y_offset = (polygon[0].second > 0) ? -20000 : 20000;
            p1 = {polygon[0].first + x_offset, polygon[0].second + y_offset};
            p2 = {p1.first + 100, p1.second + 100};
        } else if (query_type == "overlap") {
            int idx = rnd.next(0, n-1);
            p1 = polygon[idx];
            p2 = polygon[(idx + 1) % n];
            int dx = p2.first - p1.first;
            int dy = p2.second - p1.second;
            p1.first -= 10000 * dx;
            p1.second -= 10000 * dy;
            p2.first += 10000 * dx;
            p2.second += 10000 * dy;
        } else {
            do {
                p1.first = rnd.next(-10000, 10000);
                p1.second = rnd.next(-10000, 10000);
                p2.first = rnd.next(-10000, 10000);
                p2.second = rnd.next(-10000, 10000);
            } while (p1 == p2);
        }

        if (p1 == p2) {
            p2.first += 1;
        }

        p1.first = max(-10000, min(10000, p1.first));
        p1.second = max(-10000, min(10000, p1.second));
        p2.first = max(-10000, min(10000, p2.first));
        p2.second = max(-10000, min(10000, p2.second));

        queries.push_back({p1, p2});
    }
}

int main(int argc, char* argv[]) {

    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int q = opt<int>("q");
    string polygon_type = opt<string>("polygon_type", "random");
    string query_type = opt<string>("query_type", "random");

    vector<pair<int,int>> polygon;
    generate_polygon(n, polygon_type, polygon);

    vector<pair<pair<int,int>, pair<int,int>>> queries;
    generate_queries(q, query_type, polygon, queries);

    // Output polygon
    printf("%d\n", n);
    for (int i = 0; i < n; ++i) {
        printf("%d %d\n", polygon[i].first, polygon[i].second);
    }

    // Output queries
    printf("%d\n", q);
    for (int i = 0; i < q; ++i) {
        printf("%d %d %d %d\n", queries[i].first.first, queries[i].first.second,
                                queries[i].second.first, queries[i].second.second);
    }

    return 0;
}

