typedef pair<int,int> Point;

long long cross(const Point& A, const Point& B, const Point& C) {
    long long x1 = B.first - A.first;
    long long y1 = B.second - A.second;
    long long x2 = C.first - B.first;
    long long y2 = C.second - B.second;
    return x1 * y2 - x2 * y1;
}

int main(int argc, char* argv[]) {
    registerValidation(argc, argv);

    int n = inf.readInt(3, 100, "n");
    inf.readEoln();

    vector<Point> points;
    set<Point> pointSet;
    for (int i = 0; i < n; i++) {
        int xi = inf.readInt(-10000, 10000, "xi");
        inf.readSpace();
        int yi = inf.readInt(-10000, 10000, "yi");
        inf.readEoln();
        Point p = make_pair(xi, yi);
        ensuref(pointSet.count(p) == 0, "Point (%d, %d) occurs more than once", xi, yi);
        pointSet.insert(p);
        points.push_back(p);
    }

    // Check that the points form a convex polygon in counter-clockwise order
    bool isConvex = true;
    int nPoints = points.size();
    int prev_sign = 0;
    for (int i = 0; i < nPoints; i++) {
        int i1 = i;
        int i2 = (i + 1) % nPoints;
        int i3 = (i + 2) % nPoints;
        long long cr = cross(points[i1], points[i2], points[i3]);
