    int minimal_t = (sum_hp + n - 1) / n;

    // Read participant's answer
    int t = ouf.readInt(1, int(1e6), "t"); // Number of steps
    if (t != minimal_t) {
        quitf(_wa, "t is not minimal, participant's t = %d, minimal t = %d", t, minimal_t);
    }

    vector<int> s(m); // Sizes of Evlampy's groups
    int64_t sum_s = 0;
    for (int i = 0; i < m; i++) {
        s[i] = ouf.readInt(0, n, format("s[%d]", i + 1).c_str());
        if (s[i] < 0 || s[i] > n) {
            quitf(_wa, "Invalid group size s[%d] = %d", i + 1, s[i]);
        }
        sum_s += s[i];
    }
    if (sum_s != n) {
        quitf(_wa, "Sum of group sizes is %lld, expected %d", sum_s, n);
    }

    // Read attack sequences
    vector<vector<int>> attacks(t, vector<int>(m));
    for (int step = 0; step < t; step++) {
        for (int i = 0; i < m; i++) {
            attacks[step][i] = ouf.readInt(1, m, format("attack[%d][%d]", step + 1, i + 1).c_str());
        }
    }

    // Simulate the battle
    vector<int> enemy_hp = hp;
    for (int step = 0; step < t; step++) {
        vector<int> damage(m, 0);
        for (int i = 0; i < m; i++) {
            int a_i = attacks[step][i] - 1; // zero-based index
            if (a_i < 0 || a_i >= m) {
                quitf(_wa, "Invalid attack target at step %d: a[%d] = %d", step + 1, i + 1, attacks[step][i]);
            }
            damage[a_i] += s[i];
        }
        for (int j = 0; j < m; j++) {
            enemy_hp[j] -= damage[j];
        }
    }

    // Check if all enemy groups are destroyed
    for (int j = 0; j < m; j++) {
        if (enemy_hp[j] > 0) {
            quitf(_wa, "Enemy group %d still has %d health points left", j + 1, enemy_hp[j]);
        }
    }

    // Correct answer
    quitf(_ok, "Answer is correct");
}

