class UnionFind {
 public:
  vi par, rank, sizes;
  long long n, trees;
  UnionFind(long long n) : n(n), trees(n) {
    par.resize(n), rank.resize(n), sizes.resize(n);
    for (long long i = 0, _lim = n; i < _lim; i++) par[i] = i, sizes[i] = 1;
  }
  long long root(long long x) {
    if (par[x] == x)
      return x;
    else
      return par[x] = root(par[x]);
  }
  long long find(long long x) { return root(x); }
  void unite(long long x, long long y) {
    x = root(x);
    y = root(y);
    if (x == y) return;
    if (rank[x] < rank[y]) swap(x, y);
    trees--;
    par[y] = x;
    sizes[x] += sizes[y];
    if (rank[x] == rank[y]) rank[x]++;
  }
  bool same(long long x, long long y) { return root(x) == root(y); }
  long long size(long long x) { return sizes[root(x)]; }
  vector<vi> sets() {
    vector<vi> res(trees);
    unordered_map<long long, vi> map;
    for (long long i = 0, _lim = n; i < _lim; i++) map[root(i)].push_back(i);
    long long i = 0;
    for (auto &&p : map) {
      long long r = p.first;
      res[i].push_back(r);
      for (auto &&v : p.second) {
        if (r == v) continue;
        res[i].push_back(v);
      }
      i++;
    }
    return res;
  }
};
