const long long D_MAX = 1000000000LL;

int main(int argc, char* argv[]) {

    registerGen(argc, argv, 1);

    int n = opt<int>("n");
    int k = opt<int>("k", 0);
    string type = opt<string>("type", "random");

    vector<long long> a(n);

    if (type == "all_same") {
        /* All elements are the same */
        long long val = rnd.next(1LL, D_MAX / n);
        for(int i = 0; i < n; ++i)
            a[i] = val;
    } else if (type == "max_elements") {
        /* All elements are maximal to keep sum <= D_MAX */
        long long val = D_MAX / n;
        if (val == 0) val = 1;
        for(int i = 0; i < n; ++i)
            a[i] = val;
    } else if (type == "min_elements") {
        /* All elements are minimal */
        for(int i = 0; i < n; ++i)
            a[i] = 1;
    } else if (type == "unlucky_overlap") {
        /* Elements are 1 so cumulative sums are 1..n */
        for(int i = 0; i < n; ++i)
            a[i] = 1;
    } else if (type == "large_elements") {
        /* Elements are large so sums exceed D_MAX */
        long long val = D_MAX + rnd.next(1LL, D_MAX);
        for(int i = 0; i < n; ++i)
            a[i] = val;
    } else { // "random"
        /* Generate random elements ensuring sum <= D_MAX */
        long long sum = 0;
        for(int i = 0; i < n; ++i) {
            a[i] = rnd.next(1LL, D_MAX / n);
            sum += a[i];
        }
    }

    // Adjust total sum to not exceed D_MAX if necessary
    long long sum = accumulate(a.begin(), a.end(), 0LL);
    if (sum > D_MAX && (type != "large_elements")) {
        for(int i = 0; i < n; ++i)
            a[i] = (a[i] * D_MAX) / sum;
    }

    /* Output n */
    printf("%d\n", n);
    /* Output a1, a2, ..., an */
    for (int i = 0; i < n; i++) {
        printf("%lld%c", a[i], " \n"[i == n - 1]);
    }

    /* Output k */
    printf("%d\n", k);
    vector<long long> unlucky;
    if (type == "unlucky_overlap") {
        /* Unlucky numbers are cumulative sums */
        for (int i = 1; i <= k; ++i) {
            unlucky.push_back(i);
        }
    } else {
        /* Generate random unlucky numbers in [1, D_MAX] */
        set<long long> unlucky_set;
        while (unlucky_set.size() < k) {
            long long num = rnd.next(1LL, D_MAX);
            unlucky_set.insert(num);
        }
        unlucky.assign(unlucky_set.begin(), unlucky_set.end());
    }
    /* Output unlucky numbers */
    for (int i = 0; i < k; i++) {
        printf("%lld%c", unlucky[i], " \n"[i == k - 1]);
    }
    return 0;
}

