    // Check no leading or trailing spaces
    if (!line.empty() && (line.front() == ' ' || line.back() == ' ')) {
        quitf(_fail, "Line starts or ends with a space");
    }

    vector<string> tokens;
    size_t pos = 0;
    while (pos < line.size()) {
        if (line[pos] == ' ') {
            quitf(_fail, "Multiple spaces detected at position %d", (int)pos);
        }
        // Read digits
        size_t start = pos;
        while (pos < line.size() && isdigit(line[pos])) {
            pos++;
        }
        if (start == pos) {
            quitf(_fail, "Expected a number at position %d", (int)pos);
        }
        tokens.push_back(line.substr(start, pos - start));
        if ((int)tokens.size() > n) {
            quitf(_fail, "More numbers than expected");
        }
        // After number, expect either space or end of line
        if (pos < line.size()) {
            if (line[pos] != ' ') {
                quitf(_fail, "Expected a single space or end of line at position %d", (int)pos);
            }
            pos++; // Skip the space
            if (pos < line.size() && line[pos] == ' ') {
                quitf(_fail, "Multiple spaces detected at position %d", (int)pos);
            }
        }
    }

    if ((int)tokens.size() != n) {
        quitf(_fail, "Expected %d numbers, found %d", n, (int)tokens.size());
    }

    for (int i = 0; i < n; ++i) {
        string num_str = tokens[i];
        if (num_str.empty()) {
            quitf(_fail, "Empty token at position %d", i+1);
        }
        if (num_str.length() > 6) {
            quitf(_fail, "Number too long at position %d", i+1);
        }
        for (char c : num_str) {
            if (!isdigit(c)) {
                quitf(_fail, "Non-digit character in number at position %d", i+1);
            }
        }
        if (num_str[0] == '0') {
            quitf(_fail, "Leading zero in number at position %d", i+1);
        }
        int num = atoi(num_str.c_str());
        if (num < 1 || num > 100000) {
            quitf(_fail, "Number out of range at position %d", i+1);
        }
    }

    inf.readEof();

    return 0;
}

